def count_powerful_integers(start: int, finish: int, limit: int, s: str) -> int:
    from functools import lru_cache

    # If any digit of s exceeds limit, no powerful integer can end with s
    if any(int(c) > limit for c in s):
        return 0

    m = len(s)
    s_val = int(s)

    def count_upto(n: int) -> int:
        # Count powerful x with 1 <= x <= n
        if n < s_val:
            return 0
        n_str = str(n)
        L = len(n_str)

        total = 0
        # Numbers with fewer total digits than n (and length >= m)
        for length in range(m, L):
            k = length - m  # prefix length
            if k == 0:
                total += 1  # x = s itself
            else:
                # first prefix digit in [1, limit], remaining in [0, limit]
                total += limit * (limit + 1) ** (k - 1)

        # Numbers with exactly L digits, x <= n
        k = L - m
        if k < 0:
            return total
        if k == 0:
            if s_val <= n:
                total += 1
            return total

        # Digit DP over the k prefix digits; compare full number to n.
        # State: position in prefix, whether prefix so far equals n's prefix.
        @lru_cache(maxsize=None)
        def dp(pos: int, tight: bool) -> int:
            if pos == k:
                # Full number = prefix + s. Compare to n.
                if not tight:
                    return 1
                # prefix equals n_str[:k]; compare s to n_str[k:]
                return 1 if s <= n_str[k:] else 0
            lo = 1 if pos == 0 else 0
            hi = min(limit, int(n_str[pos]) if tight else 9)
            res = 0
            for d in range(lo, hi + 1):
                res += dp(pos + 1, tight and d == int(n_str[pos]))
            return res

        total += dp(0, True)
        return total

    return count_upto(finish) - count_upto(start - 1)

