def count_powerful_integers(start: int, finish: int, limit: int, s: str) -> int:
    from functools import lru_cache

    if any(int(c) > limit for c in s):
        return 0

    m = len(s)
    s_val = int(s)
    base = 10 ** m

    def count_digits_le(bound: int) -> int:
        # Count integers p in [0, bound] whose decimal digits are all <= limit
        if bound < 0:
            return 0
        d = str(bound)
        L = len(d)

        @lru_cache(maxsize=None)
        def dp(pos: int, tight: bool) -> int:
            if pos == L:
                return 1
            hi = min(limit, int(d[pos])) if tight else limit
            res = 0
            for x in range(0, hi + 1):
                res += dp(pos + 1, tight and x == int(d[pos]))
            return res

        return dp(0, True)

    def count_upto(n: int) -> int:
        # Count powerful x in [1, n]; x = p * base + s_val, p >= 0, p digits <= limit
        if n < s_val:
            return 0
        p_max = (n - s_val) // base
        count = count_digits_le(p_max)
        return count

    return count_upto(finish) - count_upto(start - 1)

