        L = len(digits)
        # Numbers with fewer digits than bound: first digit 1..limit, rest 0..limit
        total = 1  # the number 0
        for length in range(1, L):
            total += limit * (limit + 1) ** (length - 1)
        # Numbers with exactly L digits, <= bound (digit-by-digit)
        tight_ok = True
        for i, dig in enumerate(digits):
            lo = 1 if i == 0 else 0
            hi = min(dig, limit) if tight_ok else limit
            # count choices strictly less than the bound digit
            if i == 0:
                choices_less = max(0, min(dig - 1, limit))  # digits in [1, dig-1]
            else:
                choices_less = min(dig, limit + 1)  # digits in [0, dig-1] capped
            rest = L - i - 1
            if tight_ok:
                total += choices_less * (limit + 1) ** rest
                if dig > limit:
                    tight_ok = False
                    break
            else:
                break
        else:
            if tight_ok:
                total += 1  # bound itself has all digits <= limit
        return total

    def count_upto(n: int) -> int:
        if n < s_val:
            return 0
        return count_digits_le((n - s_val) // base)

    return count_upto(finish) - count_upto(start - 1)


