def count_powerful_integers(start: int, finish: int, limit: int, s: str) -> int:
    from functools import lru_cache

    if any(int(c) > limit for c in s):
        return 0

    m = len(s)
    s_val = int(s)
    base = 10 ** m

    def count_p_le(bound: int) -> int:
        # Number of integers p in [0, bound] whose digits are all <= limit
        if bound < 0:
            return 0
        d = str(bound)

        @lru_cache(maxsize=None)
        def go(i: int, tight: bool, started: bool) -> int:
            if i == len(d):
                return 1  # counts the number formed (0 included when not started)
            hi = int(d[i]) if tight else 9
            hi = min(hi, limit)
            res = 0
            for digit in range(0, hi + 1):
                res += go(i + 1, tight and digit == int(d[i]), started or digit != 0)
            return res

        return go(0, True, False)

    def count_upto(n: int) -> int:
        # Count powerful x in [1, n]
        if n < s_val:
            return 0
        return count_p_le((n - s_val) // base)

    return count_upto(finish) - count_upto(start - 1)

from typing import Optional, List


def solve_grid(n: int, r: str, c: str) -> Optional[List[str]]:
    """ Given an integer N and strings R and C of length N consisting of 'A', 'B', and 'C',
    determine if it's possible to fill an N×N grid such that:
    - Each row and column contains exactly one 'A', one 'B', and one 'C'
    - The leftmost character written in the i-th row matches the i-th character of R
    - The topmost character written in the i-th column matches the i-th character of C

    Empty cells are represented by '.' in the output.

    Args:
        n: The size of the grid (3 <= n <= 5)
        r: String of length n specifying leftmost characters in each row
        c: String of length n specifying topmost characters in each column

    Returns:
        A list of n strings representing the filled grid if possible, None otherwise.
        Each string has length n, where '.' represents empty cells.

    >>> solve_grid(3, 'ABC', 'ABC')
    ['ABC', 'BCA', 'CAB']
    >>> solve_grid(3, 'AAA', 'BBB')
    None
    """
    letters = "ABC"
    grid = [['.'] * n for _ in range(n)]
    cells = [(i, j) for i in range(n) for j in range(n)]

    def row_valid(i: int) -> bool:
        row = grid[i]
        counts = {ch: 0 for ch in letters}
        for ch in row:
            if ch != '.':
                counts[ch] += 1
        if any(v > 1 for v in counts.values()):
            return False
        # Leftmost written char must match r[i]
        leftmost = next((ch for ch in row if ch != '.'), None)
        if leftmost is not None and leftmost != r[i]:
            return False
        return True

    def col_valid(j: int) -> bool:
        counts = {ch: 0 for ch in letters}
        for i in range(n):
            ch = grid[i][j]
            if ch != '.':
                counts[ch] += 1
        if any(v > 1 for v in counts.values()):
            return False
        topmost = next((grid[i][j] for i in range(n) if grid[i][j] != '.'), None)
        if topmost is not None and topmost != c[j]:
            return False
        return True

    def row_complete(i: int) -> bool:
        row = grid[i]
        return sorted(ch for ch in row if ch != '.') == sorted(letters)

    def col_complete(j: int) -> bool:
        col = [grid[i][j] for i in range(n)]
        return sorted(ch for ch in col if ch != '.') == sorted(letters)

    def backtrack(idx: int) -> bool:
        if idx == len(cells):
            for i in range(n):
                if not row_complete(i):
                    return False
            for j in range(n):
                if not col_complete(j):
                    return False
            return True

        i, j = cells[idx]
        for ch in ['.'] + list(letters):
            grid[i][j] = ch
            # Prune on partial validity of the affected row and column
            if row_valid(i) and col_valid(j):
                if backtrack(idx + 1):
                    return True
        grid[i][j] = '.'
        return False

    if backtrack(0):
        return [''.join(row) for row in grid]
    return None

