def solve_grid(n: int, r: str, c: str) -> Optional[List[str]]:
    """ Given an integer N and strings R and C of length N consisting of 'A', 'B', and 'C',
    determine if it's possible to fill an N×N grid such that:
    - Each row and column contains exactly one 'A', one 'B', and one 'C' (others are '.')
    - The leftmost character written in the i-th row matches the i-th character of R
    - The topmost character written in the i-th column matches the i-th character of C

    Empty cells are represented by '.' in the output.
    """
    letters = "ABC"
    cells = n * n

    def leftmost(row):
        return next((ch for ch in row if ch != '.'), None)

    def topmost(col):
        return next((ch for ch in col if ch != '.'), None)

    # Enumerate every grid assignment (each cell: '.', 'A', 'B', or 'C').
    for flat in product(['.'] + list(letters), repeat=cells):
        grid = [list(flat[i * n:(i + 1) * n]) for i in range(n)]
        ok = True
        for i in range(n):
            row = grid[i]
            if sorted(ch for ch in row if ch != '.') != sorted(letters):
                ok = False
                break
            if leftmost(row) != r[i]:
                ok = False
                break
        if not ok:
            continue
        for j in range(n):
            col = [grid[i][j] for i in range(n)]
            if sorted(ch for ch in col if ch != '.') != sorted(letters):
                ok = False
                break
            if topmost(col) != c[j]:
                ok = False
                break
        if ok:
            return [''.join(row) for row in grid]
    return None

