def solve_grid(n: int, r: str, c: str) -> Optional[List[str]]:
    """ Given an integer N and strings R and C of length N consisting of 'A', 'B', and 'C',
    determine if it's possible to fill an N×N grid such that:
    - Each row and column contains exactly one 'A', one 'B', and one 'C'
    - The leftmost character written in the i-th row matches the i-th character of R
    - The topmost character written in the i-th column matches the i-th character of C

    Empty cells are represented by '.' in the output.
    """
    letters = "ABC"

    # Each row/column holds exactly one A, B, C; the other cells are '.'.
    # For each row, choose a position (0..n-1) for each of A, B, C that are distinct.
    row_options = []
    for pa in range(n):
        for pb in range(n):
            for pc in range(n):
                if len({pa, pb, pc}) != 3:
                    continue
                row = ['.'] * n
                row[pa], row[pb], row[pc] = 'A', 'B', 'C'
                row_options.append(''.join(row))

    grid = [None] * n
    col_counts = [{ch: 0 for ch in letters} for _ in range(n)]
    col_first = [None] * n  # topmost letter seen so far in each column

    def leftmost(row: str):
        return next((ch for ch in row if ch != '.'), None)

    def backtrack(i: int) -> bool:
        if i == n:
            # Every column must have exactly one of each letter (row-level counts are already exact)
            return all(all(v == 1 for v in col_counts[j].values()) for j in range(n))
        for row in row_options:
            if leftmost(row) != r[i]:
                continue
            ok = True
            for j in range(n):
                ch = row[j]
                if ch == '.':
                    continue
                if col_counts[j][ch] >= 1:
                    ok = False
                    break
                # topmost letter placed in column j must match c[j]
                if col_first[j] is None:
                    if ch != c[j]:
                        ok = False
                        break
            if not ok:
                continue
            # apply
            saved_first = col_first[:]
            for j in range(n):
                ch = row[j]
                if ch != '.':
                    col_counts[j][ch] += 1
                    if col_first[j] is None:
                        col_first[j] = ch
            grid[i] = row
            if backtrack(i + 1):
                return True
            # undo
            for j in range(n):
                ch = row[j]
                if ch != '.':
                    col_counts[j][ch] -= 1
            col_first[:] = saved_first
        return False

    if backtrack(0):
        return grid[:]
    return None

