def find_cube_placement(V1: int, V2: int, V3: int) -> Optional[Tuple[int, int, int, int, int, int, int, int, int]]:
    S = 7
    TOTAL = 3 * S ** 3

    # Necessary identity: each unit of volume counted with multiplicity sums to 3 cubes' worth.
    if V1 + 2 * V2 + 3 * V3 != TOTAL:
        return None
    if min(V1, V2, V3) < 0:
        return None

    def overlap1d(a, b):
        return max(0, S - abs(a - b))

    def box_volume(lo, hi):
        v = 1
        for l, h in zip(lo, hi):
            if h <= l:
                return 0
            v *= h - l
        return v

    choices = list(range(-S, S + 1)) + [S + 1]
    for a2, b2, c2 in product(choices, repeat=3):
        I12 = overlap1d(0, a2) * overlap1d(0, b2) * overlap1d(0, c2)
        for a3, b3, c3 in product(choices, repeat=3):
            I13 = overlap1d(0, a3) * overlap1d(0, b3) * overlap1d(0, c3)
            I23 = overlap1d(a2, a3) * overlap1d(b2, b3) * overlap1d(c2, c3)
            lo = [max(0, a2, a3), max(0, b2, b3), max(0, c2, c3)]
