    True
    >>> can_tile_grid(1, 1, 2, [(2, 3)])
    False
    >>> can_tile_grid(1, 2, 2, [(1, 1)])
    False
    """
    target = h * w

    def exact_cover(subset):
        grid = [[False] * w for _ in range(h)]
        used = [False] * len(subset)

        def first_empty():
            for r in range(h):
                for c in range(w):
                    if not grid[r][c]:
                        return r, c
            return None

