                        return False
            return True

        def set_cells(r, c, rh, rw, value):
            for i in range(r, r + rh):
                for j in range(c, c + rw):
                    grid[i][j] = value

        def solve():
            pos = first_empty()
            if pos is None:
                return all(used)
            r, c = pos
            for k in range(len(subset)):
                if used[k]:
                    continue
                a, b = subset[k]
                for rh, rw in {(a, b), (b, a)}:
                    if fits(r, c, rh, rw):
                        set_cells(r, c, rh, rw, True)
                        used[k] = True
                        if solve():
                            return True
                        used[k] = False
                        set_cells(r, c, rh, rw, False)
