def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """ Determine if it's possible to place rectangular tiles on an H×W grid such that:
    - Every cell is covered by exactly one tile
    - Tiles can be rotated (so a 2×3 tile can be placed as 3×2)
    - Some tiles may remain unused
    - Tiles must be aligned with grid cells and cannot extend outside

    Args:
        n: Number of available tiles (1 ≤ n ≤ 7)
        h: Height of the grid (1 ≤ h ≤ 10)
        w: Width of the grid (1 ≤ w ≤ 10)
        tiles: List of (a, b) tuples where tile i has dimensions a×b (1 ≤ a, b ≤ 10)

    Returns:
        True if the grid can be perfectly tiled, False otherwise

    >>> can_tile_grid(5, 5, 5, [(1, 1), (3, 3), (4, 4), (2, 3), (2, 5)])
    True
    >>> can_tile_grid(1, 1, 2, [(2, 3)])
    False
    >>> can_tile_grid(1, 2, 2, [(1, 1)])
    False
    """
    target = h * w
    full = (1 << target) - 1

    def cell_bit(r, c):
        return 1 << (r * w + c)

    def placement_mask(r, c, rh, rw):
        if r + rh > h or c + rw > w:
            return None
        m = 0
        for i in range(r, r + rh):
            for j in range(c, c + rw):
                m |= cell_bit(i, j)
        return m

    def exact_cover(subset):
        # Precompute every legal placement (as a bitmask) for each tile.
        options = []
        for a, b in subset:
            opts = set()
            for rh, rw in {(a, b), (b, a)}:
                for r in range(h):
                    for c in range(w):
                        m = placement_mask(r, c, rh, rw)
                        if m is not None:
                            opts.add(m)
            options.append(opts)

        k = len(subset)
        memo = {}

        def solve(covered, idx):
            # Every tile in the subset must be placed exactly once.
            if idx == k:
                return covered == full
            key = (covered, idx)
            if key in memo:
                return memo[key]
            # Lowest uncovered cell must be covered by the next tile.
            result = False
            for m in options[idx]:
                if m & covered:
                    continue
                if solve(covered | m, idx + 1):
                    result = True
                    break
            memo[key] = result
            return result

        return solve(0, 0)

    # Try every non-empty subset of tiles with total area equal to the grid area.
    for mask in range(1, 1 << n):
        subset = [tiles[i] for i in range(n) if mask & (1 << i)]
        if sum(a * b for a, b in subset) != target:
            continue
        if exact_cover(subset):
            return True
    return False

