def count_ways_to_stair(k: int) -> int:
    MAX_JUMP = 32
    limit = 2 * k + 2

    @lru_cache(maxsize=None)
    def dfs(stair, jump, last_down):
        total = 1 if stair == k else 0
        if stair >= 1 and not last_down:
            total += dfs(stair - 1, jump, True)
        if jump < MAX_JUMP:
            nxt = stair + (1 << jump)
            if nxt <= limit:
                total += dfs(nxt, jump + 1, False)
        return total

    return dfs(1, 0, False)

