def count_good_sequences(N: int, M: int) -> int:
    def sigma(n):
        total = 0
        d = 1
        while d * d <= n:
            if n % d == 0:
                total += d
                if d * d != n:
                    total += n // d
            d += 1
        return total

    def ways(n):
        # number of ordered length-M sequences of positive integers with product n
        res = 1
        m = n
        d = 2
        while d * d <= m:
            if m % d == 0:
                e = 0
                while m % d == 0:
                    m //= d
                    e += 1
                # C(e + M - 1, e) mod MOD
                c = 1
                for i in range(1, e + 1):
                    c = c * ((M - 1 + i) % MOD) % MOD * pow(i, MOD - 2, MOD) % MOD
                res = res * c % MOD
            d += 1
        if m > 1:
            res = res * (M % MOD) % MOD
        return res

    total = 0
    for n in range(1, N + 1):
        if sigma(n) % 3 == 0:
            total = (total + ways(n)) % MOD
    return total

