def _matmul(A, B):
    n = len(A)
    C = [[0] * n for _ in range(n)]
    for i in range(n):
        Ai = A[i]
        for k in range(n):
            a = Ai[k]
            if a == 0:
                continue
            Bk = B[k]
            Ci = C[i]
            for j in range(n):
                Ci[j] = (Ci[j] + a * Bk[j]) % MOD
    return C

