from itertools import permutations
from bisect import bisect_left


def _lis(seq):
    tails = []
    for x in seq:
        i = bisect_left(tails, x)
        if i == len(tails):
            tails.append(x)
        else:
            tails[i] = x
    return len(tails)


def _lds(seq):
    return _lis([-x for x in seq])


def count_special_permutations(A: int, B: int, M: int) -> int:
    """Count the number of permutations P of (1, 2, ..., AB-1) that satisfy:
    1. The length of a longest increasing subsequence of P is A
    2. The length of a longest decreasing subsequence of P is B
    3. There exists an integer n such that appending n + 0.5 to the end of P
       does not change either the length of a longest increasing subsequence
       or the length of a longest decreasing subsequence

    Return the count modulo M.

    >>> count_special_permutations(3, 2, 998244353)
    10
    >>> count_special_permutations(10, 12, 924844033)
    623378361
    """
    n = A * B - 1
    if n > 9:
        raise NotImplementedError("Brute force only feasible for AB-1 <= 9.")
    count = 0
    for P in permutations(range(1, n + 1)):
        P = list(P)
        if _lis(P) != A or _lds(P) != B:
            continue
        ok = False
        for m in range(0, n + 1):
            Q = P + [m + 0.5]
            if _lis(Q) == A and _lds(Q) == B:
                ok = True
                break
        if ok:
            count += 1
    return count % M

from collections import deque

def tile_id(K, x, y):
    # Cell containing point (x + 0.5, y + 0.5)
    i = (x + 0.5) // K
    j = (y + 0.5) // K
    i, j = int(i), int(j)
    if (i - j) % 2 == 0:
        k = int(y - j * K)
    else:
        k = int(x - i * K)
    return (i, j, k)

def tile_bounds(K, i, j, k):
    # Returns (x0, x1, y0, y1) of the tile
    if (i - j) % 2 == 0:
        return (i * K, (i + 1) * K, j * K + k, j * K + k + 1)
    else:
        return (i * K + k, i * K + k + 1, j * K, (j + 1) * K)

def adjacent(K, a, b):
    # Two tiles are adjacent if their closed boundaries share a segment of positive length
    ax0, ax1, ay0, ay1 = tile_bounds(K, *a)
    bx0, bx1, by0, by1 = tile_bounds(K, *b)
    # Overlap in x and y projections
    ox = min(ax1, bx1) - max(ax0, bx0)
    oy = min(ay1, by1) - max(ay0, by0)
    if ox < 0 or oy < 0:
        return False
    # Share an edge: one of the projections has zero-width overlap, the other positive
    return (ox == 0 and oy > 0) or (oy == 0 and ox > 0)

def bfs_min_moves(K, S_x, S_y, T_x, T_y, search_radius=6):
    # Brute-force reference: restricts to tiles within a block window
    start = tile_id(K, S_x, S_y)
    target = tile_id(K, T_x, T_y)
    if start == target:
        return 0
    lo = min(start[0], target[0]) - search_radius
    hi = max(start[0], target[0]) + search_radius
    lo_j = min(start[1], target[1]) - search_radius
    hi_j = max(start[1], target[1]) + search_radius
    seen = {start: 0}
    q = deque([start])
    while q:
        cur = q.popleft()
        d = seen[cur]
        ci, cj, ck = cur
        # Enumerate candidate neighbors within the window
        for di in range(-2, 3):
            for dj in range(-2, 3):
                for k in range(K):
                    nb = (ci + di, cj + dj, k)
                    if not (lo <= nb[0] <= hi and lo_j <= nb[1] <= hi_j):
                        continue
                    if nb in seen:
                        continue
                    if adjacent(K, cur, nb):
                        if nb == target:
                            return d + 1
                        seen[nb] = d + 1
                        q.append(nb)
    return None

