def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    def tile_id(x, y):
        i = (x + 0.5) // K
        j = (y + 0.5) // K
        i, j = int(i), int(j)
        if (i - j) % 2 == 0:
            k = int(y - j * K)
        else:
            k = int(x - i * K)
        return (i, j, k)

    def bounds(t):
        i, j, k = t
        if (i - j) % 2 == 0:
            return (i * K, (i + 1) * K, j * K + k, j * K + k + 1)
        return (i * K + k, i * K + k + 1, j * K, (j + 1) * K)

    def adjacent(a, b):
        ax0, ax1, ay0, ay1 = bounds(a)
        bx0, bx1, by0, by1 = bounds(b)
        ox = min(ax1, bx1) - max(ax0, bx0)
        oy = min(ay1, by1) - max(ay0, by0)
        if ox < 0 or oy < 0:
            return False
        return (ox == 0 and oy > 0) or (oy == 0 and ox > 0)

    start = tile_id(S_x, S_y)
    target = tile_id(T_x, T_y)
    if start == target:
        return 0

    R = 3
    lo_i = min(start[0], target[0]) - R
    hi_i = max(start[0], target[0]) + R
    lo_j = min(start[1], target[1]) - R
    hi_j = max(start[1], target[1]) + R

    # Tiles in each block: enumerate all k for each block in the window
    def neighbors(t):
        ci, cj, _ = t
        for di in range(-1, 2):
            for dj in range(-1, 2):
                ni, nj = ci + di, cj + dj
                if not (lo_i <= ni <= hi_i and lo_j <= nj <= hi_j):
                    continue
                for k in range(K):
                    nb = (ni, nj, k)
                    if nb != t and adjacent(t, nb):
                        yield nb

    seen = {start: 0}
    q = deque([start])
    while q:
        cur = q.popleft()
        d = seen[cur]
        for nb in neighbors(cur):
            if nb in seen:
                continue
            if nb == target:
                return d + 1
            seen[nb] = d + 1
            q.append(nb)
    return -1

