def count_event_ways(n: int, x: int, y: int) -> int:
    MOD = 10**9 + 7

    # Precompute binomial coefficients C(a, b) for 0 <= a <= max(n, x)
    m = max(n, x)
    C = [[0] * (m + 1) for _ in range(m + 1)]
    for a in range(m + 1):
        C[a][0] = 1
        for b in range(1, a + 1):
            C[a][b] = (C[a - 1][b - 1] + C[a - 1][b]) % MOD

    def surj(nn: int, k: int) -> int:
        # Number of surjections from nn labeled items onto k labeled bins
        total = 0
        for j in range(k + 1):
            term = C[k][j] * pow(k - j, nn, MOD) % MOD
            if j % 2 == 0:
                total = (total + term) % MOD
            else:
                total = (total - term) % MOD
        return total

    result = 0
    for k in range(1, min(n, x) + 1):
        ways = C[x][k] * surj(n, k) % MOD * pow(y, k, MOD) % MOD
        result = (result + ways) % MOD
    return result

