def sum_concatenated_permutations(n: int) -> int:
    # Precompute factorials and inverse factorials up to n
    fact = [1] * (n + 1)
    for i in range(1, n + 1):
        fact[i] = fact[i - 1] * i % MOD
    inv_fact = [1] * (n + 1)
    inv_fact[n] = pow(fact[n], MOD - 2, MOD)
    for i in range(n, 0, -1):
        inv_fact[i - 1] = inv_fact[i] * i % MOD

    def C(a, b):
        if b < 0 or b > a:
            return 0
        return fact[a] * inv_fact[b] % MOD * inv_fact[a - b] % MOD

    # Group 1..n by digit length: counts[d], sums[d]
    classes = []  # (d, count, sum of values, 10^d mod MOD)
    lo, d = 1, 1
    while lo <= n:
        hi = min(n, 10 ** d - 1)
        cnt = hi - lo + 1
        s = (lo + hi) * cnt // 2 % MOD
        classes.append((d, cnt, s, pow(10, d, MOD)))
        lo = 10 ** d
        d += 1

    def weight_for(removed):
        # Polynomial over subset size k: coefficient = sum over subsets of
        # the other n-1 elements of size k of 10^{digits(subset)}
        poly = [1]
        for idx, (dd, cnt, s, w) in enumerate(classes):
            c = cnt - (1 if idx == removed else 0)
            if c <= 0:
                continue
            term = [C(c, j) * pow(w, j, MOD) % MOD for j in range(c + 1)]
            new = [0] * (len(poly) + c)
            for i, a in enumerate(poly):
                if a == 0:
                    continue
                for j, b in enumerate(term):
                    new[i + j] = (new[i + j] + a * b) % MOD
            poly = new
        total = 0
        for k, coef in enumerate(poly):
            if k <= n - 1:
                total = (total + coef * fact[k] % MOD * fact[n - 1 - k]) % MOD
        return total

    answer = 0
    for idx, (dd, cnt, s, w) in enumerate(classes):
        answer = (answer + s * weight_for(idx)) % MOD
    return answer

