def sum_concatenated_permutations(n: int) -> int:
    fact = [1] * (n + 1)
    for i in range(1, n + 1):
        fact[i] = fact[i - 1] * i % MOD

    # Group 1..n by digit length d: count c_d, sum s_d, weight w_d = 10^d
    classes = []
    lo, d = 1, 1
    while lo <= n:
        hi = min(n, 10 ** d - 1)
        c = hi - lo + 1
        s = (lo + hi) * c // 2 % MOD
        classes.append((c, s, pow(10, d, MOD)))
        lo = 10 ** d
        d += 1

    def subset_weight(removed):
        # poly = prod over classes of (1 + w t)^(count, minus one if this is the removed class)
        poly = [1]
        for idx, (c, _, w) in enumerate(classes):
            cc = c - (1 if idx == removed else 0)
            if cc <= 0:
                continue
            # coefficients of (1 + w t)^cc
            term = [1] * (cc + 1)
            for j in range(1, cc + 1):
                term[j] = term[j - 1] * (cc - j + 1) % MOD * pow(j, MOD - 2, MOD) % MOD * w % MOD
            new = [0] * (len(poly) + cc)
            for i, a in enumerate(poly):
                if a:
                    for j, b in enumerate(term):
                        new[i + j] = (new[i + j] + a * b) % MOD
            poly = new
        total = 0
        for k, coef in enumerate(poly):
            if k <= n - 1:
                total = (total + coef * fact[k] % MOD * fact[n - 1 - k]) % MOD
        return total

    answer = 0
    for idx, (c, s, w) in enumerate(classes):
        answer = (answer + s * subset_weight(idx)) % MOD
    return answer

