import math

_M_LIMIT = 10**6
_candidates = None

def _build():
    global _candidates
    if _candidates is not None:
        return
    n = _M_LIMIT
    # smallest prime factor sieve
    spf = list(range(n + 1))
    for i in range(2, math.isqrt(n) + 1):
        if spf[i] == i:
            for j in range(i * i, n + 1, i):
                if spf[j] == j:
                    spf[j] = i
    # m is a candidate iff m = p^a * q^b with p != q, and
    # m^2 = p^(2a) * q^(2b) is a 400 number. Every m >= 2 with
    # exactly two distinct prime factors yields a valid 400 number
    # (squared), so we only need m with exactly two distinct primes.
    cands = []
    for m in range(2, n + 1):
        x = m
        primes = []
        while x > 1:
            p = spf[x]
            primes.append(p)
            while x % p == 0:
                x //= p
            if len(primes) > 2:
                break
        if len(primes) == 2:
            cands.append(m)
    _candidates = cands

def find_largest_400_number(a: int) -> int:
    _build()
    m = math.isqrt(a)
    lo, hi = 0, len(_candidates) - 1
    best = None
    while lo <= hi:
        mid = (lo + hi) // 2
        if _candidates[mid] <= m:
            best = _candidates[mid]
            lo = mid + 1
        else:
            hi = mid - 1
    return best * best

