def min_changes_for_semi_palindromes(s: str, k: int) -> int:
    n = len(s)
    INF = float("inf")

    # cost[i][j]: minimum changes to make s[i:j+1] a semi-palindrome
    cost = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(i + 1, n):
            L = j - i + 1
            best = INF
            for d in range(1, L):
                if L % d != 0:
                    continue
                changes = 0
                for r in range(d):
                    group = s[i + r : j + 1 : d]
                    a, b = 0, len(group) - 1
                    while a < b:
                        if group[a] != group[b]:
                            changes += 1
                        a += 1
                        b -= 1
                best = min(best, changes)
            cost[i][j] = best

    # dp[p][e]: min changes to split s[0:e] into p parts
    dp = [[INF] * (n + 1) for _ in range(k + 1)]
    dp[0][0] = 0
    for p in range(1, k + 1):
        for e in range(p, n + 1):
            for st in range(p - 1, e):
                if dp[p - 1][st] == INF:
                    continue
                if st == e - 1:
                    # single character: not a valid semi-palindrome, cannot be used
                    continue
                c = dp[p - 1][st] + cost[st][e - 1]
                if c < dp[p][e]:
                    dp[p][e] = c
    return dp[k][n]

