def semi_palindrome_cost(t):
    L = len(t)
    best = float("inf")
    for d in range(1, L):
        if L % d:
            continue
        c = 0
        for r in range(d):
            g = t[r::d]
            for a in range(len(g) // 2):
                if g[a] != g[len(g) - 1 - a]:
                    c += 1
        best = min(best, c)
    return best if L >= 2 else float("inf")

def min_cost_split(s, k):
    n = len(s)
    INF = float("inf")
    dp = [[INF] * (n + 1) for _ in range(k + 1)]
    dp[0][0] = 0
    for p in range(1, k + 1):
        for e in range(1, n + 1):
            for st in range(e):
                if dp[p-1][st] < INF:
                    dp[p][e] = min(dp[p][e], dp[p-1][st] + semi_palindrome_cost(s[st:e]))
    return dp[k][n]

