def count_stepping_numbers(low: str, high: str) -> int:
    MOD = 10**9 + 7

    def count_upto(s: str) -> int:
        # Count stepping numbers in [1, int(s)]
        n = len(s)
        from functools import lru_cache

        @lru_cache(maxsize=None)
        def dp(pos, prev, tight, started):
            # pos: current index, prev: previous digit (or -1 if none)
            # tight: whether prefix equals s's prefix, started: whether a nonzero digit was placed
            if pos == n:
                return 1 if started else 0
            limit = int(s[pos]) if tight else 9
            total = 0
            for d in range(0, limit + 1):
                nt = tight and (d == limit)
                if not started:
                    if d == 0:
                        total += dp(pos + 1, -1, nt, False)
                    else:
                        total += dp(pos + 1, d, nt, True)
                else:
                    if abs(d - prev) == 1:
                        total += dp(pos + 1, d, nt, True)
            return total % MOD

        return dp(0, -1, True, False)

    # count(high) - count(low) + (1 if low itself is stepping)
    def is_stepping(s: str) -> bool:
        return all(abs(int(s[i]) - int(s[i + 1])) == 1 for i in range(len(s) - 1))

    result = count_upto(high) - count_upto(low) + (1 if is_stepping(low) else 0)
    return result % MOD

