def min_sensor_cost(n: int, sections: List[int], sensor1: Tuple[int, int, int], sensor2: Tuple[int, int, int]) -> int:
    L1, C1, K1 = sensor1
    L2, C2, K2 = sensor2
    INF = float('inf')

    # dp[a][b] = min cost using a type-1 sensors and b type-2 sensors so far
    dp = [[INF] * (K2 + 1) for _ in range(K1 + 1)]
    dp[0][0] = 0

    for d in sections:
        new_dp = [[INF] * (K2 + 1) for _ in range(K1 + 1)]
        # enumerate sensor counts for this section
        for x in range(0, K1 + 1):
            # minimal y2 needed for this x
            covered = x * L1
            y_needed = max(0, -(-(d - covered) // L2)) if d > covered else 0
            for y in range(y_needed, K2 + 1):
                if d <= covered + y * L2 and y_needed == 0 and y > 0 and d <= covered:
                    # avoid useless extra sensors beyond need
                    continue
                cost = x * C1 + y * C2
                for a in range(K1 + 1 - x):
                    row = dp[a]
                    nrow = new_dp[a + x]
                    for b in range(K2 + 1 - y):
                        if row[b] + cost < nrow[b + y]:
                            nrow[b + y] = row[b] + cost
        dp = new_dp

    best = min(min(row) for row in dp)
    return -1 if best == INF else int(best)

