def min_sensor_cost(n: int, sections: List[int], sensor1: Tuple[int, int, int], sensor2: Tuple[int, int, int]) -> int:
    # Best-guess model: K1 and K2 are global caps on total sensors used.
    # For each section, choose x type-1 and y type-2 sensors with x*L1 + y*L2 >= d.
    # Track (type-1 used, type-2 used) across sections and minimize cost.
    L1, C1, K1 = sensor1
    L2, C2, K2 = sensor2
    INF = float('inf')

    dp = [[INF] * (K2 + 1) for _ in range(K1 + 1)]
    dp[0][0] = 0

    for d in sections:
        new_dp = [[INF] * (K2 + 1) for _ in range(K1 + 1)]
        options = []
        for x in range(K1 + 1):
            covered = x * L1
            if covered >= d:
                options.append((x, 0, x * C1))
                continue
            need = d - covered
            y = -(-need // L2)
            if y <= K2:
                options.append((x, y, x * C1 + y * C2))
        for a in range(K1 + 1):
            for b in range(K2 + 1):
                if dp[a][b] == INF:
                    continue
                for x, y, cost in options:
                    na, nb = a + x, b + y
                    if na <= K1 and nb <= K2:
                        val = dp[a][b] + cost
                        if val < new_dp[na][nb]:
                            new_dp[na][nb] = val
        dp = new_dp

    best = min(min(row) for row in dp)
    return -1 if best == INF else int(best)

