def count_good_strings(n: int, k: int, s: str) -> int:
    """ Count ways to replace '?' with 'A' or 'B' so that no substring of length k
    is a palindrome. Return the count modulo 998244353.
    """
    def is_pal_mask(m):
        bits = [(m >> i) & 1 for i in range(k)]
        return bits == bits[::-1]

    pal = [is_pal_mask(m) for m in range(1 << k)]
    full = k - 1
    dp = {(0, 0): 1}

    for i in range(n):
        c = s[i]
        if c == 'A':
            choices = [0]
        elif c == 'B':
            choices = [1]
        else:
            choices = [0, 1]

        ndp = {}
        for (mask, length), cnt in dp.items():
            for b in choices:
                if length + 1 >= k:
                    window = ((mask << 1) | b) & ((1 << k) - 1)
                    if pal[window]:
                        continue
                    new_mask = window & ((1 << full) - 1) if full > 0 else 0
                    new_len = full
                else:
                    new_mask = (mask << 1) | b
                    new_len = length + 1
                key = (new_mask, new_len)
                ndp[key] = (ndp.get(key, 0) + cnt) % MOD
        dp = ndp

    return sum(dp.values()) % MOD

