def count_valid_permutations(n: int, requirements: List[List[int]]) -> int:
    MAXK = 400
    req = {}
    for end, cnt in requirements:
        req[end] = cnt

    dp = [0] * (MAXK + 1)
    dp[0] = 1
    if 0 in req:
        target = req[0]
        dp = [dp[k] if k == target else 0 for k in range(MAXK + 1)]

    for i in range(1, n):
        prefix = [0] * (MAXK + 2)
        for k in range(MAXK + 1):
            prefix[k + 1] = (prefix[k] + dp[k]) % MOD
        new = [0] * (MAXK + 1)
        for k in range(MAXK + 1):
            lo = max(0, k - i)
            new[k] = (prefix[k + 1] - prefix[lo]) % MOD
        dp = new
        if i in req:
            target = req[i]
            dp = [dp[k] if k == target else 0 for k in range(MAXK + 1)]

    return sum(dp) % MOD

