def count_paths(N: int, M: int, K: int, extra_edges: list) -> int:
    extra = {}
    for x, y in extra_edges:
        extra.setdefault(x, []).append(y)

    specials = sorted(set([1] + list(extra.keys())))
    sidx = {v: i for i, v in enumerate(specials)}
    S = len(specials)
    spec_set = set(specials)

    def to_next_special(w):
        steps = 0
        v = w
        while v not in spec_set:
            v = v % N + 1
            steps += 1
        return v, steps

    trans = [[] for _ in range(S)]
    for u in specials:
        i = sidx[u]
        tgt, d = to_next_special(u % N + 1)
        trans[i].append((sidx[tgt], 1 + d))
        for v in extra.get(u, []):
            tgt2, d2 = to_next_special(v)
            trans[i].append((sidx[tgt2], 1 + d2))

    f = [[0] * (K + 1) for _ in range(S)]
    f[sidx[1]][0] = 1
    diff = [0] * (K + 2)

    for t in range(K + 1):
        for i in range(S):
            w = f[i][t]
            if w == 0:
                continue
            for (j, L) in trans[i]:
                nt = t + L
                if nt <= K:
                    f[j][nt] = (f[j][nt] + w) % MOD
                lo = t + 1
                hi = min(t + L - 1, K)
                if lo <= hi:
                    diff[lo] = (diff[lo] + w) % MOD
                    diff[hi + 1] = (diff[hi + 1] - w) % MOD

    total = 0
    for i in range(S):
        total = (total + f[i][K]) % MOD

    run = 0
    for t in range(1, K + 1):
        run = (run + diff[t]) % MOD
        if t == K:
            total = (total + run) % MOD

    return total % MOD

