def max_score(grid: List[List[int]]) -> int:
    states = {0: 0}
    best = 0
    for row in grid:
        new_states = dict(states)
        for mask, total in states.items():
            for v in set(row):
                bit = 1 << v
                if mask & bit:
                    continue
                nmask = mask | bit
                nsum = total + v
                if new_states.get(nmask, -1) < nsum:
                    new_states[nmask] = nsum
                if nsum > best:
                    best = nsum
        states = new_states
    return best

