def min_ng_list_size(n: int, product_names: List[str]) -> int:
    parent = {}

    def find(x):
        parent.setdefault(x, x)
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[ra] = rb

    out_deg = {}
    in_deg = {}
    for name in product_names:
        u, v = name[0], name[1]
        out_deg[u] = out_deg.get(u, 0) + 1
        in_deg[v] = in_deg.get(v, 0) + 1
        union(u, v)

    comp_surplus = {}
    comp_has_edge = set()
    vertices = set(out_deg) | set(in_deg)
    for v in vertices:
        root = find(v)
        comp_has_edge.add(root)
        diff = out_deg.get(v, 0) - in_deg.get(v, 0)
        if diff > 0:
            comp_surplus[root] = comp_surplus.get(root, 0) + diff

