def min_ng_list_size(n: int, product_names: List[str]) -> int:
    edges = list(set(product_names))
    m = len(edges)

    # Each edge must be covered by at least one string (a simple path
    # in the letter graph, where a letter may be reused across strings).
    # Greedy-free exact search: try increasing k and check whether the
    # edges can be covered by k walks.
    adj = {}
    for e in edges:
        adj.setdefault(e[0], []).append(e[1])

    def walks_from(start_letter, covered_mask):
        # enumerate maximal walks from start_letter as edge-index masks
        results = []
        idx = {e: i for i, e in enumerate(edges)}

        def dfs(cur, mask, depth):
            extended = False
            for nxt in adj.get(cur, []):
                e = cur + nxt
                i = idx[e]
                extended = True
                dfs(nxt, mask | (1 << i), depth + 1)
            if not extended or depth == 0:
                results.append(mask)

        dfs(start_letter, 0, 0)
        return results

    full = (1 << m) - 1
    # Build all candidate walks as edge masks (each walk starts at an edge).
    idx = {e: i for i, e in enumerate(edges)}
    candidates = set()

    def extend(cur, mask, visited_edges):
        if mask:
            candidates.add(mask)
        for nxt in adj.get(cur, []):
            e = cur + nxt
            if e in visited_edges:
                continue
            extend(nxt, mask | (1 << idx[e]), visited_edges | {e})

    for start in adj:
        extend(start, 0, frozenset())

    candidates = list(candidates)

    best = [m]

    def search(remaining, count):
        if remaining == 0:
            best[0] = min(best[0], count)
            return
        if count + 1 >= best[0]:
            return
        # pick lowest uncovered edge
        low = remaining & -remaining
        for c in candidates:
            if c & low:
                search(remaining & ~c, count + 1)

    search(full, 0)
    return best[0]

