def min_ng_list_size(n: int, product_names: List[str]) -> int:
    edges = sorted(set(product_names))
    m = len(edges)
    if m == 0:
        return 0
    idx = {e: i for i, e in enumerate(edges)}
    adj = {}
    for e in edges:
        adj.setdefault(e[0], []).append(e[1])

    # Enumerate every walk (as a set of covered edge indices) starting at any
    # letter, allowing edge reuse, up to a length bound that covers all edges.
    walk_masks = set()

    def dfs(cur, mask, length):
        if mask:
            walk_masks.add(mask)
        if length >= 2 * m:
            return
        for nxt in adj.get(cur, []):
            dfs(nxt, mask | (1 << idx[cur + nxt]), length + 1)

    for start in adj:
        dfs(start, 0, 0)

    full = (1 << m) - 1
    masks = sorted(walk_masks, key=lambda x: -bin(x).count("1"))

    # Iterative deepening over number of walks k.
    def can_cover(remaining, k):
        if remaining == 0:
            return True
        if k == 0:
            return False
        low = remaining & -remaining
        for mk in masks:
            if mk & low and can_cover(remaining & ~mk, k - 1):
                return True
        return False

    k = 1
    while not can_cover(full, k):
        k += 1
    return k

