def min_ng_list_size(n: int, product_names: List[str]) -> int:
    parent = {}

    def find(x):
        parent.setdefault(x, x)
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[ra] = rb

    out_deg = {}
    in_deg = {}
    for name in set(product_names):
        u, v = name[0], name[1]
        out_deg[u] = out_deg.get(u, 0) + 1
        in_deg[v] = in_deg.get(v, 0) + 1
        union(u, v)

    surplus = {}
    roots = set()
    for v in set(out_deg) | set(in_deg):
        r = find(v)
        roots.add(r)
        d = out_deg.get(v, 0) - in_deg.get(v, 0)
        if d > 0:
            surplus[r] = surplus.get(r, 0) + d

    return sum(max(1, surplus.get(r, 0)) for r in roots)

