def min_team_switches(people: List[Tuple[int, int]]) -> int:
    total = sum(s for _, s in people)
    if total % 3 != 0:
        return -1
    target = total // 3

    # dp maps (sum_team1, sum_team2) -> minimum number of switches so far
    # sum_team3 is implied by the number of processed strengths.
    dp = {(0, 0): 0}
    processed = 0
    processed_sum = 0
    for team, strength in people:
        processed += 1
        processed_sum += strength
        new_dp = {}
        for (s1, s2), cost in dp.items():
            s3 = processed_sum - strength - s1 - s2
            # assign this person to team 1, 2, or 3
            for new_team in (1, 2, 3):
                n1, n2, n3 = s1, s2, s3
                if new_team == 1:
                    n1 += strength
                elif new_team == 2:
                    n2 += strength
                else:
                    n3 += strength
                if n1 > target or n2 > target or n3 > target:
                    continue
                new_cost = cost + (0 if new_team == team else 1)
                key = (n1, n2)
                if key not in new_dp or new_cost < new_dp[key]:
                    new_dp[key] = new_cost
        dp = new_dp

    if (target, target) in dp:
        return dp[(target, target)]
    return -1

