def count_valid_grids(H: int, W: int, grid: list[str]) -> int:
    MOD = 998244353

    # Make the profile width the smaller dimension so the state space stays small.
    if W > H:
        # transpose
        g = [[grid[i][j] for i in range(H)] for j in range(W)]
        R, C = W, H
    else:
        g = [list(row) for row in grid]
        R, C = H, W

    # dp: profile tuple of length C holding colors of the most recent C cells
    # in row-major order (position j holds the cell above column j, or the
    # already-processed cell in the current row for columns < current).
    # Initially, use 0 as "no cell" marker.
    dp = {tuple([0] * C): 1}

    for i in range(R):
        for j in range(C):
            ch = g[i][j]
            options = [1, 2, 3] if ch == '?' else [int(ch)]
            ndp = {}
            for prof, cnt in dp.items():
                up = prof[j]          # cell directly above (0 if none)
                left = prof[j - 1] if j > 0 else 0  # already updated cell to the left
                for c in options:
                    if c == up or c == left:
                        continue
                    newprof = list(prof)
                    newprof[j] = c
                    key = tuple(newprof)
                    ndp[key] = (ndp.get(key, 0) + cnt) % MOD
            dp = ndp
            if not dp:
                return 0

    return sum(dp.values()) % MOD

