def minimize_path_weights(n: int, edges: List[Tuple[int, int, int]], a: List[int], b: List[int]) -> int:
    # Build minimax distance matrix via Kruskal MST processing edges by weight.
    parent = list(range(n + 1))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    # comp_members: for each component root, the list of vertices in it
    members = {i: [i] for i in range(1, n + 1)}
    f = [[0] * (n + 1) for _ in range(n + 1)]

    for u, v, w in sorted(edges, key=lambda e: e[2]):
        ru, rv = find(u), find(v)
        if ru == rv:
            continue
        # every pair spanning the two components has minimax distance w
        for x in members[ru]:
            for y in members[rv]:
                f[x][y] = f[y][x] = w
        parent[ru] = rv
        members[rv].extend(members.pop(ru))

    # Minimum cost assignment (Hungarian algorithm) over matrix cost[i][j] = f[a[i]][b[j]]
    m = len(a)
    INF = float("inf")
    cost = [[f[a[i]][b[j]] for j in range(m)] for i in range(m)]
    u_pot = [0] * (m + 1)
    v_pot = [0] * (m + 1)
    p = [0] * (m + 1)
    way = [0] * (m + 1)
    for i in range(1, m + 1):
        p[0] = i
        j0 = 0
        minv = [INF] * (m + 1)
        used = [False] * (m + 1)
        while True:
            used[j0] = True
            i0 = p[j0]
            delta = INF
            j1 = 0
            for j in range(1, m + 1):
                if not used[j]:
                    cur = cost[i0 - 1][j - 1] - u_pot[i0] - v_pot[j]
                    if cur < minv[j]:
                        minv[j] = cur
