def min_deletions_to_snowflake(n: int, edges: List[Tuple[int, int]]) -> int:
    adj = [[] for _ in range(n + 1)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)
    deg = [len(a) for a in adj]

    def leafcnt(u: int, p: int) -> int:
        cnt = 0
        for w in adj[u]:
            if w != p and deg[w] == 1:
                cnt += 1
        return cnt

    best = 0
    for c in range(1, n + 1):
        kept = 1
        for u in adj[c]:
            lc = leafcnt(u, c)
            if lc >= 1:
                kept += 1 + lc
        if kept > best:
            best = kept
    return n - best

def lev(s, t):
