    for i in range(1, len(s) + 1):
        cur = [i] + [0] * len(t)
        for j in range(1, len(t) + 1):
            cur[j] = min(prev[j-1] + (s[i-1] != t[j-1]), prev[j] + 1, cur[j-1] + 1)
        prev = cur
