def count_ball_sets(n: int, positions: List[Tuple[int, int]]) -> int:
    MOD = 998244353
    start = frozenset(range(n))
    seen = {start}
    stack = [start]
    while stack:
        cur = stack.pop()
        for k in cur:
            xk, yk = positions[k]
            nxt = frozenset(
                i for i in cur
                if i == k
                or not ((positions[i][0] < xk and positions[i][1] < yk)
                        or (positions[i][0] > xk and positions[i][1] > yk))
            )
            if nxt not in seen:
                seen.add(nxt)
                stack.append(nxt)
    return len(seen) % MOD

