def fixed_count_set(n: int) -> set:
    """Return the set of achievable fixed-element counts for n x n binary matrices.
    Brute force: exponential in n^2, practical for n <= 4."""
    cells = n * n
    classes = {}
    for bits in product((0, 1), repeat=cells):
        rows = tuple(sum(bits[i * n:(i + 1) * n]) for i in range(n))
        cols = tuple(sum(bits[j::n]) for j in range(n))
        classes.setdefault((rows, cols), []).append(bits)

    achievable = set()
    for members in classes.values():
        fixed = 0
        for pos in range(cells):
            vals = {m[pos] for m in members}
            if len(vals) == 1:
                fixed += 1
        achievable.add(fixed)
    return achievable

