_KNOWN = {}

def matrix_with_k_fixed_elements_exists(n: int, k: int) -> bool:
    """Return True iff some n x n binary matrix has exactly k fixed elements.

    Computed exactly by enumeration for n <= 3 (512 matrices). For larger n
    this function does not yet have a verified rule, so it returns None
    rather than guessing."""
    if not (0 <= k <= n * n):
        return False
    if n not in _KNOWN:
        if n <= 3:
            _KNOWN[n] = _fixed_count_set_bruteforce(n)
        else:
            return None
    return k in _KNOWN[n]

