MOD = 998244353

def count_sequences_without_subsequence(N: int, M: int, K: int, X: list[int]) -> int:
    def contains(seq, pat):
        it = iter(seq)
        return all(c in it for c in pat)

    X = tuple(X)
    all_patterns = [p for p in product(range(1, K + 1), repeat=M) if p != X]
    count = 0
    for S in product(range(1, K + 1), repeat=N):
        if contains(S, X):
            continue
        if all(contains(S, p) for p in all_patterns):
            count += 1
    return count % MOD

