def count_good_string_replacements(n: int, k: int, s: str) -> int:
    def is_good(t: str) -> bool:
        # Reducibility check via memoized search on the string contents.
        @lru_cache(maxsize=None)
        def reduce_ok(x: str) -> bool:
            if x == "":
                return True
            L = len(x)
            # Operation 1: remove two identical characters
            for i in range(L):
                for j in range(i + 1, L):
                    if x[i] == x[j]:
                        if reduce_ok(x[:i] + x[i+1:j] + x[j+1:]):
                            return True
            # Operation 2: remove one A, one B, one C
