            ones += 1

    total = 0
    for c in range(1, L + 1):
        # x with popcount c reduces to c in 1 step, then ops[c] more steps
        if c == 1:
            # x is a power of two; x = 1 needs 0 ops, others need 1 + ops[1] = 1
            if k >= 1:
