def count_balanced_graphs(n: int, p: int) -> list[int]:
    max_m = n * (n - 1) // 2
    half = n // 2
    result = [0] * (max_m + 1)

    # Vertex 1 is fixed at distance 0. Choose the other vertices' distance labels
    # so that exactly half of all vertices are at even distance and half at odd.
    # We enumerate distance assignments as layer sizes, then count graphs
    # per assignment via inclusion-exclusion on edges allowed between layers.
    others = list(range(2, n + 1))

    def layer_partitions(vertices, sizes):
        if not sizes:
            if not vertices:
                yield []
            return
        for chosen in combinations(vertices, sizes[0]):
            rest = [v for v in vertices if v not in chosen]
            for tail in layer_partitions(rest, sizes[1:]):
                yield [list(chosen)] + tail

    def compositions(total, parts):
        # positive integer sequences of length parts summing to total
        if parts == 0:
            if total == 0:
                yield []
            return
        for first in range(1, total - parts + 2):
            for rest in compositions(total - first, parts - 1):
                yield [first] + rest

    seen = set()
    for k in range(1, n):  # number of layers beyond layer 0
        for sizes_rest in compositions(n - 1, k):
            sizes = [1] + sizes_rest
            even = sum(sizes[d] for d in range(0, len(sizes), 2))
            odd = n - even
            if even != odd:
                continue
            key = tuple(sizes)
            if key in seen:
                continue
            seen.add(key)
            # Count graphs with this layering: edges only between same or adjacent
            # layers, every layer>=1 vertex has a parent in previous layer, connected.
            # Edge-polynomial via brute force over candidate edge sets (small n only).
            cand = []
            layer_of = {1: 0}
            idx = 2
            for d in range(1, len(sizes)):
                for _ in range(sizes[d]):
                    layer_of[idx] = d
                    idx += 1
            verts = list(range(1, n + 1))
            for a, b in combinations(verts, 2):
                if abs(layer_of[a] - layer_of[b]) <= 1:
                    cand.append((a, b))
            # Brute-force count by edge count, checking BFS distances match layering.
            for mask in range(1 << len(cand)):
                edges = [cand[i] for i in range(len(cand)) if mask >> i & 1]
                m = len(edges)
                if m > max_m:
                    continue
                adj = {v: [] for v in verts}
                for a, b in edges:
                    adj[a].append(b)
                    adj[b].append(a)
                dist = {1: 0}
                q = [1]
                for u in q:
                    for w in adj[u]:
                        if w not in dist:
                            dist[w] = dist[u] + 1
                            q.append(w)
                if len(dist) != n:
                    continue
                if any(dist[v] != layer_of[v] for v in verts):
                    continue
                result[m] = (result[m] + 1) % p

    return result[n - 1:]

