def count_balanced_graphs(n: int, p: int) -> list[int]:
    verts = list(range(1, n + 1))
    all_pairs = list(combinations(verts, 2))
    max_m = n * (n - 1) // 2
    counts = [0] * (max_m + 1)

    for mask in range(1 << len(all_pairs)):
        edges = [all_pairs[i] for i in range(len(all_pairs)) if mask >> i & 1]
        m = len(edges)
        adj = {v: [] for v in verts}
        for a, b in edges:
            adj[a].append(b)
            adj[b].append(a)

        dist = {1: 0}
        q = deque([1])
        while q:
            u = q.popleft()
            for w in adj[u]:
                if w not in dist:
                    dist[w] = dist[u] + 1
                    q.append(w)

