def count_strings_by_lcs_length(n: int, m: int, s: str) -> List[int]:
    MOD = 998244353

    # State: bitmask over positions 1..n of s. Bit j-1 set means
    # dp[j] - dp[j-1] == 1, where dp[j] = LCS(s[:j], t_prefix).
    # dp[0] is always 0. Initial state (empty t): all zeros.
    # Transition on character c: standard LCS row update.
    # New row computed from old row: for the bit-vector representation,
    # we recompute the row values explicitly from the mask.

    def row_from_mask(mask):
        row = [0] * (n + 1)
        for j in range(1, n + 1):
            row[j] = row[j - 1] + ((mask >> (j - 1)) & 1)
        return row

    def mask_from_row(row):
        mask = 0
        for j in range(1, n + 1):
            if row[j] - row[j - 1]:
                mask |= 1 << (j - 1)
        return mask

    def step(mask, c):
        old = row_from_mask(mask)
        new = [0] * (n + 1)
        for j in range(1, n + 1):
            if s[j - 1] == c:
                new[j] = old[j - 1] + 1
            else:
                new[j] = max(old[j], new[j - 1])
        return mask_from_row(new)

    # Precompute transitions per character index (only 26 letters).
    letters = [chr(ord('a') + i) for i in range(26)]
    num_states = 1 << n
    trans = [[0] * 26 for _ in range(num_states)]
    for mask in range(num_states):
        for ci, c in enumerate(letters):
            trans[mask][ci] = step(mask, c)

    # DP over m steps: count[mask] = number of prefixes ending in mask.
    cnt = [0] * num_states
    cnt[0] = 1
    for _ in range(m):
        nxt = [0] * num_states
        for mask in range(num_states):
            v = cnt[mask]
            if v:
                row = trans[mask]
                for ci in range(26):
                    nm = row[ci]
                    nxt[nm] = (nxt[nm] + v) % MOD
        cnt = nxt

    # Final LCS length equals dp[n] = popcount(mask).
    result = [0] * (n + 1)
    for mask in range(num_states):
        k = bin(mask).count('1')
        result[k] = (result[k] + cnt[mask]) % MOD
    return result

