def count_strings_by_lcs_length(n: int, m: int, s: str) -> List[int]:
    MOD = 998244353

    # The LCS DP row over s, after processing a prefix t, is
    #   row[j] = LCS(s[:j], t),  j = 0..n.
    # It is non-decreasing with increments in {0, 1}, so it is fully
    # encoded by mask bit (j-1) = row[j] - row[j-1].
    # Transition on char c (standard LCS update, computed exactly):
    #   new[0] = 0
    #   new[j] = old[j-1] + 1           if s[j-1] == c
    #          = max(old[j], new[j-1])  otherwise

    def decode(mask):
        row = [0] * (n + 1)
        for j in range(1, n + 1):
            row[j] = row[j - 1] + ((mask >> (j - 1)) & 1)
        return row

    def encode(row):
        mask = 0
        for j in range(1, n + 1):
            if row[j] != row[j - 1]:
                mask |= 1 << (j - 1)
        return mask

    def step(mask, c):
        old = decode(mask)
        new = [0] * (n + 1)
        for j in range(1, n + 1):
            if s[j - 1] == c:
                new[j] = old[j - 1] + 1
            else:
                new[j] = max(old[j], new[j - 1])
        return encode(new)

    letters = 'abcdefghijklmnopqrstuvwxyz'
    num_states = 1 << n

    # Precompute transitions as (next_mask, multiplicity) per state,
    # aggregating the 26 letters so each state is processed once per step.
    trans = []
    for mask in range(num_states):
        counts = {}
        for c in letters:
            nm = step(mask, c)
            counts[nm] = counts.get(nm, 0) + 1
        trans.append(list(counts.items()))

    cnt = [0] * num_states
    cnt[0] = 1
    for _ in range(m):
        nxt = [0] * num_states
        for mask in range(num_states):
            v = cnt[mask]
            if v:
                for nm, mult in trans[mask]:
                    nxt[nm] = (nxt[nm] + v * mult) % MOD
        cnt = nxt

    result = [0] * (n + 1)
    for mask in range(num_states):
        k = bin(mask).count('1')
        result[k] = (result[k] + cnt[mask]) % MOD
    return result

