        row = states[i]
        counts = {}
        for c in letters:
            nr = advance(row, c)
            if nr not in index:
                index[nr] = len(states)
                states.append(nr)
            t = index[nr]
            counts[t] = counts.get(t, 0) + 1
        trans.append(list(counts.items()))
        i += 1

    num = len(states)
    cnt = [0] * num
    cnt[0] = 1
    for _ in range(m):
        nxt = [0] * num
        for idx in range(num):
            v = cnt[idx]
            if v:
                for t, mult in trans[idx]:
                    nxt[t] = (nxt[t] + v * mult) % MOD
        cnt = nxt

    result = [0] * (n + 1)
    for idx in range(num):
        k = states[idx][n]
        result[k] = (result[k] + cnt[idx]) % MOD
    return result

