def max_alkane_vertices(n: int, edges: List[Tuple[int, int]]) -> int:
    """ Given an undirected tree with n vertices (numbered 1 to n) and edges connecting them,
    find the maximum number of vertices in a subgraph that forms an alkane.

    An alkane is defined as:
    - An undirected tree
    - Every vertex has degree 1 or 4
    - There is at least one vertex of degree 4

    If no such subgraph exists, return -1.
    """
    if n < 5:
        return -1

    adj = defaultdict(list)
    for a, b in edges:
        adj[a].append(b)
        adj[b].append(a)

    cand = {v for v in range(1, n + 1) if len(adj[v]) >= 4}
    if not cand:
        return -1

    visited = set()
    best_core = 0

    for start in cand:
        if start in visited:
            continue
        # Collect the component of candidate vertices and a DFS order with parents.
        parent = {start: 0}
        order = []
        stack = [start]
        visited.add(start)
        while stack:
            u = stack.pop()
            order.append(u)
            for w in adj[u]:
                if w in cand and w not in visited:
                    visited.add(w)
                    parent[w] = u
                    stack.append(w)

        # dp[v] = largest connected core rooted at v within v's subtree,
        # where v keeps at most 4 core neighbors in total (parent slot included).
        dp = {}
        for v in reversed(order):
            children = [w for w in adj[v] if w in cand and parent.get(w) == v]
            child_vals = sorted((dp[w] for w in children), reverse=True)
            slots = 4 - (1 if parent[v] != 0 else 0)
            total = 1
            for g in child_vals[:slots]:
                total += g
            dp[v] = total

        # Each component root is a valid connected core; take the best one.
        for v in order:
            if parent[v] == 0:
                best_core = max(best_core, dp[v])

    if best_core == 0:
        return -1
    return 3 * best_core + 2

