def max_shortest_distance(n: int, m: int, k: int, edges: List[Tuple[int, int]]) -> int:
    best = 0
    for chosen in combinations(range(m), k):
        chosen_set = set(chosen)
        # 0-1 BFS: weight 1 for chosen edge indices, 0 otherwise
        adj = [[] for _ in range(n + 1)]
        for idx, (u, v) in enumerate(edges):
            adj[u].append((v, 1 if idx in chosen_set else 0))
        INF = float("inf")
        dist = [INF] * (n + 1)
        dist[1] = 0
        from collections import deque
        dq = deque([1])
        while dq:
            x = dq.popleft()
            for y, w in adj[x]:
                if dist[x] + w < dist[y]:
                    dist[y] = dist[x] + w
                    if w == 0:
                        dq.appendleft(y)
                    else:
                        dq.append(y)
        if dist[n] != INF:
            best = max(best, dist[n])
    return best

