def sum_of_subarray_powers(n: int, k: int, a: List[int]) -> int:
    MOD = 998244353
    # Prefix sums of the input, kept as exact integers and reduced modulo MOD.
    prefix = [0] * (n + 1)
    for i in range(n):
        prefix[i + 1] = prefix[i] + a[i]

    total = 0
    # Each subarray [l, r) has sum prefix[r] - prefix[l] with l < r.
    for l in range(n):
        for r in range(l + 1, n + 1):
            total = (total + pow(prefix[r] - prefix[l], k, MOD)) % MOD
    return total

