MOD = 998244353

def _prime_factors(x: int) -> dict:
    f = {}
    d = 2
    while d * d <= x:
        while x % d == 0:
            f[d] = f.get(d, 0) + 1
            x //= d
        d += 1
    if x > 1:
        f[x] = f.get(x, 0) + 1
    return f

def sum_good_sequence_scores(n: int, a: list[int]) -> int:
    # Collect all primes involved.
    primes = set()
    for v in a:
        primes.update(_prime_factors(v).keys())
    primes = sorted(primes)

    # Each element S[j] is a product over primes of p^e_j. For each prime p,
    # the edge i splits a[i]'s exponent of p to one side (all of it) or the other.
    # Track, per position, whether the prime's exponent there is "left-side" or
