def rev_flip(t):
    return ''.join(')' if c == '(' else '(' for c in reversed(t))

def reachable(s):
    seen = {s}
    q = deque([s])
    while q:
        cur = q.popleft()
        n = len(cur)
        for k in range(n):
            if cur[k] != '(':
                continue
            bal = 0
            for j in range(k, n):
                bal += 1 if cur[j] == '(' else -1
                if bal < 0:
                    break
                if bal == 0:
                    new = cur[:k] + rev_flip(cur[k:j + 1]) + cur[j + 1:]
                    if new not in seen:
                        seen.add(new)
                        q.append(new)
    return seen

