from typing import List


def kth_alternating_permutation(n: int, k: int) -> List[int]:
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def count(odd: int, even: int, last: int) -> int:
        if odd == 0 and even == 0:
            return 1
        total = 0
        if odd > 0 and last != 1:
            total += odd * count(odd - 1, even, 1)
        if even > 0 and last != 0:
            total += even * count(odd, even - 1, 0)
        return total

    odd_vals = [x for x in range(1, n + 1) if x % 2 == 1]
    even_vals = [x for x in range(1, n + 1) if x % 2 == 0]

    if count(len(odd_vals), len(even_vals), 2) < k:
        return []

    result: List[int] = []
    last = 2
    rank = k

    for _ in range(n):
        for v in sorted(odd_vals + even_vals):
            p = 1 if v % 2 == 1 else 0
            if last != 2 and p == last:
                continue
            o = len(odd_vals) - (1 if p == 1 else 0)
            e = len(even_vals) - (1 if p == 0 else 0)
            ways = count(o, e, p)
            if rank <= ways:
                result.append(v)
                (odd_vals if p == 1 else even_vals).remove(v)
                last = p
                break
            rank -= ways

    return result

