from itertools import product

def brute(n, r, c):
    letters = "ABC"
    cells = [(i, j) for i in range(n) for j in range(n)]
    sols = []
    for vals in product(letters + '.', repeat=n * n):
        g = [list(vals[i*n:(i+1)*n]) for i in range(n)]
        ok = True
        for i in range(n):
            row = g[i]
            if sorted(x for x in row if x != '.') != sorted(letters):
                ok = False; break
            first = next(x for x in row if x != '.')
            if first != r[i]:
                ok = False; break
        if not ok:
            continue
        for j in range(n):
            col = [g[i][j] for i in range(n)]
            if sorted(x for x in col if x != '.') != sorted(letters):
                ok = False; break
            first = next(x for x in col if x != '.')
            if first != c[j]:
                ok = False; break
        if ok:
            sols.append([''.join(row) for row in g])
    return sols

