from itertools import permutations

def first_solutions(n, r, c, limit=3):
    letters = "ABC"
    # each row: positions of A, B, C in distinct columns
    rows = []
    for i in range(n):
        opts = []
        for pos in permutations(range(n), 3):
            g = ['.'] * n
            for ch, p in zip(letters, pos):
                g[p] = ch
            first = next(x for x in g if x != '.')
            if first == r[i]:
                opts.append(g)
        rows.append(opts)
    found = []
    def go(i, grid):
        if len(found) >= limit:
            return
        if i == n:
            for j in range(n):
                col = [grid[x][j] for x in range(n) if grid[x][j] != '.']
                if sorted(col) != sorted(letters):
                    return
                if next(grid[x][j] for x in range(n) if grid[x][j] != '.') != c[j]:
                    return
            found.append([''.join(row) for row in grid])
            return
        for g in rows[i]:
            go(i + 1, grid + [g])
    go(0, [])
    return found

print(first_solutions(4, 'ABCC', 'BCCA'))

