def solve_grid(n: int, r: str, c: str) -> Optional[List[str]]:
    """ Given an integer N and strings R and C of length N consisting of 'A', 'B', and 'C',
    determine if it's possible to fill an N×N grid such that:
    - Each row and column contains exactly one 'A', one 'B', and one 'C'
    - The leftmost character written in the i-th row matches the i-th character of R
    - The topmost character written in the i-th column matches the i-th character of C

    Empty cells are represented by '.' in the output.

    Args:
        n: The size of the grid (3 <= n <= 5)
        r: String of length n specifying leftmost characters in each row
        c: String of length n specifying topmost characters in each column

    Returns:
        A list of n strings representing the filled grid if possible, None otherwise.
        Each string has length n, where '.' represents empty cells.

    >>> solve_grid(3, 'ABC', 'ABC')
    ['ABC', 'BCA', 'CAB']
    >>> solve_grid(3, 'AAA', 'BBB')
    None
    """
    letters = "ABC"
    grid = [['.'] * n for _ in range(n)]

    def row_letters(i):
        return [x for x in grid[i] if x != '.']

    def col_letters(j):
        return [grid[x][j] for x in range(n) if grid[x][j] != '.']

    def prefix_ok(seq, target):
        # the first filled entry, if any, must equal target
        return len(seq) == 0 or seq[0] == target

    def valid_partial(i, j):
        rl = row_letters(i)
        cl = col_letters(j)
        if len(rl) > 3 or len(cl) > 3:
            return False
        if len(set(rl)) != len(rl) or len(set(cl)) != len(cl):
            return False
        # first filled cell of row i must be r[i]
        first_r = next((grid[i][k] for k in range(n) if grid[i][k] != '.'), None)
        if first_r is not None and first_r != r[i]:
            return False
        first_c = next((grid[k][j] for k in range(n) if grid[k][j] != '.'), None)
        if first_c is not None and first_c != c[j]:
            return False
        return True

    def final_ok():
        for i in range(n):
            if sorted(row_letters(i)) != sorted(letters):
                return False
        for j in range(n):
            if sorted(col_letters(j)) != sorted(letters):
                return False
        return True

    cells = [(i, j) for i in range(n) for j in range(n)]

    def backtrack(idx):
        if idx == len(cells):
            return final_ok()
        i, j = cells[idx]
        for ch in ['.'] + list(letters):
            grid[i][j] = ch
            if valid_partial(i, j) and backtrack(idx + 1):
                return True
        grid[i][j] = '.'
        return False

    if backtrack(0):
        return [''.join(row) for row in grid]
    return None

