from itertools import product

_CACHE = None


def _build_table():
    S = 7
    CUBE = S ** 3

    def ov1(d):
        return max(0, S - abs(d))

    rng = range(-(S - 1), S)
    table = {}
    for p2 in product(rng, repeat=3):
        o12 = ov1(p2[0]) * ov1(p2[1]) * ov1(p2[2])
        for p3 in product(rng, repeat=3):
            o13 = ov1(p3[0]) * ov1(p3[1]) * ov1(p3[2])
            d23 = (p3[0] - p2[0], p3[1] - p2[1], p3[2] - p2[2])
            o23 = ov1(d23[0]) * ov1(d23[1]) * ov1(d23[2])
            t = 1
            for i in range(3):
                lo = max(0, p2[i], p3[i])
                hi = min(S, p2[i] + S, p3[i] + S)
                t *= max(0, hi - lo)
            e3 = t
            e2 = o12 + o13 + o23 - 3 * t
            e1 = 3 * CUBE - 2 * (o12 + o13 + o23) + 3 * t
            key = (e1, e2, e3)
            if key not in table:
                table[key] = (0, 0, 0, p2[0], p2[1], p2[2], p3[0], p3[1], p3[2])
    return table


def find_cube_placement(V1: int, V2: int, V3: int) -> Optional[Tuple[int, int, int, int, int, int, int, int, int]]:
    """ Find three side-7 cubes whose exactly-one, exactly-two, and exactly-three
    region volumes are V1, V2, V3. Returns None if no placement exists.
    """
    global _CACHE
    if _CACHE is None:
        _CACHE = _build_table()
    return _CACHE.get((V1, V2, V3))

