def find_cube_placement(V1: int, V2: int, V3: int) -> Optional[Tuple[int, int, int, int, int, int, int, int, int]]:
    """ Find three side-7 cubes C(a,b,c) so that the volume covered by exactly one cube is V1,
    exactly two cubes is V2, and all three cubes is V3. Coordinates are bounded by 100 in
    absolute value. Returns None if no placement exists.
    """
    S = 7
    CUBE = S ** 3

    if V1 < 0 or V2 < 0 or V3 < 0 or V3 > CUBE:
        return None

    # Per-axis overlap of two intervals [0,S] and [p,p+S]
    def ov(d):
        return max(0, S - abs(d))

    # Per-axis triple overlap of [0,S], [p,p+S], [q,q+S]
    def tri(p, q):
        lo = max(0, p, q)
        hi = min(S, p + S, q + S)
        return max(0, hi - lo)

    rng = range(-(S - 1), S)

    # Iterate cube 2 offsets first; ov12 is cheap to precompute per offset
    for x2 in rng:
        for y2 in rng:
            for z2 in rng:
                o12 = ov(x2) * ov(y2) * ov(z2)
                for x3 in rng:
                    for y3 in rng:
                        # Precompute axis factors that don't depend on z3
                        ox13 = ov(x3)
                        oy13 = ov(y3)
                        tx = tri(x2, x3)
                        ty = tri(y2, y3)
                        dx23 = ov(x3 - x2)
                        dy23 = ov(y3 - y2)
                        for z3 in rng:
                            o13 = ox13 * oy13 * ov(z3)
                            o23 = dx23 * dy23 * ov(z3 - z2)
                            t = tx * ty * tri(z2, z3)
                            if t != V3:
                                continue
                            e2 = o12 + o13 + o23 - 3 * t
                            if e2 != V2:
                                continue
                            e1 = 3 * CUBE - 2 * (o12 + o13 + o23) + 3 * t
                            if e1 != V1:
                                continue
                            return (0, 0, 0, x2, y2, z2, x3, y3, z3)
    return None

