                for x3 in rng:
                    for y3 in rng:
                        tx = tri(x2, x3)
                        ty = tri(y2, y3)
                        dx23 = ov(x3 - x2)
                        dy23 = ov(y3 - y2)
                        ox13 = ov(x3)
                        oy13 = ov(y3)
                        for z3 in rng:
                            t = tx * ty * tri(z2, z3)
                            if t != V3:
                                continue
                            o13 = ox13 * oy13 * ov(z3)
                            o23 = dx23 * dy23 * ov(z3 - z2)
                            e2 = o12 + o13 + o23 - 3 * t
                            if e2 != V2:
                                continue
                            e1 = 3 * CUBE - 2 * (o12 + o13 + o23) + 3 * t
                            if e1 != V1:
                                continue
                            return (0, 0, 0, x2, y2, z2, x3, y3, z3)
    return None

