def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """ Determine if it's possible to place rectangular tiles on an H×W grid such that:
    - Every cell is covered by exactly one tile
    - Tiles can be rotated (so a 2×3 tile can be placed as 3×2)
    - Some tiles may remain unused
    - Tiles must be aligned with grid cells and cannot extend outside

    Args:
        n: Number of available tiles (1 ≤ n ≤ 7)
        h: Height of the grid (1 ≤ h ≤ 10)
        w: Width of the grid (1 ≤ w ≤ 10)
        tiles: List of (a, b) tuples where tile i has dimensions a×b (1 ≤ a, b ≤ 10)

    Returns:
        True if the grid can be perfectly tiled, False otherwise

    >>> can_tile_grid(5, 5, 5, [(1, 1), (3, 3), (4, 4), (2, 3), (2, 5)])
    True
    >>> can_tile_grid(1, 1, 2, [(2, 3)])
    False
    >>> can_tile_grid(1, 2, 2, [(1, 1)])
    False
    """
    total_area = sum(a * b for a, b in tiles[:n])
    if total_area < h * w:
        return False

    grid = [[False] * w for _ in range(h)]
    used = [False] * n

    def find_first_empty():
        for r in range(h):
            for c in range(w):
                if not grid[r][c]:
                    return r, c
        return None

    def can_place(r: int, c: int, ph: int, pw: int) -> bool:
        if r + ph > h or c + pw > w:
            return False
        for i in range(r, r + ph):
            for j in range(c, c + pw):
                if grid[i][j]:
                    return False
        return True

    def set_region(r: int, c: int, ph: int, pw: int, value: bool):
        for i in range(r, r + ph):
            for j in range(c, c + pw):
                grid[i][j] = value

    def backtrack() -> bool:
        pos = find_first_empty()
        if pos is None:
            return True
        r, c = pos
        tried = set()
        for idx in range(n):
            if used[idx]:
                continue
            a, b = tiles[idx]
            key = (min(a, b), max(a, b))
            if key in tried:
                continue
            tried.add(key)
            for ph, pw in {(a, b), (b, a)}:
                if can_place(r, c, ph, pw):
                    set_region(r, c, ph, pw, True)
                    used[idx] = True
                    if backtrack():
                        return True
                    used[idx] = False
                    set_region(r, c, ph, pw, False)
        return False

    return backtrack()

