import itertools

def brute(N, K):
    dist = {tuple([1] + [0]*(N-1)): Fraction(1)}  # not used directly
    # position of black ball as distribution over 1..N
    pos = [Fraction(0)]*N
    pos[0] = Fraction(1)
    pairs = [(a, b) for a in range(N) for b in range(N)]
    for _ in range(K):
        new = [Fraction(0)]*N
        for i in range(N):
            if pos[i] == 0:
                continue
            for a, b in pairs:
                j = i
                if a != b:
                    if i == a: j = b
                    elif i == b: j = a
                new[j] += pos[i] / (N*N)
        pos = new
    return sum((i+1)*pos[i] for i in range(N))

def brute_count(n):
    s = set()
    a = 2
    while a * a <= n:
        p = a * a
        while p <= n:
            s.add(p)
            p *= a
        a += 1
    return len(s) + (1 if n >= 1 else 0)

