from math import isqrt

def count_power_representations(n: int) -> int:
    """ Count how many integers x between 1 and n (inclusive) can be expressed as x = a^b
    where a is a positive integer and b is an integer greater than or equal to 2.

    Args:
        n: The upper bound (1 <= n <= 10^18)

    Returns:
        The count of integers that can be expressed as a^b where b >= 2

    >>> count_power_representations(99)
    12
    >>> count_power_representations(1000000000000000000)
    1001003332
    """
    if n < 1:
        return 0

    def mobius(m):
        result = 1
        d = 2
        while d * d <= m:
            if m % d == 0:
                m //= d
                if m % d == 0:
                    return 0
                result = -result
            d += 1
        if m > 1:
            result = -result
        return result

    def iroot(x, k):
        # exact largest r with r**k <= x
        if k == 2:
            return isqrt(x)
        lo, hi = 1, 1 << (x.bit_length() // k + 1)
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if mid ** k <= x:
                lo = mid
            else:
                hi = mid - 1
        return lo

    total = 0
    for k in range(2, n.bit_length() + 1):
        r = iroot(n, k)
        if r < 2:
            break
        total += -mobius(k) * (r - 1)
    return total + 1

from math import isqrt

def reference(n):
    # exact set-based count, feasible for n up to ~1e12
    if n < 1:
        return 0
    s = set()
    k = 2
    while 2 ** k <= n:
        a = 2
        while a ** k <= n:
            s.add(a ** k)
            a += 1
        k += 1
    return len(s) + 1

def mobius_version(n):
    if n < 1:
        return 0
    def mu(m):
        r, d = 1, 2
        while d * d <= m:
            if m % d == 0:
                m //= d
                if m % d == 0:
                    return 0
                r = -r
            d += 1
        return -r if m > 1 else r
    def iroot(x, k):
        lo, hi = 1, 1 << (x.bit_length() // k + 1)
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if mid ** k <= x:
                lo = mid
            else:
                hi = mid - 1
        return lo
    total = 0
    for k in range(2, n.bit_length() + 1):
        r = iroot(n, k)
        if r < 2:
            break
        total += -mu(k) * (r - 1)
    return total + 1

