def find_palindrome_expression(n: int) -> str:
    from functools import lru_cache
    import sys

    sys.setrecursionlimit(10000)

    if n == 1:
        return '1'

    def is_pal(s: str) -> bool:
        return s == s[::-1]

    # Enumerate palindromic digit strings (1-9 only) whose integer value divides n.
    # Each factor string is a palindrome with no zeros.
    def pal_factors(limit_n: int):
        results = []
        # Generate palindromes of length up to 13 (since n <= 1e12)
        for length in range(1, 14):
            half = (length + 1) // 2
            # enumerate all digit combos for first half
            def gen(prefix):
                if len(prefix) == half:
                    if length % 2 == 0:
                        s = prefix + prefix[::-1]
                    else:
                        s = prefix + prefix[-2::-1]
                    v = int(s)
                    if v <= limit_n and limit_n % v == 0:
                        results.append((v, s))
                    return
                for d in '123456789':
                    gen(prefix + d)
            gen('')
        return results

    divisors_pal = pal_factors(n)
    divisors_pal.sort()

    # Search: find a multiset product of palindromic factors (as expression) equal to n,
    # with the whole joined expression being a palindrome.
    # Strategy: build factor sequences f1*f2*...*fk that are symmetric (f_i == f_{k+1-i})
    # and whose concatenation with '*' is a palindrome; or a single palindromic factor.
    if n <= 9:
        return str(n)

    # Single palindrome term equal to n
    if is_pal(str(n)) and all(c in '123456789' for c in str(n)):
        return str(n)

    pal_map = {v: s for v, s in divisors_pal}
    pal_vals = [v for v, _ in divisors_pal]

    best = None

    # Try symmetric sequences: left factors L, optional middle M, mirrored right factors.
    # Expression = L1*...*Lk [*M] *Lk*...*L1 ; its value = (prod L)^2 * M must equal n.
    def search(remaining, left_seq, depth_limit=8):
        nonlocal best
        if best is not None:
            return
        # Option: remaining itself is a palindrome middle factor
        if remaining in pal_map and left_seq is not None:
            mid = pal_map[remaining]
            expr = '*'.join(left_seq + [mid] + left_seq[::-1])
            if is_pal(expr):
                best = expr
                return
        if remaining == 1 and left_seq:
            expr = '*'.join(left_seq + left_seq[::-1])
            if is_pal(expr):
                best = expr
                return
        if len(left_seq) >= depth_limit:
            return
        for v in pal_vals:
            if v == 1:
                continue
            if remaining % (v * v) == 0:
                search(remaining // (v * v), left_seq + [pal_map[v]], depth_limit)
                if best is not None:
                    return

    # Symmetric search: n = P^2 * M, with M a palindromic factor (or 1)
    search(n, [], 8)
    if best is not None:
        return best

    # Simple direct form: product of palindromic factors whose join is palindrome
    def direct(remaining, seq):
        nonlocal best
        if best is not None:
            return
        if remaining == 1:
            expr = '*'.join(seq)
            if seq and is_pal(expr):
                best = expr
            return
        if len(seq) > 6:
            return
        for v in pal_vals:
            if v > 1 and remaining % v == 0:
                direct(remaining // v, seq + [pal_map[v]])
                if best is not None:
                    return

    direct(n, [])
    if best is not None:
        return best

    return '-1'

def find_palindrome_expression(n: int) -> str:
    from functools import lru_cache

    if n == 1:
        return '1'

    def is_pal(s: str) -> bool:
        return s == s[::-1]

    def all_divisors(m: int):
        divs = []
        i = 1
        while i * i <= m:
            if m % i == 0:
                divs.append(i)
                if i != m // i:
                    divs.append(m // i)
            i += 1
        return sorted(divs)

    # Palindromic factors: divisors of n whose decimal form is a palindrome of digits 1-9
    pal_factors = []
    for d in all_divisors(n):
