def sum_of_scores(n: int, m: int) -> int:
    primes = [2, 3, 5, 7, 11, 13]
    # exponent contribution of each value 1..m to each prime
    def factor(v):
        e = []
        for p in primes:
            c = 0
            while v % p == 0:
                v //= p
                c += 1
            e.append(c)
        return tuple(e)
    vecs = [factor(v) for v in range(1, m + 1)]

    # dp maps exponent-vector -> number of sequences of current length with that product
    # total answer accumulates sum over lengths k=1..n of sum over sequences of prod(e+1)
    from collections import defaultdict

    cur = defaultdict(int)
    for e in vecs:
        cur[e] += 1
    ans = 0
    length = 1
    while length <= n:
        for e, cnt in cur.items():
            score = 1
            for x in e:
                score = score * (x + 1) % MOD
            ans = (ans + cnt * score) % MOD
        if length == n:
            break
        nxt = defaultdict(int)
        for e, cnt in cur.items():
            for v in vecs:
                ne = tuple(a + b for a, b in zip(e, v))
                nxt[ne] = (nxt[ne] + cnt) % MOD
        cur = nxt
        length += 1
    return ans % MOD

