def count_special_permutations(A: int, B: int, M: int) -> int:
    N = A * B - 1

    # Enumerate partitions lambda of N with lambda_1 = A and number of rows = B.
    # Under RSK, the shape must have first row A and first column B, i.e. a hook
    # of size A + B - 1 with the remaining N - (A + B - 1) boxes fitting inside
    # the (B-1) x (A-1) rectangle below/right of the hook.
    rest = N - (A + B - 1)
    if rest < 0:
        return 0

    def partitions_in_box(n, max_part, max_rows):
        # partitions of n with at most max_rows parts, each part <= max_part
        if n == 0:
            yield ()
            return
        if max_rows == 0 or max_part == 0:
            return
        for first in range(min(n, max_part), 0, -1):
            for tail in partitions_in_box(n - first, first, max_rows - 1):
                yield (first,) + tail

    # The shape is (A, mu) where mu is a partition of N - A fitting in B-1 rows
    # with parts <= A, and column 1 height must equal B, so mu has exactly B-1 rows
    # each >= 1 and the total below the first row sums to N - A.
    def shapes():
        for mu in partitions_in_box(N - A, A, B - 1):
            if len(mu) == B - 1 and all(p >= 1 for p in mu):
                yield (A,) + mu

    def hook_length_count(shape):
        # number of SYT of given shape via hook length formula, as exact integer
        n = sum(shape)
        conj = [sum(1 for r in shape if r > j) for j in range(shape[0])]
        prod = 1
        for i, r in enumerate(shape):
            for j in range(r):
                prod *= (r - j - 1) + (conj[j] - i - 1) + 1
        from math import factorial
        return factorial(n) // prod

    total = 0
    for lam in shapes():
        f = hook_length_count(lam)
        total = (total + f * f) % M
    return total % M

