def lis(seq):
    from bisect import bisect_left
    t = []
    for x in seq:
        i = bisect_left(t, x)
        if i == len(t): t.append(x)
        else: t[i] = x
    return len(t)

def lds(seq):
    return lis([-x for x in seq])

def brute(A, B):
    N = A * B - 1
    cnt = 0
    for P in permutations(range(1, N + 1)):
        if lis(P) != A or lds(P) != B:
            continue
        ok = False
        for n in range(0, N + 1):
            Q = list(P) + [n + 0.5]
            if lis(Q) == A and lds(Q) == B:
                ok = True
                break
        cnt += ok
    return cnt

