def _tile_rect(K, i, j, k):
    # Returns (x0, x1, y0, y1) for the tile (i, j, k).
    if (i - j) % 2 == 0:
        # same parity: iK <= x <= (i+1)K, jK+k <= y <= jK+k+1
        return (i * K, (i + 1) * K, j * K + k, j * K + k + 1)
    else:
        # different parity: iK+k <= x <= iK+k+1, jK <= y <= (j+1)K
        return (i * K + k, i * K + k + 1, j * K, (j + 1) * K)

def _tile_containing(K, px, py):
