def count_good_integers(num1: str, num2: str, min_sum: int, max_sum: int) -> int:
    MOD = 10**9 + 7

    def count_at_most(s: str) -> int:
        # Count x in [0, int(s)] with min_sum <= digit_sum(x) <= max_sum
        n = len(s)
        # ways[k][t] = number of digit strings of length k with digit sum t
        max_total = 9 * n
        ways = [[0] * (max_total + 1) for _ in range(n + 1)]
        ways[0][0] = 1
        for k in range(1, n + 1):
            for t in range(max_total + 1):
                total = 0
                for d in range(10):
                    if t - d >= 0:
                        total += ways[k - 1][t - d]
                ways[k][t] = total

        result = 0
        prefix_sum = 0
        for i in range(n):
            cur = int(s[i])
            remaining = n - i - 1
            for d in range(cur):
                s_total = prefix_sum + d
                for t in range(max_total + 1):
                    if ways[remaining][t] == 0:
                        continue
                    full = s_total + t
                    if min_sum <= full <= max_sum:
                        result += ways[remaining][t]
            prefix_sum += cur

        # Include s itself
        if min_sum <= prefix_sum <= max_sum:
            result += 1
        return result % MOD

    # count in [num1, num2] = count(<= num2) - count(<= num1 - 1)
    # Instead of subtracting 1 from a string, check num1 directly:
    upper = count_at_most(num2)
    lower = count_at_most(num1)
    # count_at_most(num1) includes num1 itself, so subtract it only if it's good
    digit_sum_num1 = sum(int(c) for c in num1)
    if min_sum <= digit_sum_num1 <= max_sum:
        lower_excl = (lower - 1) % MOD
    else:
        lower_excl = lower
    return (upper - lower_excl) % MOD

