def min_changes_for_semi_palindromes(s: str, k: int) -> int:
    n = len(s)

    # cost[i][j]: min changes to make s[i:j+1] a semi-palindrome
    def semi_cost(sub: str) -> int:
        m = len(sub)
        if m < 2:
            return float("inf")
        best = float("inf")
        for d in range(1, m):
            if m % d != 0:
                continue
            changes = 0
            for r in range(d):
                group = sub[r::d]
                i, j = 0, len(group) - 1
                while i < j:
                    if group[i] != group[j]:
                        changes += 1
                    i += 1
                    j -= 1
            best = min(best, changes)
        return best

    cost = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(i + 1, n):
            cost[i][j] = semi_cost(s[i:j + 1])

    INF = float("inf")
    # dp[p][e]: min cost to split s[:e] into p pieces
    dp = [[INF] * (n + 1) for _ in range(k + 1)]
    dp[0][0] = 0
    for p in range(1, k + 1):
        for e in range(p, n + 1):
            for start in range(p - 1, e):
                if dp[p - 1][start] == INF:
                    continue
                c = 0 if start == e - 1 else cost[start][e - 1]
                if c == INF:
                    continue
                val = dp[p - 1][start] + c
                if val < dp[p][e]:
                    dp[p][e] = val
    return int(dp[k][n])

