def greedy(s, k):
    n, parts, i = len(s), 0, 0
    while i < n:
        seen, j = set(), i
        while j < n:
            if s[j] not in seen:
                if len(seen) == k:
                    break
                seen.add(s[j])
            j += 1
        parts += 1
        i = j
    return parts

