def count_arithmetic_subsequences(n: int, a: List[int]) -> List[int]:
    MOD = 998244353
    ans = [0] * (n + 1)
    ans[1] = n % MOD
    # dp[i][d][k]: number of index subsequences of length k ending at index i
    # whose common difference is d (k >= 2).
    dp = [dict() for _ in range(n)]
    for i in range(n):
        for j in range(i):
            d = a[i] - a[j]
            # Start a new subsequence (j, i) of length 2.
            if d not in dp[i]:
                dp[i][d] = [0] * (n + 1)
            dp[i][d][2] = (dp[i][d][2] + 1) % MOD
            # Extend every subsequence ending at j with difference d.
            if d in dp[j]:
                src = dp[j][d]
                tgt = dp[i][d]
                for k in range(2, n):
                    if src[k]:
                        tgt[k + 1] = (tgt[k + 1] + src[k]) % MOD
        for d, arr in dp[i].items():
            for k in range(2, n + 1):
                ans[k] = (ans[k] + arr[k]) % MOD
    return ans[1:]

