def count_valid_permutations(n: int, requirements: List[List[int]]) -> int:
    MOD = 10**9 + 7
    MAXC = 400

    req = [-1] * n
    for end, cnt in requirements:
        req[end] = cnt

    dp = [0] * (MAXC + 1)
    dp[0] = 1

    for i in range(n):
        prefix = [0] * (MAXC + 2)
        for s in range(MAXC + 1):
            prefix[s + 1] = (prefix[s] + dp[s]) % MOD

        new_dp = [0] * (MAXC + 1)
        for s in range(MAXC + 1):
            lo = max(0, s - i)
            new_dp[s] = (prefix[s + 1] - prefix[lo]) % MOD

        if req[i] != -1:
            target = req[i]
            if target > MAXC:
                return 0
            for s in range(MAXC + 1):
                if s != target:
                    new_dp[s] = 0

        dp = new_dp

    return sum(dp) % MOD

