def count_paths(N: int, M: int, K: int, extra_edges: list) -> int:
    MOD = 998244353

    # Frame trick: p = (v - t) mod N. A cycle move keeps p fixed, so only
    # extra edges move mass between frame positions. Work is O(K * M).
    dp = {1 % N: 1}

    for t in range(K):
        new = dict(dp)
        for x, y in extra_edges:
            p = (x - t) % N
            c = dp.get(p, 0)
            if c:
                q = (y - (t + 1)) % N
                new[q] = (new.get(q, 0) + c) % MOD
        dp = new

    return sum(dp.values()) % MOD

