def max_score(grid: List[List[int]]) -> int:
    """ Given a 2D matrix of positive integers, select one or more cells such that:
    - No two selected cells are in the same row
    - The values in the selected cells are unique

    Return the maximum sum of values you can achieve.

    Args:
        grid: A 2D list where 1 <= len(grid), len(grid[i]) <= 10 and 1 <= grid[i][j] <= 100

    >>> max_score([[1,2,3],[4,3,2],[1,1,1]])
    8
    >>> max_score([[8,7,6],[8,3,2]])
    15
    """
    # Map each distinct value to a bit position.
    all_values = sorted({v for row in grid for v in row})
    index = {v: i for i, v in enumerate(all_values)}

    # best[mask] = max sum using a set of distinct values exactly equal to mask,
    # considering rows processed so far (each row contributes at most one value).
    best = {0: 0}
    for row in grid:
        options = {index[v]: v for v in set(row)}
        new_best = dict(best)  # skip this row
        for mask, score in best.items():
            for bit, v in options.items():
                b = 1 << bit
                if mask & b:
                    continue
                nm = mask | b
                ns = score + v
                if new_best.get(nm, -1) < ns:
                    new_best[nm] = ns
        best = new_best

    return max(best.values())

