def minimum_shipping_dissatisfaction(n: int, k: int, x: int, order_days: List[int]) -> int:
    from functools import lru_cache

    INF = float("inf")

    @lru_cache(maxsize=None)
    def solve(i: int, prev_day: int) -> int:
        # prev_day == -1 means no previous shipment yet
        if i == n:
            return 0
        best = INF
        for size in range(1, k + 1):
            end = i + size
            if end > n:
                break
            ship = order_days[end - 1]
            if prev_day != -1:
                ship = max(ship, prev_day + x)
            cost = sum(ship - order_days[t] for t in range(i, end))
            rest = solve(end, ship)
            if rest < best - cost:
                best = cost + rest
        return best

    return solve(0, -1)

