def min_ng_list_size(n: int, product_names: List[str]) -> int:
    """
    Minimum number of strings covering all product names, modeled as a
    minimum path cover over the edges: answer = n - maximum matching, where
    edge XY may be matched to edge YZ (XY can be followed by YZ in a string).
    NOT verified against all asserts.
    """
    edges = list(product_names)
    # successors[i] = indices j such that edges[i][1] == edges[j][0]
    successors = [[] for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if i != j and edges[i][1] == edges[j][0]:
                successors[i].append(j)

    match_right = [-1] * n  # match_right[j] = i means i -> j is in the matching

    def try_augment(i, seen):
        for j in successors[i]:
            if not seen[j]:
                seen[j] = True
                if match_right[j] == -1 or try_augment(match_right[j], seen):
                    match_right[j] = i
                    return True
        return False

    matching = 0
    for i in range(n):
        seen = [False] * n
        if try_augment(i, seen):
            matching += 1

    return n - matching

