def max_production_capacity(n: int, x: int, machines: List[Tuple[int, int, int, int]]) -> int:
    """Given N processes and a budget X, find the maximum achievable production capacity.

    For each process i, machine type S gives A_i products/day at P_i yen per unit,
    and machine type T gives B_i products/day at Q_i yen per unit.
    Any number of each machine type may be bought. The capacity is the minimum
    products/day across all processes.
    """
    def cost_for_process(c: int, a: int, p: int, b: int, q: int) -> int:
        best = None
        max_s = (c + a - 1) // a
        for k in range(max_s + 1):
            remaining = c - k * a
            t = 0 if remaining <= 0 else (remaining + b - 1) // b
            cost = k * p + t * q
            if best is None or cost < best:
                best = cost
        return best

    def feasible(c: int) -> bool:
        total = 0
        for a, p, b, q in machines:
            total += cost_for_process(c, a, p, b, q)
            if total > x:
                return False
        return total <= x

    lo, hi = 0, 2 * 10**9
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if feasible(mid):
            lo = mid
        else:
            hi = mid - 1
    return lo

