def count_paths(H: int, W: int, K: int, grid: list[str]) -> int:
    """Count directed simple paths of K+1 empty cells (K moves) on the grid."""
    # Count paths by DFS from every empty cell, tracking visited cells with a bitmask.
    # Each path is a sequence of distinct empty cells where consecutive cells are adjacent.
    total = 0
    dirs = ((1, 0), (-1, 0), (0, 1), (0, -1))

    def idx(r, c):
        return r * W + c

    def dfs(r, c, mask, moves_left):
        if moves_left == 0:
            return 1
        count = 0
        for dr, dc in dirs:
            nr, nc = r + dr, c + dc
            if 0 <= nr < H and 0 <= nc < W and grid[nr][nc] == '.':
                bit = 1 << idx(nr, nc)
                if not mask & bit:
                    count += dfs(nr, nc, mask | bit, moves_left - 1)
        return count

    for r in range(H):
        for c in range(W):
            if grid[r][c] == '.':
                total += dfs(r, c, 1 << idx(r, c), K)
    return total

