MOD = 998244353

def count_valid_grids(H: int, W: int, grid: list[str]) -> int:
    """ Given a grid with H rows and W columns consisting of '1', '2', '3', and '?',
    count how many ways we can replace each '?' with '1', '2', or '3' such that
    any two adjacent (edge-sharing) cells contain different digits.

    Return the count modulo 998244353.

    >>> count_valid_grids(2, 2, ['1?', '??'])
    6
    >>> count_valid_grids(2, 3, ['123', '3?1'])
    0
    >>> count_valid_grids(1, 1, ['?'])
    3
    """
    # Make the profile width the smaller dimension.
    if W > H:
        g = [''.join(grid[i][j] for i in range(H)) for j in range(W)]
        H, W = W, H
        grid = g

    # Fixed digits that are already adjacent to an equal fixed digit: no valid fill.
    for i in range(H):
        for j in range(W):
            if grid[i][j] != '?':
                if j + 1 < W and grid[i][j + 1] == grid[i][j]:
                    return 0
                if i + 1 < H and grid[i + 1][j] == grid[i][j]:
                    return 0

    # frontier[j] = color (0,1,2) of most recent cell in column j, or -1 if none yet.
    dp = {tuple([-1] * W): 1}

    for i in range(H):
        for j in range(W):
            ch = grid[i][j]
            if ch == '?':
                options = (0, 1, 2)
            else:
                options = (int(ch) - 1,)
            new_dp = {}
            for state, ways in dp.items():
                up = state[j]
                left = state[j - 1] if j > 0 else -1
                for c in options:
                    if c == up or c == left:
                        continue
                    lst = list(state)
                    lst[j] = c
                    key = tuple(lst)
                    new_dp[key] = (new_dp.get(key, 0) + ways) % MOD
            dp = new_dp
            if not dp:
                return 0

    return sum(dp.values()) % MOD

