def count_polish_sequences(n: int, a: list[int]) -> int:
    """ Count the number of Polish sequences of length n that are lexicographically
    not greater than the given sequence a, modulo 998244353.
    """
    # Brute-force enumeration built from the definition:
    # a Polish sequence of length m starts with V1; it is then followed by
    # V1 Polish sequences whose total length is m - 1.
    # The sequence (0) is Polish of length 1.
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def polish_list(length):
        # all Polish sequences of exactly this length, as tuples
        if length == 0:
            return [()]
        result = []
        for v in range(0, length):
            # need v Polish blocks covering length - 1 elements
            for combo in split_into_blocks(length - 1, v):
                result.append((v,) + combo)
        return result

    @lru_cache(maxsize=None)
    def split_into_blocks(total, k):
        # all ways to write `total` elements as an ordered concatenation of k Polish sequences
        if k == 0:
            return [()] if total == 0 else []
        out = []
        for first_len in range(1, total + 1):
            for first in polish_list(first_len):
                for rest in split_into_blocks(total - first_len, k - 1):
                    out.append(first + rest)
        return out

    target = tuple(a)
    count = 0
    for seq in polish_list(n):
        if seq <= target:
            count += 1
    return count % MOD

