        C[i][0] = 1
        for j in range(1, i + 1):
            C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % MOD

    # ops[c] = number of operations to reduce an integer with popcount c to 1,
    # computed as: a value v >= 2 maps to popcount(v); v = 1 needs 0 operations.
