            for c in range(L + 1):
                need = c - ones
                if 0 <= need <= rem:
                    cnt[c] = (cnt[c] + C[rem][need]) % MOD
            ones += 1

    # For a positive x:
    #   x = 1 needs 0 operations.
    #   x >= 2 needs 1 + ops_from_value(popcount(x)) operations.
    total = 0
    # x = 1 (only if n > 1, i.e. s != "1"): always reducible for k >= 0
