from typing import List, Tuple


def can_reach_end(n: int, m: int, a: int, b: int, bad_intervals: List[Tuple[int, int]]) -> bool:
    if n == 1:
        return True

    bad = sorted(bad_intervals)

    def is_bad(x: int) -> bool:
        lo, hi = 0, len(bad) - 1
        idx = -1
        while lo <= hi:
            mid = (lo + hi) // 2
            if bad[mid][0] <= x:
                idx = mid
                lo = mid + 1
            else:
                hi = mid - 1
        return idx != -1 and bad[idx][1] >= x

    # reachable_window holds reachable squares within the last b positions.
    # A square x is reachable iff it is good and some reachable y satisfies
    # a <= x - y <= b.
    reachable = {1}
    for x in range(2, n + 1):
        # Drop squares too far back to jump to x.
        reachable = {y for y in reachable if x - y <= b}
        if not any(x - y >= a for y in reachable):
            continue
        if is_bad(x):
            continue
        reachable.add(x)
        if x == n:
            return True
    return n in reachable

