from collections import defaultdict
from math import comb


def count_balanced_graphs(n: int, p: int) -> list[int]:
    # Counts connected labeled graphs on vertices 1..n, classified by BFS layers
    # from vertex 1, with total edges M, such that the number of vertices at even
    # distance equals the number at odd distance (both n/2).
    maxM = n * (n - 1) // 2

    def poly_mul(a, b):
        r = [0] * (len(a) + len(b) - 1)
        for i, x in enumerate(a):
            if x == 0:
                continue
            for j, y in enumerate(b):
                if y:
                    r[i + j] += x * y
        return r

    def poly_add(a, b):
        m = max(len(a), len(b))
        r = [0] * m
        for i, x in enumerate(a):
            r[i] += x
        for i, x in enumerate(b):
            r[i] += x
        return r

    # Polynomial for one new vertex choosing a nonempty parent set in a layer of size `last`
    def parent_poly(last):
        r = [0] * (last + 1)
        for k in range(1, last + 1):
            r[k] = comb(last, k)
        return r

    # Free edges inside a layer of size s: (1+x)^{C(s,2)}
    def inner_poly(s):
        m = s * (s - 1) // 2
        return [comb(m, k) for k in range(m + 1)]

    # State: (used, even_count, last_layer_size, last_layer_is_even) -> poly in edges
    # Layer 0 is vertex 1 (even depth).
    states = defaultdict(lambda: [0])
    states[(1, 1, 1, True)] = [1]

    result = [0] * (maxM + 1)

    # Process states in order of increasing `used` (layers always add vertices).
    for used in range(1, n + 1):
        for key in [k for k in list(states.keys()) if k[0] == used]:
            poly = states.pop(key)
            _, ev, last, last_even = key
            if used == n:
                if 2 * ev == n:
                    for e, c in enumerate(poly):
                        if e <= maxM:
                            result[e] = (result[e] + c) % p
                continue
            rem = n - used
            new_even = not last_even
            for s in range(1, rem + 1):
                ways = comb(rem, s)
                attach = [1]
                base = parent_poly(last)
                for _ in range(s):
                    attach = poly_mul(attach, base)
                layer = poly_mul(attach, inner_poly(s))
                layer = [c * ways for c in layer]
                new_poly = poly_mul(poly, layer)
                nkey = (used + s, ev + (s if new_even else 0), s, new_even)
                states[nkey] = poly_add(states[nkey], new_poly)

    # Return counts for M = n-1 .. n(n-1)/2
    out = []
    for M in range(n - 1, maxM + 1):
        out.append(result[M] % p)
    return out

