def count_strings_by_lcs_length(n: int, m: int, s: str) -> List[int]:
    MOD = 998244353

    def row_from_mask(mask: int) -> List[int]:
        dp = [0] * (n + 1)
        for j in range(1, n + 1):
            dp[j] = dp[j - 1] + ((mask >> (j - 1)) & 1)
        return dp

    def mask_from_row(dp: List[int]) -> int:
        mask = 0
        for j in range(1, n + 1):
            if dp[j] - dp[j - 1]:
                mask |= 1 << (j - 1)
