def count_paths(W: int, H: int, L: int, R: int, D: int, U: int) -> int:
    def is_block(x, y):
        return 0 <= x <= W and 0 <= y <= H and (x < L or x > R or y < D or y > U)

    # f[x][y] = number of valid paths whose last point is (x, y)
    # (a path may start at any block, so each block contributes 1 for "start here")
    f = [[0] * (H + 1) for _ in range(W + 1)]
    total = 0
    for x in range(W + 1):
        for y in range(H + 1):
            if not is_block(x, y):
                continue
            val = 1  # path consisting only of (x, y)
            if x > 0 and is_block(x - 1, y):
                val += f[x - 1][y]
            if y > 0 and is_block(x, y - 1):
                val += f[x][y - 1]
            val %= MOD
            f[x][y] = val
            total = (total + val) % MOD
    return total

