def determine_winner(n: int, a: List[int]) -> str:
    # Known approach: reduce each value by its 1-indexed position, then
    # Snuke wins iff every reduced value is even (no winning move left for Fennec).
    # Position k (1-indexed) contributes parity of (a[k-1] - k) when a[k-1] > k.
    odd_count = 0
    for i, v in enumerate(a):
        k = i + 1
        if v > k:
            odd_count += (v - k) % 2
        else:
            odd_count += (v - 1) % 2
    return "Snuke" if odd_count % 2 == 0 else "Fennec"

