from functools import lru_cache


def determine_winner(n: int, a: List[int]) -> str:
    # Exact game simulation with memoization over (remaining counts, covered set).
    # Correct but exponential; intended for small inputs such as the test cases.
    @lru_cache(maxsize=None)
    def win(state, covered_mask):
        full = (1 << n) - 1
        if covered_mask == full:
            # game already over: player to move has no move, so they lose
            return False
        for i in range(n):
            if state[i] >= 1:
                new_state = list(state)
                new_state[i] -= 1
                new_mask = covered_mask | (1 << i)
                if not win(tuple(new_state), new_mask):
                    return True
        return False

    return "Fennec" if win(tuple(a), 0) else "Snuke"

