    # scaled by g; elements grow at most by factors of a[i] per step.
    LIM = 1
    for x in a:
        LIM *= max(x, 1)
    LIM = min(LIM, 10**6)

    base_starts = set()
    for p in range(1, a[0] + 1):
        if a[0] % p == 0:
            q = a[0] // p
            if gcd(p, q) == 1:
                g = 1
                while g * max(p, q) <= LIM:
                    base_starts.add(g * p)
                    g += 1

