from math import gcd

def sum_good_sequence_scores(n: int, a: list[int]) -> int:
    def successors(u, ai):
        # All v >= 1 with (u/g)*(v/g) == ai, where g = gcd(u, v).
        out = []
        for p in range(1, ai + 1):
            if ai % p:
                continue
            q = ai // p
            if gcd(p, q) != 1 or u % p:
                continue
            g = u // p
            v = g * q
            if gcd(u, v) == g:
                out.append(v)
        return out

    # DP state: (current value, gcd so far) -> (count, sum of products)
    dp = {}
    for p in range(1, a[0] + 1):
        if a[0] % p:
            continue
        q = a[0] // p
        if gcd(p, q) != 1:
            continue
        for g in range(1, 201):
            for s in (g * p, g * q):
                key = (s, s)
                c, sp = dp.get(key, (0, 0))
                dp[key] = ((c + 1) % MOD, (sp + s) % MOD)

    for i in range(1, n - 1):
        ndp = {}
        for (u, gg), (cnt, sp) in dp.items():
            for v in successors(u, a[i]):
                ng = gcd(gg, v)
                c0, s0 = ndp.get((v, ng), (0, 0))
                ndp[(v, ng)] = ((c0 + cnt) % MOD, (s0 + sp * v) % MOD)
        dp = ndp

    total = 0
    for (u, gg), (cnt, sp) in dp.items():
        if gg == 1:
            total = (total + sp) % MOD
    return total % MOD

