def count_in_degree_sequences(n: int, s: str) -> int:
    """Brute force: enumerate all orientations and collect distinct in-degree vectors."""
    edges = []
    for i in range(n):
        edges.append((i, (i + 1) % n))
    for i in range(n):
        if s[i] == '1':
            edges.append((i, n))
    seqs = set()
    for bits in product((0, 1), repeat=len(edges)):
        deg = [0] * (n + 1)
        for (u, v), b in zip(edges, bits):
            if b:
                deg[v] += 1
            else:
                deg[u] += 1
        seqs.add(tuple(deg))
    return len(seqs) % MOD

