                for j in range(i + 2, n + 1, 2):
                    sub = cur[i:j]
                    if is_valid(sub):
                        new = cur[:i] + flip_reverse(sub) + cur[j:]
                        if new not in seen:
                            seen.add(new)
                            nxt.append(new)
        frontier = nxt
    return len(seen) % MOD

