from functools import lru_cache


def kth_alternating_permutation(n: int, k: int) -> List[int]:
    """ Given two integers n and k, return the k-th alternating permutation of the first n positive integers.

    An alternating permutation is a permutation where no two adjacent elements are both odd or both even.
    The permutations are sorted in lexicographical order.

    If there are fewer than k valid alternating permutations, return an empty list.
    """
    if n < 1 or k < 1:
        return []

    # parity of value v: 1 = odd, 0 = even
    @lru_cache(maxsize=None)
    def count(remaining: frozenset, last_parity: int) -> int:
        # number of valid arrangements of `remaining` given the previous element's parity
        if not remaining:
            return 1
        total = 0
        for v in remaining:
            if last_parity == -1 or (v % 2) != last_parity:
                total += count(remaining - {v}, v % 2)
        return total

    all_vals = frozenset(range(1, n + 1))
    if count(all_vals, -1) < k:
        return []

    result = []
    remaining = all_vals
    last_parity = -1
    for _ in range(n):
        for v in sorted(remaining):
            if last_parity != -1 and (v % 2) == last_parity:
                continue
            c = count(remaining - {v}, v % 2)
            if k <= c:
                result.append(v)
                remaining = remaining - {v}
                last_parity = v % 2
                break
            k -= c
    return result

