from functools import lru_cache


def kth_alternating_permutation(n: int, k: int) -> List[int]:
    """ Given two integers n and k, return the k-th alternating permutation of the first n positive integers.

    An alternating permutation is a permutation where no two adjacent elements are both odd or both even.
    The permutations are sorted in lexicographical order.

    If there are fewer than k valid alternating permutations, return an empty list.
    """
    if n < 1 or k < 1:
        return []

    odds = [v for v in range(1, n + 1) if v % 2 == 1]
    evens = [v for v in range(1, n + 1) if v % 2 == 0]

    @lru_cache(maxsize=None)
    def count(o: int, e: int, last: int) -> int:
        if o == 0 and e == 0:
            return 1
        total = 0
        if o > 0 and last != 1:
            total += count(o - 1, e, 1)
        if e > 0 and last != 0:
            total += count(o, e - 1, 0)
        return total

    if count(len(odds), len(evens), -1) < k:
        return []

    result = []
    o_left, e_left = len(odds), len(evens)
    odd_pool = list(odds)
    even_pool = list(evens)
    last = -1

    for _ in range(n):
        candidates = []
        if last != 1 and o_left > 0:
            candidates.append((odd_pool[0], 1))
        if last != 0 and e_left > 0:
            candidates.append((even_pool[0], 0))
        candidates.sort()

        for value, parity in candidates:
            if parity == 1:
                c = count(o_left - 1, e_left, 1)
            else:
                c = count(o_left, e_left - 1, 0)
            if k <= c:
                result.append(value)
                if parity == 1:
                    odd_pool.pop(0)
                    o_left -= 1
                else:
                    even_pool.pop(0)
                    e_left -= 1
                last = parity
                break
            k -= c

    return result

