def kth_alternating_permutation(n: int, k: int) -> List[int]:
    """ Given two integers n and k, return the k-th alternating permutation of the first n positive integers.

    An alternating permutation is a permutation where no two adjacent elements are both odd or both even.
    The permutations are sorted in lexicographical order.

    If there are fewer than k valid alternating permutations, return an empty list.
    """
    if n < 1 or k < 1:
        return []
    if n <= 8:
        valid = []
        for p in permutations(range(1, n + 1)):
            if all((p[i] % 2) != (p[i + 1] % 2) for i in range(n - 1)):
                valid.append(list(p))
        # permutations() already yields lexicographic order for sorted input
        if k > len(valid):
            return []
        return valid[k - 1]
    return []

def count_powerful_integers(start: int, finish: int, limit: int, s: str) -> int:
    L = len(s)
    mult = 10 ** L
    s_val = int(s)

    # s itself must have all digits <= limit, otherwise no valid x exists
    if any(int(c) > limit for c in s):
        return 0

    def count_upto(n: int) -> int:
        # Count integers p in [0, n] whose decimal digits are all <= limit.
        if n < 0:
            return 0
        digits = str(n)
        m = len(digits)
        total = 0
        # Count p with fewer digits than n (positive, leading digit 1..limit)
        for length in range(1, m):
            total += limit * (limit + 1) ** (length - 1)
        # Count p with exactly m digits that are <= n
        valid_n = True
        for i, ch in enumerate(digits):
            d = int(ch)
            remaining = m - i - 1
            lo_choice = 1 if i == 0 else 0
            # digits c with lo_choice <= c < d and c <= limit
            upper = min(d - 1, limit)
            if upper >= lo_choice:
                total += (upper - lo_choice + 1) * (limit + 1) ** remaining
            if d > limit:
                valid_n = False
                break
        if valid_n:
            total += 1  # n itself
        # Add p = 0 (x == s), which is always valid since s's digits are <= limit
        return total + 1

    if finish < s_val:
        return 0
    hi = (finish - s_val) // mult
    lo_num = start - s_val
    lo = 0 if lo_num <= 0 else (lo_num + mult - 1) // mult
    if lo > hi:
        return 0

    # Count p in [lo, hi]
    if lo == 0:
        return count_upto(hi)
    return count_upto(hi) - count_upto(lo - 1)

def count_powerful_integers(start: int, finish: int, limit: int, s: str) -> int:
    L = len(s)
    mult = 10 ** L
    s_val = int(s)

    # Every digit of s must be <= limit
    if any(int(c) > limit for c in s):
        return 0

    if finish < s_val:
        return 0

    # Valid prefix p gives x = p * mult + s_val, with start <= x <= finish
    hi = (finish - s_val) // mult
    lo_num = start - s_val
    lo = 0 if lo_num <= 0 else (lo_num + mult - 1) // mult
    if lo > hi:
        return 0

    def valid_digits(p: int) -> bool:
        # p == 0 represents x == s, which is always allowed
        if p == 0:
            return True
        return all(int(c) <= limit for c in str(p))

    # Count p in [lo, hi] with all digits <= limit.
    # Use a digit DP over [0, n] for speed.
    def count_upto(n: int) -> int:
        if n < 0:
            return 0
        digits = [int(c) for c in str(n)]
        m = len(digits)
        # Numbers with fewer digits than n, excluding 0: first digit 1..limit
        total = 0
        for length in range(1, m):
            total += limit * (limit + 1) ** (length - 1)
        # Numbers with exactly m digits, <= n
        for i, d in enumerate(digits):
            lo_choice = 1 if i == 0 else 0
            upper = min(d - 1, limit)
            if upper >= lo_choice:
                total += (upper - lo_choice + 1) * (limit + 1) ** (m - i - 1)
            if d > limit:
                return total  # cannot place d, so n and larger are excluded
        total += 1  # n itself is valid (all digits <= limit)
        return total

    # count_upto counts positive p in [1, n] with valid digits; add p = 0
    def count_range(a: int, b: int) -> int:
        # count valid p in [a, b]
        if b < a:
            return 0
        base_b = count_upto(b)
        base_a = count_upto(a - 1)
        return base_b - base_a

    zero_bonus = 1 if lo == 0 else 0
    return zero_bonus + count_range(max(lo, 1), hi)

def count_powerful_integers(start: int, finish: int, limit: int, s: str) -> int:
    L = len(s)
    mult = 10 ** L
    s_val = int(s)

    # s itself must have all digits <= limit
    if any(int(c) > limit for c in s):
        return 0
    if finish < s_val:
        return 0

    # x = p * mult + s_val, p >= 0, every digit of p <= limit
    hi = (finish - s_val) // mult
    lo_num = start - s_val
    lo = 0 if lo_num <= 0 else (lo_num + mult - 1) // mult
    if lo > hi:
        return 0

    def count_leq(n: int) -> int:
        # Number of p in [0, n] whose digits are all <= limit.
        if n < 0:
            return 0
        digits = [int(c) for c in str(n)]
        m = len(digits)
        # p = 0 always qualifies (since limit >= 1)
        total = 1
        # Positive p with fewer digits than n
        for length in range(1, m):
            total += limit * (limit + 1) ** (length - 1)
        # Positive p with exactly m digits and p <= n
        prefix_ok = True
        for i, d in enumerate(digits):
            lo_choice = 1 if i == 0 else 0
            upper = min(d - 1, limit)
            if upper >= lo_choice:
                total += (upper - lo_choice + 1) * (limit + 1) ** (m - i - 1)
            if d > limit:
                prefix_ok = False
                break
        if prefix_ok:
            total += 1  # n itself
        return total

    return count_leq(hi) - (count_leq(lo - 1) if lo > 0 else 0)

def count_powerful_integers(start: int, finish: int, limit: int, s: str) -> int:
    L = len(s)
    mult = 10 ** L
    s_val = int(s)

    # s itself must have all digits <= limit
    if any(int(c) > limit for c in s):
        return 0
    if finish < s_val:
        return 0

    # x = p * mult + s_val, where p >= 0 and every digit of p is <= limit
    hi = (finish - s_val) // mult
    lo_num = start - s_val
    lo = 0 if lo_num <= 0 else (lo_num + mult - 1) // mult
    if lo > hi:
        return 0

    def valid(p: int) -> bool:
        return all(int(c) <= limit for c in str(p))

    count = 0
    for p in range(lo, hi + 1):
        if valid(p):
            count += 1
    return count

def count_powerful_integers(start: int, finish: int, limit: int, s: str) -> int:
    suffix = s
    count = 0
    for x in range(start, finish + 1):
        xs = str(x)
        if xs.endswith(suffix) and all(int(c) <= limit for c in xs):
            count += 1
    return count

