def solve_grid(n: int, r: str, c: str) -> Optional[List[str]]:
    letters = ['A', 'B', 'C']
    # Each cell is one of 'A', 'B', 'C', or '.'
    options = letters + ['.']

    grid = [['.'] * n for _ in range(n)]

    def valid_partial(grid):
        # Each row and column: at most one of each letter
        for i in range(n):
            row = [grid[i][j] for j in range(n) if grid[i][j] != '.']
            col = [grid[j][i] for j in range(n) if grid[j][i] != '.']
            if len(row) != len(set(row)) or len(col) != len(set(col)):
                return False
        return True

    def row_hint_ok(grid):
        # Leftmost character of row i must match r[i] (if the row has a letter)
        for i in range(n):
            first = next((grid[i][j] for j in range(n) if grid[i][j] != '.'), None)
            if first is not None and first != r[i]:
                return False
        return True

    def col_hint_ok(grid):
        # Topmost character of column j must match c[j] (if the column has a letter)
        for j in range(n):
            first = next((grid[i][j] for i in range(n) if grid[i][j] != '.'), None)
            if first is not None and first != c[j]:
                return False
        return True

    cells = [(i, j) for i in range(n) for j in range(n)]

    def backtrack(idx):
        if idx == len(cells):
            if row_hint_ok(grid) and col_hint_ok(grid):
                return True
            return False
        i, j = cells[idx]
        for ch in options:
            grid[i][j] = ch
            if valid_partial(grid) and backtrack(idx + 1):
                return True
        grid[i][j] = '.'
        return False

    if backtrack(0):
        return [''.join(row) for row in grid]
    return None

