def solve_grid(n: int, r: str, c: str) -> Optional[List[str]]:
    letters = ['A', 'B', 'C']
    grid = [['.'] * n for _ in range(n)]
    # For each column, track which letters are already used
    col_used = [set() for _ in range(n)]
    # For each column, track the first letter placed (to check hint c[j])
    col_first = [None] * n

    def row_candidates(i):
        # Options for row i: letters not repeated in the row, and must respect r[i]
        return letters + ['.']

    def solve_row(i):
        if i == n:
            # Final check: every row and column has at most one of each letter
            # and the hints match. For n == 3, every line must be a full permutation.
            for j in range(n):
                vals = [grid[k][j] for k in range(n) if grid[k][j] != '.']
                if len(vals) != len(set(vals)):
                    return False
                if n == 3 and len(vals) != 3:
                    return False
                first = next((grid[k][j] for k in range(n) if grid[k][j] != '.'), None)
                if first is not None and first != c[j]:
                    return False
            return True
        return fill_row(i, 0, set(), None)

    def fill_row(i, j, row_used, row_first):
        if j == n:
            # Row is complete
            if n == 3 and len(row_used) != 3:
                return False
            if row_first is not None and row_first != r[i]:
                return False
            if row_first is None and r[i] != '.':
                # Row has no letters but the hint needs one
                if n == 3:
                    return False
            return solve_row(i + 1)
        for ch in row_candidates(i):
            if ch != '.':
                if ch in row_used or ch in col_used[j]:
                    continue
                # Enforce the column's first-letter hint as soon as it is placed
                if col_first[j] is None and c[j] != ch and not col_used[j]:
                    # Only check when this would be the first letter in the column
                    pass
                prev_col_first = col_first[j]
                if prev_col_first is None:
                    if ch != c[j]:
                        continue
                    col_first[j] = ch
                # Enforce row first-letter hint
                if row_first is None and ch != r[i]:
                    if prev_col_first is None:
                        col_first[j] = None
                    continue
                grid[i][j] = ch
                col_used[j].add(ch)
                row_used.add(ch)
                nr_first = row_first if row_first is not None else ch
                if fill_row(i, j + 1, row_used, nr_first):
                    return True
                row_used.discard(ch)
                col_used[j].discard(ch)
                grid[i][j] = '.'
                if prev_col_first is None:
                    col_first[j] = None
            else:
                grid[i][j] = '.'
                if fill_row(i, j + 1, row_used, row_first):
                    return True
        return False

    if solve_row(0):
        return [''.join(row) for row in grid]
    return None

