def solve_grid(n: int, r: str, c: str) -> Optional[List[str]]:
    letters = ['A', 'B', 'C']
    grid = [['.'] * n for _ in range(n)]
    row_used = [set() for _ in range(n)]
    col_used = [set() for _ in range(n)]
    row_first = [None] * n
    col_first = [None] * n
    cells = [(i, j) for i in range(n) for j in range(n)]
    full = (n == 3)

    def ok_place(i, j, ch):
        if ch in row_used[i] or ch in col_used[j]:
            return False
        if row_first[i] is None and ch != r[i]:
            return False
        if col_first[j] is None and ch != c[j]:
            return False
        return True

    def finish_ok():
        if full:
            for i in range(n):
                if len(row_used[i]) != 3 or len(col_used[i]) != 3:
                    return False
        return True

    def backtrack(idx):
        if idx == len(cells):
            return finish_ok()
        i, j = cells[idx]
        for ch in letters + ['.']:
            if ch == '.':
                if full:
                    # Blank not allowed in a full 3x3 grid
                    continue
                if backtrack(idx + 1):
                    return True
                continue
            if not ok_place(i, j, ch):
                continue
            prev_rf, prev_cf = row_first[i], col_first[j]
            grid[i][j] = ch
            row_used[i].add(ch)
            col_used[j].add(ch)
            if row_first[i] is None:
                row_first[i] = ch
            if col_first[j] is None:
                col_first[j] = ch
            if backtrack(idx + 1):
                return True
            grid[i][j] = '.'
            row_used[i].discard(ch)
            col_used[j].discard(ch)
            row_first[i], col_first[j] = prev_rf, prev_cf
        return False

    if backtrack(0):
        return [''.join(row) for row in grid]
    return None

