def solve_grid(n: int, r: str, c: str) -> Optional[List[str]]:
    if n != 3:
        return None
    perms = [''.join(p) for p in permutations('ABC')]
    rows = [p for p in perms if p[0] == r[0]]
    for row0 in rows:
        for row1 in perms:
            for row2 in perms:
                grid = [row0, row1, row2]
                if any(grid[i][0] != r[i] for i in range(3)):
                    continue
                if any(sorted(grid[i][j] for i in range(3)) != ['A', 'B', 'C'] for j in range(3)):
                    continue
                if any(grid[0][j] != c[j] for j in range(3)):
                    continue
                return grid
    return None

def calculate_black_area_doubled(A: int, B: int, C: int, D: int) -> int:
    def prefix(X: int, Y: int) -> int:
        # doubled black area in [0, X] x [0, Y] (X, Y may be negative handled by caller)
        # each 2x2 block contributes exactly 2 units of doubled area (half of 4)
        bx, by = X // 2, Y // 2
        full = 2 * bx * by * 2
        # partial strips
        rx, ry = X - 2 * bx, Y - 2 * by
        full += rx * by * 2 // 2 * 1 + ry * bx * 2 // 2 * 1
        return full

    def signed(X: int, Y: int) -> int:
        sign = 1
        if X < 0:
            X, sign = -X, -sign
        if Y < 0:
            Y, sign = -Y, -sign
        return sign * prefix(X, Y)

    return signed(C, D) - signed(A, D) - signed(C, B) + signed(A, B)

