def kth_smallest_amount(coins: List[int], k: int) -> int:
    from math import gcd

    coins = sorted(set(coins))
    n = len(coins)

    def count_le(x: int) -> int:
        # Count distinct positive integers <= x that are multiples of at least one coin.
        # Inclusion-exclusion over all non-empty subsets, pruning subsets whose lcm > x.
        total = 0

        def dfs(idx: int, cur_lcm: int, chosen: int) -> None:
            nonlocal total
            for j in range(idx, n):
                c = coins[j]
                new_lcm = cur_lcm * c // gcd(cur_lcm, c)
                if new_lcm > x:
                    continue
                if chosen % 2 == 0:
                    total += x // new_lcm
                else:
                    total -= x // new_lcm
                dfs(j + 1, new_lcm, chosen + 1)

        dfs(0, 1, 0)
        return total

    lo, hi = 1, max(coins) * k
    while lo < hi:
        mid = (lo + hi) // 2
        if count_le(mid) >= k:
            hi = mid
        else:
            lo = mid + 1
    return lo

