from collections import deque

def min_operations_to_rearrange(n: int, s: str, t: str) -> int:
    if s == t:
        return 0
    start = tuple(list(s) + ['.', '.'])
    # Track how the board can be read as a stone sequence: stones in order
    # with holes removed.
    def stones(state):
        return ''.join(c for c in state if c != '.')

    visited = {start}
    queue = deque([(start, 0)])
    while queue:
        state, d = queue.popleft()
        # Find the two empty cells (they are adjacent by invariant)
        holes = [i for i, c in enumerate(state) if c == '.']
        if len(holes) != 2:
            continue
        h1 = holes[0]
        for i in range(len(state) - 1):
            if i + 1 == h1 or i == h1 + 1 or i in holes or i + 1 in holes:
                continue
            a, b = state[i], state[i + 1]
            if a == '.' or b == '.':
                continue
            new = list(state)
            new[h1], new[h1 + 1] = a, b
            new[i], new[i + 1] = '.', '.'
            ns = tuple(new)
            if ns in visited:
                continue
            if stones(ns) == t:
                return d + 1
            visited.add(ns)
            queue.append((ns, d + 1))
    return -1

