def min_operations_to_rearrange(n: int, s: str, t: str) -> int:
    if s == t:
        return 0
    # State: tuple of length n+2; '.' marks a hole. Holes are always adjacent.
    start = tuple(list(s) + ['.', '.'])
    goal = tuple(list(t) + ['.', '.'])
    visited = {start}
    queue = deque([(start, 0)])
    while queue:
        state, d = queue.popleft()
        h = state.index('.')  # left hole index; right hole is h+1
        # Move any adjacent stone pair (i, i+1) that is fully contained
        # in the stone region, into the hole pair.
        for i in range(len(state) - 1):
            if i + 1 < h or i > h + 1:
                # both stones must be outside the hole pair
                if state[i] == '.' or state[i + 1] == '.':
                    continue
                new = list(state)
                new[h], new[h + 1] = state[i], state[i + 1]
                new[i], new[i + 1] = '.', '.'
                ns = tuple(new)
                if ns == goal:
                    return d + 1
                if ns not in visited:
                    visited.add(ns)
                    queue.append((ns, d + 1))
    return -1

