def count_power_representations(n: int) -> int:
    """ Count how many integers x between 1 and n (inclusive) can be expressed as x = a^b
    where a is a positive integer and b is an integer greater than or equal to 2.

    Args:
        n: The upper bound (1 <= n <= 10^18)

    Returns:
        The count of integers that can be expressed as a^b where b >= 2

    >>> count_power_representations(99)
    12
    >>> count_power_representations(1000000000000000000)
    1001003332
    """
    if n < 1:
        return 0

    def exact_kth_root(x: int, k: int) -> int:
        # Largest r with r^k <= x, using exact integer binary search
        lo, hi = 1, 2
        while hi ** k <= x:
            hi *= 2
        while hi - lo > 1:
            mid = (lo + hi) // 2
            if mid ** k <= x:
                lo = mid
            else:
                hi = mid
        return lo

    def mobius(m: int) -> int:
        result = 1
        d = 2
        while d * d <= m:
            if m % d == 0:
                m //= d
                if m % d == 0:
                    return 0
                result = -result
            d += 1
        if m > 1:
            result = -result
        return result

    total = 0
    for k in range(2, n.bit_length() + 1):
        mu = mobius(k)
        if mu != 0:
            total -= mu * (exact_kth_root(n, k) - 1)

    # Add 1 for x = 1 = 1^2
    return total + 1

