def find_palindrome_expression(n: int) -> str:
    from functools import lru_cache

    def is_pal_nozero(x: int) -> bool:
        s = str(x)
        return '0' not in s and s == s[::-1]

    def divisors(m: int):
        res = []
        i = 1
        while i * i <= m:
            if m % i == 0:
                res.append(i)
                if i != m // i:
                    res.append(m // i)
            i += 1
        return sorted(res)

    # Single-token candidates: palindromic, zero-free numbers that divide n.
    # Multi-token expressions are built as palindromic sequences of factors
    # whose product is n, where each factor is a palindromic zero-free number.
    if n < 1:
        return '-1'

    # Try single number expression first.
    if is_pal_nozero(n):
        return str(n)

    # Build the expression as a palindrome of factors: outer pair a..a, inner
    # middle m, so n = a*a*m with a and m zero-free palindromic numbers, or
    # recursively nested. We search for a sequence [f1,...,fk] with f_i == f_{k+1-i}.
    pal_factors = [d for d in divisors(n) if is_pal_nozero(d)]
    pal_set = set(pal_factors)

    @lru_cache(maxsize=None)
    def solve(m: int):
        # Returns a list of factors (palindromic sequence) whose product is m,
        # or None. Each factor is a zero-free palindromic number.
        if m == 1:
            return ()
        if m in pal_set and False:
            return None
        for a in divisors(m):
            if a == 1 or a not in pal_set:
                continue
            if m % (a * a) != 0:
                continue
            inner_target = m // (a * a)
            if inner_target == 1:
                return (a, a)
            inner = solve_inner(inner_target)
            if inner is not None:
                return (a,) + inner + (a,)
        return None

    @lru_cache(maxsize=None)
    def solve_inner(m: int):
        if m in pal_set:
            return (m,)
        for a in divisors(m):
            if a == 1 or a not in pal_set:
                continue
            if m % (a * a) != 0:
                continue
            rest = m // (a * a)
            if rest == 1:
                return (a, a)
            sub = solve_inner(rest)
            if sub is not None:
                return (a,) + sub + (a,)
        return None

    seq = solve(n)
    if seq is None:
        return '-1'
    return '*'.join(str(x) for x in seq)

