from math import comb

MOD = 998244353

def _is_good(n: int) -> bool:
    # sigma(n) divisible by 3, via factorization
    total = 1
    x = n
    p = 2
    while p * p <= x:
        if x % p == 0:
            e = 0
            while x % p == 0:
                x //= p
                e += 1
            s = (pow(p, e + 1) - 1) // (p - 1)
            total *= s
        p += 1
    if x > 1:
        total *= (x + 1)
    return total % 3 == 0

def count_good_sequences(N: int, M: int) -> int:
    ans = 0
    for n in range(1, N + 1):
        if not _is_good(n):
            continue
        # d_M(n) = product over p^e of C(e+M-1, M-1)
        d = 1
        x = n
        p = 2
        while p * p <= x:
            if x % p == 0:
                e = 0
                while x % p == 0:
                    x //= p
                    e += 1
                d = d * comb(e + M - 1, M - 1) % MOD
            p += 1
        if x > 1:
            d = d * M % MOD
        ans = (ans + d) % MOD
    return ans % MOD

