def brute(n, k):
    """Brute force: count n-digit integers x (no leading zero) whose digits can be
    rearranged into a k-palindrome with no leading zero."""
    count = 0
    for x in range(10 ** (n - 1), 10 ** n):
        digits = sorted(str(x))
        ok = False
        for p in set(permutations(digits)):
            if p[0] == '0':
                continue
            s = ''.join(p)
            if s == s[::-1] and int(s) % k == 0:
                ok = True
                break
        if ok:
            count += 1
    return count

