from bisect import bisect_left


def _lis_len(seq):
    tails = []
    for x in seq:
        i = bisect_left(tails, x)
        if i == len(tails):
            tails.append(x)
        else:
            tails[i] = x
    return len(tails)


def _lds_len(seq):
    return _lis_len([-x for x in seq])


def _brute_count(A, B):
    N = A * B - 1
    count = 0
    for P in permutations(range(1, N + 1)):
        if _lis_len(P) != A or _lds_len(P) != B:
            continue
        ok = False
        for n in range(0, N + 1):
