                for k in range(K):
                    if covers((i, j, k), px, py):
                        return (i, j, k)
        raise ValueError("no tile found")

    def boundary_segments(t):
        # Four axis-aligned edges of the tile as ((x0, y0), (x1, y1)) pairs.
        i, j, k = t
        if (i - j) % 2 == 0:
            x0, x1 = i * K, (i + 1) * K
            y0, y1 = j * K + k, j * K + k + 1
        else:
            x0, x1 = i * K + k, i * K + k + 1
            y0, y1 = j * K, (j + 1) * K
        return [
            ((x0, y0), (x1, y0)),
            ((x0, y1), (x1, y1)),
            ((x0, y0), (x0, y1)),
            ((x1, y0), (x1, y1)),
        ]

    def shares_edge(a, b):
        # Two axis-aligned tiles are adjacent if some pair of edges is
        # collinear and overlaps in a segment of positive length.
        for (p1, p2) in boundary_segments(a):
            for (q1, q2) in boundary_segments(b):
                if p1[0] == p2[0] == q1[0] == q2[0]:  # both vertical
                    lo = max(min(p1[1], p2[1]), min(q1[1], q2[1]))
                    hi = min(max(p1[1], p2[1]), max(q1[1], q2[1]))
                    if hi > lo:
                        return True
                if p1[1] == p2[1] == q1[1] == q2[1]:  # both horizontal
                    lo = max(min(p1[0], p2[0]), min(q1[0], q2[0]))
                    hi = min(max(p1[0], p2[0]), max(q1[0], q2[0]))
                    if hi > lo:
