import itertools

MOD = 998244353

def _exact_expected_operations(N: int, M: int) -> Fraction:
    # Build the tree: vertex i (1..N*M) connects to max(i - N, 0).
    V = N * M + 1
    adj = [[] for _ in range(V)]
    for i in range(1, V):
        p = max(i - N, 0)
        adj[i].append(p)
        adj[p].append(i)

    # State: (current vertex, frozenset of painted vertices).
    # Expected remaining steps E(state); terminal when all painted.
    from functools import lru_cache
    full = (1 << V) - 1

    @lru_cache(maxsize=None)
    def E(cur: int, mask: int) -> Fraction:
        if mask == full:
            return Fraction(0)
        d = len(adj[cur])
        total = Fraction(0)
        for nxt in adj[cur]:
            nmask = mask | (1 << nxt)
            total += E(nxt, nmask)
        return Fraction(1) + total / d

    return E(0, 1)

def expected_operations(N: int, M: int) -> int:
    if N * M + 1 > 20:
        # Too large for the exact solver; no verified closed form is available.
        raise NotImplementedError("need the closed-form formula for large inputs")
    val = _exact_expected_operations(N, M)
    return (val.numerator % MOD) * pow(val.denominator % MOD, MOD - 2, MOD) % MOD

from functools import lru_cache
from math import gcd

def can_color_all_points(n: int, k: int) -> bool:
    """Exact game search for small n; closed-form fallback for large n."""
    if n <= 16:
        full = (1 << n) - 1

        def reflect_set(mask, axis):
            # Points symmetric to each colored point about the axis through `axis`.
            # Reflection of p across axis a is (2a - p) mod n.
            out = 0
            for p in range(n):
                if mask >> p & 1:
                    out |= 1 << ((2 * axis - p) % n)
            return out

        @lru_cache(maxsize=None)
        def win(mask, turn):
            # turn 0 = Alice (at 0), turn 1 = Bob (at k).
            # Returns True if all points can eventually be colored under best cooperation.
            if mask == full:
                return True
            pos = 0 if turn == 0 else k
            moves = []
            for p in range(n):
                if mask >> p & 1:
                    continue
                new = mask | (1 << p)
                # Symmetry must hold w.r.t. the axis through the current player.
                if reflect_set(new, pos) == new:
                    moves.append(new)
            if not moves:
                return False
            return any(win(m, 1 - turn) for m in moves)

        return win(0, 0)

    # Fallback for large n (not verified against the tests).
    g = gcd(n, k)
    return (n // g) % 2 == 1

