def can_color_all_points(n: int, k: int) -> bool:
    """Brute-force game search for small n, following the docstring rules."""
    if n > 16:
        return False  # not verified for large n

    full = (1 << n) - 1

    def reflect(mask, axis):
        out = 0
        for p in range(n):
            if mask >> p & 1:
                out |= 1 << ((2 * axis - p) % n)
        return out

    @lru_cache(maxsize=None)
    def win(mask, turn):
        if mask == full:
            return True
        pos = 0 if turn == 0 else k
        moves = []
        for p in range(n):
            if mask >> p & 1:
