MOD = 998244353


def _ntt(arr, invert):
    n = len(arr)
    j = 0
    for i in range(1, n):
        bit = n >> 1
        while j & bit:
            j ^= bit
            bit >>= 1
        j ^= bit
        if i < j:
            arr[i], arr[j] = arr[j], arr[i]
    length = 2
    while length <= n:
        w = pow(3, (MOD - 1) // length, MOD)
        if invert:
            w = pow(w, MOD - 2, MOD)
        half = length // 2
        wp = [1] * half
        for k in range(1, half):
            wp[k] = wp[k - 1] * w % MOD
        for i in range(0, n, length):
            for k in range(half):
                u = arr[i + k]
                v = arr[i + k + half] * wp[k] % MOD
                arr[i + k] = (u + v) % MOD
                arr[i + k + half] = (u - v) % MOD
        length <<= 1
    if invert:
        inv_n = pow(n, MOD - 2, MOD)
        for i in range(n):
            arr[i] = arr[i] * inv_n % MOD


def _multiply(a, b):
    if not a or not b:
        return []
    need = len(a) + len(b) - 1
    if min(len(a), len(b)) <= 32:
        res = [0] * need
        for i, x in enumerate(a):
            if x == 0:
                continue
            for j, y in enumerate(b):
                res[i + j] = (res[i + j] + x * y) % MOD
        return res
    size = 1
    while size < need:
        size <<= 1
    fa = a + [0] * (size - len(a))
    fb = b + [0] * (size - len(b))
    _ntt(fa, False)
    _ntt(fb, False)
    for i in range(size):
        fa[i] = fa[i] * fb[i] % MOD
    _ntt(fa, True)
    return fa[:need]


def _binom_series(w, c):
    # Coefficients of (1 + w x)^c, length c + 1.
    res = [0] * (c + 1)
    binom = 1
    p = 1
    for j in range(c + 1):
        res[j] = binom * p % MOD
        p = p * w % MOD
        binom = binom * (c - j) % MOD * pow(j + 1, MOD - 2, MOD) % MOD
    return res


def sum_concatenated_permutations(n: int) -> int:
    if n <= 0:
        return 0
    fact = [1] * (n + 1)
    for i in range(1, n + 1):
        fact[i] = fact[i - 1] * i % MOD

    # Group 1..n by digit count: (weight w = 10^d, count c, value-sum s).
    groups = []
    lo, d, p10 = 1, 1, 10
    while lo <= n:
        hi = min(n, p10 - 1)
        c = hi - lo + 1
        s = (lo + hi) * c // 2 % MOD
        groups.append((pow(10, d, MOD), c, s))
        lo = hi + 1
        d += 1
        p10 *= 10

    total = 0
    for idx, (w, c, s) in enumerate(groups):
        # Polynomial of all elements except one element of group idx.
        poly = [1]
        for jdx, (w2, c2, _) in enumerate(groups):
            cnt = c2 - 1 if jdx == idx else c2
            if cnt > 0:
                poly = _multiply(poly, _binom_series(w2, cnt))
        # poly[j] = e_j over all other elements; weight by j!(n-1-j)!.
        contrib = 0
        for j in range(min(len(poly), n)):
            contrib = (contrib + fact[j] * fact[n - 1 - j] % MOD * poly[j]) % MOD
        # Each element in this group contributes value * 10-power term;
        # the sum of their values is s, and each uses the same polynomial.
        total = (total + s * contrib) % MOD

    return total % MOD

