def find_largest_400_number(a: int) -> int:
    """ Find the largest 400 number not exceeding a.

    A 400 number is a square m*m where m has exactly two distinct prime factors.
    So we search downward for the largest m with m*m <= a such that m has
    exactly two distinct prime factors.

    Args:
        a: An integer where 36 <= a <= 10^12

    Returns:
        The largest 400 number not exceeding a
    """
    def distinct_prime_count(n: int) -> int:
        count = 0
        d = 2
        while d * d <= n:
            if n % d == 0:
                count += 1
                while n % d == 0:
                    n //= d
            d += 1
        if n > 1:
            count += 1
        return count

    m = int(a ** 0.5)
    while m * m > a:
        m -= 1
    while m * m < a + 1 and m * m > a:
        m -= 1
    while m >= 2:
        if m * m <= a and distinct_prime_count(m) == 2:
            return m * m
        m -= 1
    return 0

