                    k += 1
                exponents.append(k)
            d += 1
        if n > 1:
            exponents.append(1)
        return len(exponents) == 2 and all(e % 2 == 0 for e in exponents)

    n = a
    while n >= 1:
        if is_400_number(n):
            return n
        n -= 1
    return 0

