def count_beautiful_numbers(l: int, r: int) -> int:
    def count_upto(n: int) -> int:
        # Count beautiful numbers in [0, n]; zero is excluded below since its digit sum is 0.
        if n <= 0:
            return 0
        digits = list(map(int, str(n)))
        total = 0
        # For each possible digit sum s (max 9*9 = 81), count numbers with digit sum exactly s
        # and digit product divisible by s.
        for s in range(1, 82):
            @lru_cache(maxsize=None)
            def dp(pos, cur_sum, prod_mod, tight, started):
                # Prune if sum already exceeds s
                if cur_sum > s:
                    return 0
                if pos == len(digits):
                    if not started:
                        return 0
                    return 1 if (cur_sum == s and prod_mod % s == 0) else 0
                limit = digits[pos] if tight else 9
                res = 0
                for d in range(limit + 1):
                    nt = tight and d == limit
                    ns = started or d != 0
                    if ns:
                        nsum = cur_sum + d
                        nprod = (prod_mod * d) % s if started else d % s
                    else:
                        nsum = cur_sum
                        nprod = 1 % s
                    res += dp(pos + 1, nsum, nprod, nt, ns)
                return res
            total += dp(0, 0, 1 % s, True, False)
            dp.cache_clear()
        return total

    return count_upto(r) - count_upto(l - 1)

