    def count_upto(n: int) -> int:
        # number of beautiful x in [1, n]
        if n <= 0:
            return 0
        digits = list(map(int, str(n)))
        L = len(digits)
        total = 0
        for s in range(1, 82):
            # free[sum][mod]: count of already-started, non-tight prefixes
            # with digit sum `sum` and product `mod` (mod s)
            free = [[0] * s for _ in range(s + 1)]
            tight_sum, tight_prod = 0, 1 % s   # the tight prefix's state
            tight_alive = True
            for pos in range(L):
                nfree = [[0] * s for _ in range(s + 1)]
                # extend non-tight prefixes with any digit 0..9
                for sm in range(s + 1):
                    row = free[sm]
                    for md in range(s):
                        c = row[md]
                        if not c:
                            continue
                        for d in range(10):
                            ns = sm + d
                            if ns > s:
                                break
                            nfree[ns][(md * d) % s] += c
                # extend the tight prefix
                if tight_alive:
                    lim = digits[pos]
                    # digits strictly below the limit become non-tight
                    for d in range(lim):
                        ns = tight_sum + d
                        if ns <= s:
                            if pos == 0 and d == 0:
                                # leading zero: not started yet, product stays 1
                                nfree[ns][1 % s if ns else 0] += 0  # handled below
                            nfree[ns][(tight_prod * d) % s] += 1 if pos > 0 or d > 0 else 0
                    tight_sum += lim
                    tight_prod = (tight_prod * lim) % s
                    if tight_sum > s:
                        tight_alive = False
                # a fresh number can start at this position (leading zeros skipped)
                if pos > 0:
                    for d in range(1, 10):
                        if d <= s:
                            nfree[d][d % s] += 1
                free = nfree
            # tight number itself, if it is valid and nonzero
            if tight_alive and tight_sum == s and tight_prod % s == 0:
                total += 1
            total += sum(free[s][md] for md in range(s) if md == 0)
            # all counted numbers in `free` with sum s and product ≡ 0 mod s
        return total

    return count_upto(r) - count_upto(l - 1)

