from typing import List


def paint_walls(cost: List[int], time: List[int]) -> int:
    n = len(cost)
    INF = float('inf')
    dp = [INF] * (n + 1)
    dp[0] = 0
    for i in range(n):
        gain = time[i] + 1
        for j in range(n, -1, -1):
            prev = max(0, j - gain)
            if dp[prev] != INF:
                dp[j] = min(dp[j], dp[prev] + cost[i])
    return dp[n]

