def min_changes_for_semi_palindromes(s: str, k: int) -> int:
    n = len(s)

    # cost[i][j]: min changes to make s[i..j] (inclusive) a semi-palindrome
    # Returns a large value if length < 2 (not allowed as a semi-palindrome).
    INF = float("inf")

    def semi_cost(sub: str) -> int:
        L = len(sub)
        if L < 2:
            return INF
        best = INF
        for d in range(1, L):
            if L % d != 0:
                continue
            # For each residue class mod d, count changes to make it a palindrome
            changes = 0
            for r in range(d):
                group = sub[r::d]
                i, j = 0, len(group) - 1
                while i < j:
                    if group[i] != group[j]:
                        changes += 1
                    i += 1
                    j -= 1
            best = min(best, changes)
        return best

    cost = [[INF] * n for _ in range(n)]
    for i in range(n):
        for j in range(i + 1, n):
            cost[i][j] = semi_cost(s[i:j + 1])

    # dp[p][j]: min changes to split first j chars into p parts
    dp = [[INF] * (n + 1) for _ in range(k + 1)]
    dp[0][0] = 0
    for p in range(1, k + 1):
        for j in range(1, n + 1):
            for i in range(p - 1, j):
                if dp[p - 1][i] == INF:
                    continue
                # part is s[i:j]
                if i == j - 1:
                    c = INF  # length 1 can't be a semi-palindrome
                else:
                    c = cost[i][j - 1]
                if c == INF:
                    continue
                val = dp[p - 1][i] + c
                if val < dp[p][j]:
                    dp[p][j] = val

    return int(dp[k][n])

