def count_partitions(t, k):
    n = len(t); parts = 0; i = 0
    while i < n:
        window = set(); j = i
        while j < n and (t[j] in window or len(window) < k):
            window.add(t[j]); j += 1
        parts += 1; i = j
    return parts

