from itertools import permutations


def _inversions(p) -> int:
    n = len(p)
    count = 0
    for i in range(n):
        for j in range(i + 1, n):
            if p[i] > p[j]:
                count += 1
    return count


def min_operations_to_match_grids(H: int, W: int, A: List[List[int]], B: List[List[int]]) -> Optional[int]:
    best = None
    row_perms = list(permutations(range(H)))
    col_perms = list(permutations(range(W)))
    col_inv = {q: _inversions(q) for q in col_perms}
    for p in row_perms:
        rc = _inversions(p)
        for q in col_perms:
            ok = True
            for i in range(H):
                ai = A[p[i]]
                bi = B[i]
                for j in range(W):
                    if ai[q[j]] != bi[j]:
                        ok = False
                        break
                if not ok:
                    break
            if ok:
                cost = rc + col_inv[q]
                if best is None or cost < best:
                    best = cost
    return best

