def min_weight_hamiltonian_walk(n: int, m: int, edges: List[Tuple[int, int, int]]) -> Optional[int]:
    INF = float("inf")

    # All-pairs shortest walk costs (no negative cycles guaranteed).
    dist = [[INF] * n for _ in range(n)]
    for i in range(n):
        dist[i][i] = 0
    for u, v, w in edges:
        u -= 1
        v -= 1
        if w < dist[u][v]:
            dist[u][v] = w

    for k in range(n):
        for i in range(n):
            dik = dist[i][k]
            if dik == INF:
                continue
            for j in range(n):
                nd = dik + dist[k][j]
                if nd < dist[i][j]:
                    dist[i][j] = nd

    # dp[mask][v]: min cost of a walk that has visited exactly the vertices in
    # mask and currently ends at v, where the walk is over the metric closure.
    full = (1 << n) - 1
    dp = [[INF] * n for _ in range(1 << n)]
    for v in range(n):
        dp[1 << v][v] = 0

    for mask in range(1 << n):
        for v in range(n):
            cur = dp[mask][v]
            if cur == INF:
                continue
            for u in range(n):
                if mask & (1 << u):
                    continue
                if dist[v][u] == INF:
                    continue
                nmask = mask | (1 << u)
                nc = cur + dist[v][u]
                if nc < dp[nmask][u]:
                    dp[nmask][u] = nc

    best = min(dp[full])
    return None if best == INF else int(best)

