    for i in range(n):
        for j in range(i):
            d = a[i] - a[j]
            counts = dp[i].setdefault(d, [0] * (n + 1))
            counts[2] = (counts[2] + 1) % MOD
            if d in dp[j]:
                src = dp[j][d]
                for length in range(2, n):
                    if src[length]:
                        counts[length + 1] = (counts[length + 1] + src[length]) % MOD

    for i in range(n):
        for counts in dp[i].values():
            for length in range(2, n + 1):
                res[length - 1] = (res[length - 1] + counts[length]) % MOD

    return res

