def max_dishes_eaten(n: int, x: int, y: int, dishes: List[Tuple[int, int]]) -> int:
    best = 0
    m = len(dishes)
    if m == 0:
        return 0
    # Try every dish as the final (overflowing) dish, which is counted.
    # Among the remaining dishes, pick the largest subset with
    # sum of sweetness < x and sum of saltiness < y.
    # Use a DP over dishes: dp[s] = minimum saltiness achieving sweetness sum s
    # using a chosen count k, i.e. dp[k][s] = min saltiness.
    INF = float("inf")
    for skip in range(m):
        rest = [dishes[i] for i in range(m) if i != skip]
        # dp[k] maps sweetness sum -> minimum saltiness sum with k dishes chosen
        dp = [dict() for _ in range(len(rest) + 1)]
        dp[0][0] = 0
        for s_val, t_val in rest:
            for k in range(len(rest), 0, -1):
                for s_sum, t_sum in list(dp[k - 1].items()):
                    ns = s_sum + s_val
                    nt = t_sum + t_val
                    if ns < x and nt < y:
                        if nt < dp[k].get(ns, INF):
                            dp[k][ns] = nt
        chosen = 0
        for k in range(len(rest) + 1):
            if dp[k]:
                chosen = max(chosen, k)
        best = max(best, chosen + 1)
    return best

