    m = len(dishes)
    best = 0
    # dp[s] = minimum saltiness achievable with total sweetness exactly s,
    # for each count k of dishes chosen (k is the number of dishes eaten)
    INF = float("inf")
    # Sort dishes so that eating order is by sweetness+saltiness is not needed:
    # we track, for each subset size k, the min saltiness per sweetness sum.
    dp = [dict() for _ in range(m + 1)]
    dp[0][0] = 0
    for s_val, t_val in dishes:
        for k in range(m - 1, -1, -1):
            for s_sum, t_sum in list(dp[k].items()):
                ns = s_sum + s_val
                nt = t_sum + t_val
                if ns <= x and nt <= y:
                    if nt < dp[k + 1].get(ns, INF):
                        dp[k + 1][ns] = nt
    # The maximum number of dishes whose sweetness and saltiness fit within the limits
    for k in range(m + 1):
        if dp[k]:
            best = max(best, k)
    # Each feasible subset of size k can be followed by one more dish (the overflow),
    # so the answer is at most k + 1 when a dish remains outside the subset.
    result = best
    if best < m:
        result = best + 1
    return min(result, m)

