def count_valid_permutations(n: int, requirements: List[List[int]]) -> int:
    req = {end: cnt for end, cnt in requirements}
    CAP = max(cnt for _, cnt in requirements)

    # dp[s]: number of ways to choose d_0..d_i (d_k in [0, k]) with sum s
    dp = [0] * (CAP + 1)
    for d in range(min(0, CAP) + 1):
        dp[d] = 1

    for i in range(n):
        if i > 0:
            new_dp = [0] * (CAP + 1)
            for s in range(CAP + 1):
                if dp[s]:
                    for d in range(i + 1):
                        if s + d > CAP:
                            break
                        new_dp[s + d] = (new_dp[s + d] + dp[s]) % MOD
            dp = new_dp

        if i in req:
            target = req[i]
            kept = dp[target]
            dp = [0] * (CAP + 1)
            dp[target] = kept

    return sum(dp) % MOD

