def count_paths(N: int, M: int, K: int, extra_edges: list) -> int:
    # Out-edges: cycle edge i -> i+1 (N -> 1), plus extra edges.
    out = [[] for _ in range(N + 1)]
    for i in range(1, N + 1):
        out[i].append(i % N + 1)
    for x, y in extra_edges:
        out[x].append(y)

    # Walks of exactly K moves from vertex 1, counted by the DP over
    # the vertices that the walk can occupy at each step. Since the
    # graph is a cycle plus at most 50 extra edges, the set of distinct
    # reachable vertices is small in practice, so we track a dict of
    # vertex -> number of ways.
    cur = {1: 1}
    for _ in range(K):
        nxt = {}
        for v, c in cur.items():
            for w in out[v]:
                nxt[w] = (nxt.get(w, 0) + c) % MOD
        cur = nxt
        if not cur:
            break
    return sum(cur.values()) % MOD

