def count_paths(N: int, M: int, K: int, extra_edges: list) -> int:
    extra = {}
    for x, y in extra_edges:
        extra.setdefault(x, []).append(y)
    specials = sorted(extra.keys())

    def dist(v, s):
        return (s - v) % N

    from functools import lru_cache
    import sys
    sys.setrecursionlimit(10**6)

    @lru_cache(maxsize=None)
    def g(v, r):
        if r == 0:
            return 1
        best = None
        for s in specials:
            d = dist(v, s)
            if d < r and (best is None or d < best[0]):
                best = (d, s)
        if best is None:
            return 1
        d, s = best
        rest = r - d - 1
        total = g(s % N + 1, rest)
        for y in extra[s]:
            total += g(y, rest)
        return total % MOD

    return g(1, K) % MOD

