    # Extra out-edges per vertex. Only these vertices have a choice.
    extra = {}
    for x, y in extra_edges:
        extra.setdefault(x, []).append(y)
    specials = sorted(extra.keys())

    # g(v, r): number of walks of exactly r moves starting at v.
    # Without a special vertex within reach, the walk is forced: 1 way.
    # Otherwise the walk takes d forced cycle steps to the nearest
    # special s, then makes one move: the cycle edge or an extra edge.
    from functools import lru_cache
    import sys
    sys.setrecursionlimit(10**6)

    @lru_cache(maxsize=None)
    def g(v, r):
        if r == 0:
            return 1
        best = None
        for s in specials:
            d = (s - v) % N
            if d < r and (best is None or d < best[0]):
                best = (d, s)
        if best is None:
            return 1
        d, s = best
        rest = r - d - 1
        total = g(s % N + 1, rest)
        for y in extra[s]:
            total += g(y, rest)
        return total % MOD

    return g(1, K) % MOD

