from collections import defaultdict, deque


def min_ng_list_size(n: int, product_names: List[str]) -> int:
    # Build the directed graph on letters: each product name is an edge.
    adj = defaultdict(set)
    nodes = set()
    for name in product_names:
        u, v = name[0], name[1]
        adj[u].add(v)
        nodes.add(u)
        nodes.add(v)

    # Reachability closure: an edge can be covered by a walk through
    # any vertex reachable along existing edges, so compute transitive
    # reachability and do a bipartite matching of out-stubs to in-stubs.
    reach = {}
    for s in nodes:
        seen = {s}
        q = deque([s])
        while q:
            x = q.popleft()
            for y in adj[x]:
                if y not in seen:
                    seen.add(y)
                    q.append(y)
        reach[s] = seen - {s}

    # Each vertex with out-degree d must start d walks that go out;
    # match "out-stubs" of u to "in-stubs" of v where v is reachable from u.
    # Walks needed = total out-edges minus maximum matching size, with
    # the standard floor of 1 for nonempty components.
    left = []
    for u in nodes:
        left.extend([u] * len(adj[u]))
    match_right = {}

    def try_assign(u, visited):
        for v in reach[u] | {u}:
            if v in visited:
                continue
            visited.add(v)
            if v not in match_right or try_assign(match_right[v], visited):
                match_right[v] = u
                return True
        return False

    matched = 0
    for u in left:
        if try_assign(u, set()):
            matched += 1

    return max(1, len(left) - matched) if left else 0


