    def cost_for(c: int) -> int:
        total = 0
        for a, p, b, q in machines:
            # cheapest way to get at least c products/day for this process
            best = min((c + a - 1) // a * p, (c + b - 1) // b * q)
            total += best
            if total > x:
                return total
        return total

    lo, hi = 0, 2 * 10**9
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if cost_for(mid) <= x:
            lo = mid
        else:
            hi = mid - 1
    return lo

