def max_production_capacity(n: int, x: int, machines: List[Tuple[int, int, int, int]]) -> int:
    def min_cost_for_process(c: int, a: int, p: int, b: int, q: int) -> int:
        # Minimum cost s*p + t*q subject to s*a + t*b >= c, s, t >= 0 integers.
        if c <= 0:
            return 0
        best = None
        # Enumerate the count of machine T; it never needs to exceed a (exchange argument:
        # a units of T can be replaced by b units of S at no greater cost when a*q >= b*p,
        # and symmetric otherwise). Cover both orderings for safety.
        max_t = min((c + b - 1) // b, a)
        for t in range(max_t + 1):
            rem = c - t * b
            s = max(0, (rem + a - 1) // a)
            cost = s * p + t * q
            if best is None or cost < best:
                best = cost
        max_s = min((c + a - 1) // a, b)
        for s in range(max_s + 1):
            rem = c - s * a
            t = max(0, (rem + b - 1) // b)
            cost = s * p + t * q
            if cost < best:
                best = cost
        return best

    def feasible(c: int) -> bool:
        total = 0
        for a, p, b, q in machines:
            total += min_cost_for_process(c, a, p, b, q)
            if total > x:
                return False
        return total <= x

    lo, hi = 0, 2 * 10**9
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if feasible(mid):
            lo = mid
        else:
            hi = mid - 1
    return lo

