def min_deletions_to_snowflake(n: int, edges: List[Tuple[int, int]]) -> int:
    adj = [[] for _ in range(n + 1)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    deg = [len(adj[i]) for i in range(n + 1)]

    best = 0
    for c in range(1, n + 1):
        total = 0
        branches = 0
        for b in adj[c]:
            # Each child b of center c keeps its own leaves (neighbors other than c).
            leaves = deg[b] - 1
            if leaves >= 1:
                total += 1 + leaves
                branches += 1
        if branches >= 1:
            kept = 1 + total
            if kept > best:
                best = kept

    return n - best

