def min_deletions_to_snowflake(n: int, edges: List[Tuple[int, int]]) -> int:
    adj = [[] for _ in range(n + 1)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    # Root the tree at 1 to get parent pointers and a processing order.
    parent = [0] * (n + 1)
    order = []
    visited = [False] * (n + 1)
    stack = [1]
    visited[1] = True
    while stack:
        u = stack.pop()
        order.append(u)
        for w in adj[u]:
            if not visited[w]:
                visited[w] = True
                parent[w] = u
                stack.append(w)

    # childless[v]: 1 if v has no children when rooted at 1 (a leaf of the rooted tree).
    # For center c we need the number of childless neighbors of b, excluding c,
    # where "childless" depends on the rooting at c, so we compute per center directly.
    best = 0
    for c in range(1, n + 1):
        total = 0
        for b in adj[c]:
            leaves = 0
            for w in adj[b]:
                if w != c and len(adj[w]) == 1:
                    leaves += 1
            if leaves >= 1:
                total += 1 + leaves
        if total > 0:
            best = max(best, 1 + total - 1 + 0 if False else 1 + total)
    return n - best

