        for b in adj[c]:
            children = len(adj[b]) - 1
            if children >= 1:
                kept += 1 + children
                branches += 1
        if branches >= 1:
            best = max(best, kept)
    return n - best

from itertools import product

def fixed_entries(matrix, n):
    """Return the number of fixed entries of an n x n binary matrix.
    An entry is fixed if its value is the same in every 0-1 matrix
    with the same row sums and column sums."""
    row_sums = [sum(matrix[i]) for i in range(n)]
    col_sums = [sum(matrix[i][j] for i in range(n)) for j in range(n)]
    fixed = 0
    for i in range(n):
        for j in range(n):
            values = set()
            for candidate in product((0, 1), repeat=n * n):
                m = [candidate[r * n:(r + 1) * n] for r in range(n)]
                if [sum(m[r]) for r in range(n)] == row_sums and \
                   [sum(m[r][c] for r in range(n)) for c in range(n)] == col_sums:
                    values.add(m[i][j])
                    if len(values) > 1:
                        break
            if len(values) == 1:
                fixed += 1
    return fixed

def achievable_fixed_counts(n):
    """Brute-force set of k values achieved by some n x n binary matrix (n <= 3 only)."""
    counts = set()
    for bits in product((0, 1), repeat=n * n):
        m = [bits[r * n:(r + 1) * n] for r in range(n)]
        counts.add(fixed_entries(m, n))
    return sorted(counts)

