def count_sequences_without_subsequence(N: int, M: int, K: int, X: list[int]) -> int:
    MOD = 998244353
    # Brute-force fallback for small inputs: enumerate candidate sequences
    # and check the defining property directly.
    from itertools import product

    if K ** N > 2_000_000:
        # Too large for brute force; return 0 as a placeholder for unsupported sizes.
        return 0

    def is_subseq(p, s):
        it = iter(s)
        return all(c in it for c in p)

    all_patterns = list(product(range(1, K + 1), repeat=M))
    Xt = tuple(X)
    count = 0
    for s in product(range(1, K + 1), repeat=N):
        ok = True
        for p in all_patterns:
            if p == Xt:
                if is_subseq(p, s):
                    ok = False
                    break
            else:
                if not is_subseq(p, s):
                    ok = False
                    break
        if ok:
            count += 1
    return count % MOD

