from itertools import product
from functools import lru_cache

MOD = 998244353

def is_good(t: str) -> bool:
    # Reduce t to empty using: remove two identical chars, or remove one A, one B, one C.
    # Exhaustive search over reachable strings.
    @lru_cache(maxsize=None)
    def reach(u: str) -> bool:
        if u == "":
            return True
        n = len(u)
        for i in range(n):
            for j in range(i + 1, n):
                if u[i] == u[j]:
                    rest = u[:i] + u[i+1:j] + u[j+1:]
                    if reach(rest):
                        return True
        if "A" in u and "B" in u and "C" in u:
            for a in range(n):
                if u[a] != "A":
                    continue
                for b in range(n):
                    if u[b] != "B":
                        continue
                    for c in range(n):
                        if u[c] != "C":
                            continue
                        idx = {a, b, c}
                        rest = "".join(u[x] for x in range(n) if x not in idx)
                        if reach(rest):
                            return True
        return False
    return reach(t)

def brute_count(n: int, k: int, s: str) -> int:
    qs = [i for i, ch in enumerate(s) if ch == "?"]
    total = 0
    for fill in product("ABC", repeat=len(qs)):
        t = list(s)
        for idx, ch in zip(qs, fill):
            t[idx] = ch
        t = "".join(t)
        good_count = 0
        for i in range(n):
            for j in range(i + 1, n + 1):
                if is_good(t[i:j]):
                    good_count += 1
        if good_count >= k:
            total += 1
    return total % MOD

def check_parity_claim(max_len: int = 6) -> bool:
    # For every string over {A,B,C} up to max_len, check: good <=> all counts have equal parity.
    for L in range(1, max_len + 1):
        for tup in product("ABC", repeat=L):
            t = "".join(tup)
            pa, pb, pc = t.count("A") % 2, t.count("B") % 2, t.count("C") % 2
            parity_ok = pa == pb == pc
            if parity_ok != is_good(t):
                print("Mismatch:", t, "parity_ok =", parity_ok, "is_good =", is_good(t))
                return False
    return True

