def count_k_reducible(s: str, k: int) -> int:
    MOD = 10**9 + 7
    n_len = len(s)

    # steps[x]: number of operations to reduce x to 1 (popcount chain)
    def steps(x):
        cnt = 0
        while x != 1:
            x = bin(x).count("1")
            cnt += 1
        return cnt

    # Precompute binomial coefficients up to n_len
    C = [[0] * (n_len + 1) for _ in range(n_len + 1)]
    for i in range(n_len + 1):
        C[i][0] = 1
        for j in range(1, i + 1):
            C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % MOD

    # cnt_pop[c] = number of integers x in [0, n) with popcount c, where n = int(s, 2)
    # Computed via digit-by-digit counting over the binary string.
    cnt_pop = [0] * (n_len + 2)
    ones_so_far = 0
    for i, ch in enumerate(s):
        remaining = n_len - i - 1
        if ch == "1":
            # Place 0 here, free choice for remaining bits
            for c in range(remaining + 1):
                cnt_pop[ones_so_far + c] = (cnt_pop[ones_so_far + c] + C[remaining][c]) % MOD
            ones_so_far += 1
    # Numbers in [0, n) are exactly those counted above (strictly less than n)

    # Valid popcounts: x with popcount c is k-reducible iff steps(c) + 1 <= k
    # (x != 1 case); x = 1 is handled separately (popcount 1, steps 0 -> always reducible)
    total = 0
    for c in range(1, n_len + 1):
        if c == 1:
            # x with popcount 1 (powers of two) need 1 operation to reach 1 -> reducible if k >= 1
            if k >= 1:
                total = (total + cnt_pop[c]) % MOD
        else:
            if steps(c) + 1 <= k:
                total = (total + cnt_pop[c]) % MOD

    # Exclude x = 0 (not positive); 0 has popcount 0, so it is not counted for c >= 1.
    # x = 1 has popcount 1 and is reducible in 0 operations; it is included in cnt_pop[1] when n > 1.
    # x = 1 is 0 operations, so it's valid for any k >= 0. Already counted above when k >= 1.
    return total % MOD

