    L = len(s)

    # steps[c] = number of operations to reduce integer c to 1
    # (c ranges over popcounts, which are at most L)
    steps = [0] * (L + 2)
    for c in range(2, L + 2):
        steps[c] = 1 + steps[bin(c).count("1")]

    # Binomial coefficients
    C = [[0] * (L + 1) for _ in range(L + 1)]
    for i in range(L + 1):
        C[i][0] = 1
        for j in range(1, i + 1):
            C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % MOD

    # cnt[c] = number of x in [0, n) with popcount c
    cnt = [0] * (L + 2)
    ones = 0
    for i, ch in enumerate(s):
        rem = L - i - 1
        if ch == "1":
            for c in range(rem + 1):
                cnt[ones + c] = (cnt[ones + c] + C[rem][c]) % MOD
            ones += 1

    # x in [1, n) is k-reducible iff steps(x) <= k.
    # steps(x) = 0 only for x = 1; otherwise steps(x) = 1 + steps(popcount(x)).
    total = 0
    if k >= 0 and L >= 1:
        # x = 1 (0 operations) counted if n > 1
        if int(s, 2) > 1:
            total += 1
    for c in range(1, L + 1):
        # numbers with popcount c, excluding x = 1 (popcount 1 counted separately)
        if c == 1:
            # popcount-1 numbers (powers of two) need 1 op, except x=1 which needs 0
