from math import comb
from collections import defaultdict


def count_balanced_graphs(n: int, p: int) -> list[int]:
    max_m = n * (n - 1) // 2

    def pmul(a, b):
        r = [0] * (len(a) + len(b) - 1)
        for i, x in enumerate(a):
            if x:
                for j, y in enumerate(b):
                    if y:
                        r[i + j] += x * y
        return r

    def padd(a, b):
        m = max(len(a), len(b))
        return [(a[i] if i < len(a) else 0) + (b[i] if i < len(b) else 0)
                for i in range(m)]

    def ppow(a, k):
        r = [1]
        for _ in range(k):
            r = pmul(r, a)
        return r

    def within(t):
        m = t * (t - 1) // 2
        return [comb(m, e) for e in range(m + 1)]

    def attach(s, t):
        base = [comb(s, e) for e in range(s + 1)]
        base[0] -= 1
        return ppow(base, t)

    dp = defaultdict(lambda: [0])
    dp[(1, 1, 0, 1)] = [1]

    total = [0] * (max_m + 1)

    for used in range(1, n + 1):
        keys = [k for k in dp if k[0] == used]
        for key in keys:
            used_k, s, par, bal = key
            poly = dp.pop(key)
            if used_k == n:
                if bal == 0:
                    total = padd(total, poly)
                continue
            rem = n - used_k
            for t in range(1, rem + 1):
                ways = comb(rem, t)
                new_par = 1 - par
                sign = 1 if new_par == 0 else -1
                step = pmul(pmul(attach(s, t), within(t)), [ways])
                newp = pmul(poly, step)
                key2 = (used_k + t, t, new_par, bal + sign * t)
                dp[key2] = padd(dp[key2], newp)

    result = []
    for m in range(n - 1, max_m + 1):
        val = total[m] if m < len(total) else 0
        result.append(val % p)
    return result

