MOD = 998244353


def count_strings_by_lcs_length(n: int, m: int, s: str) -> List[int]:
    letters = [chr(ord('a') + i) for i in range(26)]

    # State: the full LCS DP row (length n+1) for s vs. the current prefix of t.
    # row[j] = LCS length of s[:j] and the current prefix of t.
    def step(row, c):
        new_row = [0] * (n + 1)
        for j in range(1, n + 1):
            if s[j - 1] == c:
                new_row[j] = row[j - 1] + 1
            else:
                new_row[j] = max(row[j], new_row[j - 1])
        return tuple(new_row)

    start = tuple([0] * (n + 1))
    dp = {start: 1}

    # Cache transitions per (row, letter) since rows repeat across steps
    trans_cache = {}

    for _ in range(m):
        ndp = {}
        for row, cnt in dp.items():
            for c in letters:
                key = (row, c)
                if key in trans_cache:
                    nxt = trans_cache[key]
                else:
                    nxt = step(row, c)
                    trans_cache[key] = nxt
                ndp[nxt] = (ndp.get(nxt, 0) + cnt) % MOD
        dp = ndp

    result = [0] * (n + 1)
    for row, cnt in dp.items():
        k = row[n]
        result[k] = (result[k] + cnt) % MOD
    return result

