def is_alkane(vertices, adj):
    # induced subgraph on vertices must be a tree with degrees in {1,4}, at least one 4
    vs = set(vertices)
    edge_count = 0
    degs = {}
    for v in vs:
        d = sum(1 for w in adj[v] if w in vs)
        degs[v] = d
        edge_count += d
    edge_count //= 2
    if edge_count != len(vs) - 1:
        return False
    if any(d not in (1, 4) for d in degs.values()):
        return False
    return any(d == 4 for d in degs.values())

def brute(n, edges):
    adj = {v: [] for v in range(1, n + 1)}
    for a, b in edges:
        adj[a].append(b)
        adj[b].append(a)
    best = -1
    for r in range(1, n + 1):
        for comb in combinations(range(1, n + 1), r):
            if is_alkane(comb, adj):
                best = max(best, r)
    return best

