def count_paths(W: int, H: int, L: int, R: int, D: int, U: int) -> int:
    def is_block(x, y):
        if x < 0 or x > W or y < 0 or y > H:
            return False
        return not (L <= x <= R and D <= y <= U)

    # f[x][y] = number of valid paths starting at block (x, y), including
    # the zero-move path. Computed from the top-right corner backwards.
    f = [[0] * (H + 2) for _ in range(W + 2)]
    total = 0
    for x in range(W, -1, -1):
        for y in range(H, -1, -1):
            if not is_block(x, y):
                continue
            val = 1
            if is_block(x + 1, y):
                val += f[x + 1][y]
            if is_block(x, y + 1):
                val += f[x][y + 1]
            val %= MOD
            f[x][y] = val
            total = (total + val) % MOD
    return total

