def determine_winner(n: int, a: List[int]) -> str:
    """Brute-force game solver (correct but exponential; intended for small inputs).

    State: remaining counts tuple and the set S (as a bitmask).
    The player who makes the move that completes S wins.
    """
    full = (1 << n) - 1

    @lru_cache(maxsize=None)
    def win(counts, mask):
        # Returns True if the player to move wins from this state.
        if mask == full:
            # Game already over; the previous mover won, so the player to move loses.
            return False
        for i in range(n):
            if counts[i] >= 1:
                new_counts = counts[:i] + (counts[i] - 1,) + counts[i + 1:]
                new_mask = mask | (1 << i)
                if not win(new_counts, new_mask):
                    return True
        return False

    return 'Fennec' if win(tuple(a), 0) else 'Snuke'

