    # Every element is a divisor of some a[i], so values are <= 1000.
    # Use Mobius inversion over d for the gcd=1 condition:
    #   answer = sum_d mu(d) * G(d), where G(d) sums scores of good sequences
    #   with every element divisible by d.

    def G(d: int) -> int:
