        # Transition for constraint a[i]: pairs (x, y) with x*y = a[i], gcd(x,y)=1, d|x, d|y.
        # dp maps the value of S[i] -> sum of products of S[0..i].
        first_pairs = []
        a0 = a[0]
        for x in range(d, a0 + 1, d):
            if a0 % x == 0:
                y = a0 // x
                if y % d == 0 and _gcd(x, y) == 1:
                    first_pairs.append((x, y))
        if not first_pairs:
            return 0
        dp = {}
        for x, y in first_pairs:
            dp[x] = (dp.get(x, 0) + x) % MOD
            dp[y] = (dp.get(y, 0) + y * 0) % MOD  # placeholder, fixed below
        # Recompute cleanly: dp[v] = sum of products of S[0..i] with S[i] = v.
        dp = {}
        for x, y in first_pairs:
            # S[0] = x, S[1] = y: product so far is x*y
            dp[y] = (dp.get(y, 0) + x * y) % MOD

        for i in range(1, n - 1):
            ai = a[i]
            pairs = []
            for x in range(d, ai + 1, d):
                if ai % x == 0:
                    y = ai // x
                    if y % d == 0 and _gcd(x, y) == 1:
                        pairs.append((x, y))
            ndp = {}
            for prev_val, total in dp.items():
                for x, y in pairs:
                    if x == prev_val:
                        ndp[y] = (ndp.get(y, 0) + total * y) % MOD
            dp = ndp
            if not dp:
                return 0
        return sum(dp.values()) % MOD

    ans = 0
    for d in range(1, 1001):
        mu = _mobius(d)
        if mu == 0:
            continue
        ans = (ans + mu * G(d)) % MOD
    return ans % MOD

