            for k in range(1, LIMIT + 1):
                u, v = p * k, q * k
                if u % d == 0 and v % d == 0 and u <= LIMIT and v <= LIMIT:
                    pairs.append((u, v))
        return pairs

    def G(d: int) -> int:
        # dp[u] = sum of products of S[0..i] with S[i] = u, over sequences with all elements divisible by d
        dp = {}
        for u in range(d, LIMIT + 1, d):
            dp[u] = u
        for ai in a:
            trans = transitions(ai, d)
            ndp = {}
            for u, v in trans:
                if u in dp:
                    ndp[v] = (ndp.get(v, 0) + dp[u] * v) % MOD
            dp = ndp
            if not dp:
                return 0
        return sum(dp.values()) % MOD

    ans = 0
    for d in range(1, LIMIT + 1):
        mu = _mobius(d)
        if mu == 0:
            continue
        ans = (ans + mu * G(d)) % MOD
    return ans % MOD

