from typing import Optional, List


def solve_grid(n: int, r: str, c: str) -> Optional[List[str]]:
    """ Given an integer N and strings R and C of length N consisting of 'A', 'B', and 'C',
    determine if it's possible to fill an N×N grid such that:
    - Each row and column contains exactly one 'A', one 'B', and one 'C'
    - The leftmost character written in the i-th row matches the i-th character of R
    - The topmost character written in the i-th column matches the i-th character of C

    Empty cells are represented by '.' in the output.

    Args:
        n: The size of the grid (3 <= n <= 5)
        r: String of length n specifying leftmost characters in each row
        c: String of length n specifying topmost characters in each column

    Returns:
        A list of n strings representing the filled grid if possible, None otherwise.
        Each string has length n, where '.' represents empty cells.

    >>> solve_grid(3, 'ABC', 'ABC')
    ['ABC', 'BCA', 'CAB']
    >>> solve_grid(3, 'AAA', 'BBB')
    None
    """
    letters = ['A', 'B', 'C']
    grid = [['.' for _ in range(n)] for _ in range(n)]
    # row_has[i][ch] / col_has[j][ch] track whether letter ch is already placed
    row_has = [set() for _ in range(n)]
    col_has = [set() for _ in range(n)]

    def first_letter_in_row(i: int) -> Optional[str]:
        for j in range(n):
            if grid[i][j] != '.':
                return grid[i][j]
        return None

    def first_letter_in_col(j: int) -> Optional[str]:
        for i in range(n):
            if grid[i][j] != '.':
                return grid[i][j]
        return None

    def valid_final_row(i: int) -> bool:
        # leftmost character must match R[i]
        return first_letter_in_row(i) == r[i]

    def valid_final_col(j: int) -> bool:
        # topmost character must match C[j]
        return first_letter_in_col(j) == c[j]

    def backtrack(pos: int) -> bool:
        if pos == n * n:
            # Check each row and column is complete and anchors match
            for i in range(n):
                if row_has[i] != set(letters[:3]) and len(row_has[i]) != 3:
                    return False
            for j in range(n):
                if len(col_has[j]) != 3:
                    return False
            for i in range(n):
                if not valid_final_row(i):
                    return False
            for j in range(n):
                if not valid_final_col(j):
                    return False
            return True

        i, j = divmod(pos, n)

        # Option 1: leave the cell empty
        if backtrack(pos + 1):
            return True

        # Option 2: place a letter
        for ch in letters:
            if ch in row_has[i] or ch in col_has[j]:
                continue
            # Row/col must not exceed three distinct letters (always true with
            # the check above), and the letter cannot be placed if the row/col
            # already has three letters.
            if len(row_has[i]) >= 3 or len(col_has[j]) >= 3:
                continue
            # Leftmost constraint: if this is the first letter placed in row i,
            # it must equal r[i]. Topmost: first letter in column j must equal c[j].
            if not row_has[i] and ch != r[i]:
                continue
            if not col_has[j] and ch != c[j]:
                continue

            grid[i][j] = ch
            row_has[i].add(ch)
            col_has[j].add(ch)

            if backtrack(pos + 1):
                return True

            grid[i][j] = '.'
            row_has[i].discard(ch)
            col_has[j].discard(ch)

        return False

    if backtrack(0):
        return [''.join(row) for row in grid]
    return None

