def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """ Determine if it's possible to place rectangular tiles on an H×W grid such that:
    - Every cell is covered by exactly one tile
    - Tiles can be rotated (so a 2×3 tile can be placed as 3×2)
    - Some tiles may remain unused
    - Tiles must be aligned with grid cells and cannot extend outside

    Args:
        n: Number of available tiles (1 ≤ n ≤ 7)
        h: Height of the grid (1 ≤ h ≤ 10)
        w: Width of the grid (1 ≤ w ≤ 10)
        tiles: List of (a, b) tuples where tile i has dimensions a×b (1 ≤ a, b ≤ 10)

    Returns:
        True if the grid can be perfectly tiled, False otherwise

    >>> can_tile_grid(5, 5, 5, [(1, 1), (3, 3), (4, 4), (2, 3), (2, 5)])
    True
    >>> can_tile_grid(1, 1, 2, [(2, 3)])
    False
    >>> can_tile_grid(1, 2, 2, [(1, 1)])
    False
    """
    target = h * w
    tiles = tiles[:n]

    def placements(a: int, b: int):
        res = set()
        for (ph, pw) in {(a, b), (b, a)}:
            if ph <= h and pw <= w:
                for r in range(h - ph + 1):
                    for c in range(w - pw + 1):
                        mask = 0
                        for i in range(ph):
                            for j in range(pw):
                                mask |= 1 << ((r + i) * w + (c + j))
                        res.add(mask)
        return list(res)

    full = (1 << target) - 1
    tile_places = [placements(a, b) for a, b in tiles]
    tile_areas = [a * b for a, b in tiles]

    if target == 0:
        return True

    # Try every subset of tiles whose areas sum exactly to the grid area.
    def subsets_with_area(idx: int, remaining: int, chosen: List[int]):
        if remaining == 0:
            yield list(chosen)
            return
        if idx >= len(tiles):
            return
        # include tile idx
        if tile_areas[idx] <= remaining and tile_places[idx]:
            chosen.append(idx)
            yield from subsets_with_area(idx + 1, remaining - tile_areas[idx], chosen)
            chosen.pop()
        # exclude tile idx
        yield from subsets_with_area(idx + 1, remaining, chosen)

    def exact_cover(covered: int, used: List[bool], subset: List[int]) -> bool:
        if covered == full:
            return True
        free = ~covered & full
        low = free & -free  # lowest uncovered cell must be covered next
        for k in subset:
            if used[k]:
                continue
            for mask in tile_places[k]:
                if (mask & low) and not (mask & covered):
                    used[k] = True
                    if exact_cover(covered | mask, used, subset):
                        used[k] = False
                        return True
                    used[k] = False
        return False

    for subset in subsets_with_area(0, target, []):
        used = [False] * len(tiles)
        if exact_cover(0, used, subset):
            return True
    return False

