        if idx >= len(tiles):
            return
        if tile_areas[idx] <= remaining and tile_places[idx]:
            chosen.append(idx)
            yield from subsets(idx + 1, remaining - tile_areas[idx], chosen)
            chosen.pop()
        yield from subsets(idx + 1, remaining, chosen)

    # Every tile in `pending` must be placed exactly once to cover the grid.
    def cover(covered: int, pending: frozenset) -> bool:
        if covered == full:
            return not pending  # all chosen tiles must have been placed
        free = ~covered & full
        low = free & -free
        for k in pending:
            for mask in tile_places[k]:
                if (mask & low) and not (mask & covered):
                    if cover(covered | mask, pending - {k}):
