    >>> can_tile_grid(1, 1, 2, [(2, 3)])
    False
    >>> can_tile_grid(1, 2, 2, [(1, 1)])
    False
    """
    target = h * w
    if target == 0:
        return True
    tiles = tiles[:n]
    full = (1 << target) - 1

    placements = []
    for (a, b) in tiles:
        opts = []
        for (ph, pw) in {(a, b), (b, a)}:
            if ph <= h and pw <= w:
                for r in range(h - ph + 1):
                    for c in range(w - pw + 1):
                        mask = 0
                        for i in range(ph):
                            for j in range(pw):
                                mask |= 1 << ((r + i) * w + (c + j))
                        opts.append((r * w + c, mask))
        placements.append(opts)

    def covers_exactly(subset: List[int]) -> bool:
        # Exact cover of the grid by the tiles in `subset` (each used once).
        memo = {}

        def solve(covered: int, used: int) -> bool:
            if covered == full:
                return used == sum(1 << k for k in subset)
            key = (covered, used)
            if key in memo:
                return memo[key]
            free = ~covered & full
            low = free & -free
            pos = low.bit_length() - 1
            result = False
            for k in subset:
                if used & (1 << k):
                    continue
                for anchor, mask in placements[k]:
                    if anchor != pos or (mask & covered):
                        continue
                    if solve(covered | mask, used | (1 << k)):
                        result = True
                        break
                if result:
                    break
            memo[key] = result
            return result

        return solve(0, 0)

    # Enumerate subsets of tiles whose areas sum exactly to the grid area.
    areas = [a * b for a, b in tiles]
    m = len(tiles)

    def subsets(idx: int, remaining: int, chosen: List[int]):
        if remaining == 0:
            yield list(chosen)
            return
        if idx >= m:
            return
        if areas[idx] <= remaining and placements[idx]:
            chosen.append(idx)
            yield from subsets(idx + 1, remaining - areas[idx], chosen)
            chosen.pop()
        yield from subsets(idx + 1, remaining, chosen)

    for subset in subsets(0, target, []):
        if covers_exactly(subset):
            return True
    return False

def calculate_black_area_doubled(A: int, B: int, C: int, D: int) -> int:
    def color_black(x2: int, y2: int) -> bool:
        # point (x2/2, y2/2) for unit cell test; use the 2-periodic pattern
        # cell (i,j) with lower-left corner (i,j): black iff (i + j) even
        # for cells split by lines, the editorial rule is equivalent to parity
        return (x2 // 2 + y2 // 2) % 2 == 0

    def area2_prefix(X: int, Y: int) -> int:
        # doubled black area of [0,X] x [0,Y] (X, Y >= 0)
        if X <= 0 or Y <= 0:
            return 0
        total = 0
        # full blocks of 2x2 cells contain exactly 2 black unit cells (area 2, doubled 4)
        bx, by = X // 2, Y // 2
        total += bx * by * 4 * 2  # 2x2 block has 4 cells, 2 black, area 2, doubled 4
        total = bx * by * 4
        # remainder strips
        # column strip x in [2bx, X], y in [0, 2by]
        for j in range(by):
            if X - 2 * bx >= 1:
                # unit cell at (2bx, 2j) and (2bx, 2j+1)
                total += 2 if (2 * bx + 2 * j) % 2 == 0 else 0
                total += 2 if (2 * bx + 2 * j + 1) % 2 == 0 else 0
            if X - 2 * bx >= 2:
                total += 2 if (2 * bx + 1 + 2 * j) % 2 == 0 else 0
                total += 2 if (2 * bx + 1 + 2 * j + 1) % 2 == 0 else 0
        # row strip y in [2by, Y], x in [0, X]
        for i in range(bx * 2):
            if Y - 2 * by >= 1:
                total += 2 if (i + 2 * by) % 2 == 0 else 0
            if Y - 2 * by >= 2:
                total += 2 if (i + 2 * by + 1) % 2 == 0 else 0
        # corner remainder cells
        if X - 2 * bx >= 1 and Y - 2 * by >= 1:
            total += 2 if (2 * bx + 2 * by) % 2 == 0 else 0
        return total

    return area2_prefix(C, D) - area2_prefix(A, D) - area2_prefix(C, B) + area2_prefix(A, B)

