def expected_black_ball_position(N: int, K: int) -> int:
    MOD = 998244353

    def inv(x: int) -> int:
        return pow(x % MOD, MOD - 2, MOD)

    if N == 1:
        return 1

    inv_N = inv(N)
    lam = (1 - 2 * inv_N) % MOD
    lam_k = pow(lam, K, MOD)
    s = (inv_N + (1 - inv_N) % MOD * lam_k) % MOD
    avg_other = (N + 2) % MOD * inv(2) % MOD
    return (s + (1 - s) % MOD * avg_other) % MOD

