from itertools import product

def brute(N, K):
    MOD = 998244353
    dist = {1: Fraction(1)}  # position of black ball -> probability
    for _ in range(K):
        new = {}
        for pos, pr in dist.items():
            for a, b in product(range(1, N + 1), repeat=2):
                if a == b:
                    q = pos
                elif pos == a:
                    q = b
                elif pos == b:
                    q = a
                else:
                    q = pos
                new[q] = new.get(q, Fraction(0)) + pr / (N * N)
        dist = new
    E = sum(x * p for x, p in dist.items())
    return E.numerator * pow(E.denominator, MOD - 2, MOD) % MOD

