def brute_mod(N: int, K: int) -> int:
    MOD = 998244353
    inv_NN = pow(N * N % MOD, MOD - 2, MOD)
    dist = {1: 1}
    for _ in range(K):
        new = {}
        for pos, pr in dist.items():
            for a in range(1, N + 1):
                for b in range(1, N + 1):
