from collections import deque

def min_operations_to_rearrange(n: int, s: str, t: str) -> int:
    if s == t:
        return 0
    if s.count('B') != t.count('B'):
        return -1
    # BFS over configurations (strings of length n).
    # One operation: choose adjacent pair at positions i, i+1 (0-indexed, i+1 < len),
    # remove them and append them to the end, preserving their order.
    dist = {s: 0}
    q = deque([s])
    while q:
        cur = q.popleft()
        d = dist[cur]
        for i in range(len(cur) - 1):
            nxt = cur[:i] + cur[i + 2:] + cur[i:i + 2]
            if nxt not in dist:
                dist[nxt] = d + 1
                if nxt == t:
                    return d + 1
                q.append(nxt)
    return -1

