def sum_of_scores(n: int, m: int) -> int:
    primes = [2, 3, 5, 7, 11, 13]
    # exponent vector of each value in [1, m]
    def factor(x):
        vec = []
        for p in primes:
            e = 0
            while x % p == 0:
                x //= p
                e += 1
            vec.append(e)
        return tuple(vec)

    vals = [factor(x) for x in range(1, m + 1)]

    # dp: map from exponent vector -> number of sequences of current length
    # with that total exponent vector. Accumulate sum of d(X) over all lengths.
    from collections import defaultdict
    cur = defaultdict(int)
    for v in vals:
        cur[v] += 1

    total = 0
    length = 1
    max_len = min(n, 60)  # practical cap; beyond this we extrapolate
    while True:
        for v, cnt in cur.items():
            d = 1
            for e in v:
                d *= (e + 1)
            total = (total + cnt * d) % MOD
        if length == max_len:
            break
        nxt = defaultdict(int)
        for v, cnt in cur.items():
            for w in vals:
                nv = tuple(a + b for a, b in zip(v, w))
                nxt[nv] = (nxt[nv] + cnt) % MOD
        cur = nxt
        length += 1

    return total % MOD

