def count_special_permutations(A: int, B: int, M: int) -> int:
    from itertools import permutations
    from bisect import bisect_left

    def lis_len(seq):
        tails = []
        for x in seq:
            i = bisect_left(tails, x)
            if i == len(tails):
                tails.append(x)
            else:
                tails[i] = x
        return len(tails)

    def lds_len(seq):
        return lis_len([-x for x in seq])

    n = A * B - 1
    count = 0
    for P in permutations(range(1, n + 1)):
        if lis_len(P) != A or lds_len(P) != B:
            continue
        # Condition 3: exists n' such that appending n' + 0.5 keeps both LIS and LDS.
        # Appending a value v = n' + 0.5 (any real between integers) to P:
        # check all possible insertion gap positions 0..n.
        ok = False
        for v2 in range(0, n + 1):
            v = v2 + 0.5
            Q = list(P) + [v]
            if lis_len(Q) == A and lds_len(Q) == B:
                ok = True
                break
        if ok:
            count += 1
    return count % M

