from collections import deque

def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """ Find the minimum number of moves between tiles on a coordinate plane.

    Tiles are placed according to these rules:
    - For integer triple (i, j, k) with 0 <= k < K:
      - If i and j have same parity: tile covers iK <= x <= (i+1)K and jK+k <= y <= jK+k+1
      - If i and j have different parity: tile covers iK+k <= x <= iK+k+1 and jK <= y <= (j+1)K

    Two tiles are adjacent if their edges share a positive-length segment.

    Args:
        K: The tile parameter (2 <= K <= 10^16)
        S_x, S_y: Starting coordinates (tile containing (S_x + 0.5, S_y + 0.5))
        T_x, T_y: Target coordinates (tile containing (T_x + 0.5, T_y + 0.5))

    Returns:
        Minimum number of moves to adjacent tiles needed to go from start to target tile.

    >>> min_tile_moves(3, -2, 1, 4, -1)
    4
    >>> min_tile_moves(4, 8, 8, 0, 2)
    4
    >>> min_tile_moves(5, -1000000000000, -1000000000000, 1000000000000, 1000000000000)
    800000000000
    """
    def tile_of(x, y):
        # Identify the tile containing the point (x + 0.5, y + 0.5).
        # Approach: find i, j, k such that the point falls in the tile.
        # Tiles are indexed by their parity class and offset k.
        # Vertical strips of width K-ish are split into unit-width slices by k.
        # Here we use a direct search over the block containing the point.
        # For a point (px, py) with px = x + 0.5, py = y + 0.5:
        # candidate block indices i = floor(px / K), j = floor(py / K).
        i0 = x // K
        j0 = y // K
        for i in (i0 - 1, i0, i0 + 1):
            for j in (j0 - 1, j0, j0 + 1):
                if (i - j) % 2 == 0:
                    # same parity: x in [iK, (i+1)K], y - jK in [k, k+1)
                    k = y - j * K
                    if i * K <= x < (i + 1) * K and 0 <= k < K:
                        return (i, j, k)
                else:
                    # different parity: x - iK in [k, k+1), y in [jK, (j+1)K)
                    k = x - i * K
                    if j * K <= y < (j + 1) * K and 0 <= k < K:
                        return (i, j, k)
        return None

    def neighbors(tile):
        i, j, k = tile
        result = []
        for di in (-1, 0, 1):
            for dj in (-1, 0, 1):
                if di == 0 and dj == 0:
                    continue
                ni, nj = i + di, j + dj
                # Candidate tiles in neighboring blocks; check adjacency by
                # sampling a small set of k values near the current k.
                for nk in range(max(0, k - 2), min(K, k + 3)):
                    cand = (ni, nj, nk)
                    if cand != tile and _adjacent(tile, cand):
                        result.append(cand)
        return result

    def _adjacent(a, b):
        # Two tiles are adjacent if their edges overlap on a positive-length segment.
        def rect(t):
            i, j, k = t
            if (i - j) % 2 == 0:
                return (i * K, j * K + k, (i + 1) * K, j * K + k + 1)
            else:
                return (i * K + k, j * K, i * K + k + 1, (j + 1) * K)
        ax0, ay0, ax1, ay1 = rect(a)
        bx0, by0, bx1, by1 = rect(b)
        # Shared vertical edge
        if ax1 == bx0 or bx1 == ax0:
            overlap = min(ay1, by1) - max(ay0, by0)
            if overlap > 0:
                return True
        # Shared horizontal edge
        if ay1 == by0 or by1 == ay0:
            overlap = min(ax1, bx1) - max(ax0, bx0)
            if overlap > 0:
                return True
        return False

    start = tile_of(S_x, S_y)
    target = tile_of(T_x, T_y)
    if start is None or target is None:
        return -1
    if start == target:
        return 0

    dist = {start: 0}
    q = deque([start])
    while q:
        cur = q.popleft()
        for nb in neighbors(cur):
            if nb not in dist:
                dist[nb] = dist[cur] + 1
                if nb == target:
                    return dist[nb]
                q.append(nb)
    return -1

