def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """ Find the minimum number of moves between tiles on a coordinate plane.

    Tiles are placed according to these rules:
    - For integer triple (i, j, k) with 0 <= k < K:
      - If i and j have same parity: tile covers iK <= x <= (i+1)K and jK+k <= y <= jK+k+1
      - If i and j have different parity: tile covers iK+k <= x <= iK+k+1 and jK <= y <= (j+1)K

    Two tiles are adjacent if their edges share a positive-length segment.

    Args:
        K: The tile parameter (2 <= K <= 10^16)
        S_x, S_y: Starting coordinates (tile containing (S_x + 0.5, S_y + 0.5))
        T_x, T_y: Target coordinates (tile containing (T_x + 0.5, T_y + 0.5))

    Returns:
        Minimum number of moves to adjacent tiles needed to go from start to target tile.

    >>> min_tile_moves(3, -2, 1, 4, -1)
    4
    >>> min_tile_moves(4, 8, 8, 0, 2)
    4
    >>> min_tile_moves(5, -1000000000000, -1000000000000, 1000000000000, 1000000000000)
    800000000000
    """
    def rect(t):
        i, j, k = t
        if (i - j) % 2 == 0:
            return (i * K, j * K + k, (i + 1) * K, j * K + k + 1)
        return (i * K + k, j * K, i * K + k + 1, (j + 1) * K)

    def tile_containing(px, py):
        # Point (px, py) with px = S_x + 0.5 etc. Find the tile whose rect contains it.
        # Candidate block indices around the point.
        bi = px // K
        bj = py // K
        for i in range(bi - 1, bi + 2):
            for j in range(bj - 1, bj + 2):
                for k in range(K):
                    x0, y0, x1, y1 = rect((i, j, k))
                    if x0 < px < x1 and y0 < py < y1:
                        return (i, j, k)
        return None

    def adjacent(a, b):
        ax0, ay0, ax1, ay1 = rect(a)
        bx0, by0, bx1, by1 = rect(b)
        if ax1 == bx0 or bx1 == ax0:
            if min(ay1, by1) - max(ay0, by0) > 0:
                return True
        if ay1 == by0 or by1 == ay0:
            if min(ax1, bx1) - max(ax0, bx0) > 0:
                return True
        return False

    start = tile_containing(S_x + 0.5, S_y + 0.5)
    target = tile_containing(T_x + 0.5, T_y + 0.5)
    if start is None or target is None:
        return -1
    if start == target:
        return 0

    # Bounded search: enumerate tiles in a box covering start and target.
    lo_i = min(start[0], target[0]) - 3
    hi_i = max(start[0], target[0]) + 3
    lo_j = min(start[1], target[1]) - 3
    hi_j = max(start[1], target[1]) + 3
    tiles = [(i, j, k)
             for i in range(lo_i, hi_i + 1)
             for j in range(lo_j, hi_j + 1)
             for k in range(K)]

    dist = {start: 0}
    q = deque([start])
    while q:
        cur = q.popleft()
        for nb in tiles:
            if nb not in dist and adjacent(cur, nb):
                dist[nb] = dist[cur] + 1
                if nb == target:
                    return dist[nb]
                q.append(nb)
    return -1

