        for nb in tiles:
            if nb not in dist and adjacent(cur, nb):
                dist[nb] = dist[cur] + 1
                if nb == target:
                    return dist[nb]
                q.append(nb)
    return -1

from collections import deque

def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """ Find the minimum number of moves between tiles on a coordinate plane.

    Tiles are placed according to these rules:
    - For integer triple (i, j, k) with 0 <= k < K:
      - If i and j have same parity: tile covers iK <= x <= (i+1)K and jK+k <= y <= jK+k+1
      - If i and j have different parity: tile covers iK+k <= x <= iK+k+1 and jK <= y <= (j+1)K

    Two tiles are adjacent if their edges share a positive-length segment.

    Args:
        K: The tile parameter (2 <= K <= 10^16)
        S_x, S_y: Starting coordinates (tile containing (S_x + 0.5, S_y + 0.5))
        T_x, T_y: Target coordinates (tile containing (T_x + 0.5, T_y + 0.5))

    Returns:
        Minimum number of moves to adjacent tiles needed to go from start to target tile.

    >>> min_tile_moves(3, -2, 1, 4, -1)
    4
    >>> min_tile_moves(4, 8, 8, 0, 2)
    4
    >>> min_tile_moves(5, -1000000000000, -1000000000000, 1000000000000, 1000000000000)
    800000000000
    """
    def rect2(t):
        # Doubled coordinates keep the point (S_x + 0.5, S_y + 0.5) integral.
        i, j, k = t
        if (i - j) % 2 == 0:
            x0, y0, x1, y1 = i * K, j * K + k, (i + 1) * K, j * K + k + 1
        else:
            x0, y0, x1, y1 = i * K + k, j * K, i * K + k + 1, (j + 1) * K
        return (2 * x0, 2 * y0, 2 * x1, 2 * y1)

    def tile_containing(px2, py2):
        bi = (px2 // 2) // K
        bj = (py2 // 2) // K
        for i in range(bi - 2, bi + 3):
            for j in range(bj - 2, bj + 3):
                for k in range(K):
                    x0, y0, x1, y1 = rect2((i, j, k))
                    if x0 < px2 < x1 and y0 < py2 < y1:
                        return (i, j, k)
        return None

    def adjacent(a, b):
        ax0, ay0, ax1, ay1 = rect2(a)
        bx0, by0, bx1, by1 = rect2(b)
        if ax1 == bx0 or bx1 == ax0:
            if min(ay1, by1) - max(ay0, by0) > 0:
                return True
        if ay1 == by0 or by1 == ay0:
            if min(ax1, bx1) - max(ax0, bx0) > 0:
                return True
        return False

    start = tile_containing(2 * S_x + 1, 2 * S_y + 1)
    target = tile_containing(2 * T_x + 1, 2 * T_y + 1)
    if start is None or target is None:
        return -1
    if start == target:
        return 0

    lo_i = min(start[0], target[0]) - 3
    hi_i = max(start[0], target[0]) + 3
    lo_j = min(start[1], target[1]) - 3
    hi_j = max(start[1], target[1]) + 3
    tiles = [(i, j, k)
             for i in range(lo_i, hi_i + 1)
             for j in range(lo_j, hi_j + 1)
             for k in range(K)]

    dist = {start: 0}
    q = deque([start])
    while q:
        cur = q.popleft()
        for nb in tiles:
            if nb not in dist and adjacent(cur, nb):
                dist[nb] = dist[cur] + 1
                if nb == target:
                    return dist[nb]
                q.append(nb)
    return -1

import heapq

def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """ Find the minimum number of moves between tiles on a coordinate plane.

    Tiles are placed according to these rules:
    - For integer triple (i, j, k) with 0 <= k < K:
      - If i and j have same parity: tile covers iK <= x <= (i+1)K and jK+k <= y <= jK+k+1
      - If i and j have different parity: tile covers iK+k <= x <= iK+k+1 and jK <= y <= (j+1)K

    Two tiles are adjacent if their edges share a positive-length segment.

    Args:
        K: The tile parameter (2 <= K <= 10^16)
        S_x, S_y: Starting coordinates (tile containing (S_x + 0.5, S_y + 0.5))
        T_x, T_y: Target coordinates (tile containing (T_x + 0.5, T_y + 0.5))

    Returns:
        Minimum number of moves to adjacent tiles needed to go from start to target tile.

    >>> min_tile_moves(3, -2, 1, 4, -1)
    4
    >>> min_tile_moves(4, 8, 8, 0, 2)
    4
    >>> min_tile_moves(5, -1000000000000, -1000000000000, 1000000000000, 1000000000000)
    800000000000
    """
    def rect2(t):
        i, j, k = t
        if (i - j) % 2 == 0:
            x0, y0, x1, y1 = i * K, j * K + k, (i + 1) * K, j * K + k + 1
        else:
            x0, y0, x1, y1 = i * K + k, j * K, i * K + k + 1, (j + 1) * K
        return (2 * x0, 2 * y0, 2 * x1, 2 * y1)

    def tile_containing(px2, py2):
        bi = (px2 // 2) // K
        bj = (py2 // 2) // K
        for i in range(bi - 1, bi + 2):
            for j in range(bj - 1, bj + 2):
                for k in range(K):
                    x0, y0, x1, y1 = rect2((i, j, k))
                    if x0 < px2 < x1 and y0 < py2 < y1:
                        return (i, j, k)
        return None

    def neighbors(t):
        # Candidate neighbors: tiles in the 3x3 block neighborhood sharing an edge.
        i, j, k = t
        out = []
        for di in (-1, 0, 1):
            for dj in (-1, 0, 1):
                if di == 0 and dj == 0:
                    continue
                for nk in (0, 1, K - 1, k - 1, k, k + 1):
                    if 0 <= nk < K:
                        cand = (i + di, j + dj, nk)
                        if adjacent(t, cand):
                            out.append(cand)
        return out

    def adjacent(a, b):
        ax0, ay0, ax1, ay1 = rect2(a)
        bx0, by0, bx1, by1 = rect2(b)
        if ax1 == bx0 or bx1 == ax0:
            if min(ay1, by1) - max(ay0, by0) > 0:
                return True
        if ay1 == by0 or by1 == ay0:
            if min(ax1, bx1) - max(ax0, bx0) > 0:
                return True
        return False

    start = tile_containing(2 * S_x + 1, 2 * S_y + 1)
    target = tile_containing(2 * T_x + 1, 2 * T_y + 1)
    if start is None or target is None:
        return -1
    if start == target:
        return 0

    dist = {start: 0}
    pq = [(0, start)]
    while pq:
        d, cur = heapq.heappop(pq)
        if cur == target:
            return d
        if d > dist.get(cur, float('inf')):
            continue
        for nb in neighbors(cur):
            nd = d + 1
            if nd < dist.get(nb, float('inf')):
                dist[nb] = nd
                heapq.heappush(pq, (nd, nb))
    return -1

from fractions import Fraction

def expected_operations_bruteforce(N: int, M: int) -> int:
    # Exact expected cover time via solving linear equations over the states
    # (current vertex, frozenset of painted vertices) is exponential; this
    # version only works for very small N*M.
    import itertools
    V = N * M + 1
    adj = {v: [] for v in range(V)}
    for i in range(1, V):
        p = max(i - N, 0)
        adj[i].append(p)
        adj[p].append(i)
    full = (1 << V) - 1
    from functools import lru_cache
    @lru_cache(maxsize=None)
    def E(v, mask):
        if mask == full:
            return Fraction(0)
        total = Fraction(0)
        for u in adj[v]:
            nmask = mask | (1 << u)
            total += 1 + E(u, nmask)
        return total / len(adj[v])
    return int(E(0, 1)) % 998244353

