MOD = 998244353

def expected_operations(N: int, M: int) -> int:
    V = N * M + 1
    adj = [[] for _ in range(V)]
    for i in range(1, V):
        p = max(i - N, 0)
        adj[i].append(p)
        adj[p].append(i)

    full = (1 << V) - 1
    memo = {}

    def E(v, mask):
        if mask == full:
            return Fraction(0)
        key = (v, mask)
        if key in memo:
            return memo[key]
        total = Fraction(0)
        for u in adj[v]:
            nmask = mask | (1 << u)
            total += 1 + E(u, nmask)
        res = total / len(adj[v])
        memo[key] = res
        return res

    val = E(0, 1)
    return val.numerator % MOD * pow(val.denominator % MOD, MOD - 2, MOD) % MOD

from functools import lru_cache

def can_color_all_points(n: int, k: int) -> bool:
    """Exact game search: returns True if all n points can be colored black."""
    # Reflection symmetry about the line from a player through the center
    # pairs point i with point (2p - i) mod n for the player's position p.
    # State: frozenset of black points and whose turn it is (implicit by count).
    # Players alternate starting with Alice (at 0); Bob is at k.
    # Each move colors one white point so the black set stays symmetric
    # about the current player's axis. Cooperative maximization means we
    # search for any sequence that colors everything.

    full = (1 << n) - 1

    def symmetric_partners(mask, pos):
        # Points that can be colored together with a new point c so that
        # the black pattern is symmetric about the axis through pos.
        return None

    @lru_cache(maxsize=None)
    def reachable(mask, turn):
        if mask == full:
            return True
        pos = 0 if turn == 0 else k
        for c in range(n):
            if mask & (1 << c):
                continue
            new_mask = mask | (1 << c)
            # Symmetry check about the axis through pos: the reflection of c
            # across the axis through pos must also be black (or be c itself).
            r = (2 * pos - c) % n
            if r != c and not (new_mask & (1 << r)):
                continue
            if reachable(new_mask, 1 - turn):
                return True
        return False

    return reachable(0, 0)

def can_color_all_points(n: int, k: int) -> bool:
    # Hypothesis: the game fails only when n is even and Bob's position
    # is an odd multiple of n/2's gcd structure. Check: n even, and
    # the gap d = min(k, n-k) has the same parity as n/2 with d not 0.
    if n % 2 == 1:
        return True
    d = min(k, n - k)
    half = n // 2
    return (d % 2) != (half % 2)

def count_good_arrays(n: int, m: int, k: int) -> int:
    MOD = 10**9 + 7

    N = n - 1
    fact = [1] * (N + 1)
    for i in range(1, N + 1):
        fact[i] = fact[i - 1] * i % MOD

    def mod_inv(a: int) -> int:
        return pow(a, MOD - 2, MOD)

    comb = fact[N] * mod_inv(fact[k]) % MOD * mod_inv(fact[N - k]) % MOD
    ways = m % MOD * pow(m - 1, N - k, MOD) % MOD

    return comb * ways % MOD

