def sum_concatenated_permutations(n: int) -> int:
    MOD = 998244353

    fact = [1] * (n + 1)
    for i in range(1, n + 1):
        fact[i] = fact[i - 1] * i % MOD
    inv_fact = [1] * (n + 1)
    inv_fact[n] = pow(fact[n], MOD - 2, MOD)
    for i in range(n, 0, -1):
        inv_fact[i - 1] = inv_fact[i] * i % MOD

    def C(a, b):
        if b < 0 or b > a or a < 0:
            return 0
        return fact[a] * inv_fact[b] % MOD * inv_fact[a - b] % MOD

    groups = []
    lo, L = 1, 1
    while lo <= n:
        hi = min(n, 10 ** L - 1)
        c = hi - lo + 1
        s = (lo + hi) * c // 2 % MOD
        groups.append((pow(10, L, MOD), c, s))
        lo = hi + 1
        L += 1

    def mul(a, b):
        # Polynomial multiplication truncated to degree n
        res = [0] * (n + 1)
        for i, x in enumerate(a):
            if x == 0:
                continue
            for j, y in enumerate(b):
                if i + j > n:
                    break
                res[i + j] = (res[i + j] + x * y) % MOD
        return res

    def binom_power(q, c):
        # Coefficients of (1 + q z)^c, truncated to degree min(c, n)
        d = min(c, n)
        return [C(c, j) * pow(q, j, MOD) % MOD for j in range(d + 1)]

    # P(z) = prod over groups of (1 + q z)^c
    P = [1]
    for q, c, s in groups:
        P = mul(P, binom_power(q, c))

    # H(z) = sum over groups g of s_g * q_g z * (1 + q_g z)^{c_g - 1} * prod_{L != g} (1+q_L z)^{c_L}
    H = [0] * (n + 1)
    for gi, (q, c, s) in enumerate(groups):
        term = [1]
        for hj, (q2, c2, _) in enumerate(groups):
            cc = c2 - 1 if hj == gi else c2
            if cc < 0:
                term = []
                break
            term = mul(term, binom_power(q2, cc))
        if not term:
            continue
        shifted = [0] * (n + 1)
        for j, x in enumerate(term):
            if j + 1 <= n:
                shifted[j + 1] = x * q % MOD * s % MOD
        H = [(a + b) % MOD for a, b in zip(H, shifted)]

    A = n * (n + 1) // 2 % MOD
    total = 0
    for t in range(n):
        coef = fact[t] * fact[n - 1 - t] % MOD
        total = (total + coef * ((A * P[t] - H[t]) % MOD)) % MOD
    return total % MOD

def sum_concatenated_permutations(n: int) -> int:
    MOD = 998244353
    G = 3

    def ntt(a, invert):
        n_ = len(a)
        j = 0
        for i in range(1, n_):
            bit = n_ >> 1
            while j & bit:
                j ^= bit
                bit >>= 1
            j ^= bit
            if i < j:
                a[i], a[j] = a[j], a[i]
        length = 2
        while length <= n_:
            w = pow(G, (MOD - 1) // length, MOD)
            if invert:
                w = pow(w, MOD - 2, MOD)
            half = length >> 1
            wp = [1] * half
            for k in range(1, half):
                wp[k] = wp[k - 1] * w % MOD
            for i in range(0, n_, length):
                for k in range(half):
                    u = a[i + k]
                    v = a[i + k + half] * wp[k] % MOD
                    a[i + k] = (u + v) % MOD
                    a[i + k + half] = (u - v) % MOD
            length <<= 1
        if invert:
            inv_n = pow(n_, MOD - 2, MOD)
            for i in range(n_):
                a[i] = a[i] * inv_n % MOD

    def mul(a, b):
        # Multiply polynomials mod MOD, truncated to degree n
        if not a or not b:
            return []
        need = len(a) + len(b) - 1
        size = 1
        while size < need:
            size <<= 1
        if min(len(a), len(b)) <= 32:
            res = [0] * need
            for i, x in enumerate(a):
                if x == 0:
                    continue
                for j, y in enumerate(b):
                    res[i + j] = (res[i + j] + x * y) % MOD
        else:
            fa = a + [0] * (size - len(a))
            fb = b + [0] * (size - len(b))
            ntt(fa, False)
            ntt(fb, False)
            for i in range(size):
                fa[i] = fa[i] * fb[i] % MOD
            ntt(fa, True)
            res = fa[:need]
        return res[:n + 1]

    # Factorials
    fact = [1] * (n + 1)
    for i in range(1, n + 1):
        fact[i] = fact[i - 1] * i % MOD
    inv_fact = [1] * (n + 1)
    inv_fact[n] = pow(fact[n], MOD - 2, MOD)
    for i in range(n, 0, -1):
        inv_fact[i - 1] = inv_fact[i] * i % MOD

    def C(a, b):
        if b < 0 or a < 0 or b > a:
            return 0
        return fact[a] * inv_fact[b] % MOD * inv_fact[a - b] % MOD

    # Digit-length groups: (q = 10^L, count c, value sum s)
    groups = []
    lo, L = 1, 1
    while lo <= n:
        hi = min(n, 10 ** L - 1)
        c = hi - lo + 1
        s = (lo + hi) * c // 2 % MOD
        groups.append((pow(10, L, MOD), c, s))
        lo = hi + 1
        L += 1

    def binom_power(q, c):
        # Coefficients of (1 + q z)^c up to degree min(c, n)
        d = min(c, n)
        out = [0] * (d + 1)
        qp = 1
        for j in range(d + 1):
            out[j] = C(c, j) * qp % MOD
            qp = qp * q % MOD
        return out

    # P(z) = prod (1 + q z)^c
    P = [1]
    for q, c, _ in groups:
        P = mul(P, binom_power(q, c))
    P = P + [0] * (n + 1 - len(P))

    # H(z) = sum_g s_g * q_g z * (1 + q_g z)^{c_g - 1} * prod_{other L} (1 + q_L z)^{c_L}
    H = [0] * (n + 1)
    for gi, (q, c, s) in enumerate(groups):
        term = [1]
        for hj, (q2, c2, _) in enumerate(groups):
            cc = c2 - 1 if hj == gi else c2
            term = mul(term, binom_power(q2, cc))
        for j, x in enumerate(term):
            if j + 1 <= n:
                H[j + 1] = (H[j + 1] + x * q % MOD * s) % MOD

    A = n * (n + 1) // 2 % MOD
    total = 0
    for t in range(n):
        coef = fact[t] * fact[n - 1 - t] % MOD
        total = (total + coef * ((A * P[t] - H[t]) % MOD)) % MOD
    return total % MOD

def count_good_integers(num1: str, num2: str, min_sum: int, max_sum: int) -> int:
    MOD = 10**9 + 7

    def count_upto(s: str) -> int:
        # Count integers x in [0, int(s)] with min_sum <= digit_sum(x) <= max_sum
        n = len(s)
        # ways[k][t] = number of digit strings of length k with digit sum t
        # (leading zeros allowed), capped at max_sum
        ways = [[0] * (max_sum + 1) for _ in range(n + 1)]
        ways[0][0] = 1
        for k in range(1, n + 1):
            for t in range(max_sum + 1):
                total = 0
                for d in range(10):
                    if t - d >= 0:
                        total += ways[k - 1][t - d]
                ways[k][t] = total % MOD

        result = 0
        prefix_sum = 0
        for i, ch in enumerate(s):
            cur = int(ch)
            remaining = n - i - 1
            for d in range(cur):
                for t in range(max_sum + 1):
                    if 0 <= t - prefix_sum - d <= max_sum:
                        pass
                # Count completions where total digit sum lies in [min_sum, max_sum]
                base = prefix_sum + d
                lo = max(0, min_sum - base)
                hi = max_sum - base
                if hi >= 0:
                    for t in range(lo, hi + 1):
                        if t <= max_sum:
                            result = (result + ways[remaining][t]) % MOD
            prefix_sum += cur
            if prefix_sum > max_sum:
                break
