    MOD = 998244353
    if k > n:
        return 1

    m = k - 1
    size = 1 << m
    mask_all = size - 1

    def window_is_palindrome(w: int) -> bool:
        for i in range(k // 2):
            if ((w >> i) & 1) != ((w >> (k - 1 - i)) & 1):
                return False
        return True

