            return (0,)
        if ch == 'B':
            return (1,)
        return (0, 1)

    dp = [0] * size
    for mask in range(size):
        valid = True
        for pos in range(m):
            bit = (mask >> (m - 1 - pos)) & 1
            if bit not in allowed(s[pos]):
