from typing import List


def count_arithmetic_subsequences(n: int, a: List[int]) -> List[int]:
    MOD = 998244353
    # f[i][j][k] = number of arithmetic subsequences of length k whose
    # last two positions are j < i (last element a[i]).
    f = [[[0] * (n + 1) for _ in range(n)] for _ in range(n)]
    res = [0] * (n + 1)
    res[1] = n  # every single element

    for i in range(n):
        for j in range(i):
            f[i][j][2] = 1  # the pair (j, i) itself
            d = a[i] - a[j]
            for p in range(j):
                if a[j] - a[p] == d:
                    for k in range(2, n):
                        f[i][j][k + 1] = (f[i][j][k + 1] + f[j][p][k]) % MOD
            for k in range(2, n + 1):
                res[k] = (res[k] + f[i][j][k]) % MOD

    return res[1:]

