def minimum_shipping_dissatisfaction(n: int, k: int, x: int, order_days: List[int]) -> int:
    INF = float("inf")
    # dp[i] = list of (last_ship_day, min_cost) pairs for the first i orders,
    # kept as a Pareto frontier (earlier ship day and lower cost are both better).
    dp = [[] for _ in range(n + 1)]
    dp[0] = [(-(10**18), 0)]
    for i in range(1, n + 1):
        best = {}
        for j in range(max(0, i - k), i):
            batch_last = order_days[i - 1]
            batch_cost_base = sum(batch_last - order_days[t] for t in range(j, i))
            for prev_day, prev_cost in dp[j]:
                ship = max(batch_last, prev_day + x)
                cost = prev_cost + batch_cost_base + (ship - batch_last) * (i - j)
                if ship not in best or best[ship] > cost:
                    best[ship] = cost
        # Pareto prune: keep entries where a later ship day has strictly lower cost
        items = sorted(best.items())
        frontier = []
        min_cost = INF
        for day, cost in reversed(items):
            if cost < min_cost:
                frontier.append((day, cost))
                min_cost = cost
        dp[i] = sorted(frontier)
    return min(cost for _, cost in dp[n])

