from functools import lru_cache


def minimum_shipping_dissatisfaction(n: int, k: int, x: int, order_days: List[int]) -> int:
    @lru_cache(maxsize=None)
    def solve(i: int, prev_ship: int) -> int:
        # i = index of first unshipped order; prev_ship = day of last shipment
        if i == n:
            return 0
        best = float("inf")
        for j in range(i, min(n, i + k)):
            # batch covers orders i..j, placed on day order_days[j] at the latest
            ship = max(order_days[j], prev_ship + x)
            cost = sum(ship - order_days[t] for t in range(i, j + 1))
            best = min(best, cost + solve(j + 1, ship))
        return best

    return solve(0, -10**18)

