def min_ng_list_size(n: int, product_names: List[str]) -> int:
    parent = list(range(26))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[ra] = rb

    out_deg = [0] * 26
    in_deg = [0] * 26
    used = [False] * 26

    for name in product_names:
        u = ord(name[0]) - ord('A')
        v = ord(name[1]) - ord('A')
        out_deg[u] += 1
        in_deg[v] += 1
        used[u] = True
        used[v] = True
        union(u, v)

    comp_excess = {}
    comp_has_edge = {}
    for v in range(26):
        if not used[v]:
            continue
        r = find(v)
        comp_has_edge[r] = True
        comp_excess[r] = comp_excess.get(r, 0) + max(0, out_deg[v] - in_deg[v])

    total = 0
    for r in comp_has_edge:
        total += max(1, comp_excess.get(r, 0))
    return total

