def min_ng_list_size(n: int, product_names: List[str]) -> int:
    edges = []
    for name in product_names:
        u = ord(name[0]) - ord('A')
        v = ord(name[1]) - ord('A')
        edges.append((u, v))
    m = len(edges)
    if m == 0:
        return 0

    # Weakly connected components over vertices touched by edges.
    parent = list(range(26))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    for u, v in edges:
        ru, rv = find(u), find(v)
        if ru != rv:
            parent[ru] = rv

    groups = {}
    for idx, (u, v) in enumerate(edges):
        groups.setdefault(find(u), []).append(idx)

    def covers_with(comp_edges, k):
        # Can the edges of this component be covered by k walks?
        # Each walk is a chain of edges; overlaps are allowed, so we
        # track which edges are still uncovered.
        target = frozenset(comp_edges)
        memo = set()

        def search(uncovered, walks_left):
            if not uncovered:
                return True
            if walks_left == 0:
                return False
            key = (uncovered, walks_left)
            if key in memo:
                return False
            memo.add(key)
            # Start a new walk from any uncovered edge, then extend it.
            for start in uncovered:
                if extend(start, uncovered, walks_left):
                    return True
            return False

        def extend(start, uncovered, walks_left):
            # Build one walk greedily-exhaustive from edge `start`.
            # Explore all walks by DFS; each walk may cover uncovered edges.
            stack = [(start, uncovered - {start}, edges[start][1])]
            seen = set()
            while stack:
                cur, rem, end = stack.pop()
                if (rem, end) in seen:
                    continue
                seen.add((rem, end))
                if search(rem, walks_left - 1):
                    return True
                for idx in comp_edges:
                    u, v = edges[idx]
                    if idx in rem and u == end:
                        stack.append((idx, rem - {idx}, v))
                # Allow the walk to stop here and cover nothing more.
            return False

        return search(target, k)

    total = 0
    for comp_edges in groups.values():
        k = 1
        while not covers_with(comp_edges, k):
            k += 1
        total += k
    return total

