        v = ord(name[1]) - ord('A')
        edges.append((u, v))
    if not edges:
        return 0

    parent = list(range(26))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    for u, v in edges:
        ru, rv = find(u), find(v)
        if ru != rv:
            parent[ru] = rv

    groups = {}
    for idx, (u, v) in enumerate(edges):
        groups.setdefault(find(u), []).append(idx)

    def can_cover(comp, k):
        # Cover all edges in comp with at most k walks.
        # Walks may traverse any edge in the component, including ones
        # already covered, so the walk state is (current vertex, uncovered set).
        all_edges = frozenset(comp)
        memo = {}

        def solve(uncovered, walks_left):
            if not uncovered:
                return True
            if walks_left == 0:
                return False
            key = (uncovered, walks_left)
            if key in memo:
                return memo[key]
            result = False
            # Start a new walk at the tail of some uncovered edge.
            for e in uncovered:
                start_vertex = edges[e][0]
                if walk(start_vertex, uncovered, walks_left, 0):
                    result = True
                    break
            memo[key] = result
            return result

        def walk(vertex, uncovered, walks_left, steps):
            # Option 1: end this walk here and move on.
            if solve(uncovered, walks_left - 1):
                return True
            # Limit walk length to keep the search finite.
            if steps > len(comp):
                return False
            # Option 2: take any edge out of the current vertex.
            for e in comp:
                u, v = edges[e]
                if u == vertex:
                    new_uncovered = uncovered - {e}
                    if walk(v, new_uncovered, walks_left, steps + 1):
                        return True
            return False

        return solve(all_edges, k)

    total = 0
    for comp in groups.values():
        k = 1
        while not can_cover(comp, k):
            k += 1
        total += k
    return total

