def min_ng_list_size(n: int, product_names: List[str]) -> int:
    parent = list(range(26))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    out_deg = [0] * 26
    in_deg = [0] * 26
    used = [False] * 26

    for name in product_names:
        u = ord(name[0]) - ord('A')
        v = ord(name[1]) - ord('A')
        out_deg[u] += 1
        in_deg[v] += 1
        used[u] = used[v] = True
        ru, rv = find(u), find(v)
        if ru != rv:
            parent[ru] = rv

    sink_sum = {}
    has_edge = {}
    for v in range(26):
        if not used[v]:
            continue
        r = find(v)
        has_edge[r] = True
        sink_sum[r] = sink_sum.get(r, 0) + max(0, in_deg[v] - out_deg[v])

    total = 0
    for r in has_edge:
        total += max(1, sink_sum.get(r, 0))
    return total

