def min_team_switches(people: List[Tuple[int, int]]) -> int:
    """ Given a list of people where each person is represented as (team_number, strength),
    determine the minimum number of people who need to switch teams so that all three teams
    have equal total strength. Teams are numbered 1, 2, and 3.

    Each person belongs to exactly one team and has a strength value. The strength of a team
    is the sum of strengths of all its members. Return -1 if it's impossible to make all
    teams have equal strength.

    Args:
        people: List of tuples (team_number, strength) where team_number is in {1, 2, 3}
                and strength is a positive integer.

    Returns:
        The minimum number of people who need to switch teams, or -1 if impossible.

    >>> min_team_switches([(1, 2), (2, 5), (1, 5), (3, 3), (1, 3), (3, 6)])
    2
    >>> min_team_switches([(1, 1), (1, 2), (2, 3), (3, 4)])
    -1
    >>> min_team_switches([(1, 1), (2, 1), (3, 1)])
    0
    """
    totals = {1: 0, 2: 0, 3: 0}
    members = {1: [], 2: [], 3: []}
    for team, strength in people:
        totals[team] += strength
        members[team].append(strength)

    grand = totals[1] + totals[2] + totals[3]
    if grand % 3 != 0:
        return -1
    target = grand // 3

    # Net amount each team must give away (positive) or receive (negative).
    surplus = {t: totals[t] - target for t in (1, 2, 3)}

    # For every team, precompute the best (fewest-people) way to remove exactly
    # a given amount of strength, using a DP over sums: removal_cost[t][s] is the
    # minimum number of members of team t whose strengths sum to exactly s.
    def min_count_for_sum(strengths, max_sum):
        INF = float("inf")
        dp = [INF] * (max_sum + 1)
        dp[0] = 0
        for s in strengths:
            for v in range(max_sum, s - 1, -1):
                if dp[v - s] + 1 < dp[v]:
                    dp[v] = dp[v - s] + 1
        return dp

    # Try every combination of how much each team sends to each other team.
    # Let x[a][b] be the strength moved from team a to team b (a != b).
    # Balance: for each team, out - in = surplus. There are 6 flows, and the
    # three balance equations leave 3 free variables; we enumerate them.
    best = -1
    pairs = [(1, 2), (1, 3), (2, 1), (2, 3), (3, 1), (3, 2)]

    # Upper bound on the amount any single flow can carry.
    cap = {t: totals[t] for t in (1, 2, 3)}

    # Precompute minimal person counts for every achievable removal sum per team.
    removal = {}
    for t in (1, 2, 3):
        removal[t] = min_count_for_sum(members[t], cap[t])

    def can_send(t, amount):
        if amount < 0 or amount > cap[t]:
            return None
        return removal[t][amount] if removal[t][amount] != float("inf") else None

    for x12 in range(cap[1] + 1):
        for x13 in range(cap[1] + 1 - x12):
            out1 = x12 + x13
            # team 1 net: out1 - in1 = surplus[1]; in1 = x21 + x31
            # Solve for x21 and x31 later; first pick x23 and x32 choices.
            for x23 in range(cap[2] + 1):
                for x21 in range(cap[2] + 1 - x23):
                    # team 2: out2 = x21 + x23, in2 = x12 + x32
                    # x32 determined by team 2 balance
                    x32 = (x21 + x23) - surplus[2] - x12
                    if x32 < 0:
                        continue
                    x31 = out1 - surplus[1] - x21
                    if x31 < 0:
                        continue
                    # team 3 balance: out3 = x31 + x32, in3 = x13 + x23
                    if (x31 + x32) - (x13 + x23) != surplus[3]:
                        continue
                    flows = {(1, 2): x12, (1, 3): x13, (2, 1): x21,
                             (2, 3): x23, (3, 1): x31, (3, 2): x32}
                    total_moved = 0
                    ok = True
                    for t in (1, 2, 3):
                        out_amount = sum(v for (a, b), v in flows.items() if a == t)
                        cnt = can_send(t, out_amount)
                        if cnt is None:
                            ok = False
                            break
                        total_moved += cnt
                    if not ok:
                        continue
                    if best == -1 or total_moved < best:
                        best = total_moved
    return best

