def min_team_switches(people: List[Tuple[int, int]]) -> int:
    """ Given a list of people where each person is represented as (team_number, strength),
    determine the minimum number of people who need to switch teams so that all three teams
    have equal total strength. Teams are numbered 1, 2, and 3.

    Each person belongs to exactly one team and has a strength value. The strength of a team
    is the sum of strengths of all its members. Return -1 if it's impossible to make all
    teams have equal strength.

    Args:
        people: List of tuples (team_number, strength) where team_number is in {1, 2, 3}
                and strength is a positive integer.

    Returns:
        The minimum number of people who need to switch teams, or -1 if impossible.

    >>> min_team_switches([(1, 2), (2, 5), (1, 5), (3, 3), (1, 3), (3, 6)])
    2
    >>> min_team_switches([(1, 1), (1, 2), (2, 3), (3, 4)])
    -1
    >>> min_team_switches([(1, 1), (2, 1), (3, 1)])
    0
    """
    totals = {1: 0, 2: 0, 3: 0}
    for team, strength in people:
        totals[team] += strength

    grand = totals[1] + totals[2] + totals[3]
    if grand % 3 != 0:
        return -1
    target = grand // 3

    # Net strength each team must lose (positive) or gain (negative).
    delta = {t: totals[t] - target for t in (1, 2, 3)}

    # Each moved person i leaves team src_i and joins some other team dst_i.
    # Let the signed contribution to team t be:
    #   -strength for leaving t, +strength for arriving at t.
    # Requirement: for each t, (arrivals - departures) == -delta[t].
    #
    # Because a person's strength is removed from its source and added to its
    # destination, the choice of which people move is the only real decision;
    # the destination only needs to be a team other than the source.
    #
    # Let f[t] = sum of strengths of moved people originating from team t.
    # We need to route them so that each team gets the right net amount.
    # Using a DP over (count) grouped by strength is complex; instead we do a
    # direct search over how many people (by index) leave each team, which is
    # bounded by n, and compute the net balance with subset-sum DP per team.
    from functools import lru_cache

    n_by_team = {t: [s for (tt, s) in people if tt == t] for t in (1, 2, 3)}

    # reach[t][k] = dict mapping sum-of-removed-strengths -> min count, over subsets of team t
    def removal_table(strengths):
        table = {0: 0}
        for s in strengths:
            new = dict(table)
            for total_s, cnt in table.items():
                ns = total_s + s
                if ns not in new or cnt + 1 < new[ns]:
                    new[ns] = cnt + 1
            table = new
        return table

    tables = {t: removal_table(n_by_team[t]) for t in (1, 2, 3)}

    best = -1
    for s1, c1 in tables[1].items():
        for s2, c2 in tables[2].items():
            for s3, c3 in tables[3].items():
                removed = {1: s1, 2: s2, 3: s3}
                # Net requirement per team: removed[t] - arrived[t] == delta[t]
                # so arrived[t] = removed[t] - delta[t] must be >= 0.
                arrived = {t: removed[t] - delta[t] for t in (1, 2, 3)}
                if any(a < 0 for a in arrived.values()):
                    continue
                if sum(arrived.values()) != sum(removed.values()):
                    continue
                # Each team's arrivals must come from other teams' departures.
                ok = True
                for t in (1, 2, 3):
                    others = sum(removed[u] for u in (1, 2, 3) if u != t)
                    if arrived[t] > others:
                        ok = False
                        break
                if not ok:
                    continue
                moved = c1 + c2 + c3
                if moved == 0 and any(delta[t] != 0 for t in (1, 2, 3)):
                    continue
                if best == -1 or moved < best:
                    best = moved
    return best

