def min_team_switches(people: List[Tuple[int, int]]) -> int:
    """ Given a list of people where each person is represented as (team_number, strength),
    determine the minimum number of people who need to switch teams so that all three teams
    have equal total strength. Teams are numbered 1, 2, and 3.

    Each person belongs to exactly one team and has a strength value. The strength of a team
    is the sum of strengths of all its members. Return -1 if it's impossible to make all
    teams have equal strength.

    Args:
        people: List of tuples (team_number, strength) where team_number is in {1, 2, 3}
                and strength is a positive integer.

    Returns:
        The minimum number of people who need to switch teams, or -1 if impossible.

    >>> min_team_switches([(1, 2), (2, 5), (1, 5), (3, 3), (1, 3), (3, 6)])
    2
    >>> min_team_switches([(1, 1), (1, 2), (2, 3), (3, 4)])
    -1
    >>> min_team_switches([(1, 1), (2, 1), (3, 1)])
    0
    """
    totals = {1: 0, 2: 0, 3: 0}
    members = {1: [], 2: [], 3: []}
    for team, strength in people:
        totals[team] += strength
        members[team].append(strength)

    grand = totals[1] + totals[2] + totals[3]
    if grand % 3 != 0:
        return -1
    target = grand // 3

    # For each team, the minimum number of members needed to leave so that the
    # leaving strength equals a given value. Computed over a 0/1 knapsack.
    INF = float("inf")

    def min_leave_table(strengths):
        # table[v] = minimal count of members whose strengths sum to exactly v
        total = sum(strengths)
        table = [INF] * (total + 1)
        table[0] = 0
        for s in strengths:
            for v in range(total, s - 1, -1):
                if table[v - s] + 1 < table[v]:
                    table[v] = table[v - s] + 1
        return table

    tables = {t: min_leave_table(members[t]) for t in (1, 2, 3)}

    best = INF
    # Choose how much each team sends out in total (out[t]). Then the arrivals
    # must satisfy: totals[t] - out[t] + arrive[t] = target, with arrive summing
    # to the total out. Each team can only receive from the other two teams.
    for out1 in range(len(tables[1])):
        if tables[1][out1] == INF:
            continue
        for out2 in range(len(tables[2])):
            if tables[2][out2] == INF:
                continue
            for out3 in range(len(tables[3])):
                if tables[3][out3] == INF:
                    continue
                out = {1: out1, 2: out2, 3: out3}
                arrive = {t: target - totals[t] + out[t] for t in (1, 2, 3)}
                if any(a < 0 for a in arrive.values()):
                    continue
                if sum(arrive.values()) != sum(out.values()):
                    continue
                # A team cannot receive more than the other teams send out.
                if any(arrive[t] > sum(out[u] for u in (1, 2, 3) if u != t)
                       for t in (1, 2, 3)):
                    continue
                moved = tables[1][out1] + tables[2][out2] + tables[3][out3]
                if moved < best:
                    best = moved

    return -1 if best == INF else best

def count_paths(H: int, W: int, K: int, grid: list[str]) -> int:
    """Count walks of K moves on the grid starting from any empty cell.

    Cells may be revisited. Moves are up, down, left, right, and each
    visited cell must be empty ('.').
    """
    dirs = ((1, 0), (-1, 0), (0, 1), (0, -1))
    # ways[r][c] = number of walks ending at (r, c) with the moves made so far
    ways = [[1 if grid[r][c] == '.' else 0 for c in range(W)] for r in range(H)]
    for _ in range(K):
        nxt = [[0] * W for _ in range(H)]
        for r in range(H):
            for c in range(W):
                if grid[r][c] != '.':
                    continue
                for dr, dc in dirs:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < H and 0 <= nc < W and grid[nr][nc] == '.':
                        nxt[nr][nc] += ways[r][c]
        ways = nxt
    return sum(sum(row) for row in ways)

def count_paths(H: int, W: int, K: int, grid: list[str]) -> int:
    """Count simple directed paths of K moves on the grid, starting from any empty cell."""
    visited = [[False] * W for _ in range(H)]
    dirs = ((1, 0), (-1, 0), (0, 1), (0, -1))

    def dfs(r: int, c: int, moves_left: int) -> int:
        if moves_left == 0:
            return 1
        total = 0
        for dr, dc in dirs:
            nr, nc = r + dr, c + dc
            if 0 <= nr < H and 0 <= nc < W and grid[nr][nc] == '.' and not visited[nr][nc]:
                visited[nr][nc] = True
                total += dfs(nr, nc, moves_left - 1)
                visited[nr][nc] = False
        return total

    count = 0
    for i in range(H):
        for j in range(W):
            if grid[i][j] == '.':
                visited[i][j] = True
                count += dfs(i, j, K)
                visited[i][j] = False
    return count

