def count_valid_grids(H: int, W: int, grid: list[str]) -> int:
    MOD = 998244353

    # Make the profile width the smaller dimension.
    if W > H:
        g = [''.join(grid[r][c] for r in range(H)) for c in range(W)]
        H, W = W, H
        grid = g

    # frontier: tuple of length W; frontier[c] is the color of the most recent
    # cell placed in column c (0 means not yet placed).
    dp = {tuple([0] * W): 1}

    for r in range(H):
        for c in range(W):
            ch = grid[r][c]
            if ch == '?':
                options = (1, 2, 3)
            else:
                options = (int(ch),)
            ndp = {}
            for state, ways in dp.items():
                up = state[c]          # cell above (row r-1), 0 if none
                left = state[c - 1] if c > 0 else 0  # cell to the left (row r)
                for col in options:
                    if col == up or col == left:
                        continue
                    new_state = list(state)
                    new_state[c] = col
                    key = tuple(new_state)
                    ndp[key] = (ndp.get(key, 0) + ways) % MOD
            dp = ndp
            if not dp:
                return 0

    return sum(dp.values()) % MOD

