def matrix_with_k_fixed_elements_exists(n: int, k: int) -> bool:
    # Achievable fixed-entry counts for an n x n matrix are sums of squares
    # of block sizes that are fixed, with the remaining free part having size
    # 0 or at least 2 (a free m x m block with no fixed entries needs m != 1).
    # Count fixed entries as sum of s_i^2 over fixed blocks where the blocks
    # use total size at most n, and the leftover free block has size 0 or >= 2.
    if k < 0 or k > n * n:
        return False
    if k == n * n:
        return True

    # reachable[t] = True if some sum of squares of block sizes is t,
    # using total block size exactly `used`.
    # dp[used][total] = achievable total fixed count using blocks of total size `used`
    dp = [set() for _ in range(n + 1)]
    dp[0].add(0)
    for used in range(n + 1):
        for total in dp[used]:
            for s in range(1, n - used + 1):
                nxt = used + s
                if nxt <= n:
                    dp[nxt].add(total + s * s)

    for used in range(n + 1):
        free = n - used
        if free == 1:
            continue
        if k in dp[used]:
            return True
    return False

