def count_polish_sequences(n: int, a: list[int]) -> int:
    # need = number of subtrees still owed. Start need=1.
    # Reading value v at a position: need becomes need - 1 + v.
    # Sequence is Polish iff need reaches 0 exactly at position n
    # and is >= 1 at every earlier point.

    # ways[r][k]: number of ways to fill r remaining positions, starting with
    # need k (k >= 1), so that need hits 0 exactly after the last position.
    # ways[0][0] = 1; ways[0][k>0] = 0.
    # For r >= 1 and k >= 1: ways[r][k] = sum_{v=0}^{n-1} ways[r-1][k-1+v].
    # Need k-1+v <= n (beyond that it can't reach 0 in time), so cap k at n+1.
    M = n + 2
    ways = [[0] * (M + 1) for _ in range(n + 1)]
    ways[0][0] = 1
    for r in range(1, n + 1):
        # suffix sums of ways[r-1]
        suf = [0] * (M + 2)
        for t in range(M, -1, -1):
            suf[t] = (suf[t + 1] + ways[r - 1][t]) % MOD
        for k in range(1, M + 1):
            # sum over t = k-1 .. k-1+(n-1), capped at M
            lo = k - 1
            hi = min(M, k - 1 + n - 1)
            if lo > M:
                ways[r][k] = 0
            else:
                ways[r][k] = (suf[lo] - suf[hi + 1]) % MOD

    # Check whether a prefix a[0..d-1] is valid and its resulting need.
    # Return need after reading prefix, or None if need hit 0 early or invalid.
    def need_after(prefix):
        need = 1
        for v in prefix:
            if need <= 0:
                return None
            need = need - 1 + v
        return need

    total = 0

    # Case: sequence equals a exactly.
    full_need = need_after(a)
    if full_need is not None and full_need == 0:
        # need must reach 0 only at the end
        ok = True
        need = 1
        for i, v in enumerate(a):
            if need <= 0:
                ok = False
                break
            need = need - 1 + v
            if need == 0 and i != n - 1:
                ok = False
                break
        if ok:
            total += 1

    # Case: first strict-less position d, value x < a[d].
    need = 1
    for d in range(n):
        # prefix a[0..d-1] already applied to get need; need >= 1 required
        if need <= 0:
            break
        for x in range(a[d]):
            nn = need - 1 + x
            rem = n - d - 1
            if nn < 0:
                continue
            if rem == 0:
                if nn == 0:
                    total += 1
            else:
                if nn >= 1 and nn <= M:
                    total += ways[rem][nn]
        need = need - 1 + a[d]

    return total % MOD

