def count_good_string_replacements(n: int, k: int, s: str) -> int:
    from itertools import product

    def is_good(t: str) -> bool:
        # Greedy reduction: remove triples A,B,C or equal pairs until empty.
        # Use counts; a string is reducible iff it can be emptied by these ops.
        # Parity check: each operation removes an even number of characters
        # (2 or 3). Removing 3 is odd, so we need length >= 1 with feasible counts.
        m = len(t)
        if m == 0:
            return False
        cnt = [t.count('A'), t.count('B'), t.count('C')]
        # Try to reduce by removing ABC triples as many as possible, then pairs.
        # Feasibility: after removing x triples, remaining counts must all be even
        # and m - 3x must be even (automatically true if parity matches).
        for x in range(min(cnt) + 1):
            rem = [c - x for c in cnt]
            if all(r % 2 == 0 for r in rem) and sum(rem) % 2 == 0:
                if (m - 3 * x) % 2 == 0:
                    return True
        return False

    def count_good_substrings(t: str) -> int:
        total = 0
        for i in range(len(t)):
            for j in range(i + 1, len(t) + 1):
                if is_good(t[i:j]):
                    total += 1
        return total

    q_positions = [i for i, ch in enumerate(s) if ch == '?']
    if len(q_positions) > 12:
        # Fallback: too many replacements to brute force; count via DP is needed.
        return 0

    ways = 0
    for choice in product('ABC', repeat=len(q_positions)):
        t = list(s)
        for idx, ch in zip(q_positions, choice):
            t[idx] = ch
        if count_good_substrings(''.join(t)) >= k:
            ways += 1
    return ways % MOD

def count_k_reducible(s: str, k: int) -> int:
    MOD = 10**9 + 7
    L = len(s)

    # Binomial coefficients
    C = [[0] * (L + 1) for _ in range(L + 1)]
    for i in range(L + 1):
        C[i][0] = 1
        for j in range(1, i + 1):
            C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % MOD

    # reach_one(m, ops): can m reach 1 within ops operations (m >= 1)?
    def reach_one(m: int, ops: int) -> bool:
        if m == 1:
            return True
        if ops == 0:
            return False
        return reach_one(bin(m).count("1"), ops - 1)

    # A number y >= 2 is k-reducible iff popcount(y) reaches 1 within k-1 ops.
    # y == 1 is always k-reducible (0 operations needed).
    def is_good_popcount(c: int) -> bool:
        return reach_one(c, k - 1)

    # cnt[c] = number of integers in [0, n) with exactly c set bits
    cnt = [0] * (L + 1)
    ones_seen = 0
    for i, ch in enumerate(s):
        remaining = L - i - 1
        if ch == "1":
            # choose 0 at this position, remaining bits free
            for c in range(L + 1):
                need = c - ones_seen
                if 0 <= need <= remaining:
                    cnt[c] = (cnt[c] + C[remaining][need]) % MOD
            ones_seen += 1

    total = 0
    # Positive integers y < n, grouped by popcount c (y >= 1 excludes 0)
    for c in range(1, L + 1):
        if cnt[c] == 0:
            continue
        # y with popcount 1 is y = 2^j; y=1 is popcount 1 and is 0-reducible
        # For c = 1 all such y are powers of two, all k-reducible (1 is reducible,
        # and 2^j with j>=1 has popcount 1 -> 1 in one step, which needs k>=1: true).
        if c == 1 or is_good_popcount(c):
            total = (total + cnt[c]) % MOD

    return total % MOD

