            for c in range(L + 1):
                need = c - ones_seen
                if 0 <= need <= remaining:
                    cnt[c] = (cnt[c] + C[remaining][need]) % MOD
            ones_seen += 1

    total = 0
    # Count positive y < n: y = 1 has 0 steps; others counted by popcount c
    # y with popcount c >= 2 needs steps(c) + 1 operations total.
