def count_paths(W: int, H: int, L: int, R: int, D: int, U: int) -> int:
    def is_block(x, y):
        if x < 0 or x > W or y < 0 or y > H:
            return False
        return x < L or x > R or y < D or y > U

    prev = [0] * (H + 1)
    total = 0
    for x in range(W + 1):
        cur = [0] * (H + 1)
        for y in range(H + 1):
            if not is_block(x, y):
                continue
            v = 1
            if x > 0 and is_block(x - 1, y):
                v += prev[y]
            if y > 0 and is_block(x, y - 1):
                v += cur[y - 1]
            v %= MOD
            cur[y] = v
            total = (total + v) % MOD
        prev = cur
    return total

