from collections import deque

def can_transform_string(n: int, x: int, y: int, s: str, t: str) -> bool:
    """Return True if s can be turned into t by repeatedly swapping an adjacent
    block of x 0s and y 1s (in either order), per Operations A and B."""
    if len(s) != n or len(t) != n:
        return False
    if s == t:
        return True
    if s.count('0') != t.count('0'):
        return False

    L = x + y
    zeros_then_ones = '0' * x + '1' * y
    ones_then_zeros = '1' * y + '0' * x

    seen = {s}
    queue = deque([s])
    while queue:
        cur = queue.popleft()
        if cur == t:
            return True
        for i in range(n - L + 1):
            window = cur[i:i + L]
            if window == zeros_then_ones:
                nxt = cur[:i] + ones_then_zeros + cur[i + L:]
            elif window == ones_then_zeros:
                nxt = cur[:i] + zeros_then_ones + cur[i + L:]
            else:
                continue
            if nxt not in seen:
                seen.add(nxt)
                queue.append(nxt)
    return False

