from typing import List


def max_product_subsequence(nums: List[int], k: int, limit: int) -> int:
    """ Find a non-empty subsequence of nums that has an alternating sum equal to k
    and maximizes the product of all its numbers without exceeding limit.

    The alternating sum of a 0-indexed array is defined as the sum of elements at
    even indices minus the sum of elements at odd indices.

    Returns the largest product <= limit among qualifying subsequences, or -1 if none.
    """
    OFFSET = 12 * 150
    # dp[parity][sum + OFFSET] = set of achievable products (<= limit)
    # parity 0: next element is added (even position); parity 1: next is subtracted.
    dp = [[set() for _ in range(2 * OFFSET + 1)] for _ in range(2)]
    for x in nums:
        new_dp = [[set(s) for s in row] for row in dp]
        if x <= limit:
            new_dp[1][x + OFFSET].add(x)
        for parity in range(2):
            for idx in range(2 * OFFSET + 1):
                prods = dp[parity][idx]
                if not prods:
                    continue
                if parity == 0:
                    nidx, nparity = idx + x, 1
                else:
                    nidx, nparity = idx - x, 0
                if nidx < 0 or nidx > 2 * OFFSET:
                    continue
                for p in prods:
                    q = p * x
                    if q <= limit:
                        new_dp[nparity][nidx].add(q)
        dp = new_dp

    best = -1
    target = k + OFFSET
    if 0 <= target <= 2 * OFFSET:
        for parity in range(2):
            if dp[parity][target]:
                best = max(best, max(dp[parity][target]))
    return best

