def count_valid_colorings(n: int, m: int) -> int:
    MOD = 998244353
    base = (m - 1) % MOD
    term1 = pow(base, n, MOD)
    if n % 2 == 0:
        result = (term1 + base) % MOD
    else:
        result = (term1 - base) % MOD
    return result

