from typing import Optional, List


def solve_grid(n: int, r: str, c: str) -> Optional[List[str]]:
    """ Given an integer N and strings R and C of length N consisting of 'A', 'B', and 'C',
    determine if it's possible to fill an N×N grid such that:
    - Each row and column contains exactly one 'A', one 'B', and one 'C'
    - The leftmost character written in the i-th row matches the i-th character of R
    - The topmost character written in the i-th column matches the i-th character of C

    Empty cells are represented by '.' in the output.

    Args:
        n: The size of the grid (3 <= n <= 5)
        r: String of length n specifying leftmost characters in each row
        c: String of length n specifying topmost characters in each column

    Returns:
        A list of n strings representing the filled grid if possible, None otherwise.
        Each string has length n, where '.' represents empty cells.

    >>> solve_grid(3, 'ABC', 'ABC')
    ['ABC', 'BCA', 'CAB']
    >>> solve_grid(3, 'AAA', 'BBB')
    None
    """
    grid = [['.'] * n for _ in range(n)]
    letters = ['A', 'B', 'C']

    # Track which letters are used in each row/column
    row_used = [set() for _ in range(n)]
    col_used = [set() for _ in range(n)]

    def leftmost_ok(i: int) -> bool:
        for j in range(n):
            if grid[i][j] != '.':
                return grid[i][j] == r[i]
        return False

    def topmost_ok(j: int) -> bool:
        for i in range(n):
            if grid[i][j] != '.':
                return grid[i][j] == c[j]
        return False

    def row_complete(i: int) -> bool:
        return row_used[i] == set(letters)

    def col_complete(j: int) -> bool:
        return col_used[j] == set(letters)

    def check_row_final(i: int) -> bool:
        # Row must be complete (all three letters) and leftmost must match
        return row_complete(i) and leftmost_ok(i)

    def check_col_final(j: int) -> bool:
        return col_complete(j) and topmost_ok(j)

    def backtrack(pos: int) -> bool:
        if pos == n * n:
            for i in range(n):
                if not check_row_final(i):
                    return False
            for j in range(n):
                if not check_col_final(j):
                    return False
            return True

        i, j = divmod(pos, n)
        # Option: leave cell empty
        if backtrack(pos + 1):
            return True
        # Option: place a letter
        for ch in letters:
            if ch in row_used[i] or ch in col_used[j]:
                continue
            grid[i][j] = ch
            row_used[i].add(ch)
            col_used[j].add(ch)
            # Prune: if row i is finished (last column), ensure leftmost matches
            ok = True
            if j == n - 1 and not check_row_final(i):
                ok = False
            if i == n - 1 and not check_col_final(j):
                ok = False
            if ok and backtrack(pos + 1):
                return True
            grid[i][j] = '.'
            row_used[i].discard(ch)
            col_used[j].discard(ch)
        return False

    if backtrack(0):
        return [''.join(row) for row in grid]
    return None

def calculate_black_area_doubled(A: int, B: int, C: int, D: int) -> int:
    def prefix(X: int, Y: int) -> int:
        # Twice the black area in the region [0, X] x [0, Y] (X, Y >= 0),
        # extended to negative coordinates through inclusion-exclusion.
        # Each unit cell contributes 2 (fully black) or 1 (half black) in doubled units.
        # Cell (i, j) with lower-left corner (i, j): if (i + j) even, the cell is
        # split by the anti-diagonal into two triangles of which exactly one is black
        # per triangle pair; overall each cell contributes 1 black unit (doubled: 2).
        # Pure half-cells are accounted for by the diagonal structure: summing gives
        # doubled area = X * Y exactly for the balanced pattern, with a parity correction.
        if X <= 0 or Y <= 0:
            return 0
        return X * Y

    def area(X1: int, Y1: int, X2: int, Y2: int) -> int:
        return (prefix(X2, Y2) - prefix(X1, Y2)
                - prefix(X2, Y1) + prefix(X1, Y1))

    return area(A, B, C, D)

def calculate_black_area_doubled(A: int, B: int, C: int, D: int) -> int:
    def F(X: int, Y: int) -> int:
        if X <= 0 or Y <= 0:
            return 0
        # Each 2x2 period (area 4) has black doubled-area 4.
        px, rx = divmod(X, 2)
        py, ry = divmod(Y, 2)
        total = 4 * px * py
        # Remainder strips of width 1 along x and y.
        total += 2 * rx * py + 2 * ry * px
        # Remaining corner cell: black iff its lower-left corner has even coordinate sum.
        if rx and ry:
            total += 1
        return total

    return F(C, D) - F(A, D) - F(C, B) + F(A, B)

from collections import deque

def min_operations_to_rearrange(n: int, s: str, t: str) -> int:
    if sorted(s) != sorted(t):
        # Count of colors must be preserved, otherwise impossible
        return -1
    if s == t:
        return 0

    # State: tuple of length n+2, entries 'B', 'W', or '.' (empty)
    start = tuple(list(s) + ['.', '.'])
    goal_stones = tuple(t)

    def stones_of(state):
        return tuple(c for c in state if c != '.')

    def gap_pos(state):
        for i in range(len(state) - 1):
            if state[i] == '.' and state[i + 1] == '.':
                return i
        return None

    dist = {start: 0}
    q = deque([start])
    while q:
        state = q.popleft()
        d = dist[state]
        if state[:n] == goal_stones and state[n:] == ('.', '.'):
            return d
        e = gap_pos(state)
        if e is None:
            continue
        # choose adjacent occupied pair (i, i+1), not overlapping the gap
        for i in range(len(state) - 1):
            if state[i] == '.' or state[i + 1] == '.':
                continue
            new = list(state)
            a, b = state[i], state[i + 1]
            # clear the pair's original location
            new[i] = '.'
            new[i + 1] = '.'
            # place stones into the gap; gap positions are e and e+1
            # after clearing, the gap may have shifted; recompute
            # the empty cells in the new list are exactly the gap cells
            # plus the cleared pair, we fill the original gap cells e, e+1
            new[e] = a
            new[e + 1] = b
            ns = tuple(new)
            if ns not in dist:
                dist[ns] = d + 1
                q.append(ns)
    return -1

