def min_operations_to_rearrange(n: int, s: str, t: str) -> int:
    if s == t:
        return 0
    if s.count('B') != t.count('B'):
        return -1

    start = tuple(list(s) + ['.', '.'])
    goal = tuple(list(t) + ['.', '.'])

    dist = {start: 0}
    q = deque([start])
    while q:
        state = q.popleft()
        d = dist[state]
        if state == goal:
            return d

        # locate the gap (the two adjacent empty cells)
        e = None
        for i in range(len(state) - 1):
            if state[i] == '.' and state[i + 1] == '.':
                e = i
                break
        if e is None:
            continue

        # pick an adjacent pair of stones (i, i+1) disjoint from the gap
        for i in range(len(state) - 1):
            if i + 1 >= e and i <= e + 1:
                continue  # overlaps the gap region
            a, b = state[i], state[i + 1]
            if a == '.' or b == '.':
                continue
            new = list(state)
            new[e] = a
            new[e + 1] = b
            new[i] = '.'
            new[i + 1] = '.'
            ns = tuple(new)
            if ns not in dist:
                dist[ns] = d + 1
                q.append(ns)
    return -1

