from math import isqrt

def count_power_representations(n: int) -> int:
    if n < 1:
        return 0
    # Perfect squares (including 1 = 1^2)
    count = isqrt(n)
    # Non-square perfect powers with exponent >= 3
    seen = set()
    b = 3
    while 2 ** b <= n:
        a = 2
        while True:
            p = a ** b
            if p > n:
                break
            if isqrt(p) * isqrt(p) != p:  # not a perfect square
                seen.add(p)
            a += 1
        b += 1
    return count + len(seen)

