def count_power_representations(n: int) -> int:
    if n < 1:
        return 0

    def iroot(x: int, k: int) -> int:
        # largest integer r with r**k <= x
        lo, hi = 1, 1
        while hi ** k <= x:
            hi *= 2
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if mid ** k <= x:
                lo = mid
            else:
                hi = mid - 1
        return lo

    # Mobius function for small integers
    def mobius(m: int) -> int:
        res = 1
        d = 2
        while d * d <= m:
            if m % d == 0:
                m //= d
                if m % d == 0:
                    return 0
                res = -res
            d += 1
        if m > 1:
            res = -res
        return res

    # Count perfect powers in [2, n] with exponent >= 2:
    # numbers x = a^b with b >= 2 and x > 1 equal -sum_{k>=2} mu(k) * (iroot(n, k) - 1)
    total = 0
    for k in range(2, n.bit_length() + 1):
        mu = mobius(k)
        if mu != 0:
            total -= mu * (iroot(n, k) - 1)
    # Add 1 (since 1 = 1^2 is a perfect power and is excluded above)
    return total + 1

