    return T

def _berlekamp_massey(s):
    C, B = [1], [1]
    L, m, b = 0, 1, 1
    for i in range(len(s)):
        d = s[i]
        for j in range(1, L + 1):
            d = (d + C[j] * s[i - j]) % MOD
        if d == 0:
            m += 1
            continue
        coef = d * pow(b, MOD - 2, MOD) % MOD
        T = C[:]
        C = C + [0] * max(0, len(B) + m - len(C))
        for j in range(len(B)):
            C[j + m] = (C[j + m] - coef * B[j]) % MOD
        if 2 * L <= i:
            L, B, b, m = i + 1 - L, T, d, 1
        else:
            m += 1
    return [(-c) % MOD for c in C[1:L + 1]]

def _polymulmod(a, b, rec):
    L = len(rec)
    prod = [0] * (len(a) + len(b) - 1)
    for i, x in enumerate(a):
        if x:
            for j, y in enumerate(b):
                prod[i + j] = (prod[i + j] + x * y) % MOD
    for i in range(len(prod) - 1, L - 1, -1):
        c = prod[i]
        if c:
            prod[i] = 0
            for j in range(L):
                prod[i - L + j] = (prod[i - L + j] + c * rec[j]) % MOD
    res = prod[:L]
    return res + [0] * (L - len(res))

def _kitamasa(rec, init, n):
    L = len(rec)
    if n < len(init):
        return init[n]
    result = [1] + [0] * (L - 1)
    base = ([0, 1] + [0] * (L - 2)) if L >= 2 else [0]
    e = n
    while e:
        if e & 1:
            result = _polymulmod(result, base, rec)
        base = _polymulmod(base, base, rec)
        e >>= 1
    return sum(r * init[i] for i, r in enumerate(result)) % MOD

def sum_of_scores(n: int, m: int) -> int:
    K = 16
    T = _all_terms(m, K)
    prefix, acc = [], 0
    for t in T:
        acc = (acc + t) % MOD
        prefix.append(acc)
    if n < len(prefix):
        return (prefix[n] - 1) % MOD
    rec = _berlekamp_massey(prefix)
    return (_kitamasa(rec, prefix, n) - 1) % MOD

