from collections import deque

def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    def tile_of_point(px, py):
        # Tile containing (px + 0.5, py + 0.5), returned as (i, j, k).
        # Block indices: point lies in block (bi, bj) with offsets.
        bi = px // K
        bj = py // K
        if (bi - bj) % 2 == 0:
            # same parity: tile covers iK <= x <= (i+1)K, jK+k <= y <= jK+k+1
            i = bi
            k = (py - bj * K)
            j = bj
            return (i, j, k)
        else:
            # different parity: tile covers iK+k <= x <= iK+k+1, jK <= y <= (j+1)K
            j = bj
            k = (px - bi * K)
            i = bi
            return (i, j, k)

    def neighbors(tile):
        i, j, k = tile
        res = []
        # Candidate adjacent tiles: test by sampling the four sides of the tile
        # at points just outside it, then mapping those points to tiles.
        # Tile occupies x in some range and y in some range; compute its box.
        x_lo, x_hi, y_lo, y_hi = tile_box(tile)
        eps = 0.5
        # Sample points along each side (midpoints of unit segments suffice
        # since boundaries are on integer lattice).
        samples = []
        for y in range(y_lo, y_hi):
            samples.append((x_lo - eps, y + eps))
            samples.append((x_hi + eps, y + eps))
        for x in range(x_lo, x_hi):
            samples.append((x + eps, y_lo - eps))
            samples.append((x + eps, y_hi + eps))
        for sx, sy in samples:
            t = tile_of_point(int(sx - 0.5 + 0.5) if False else int(sx // 1), int(sy // 1))
            if t != tile and t not in res:
                res.append(t)
        return res

    def tile_box(tile):
        i, j, k = tile
        if (i - j) % 2 == 0:
            return (i * K, (i + 1) * K, j * K + k, j * K + k + 1)
        else:
            return (i * K + k, i * K + k + 1, j * K, (j + 1) * K)

    start = tile_of_point(S_x, S_y)
    target = tile_of_point(T_x, T_y)
    if start == target:
        return 0
    dist = {start: 0}
    q = deque([start])
    while q:
        cur = q.popleft()
        for nb in neighbors(cur):
            if nb not in dist:
                dist[nb] = dist[cur] + 1
                if nb == target:
                    return dist[nb]
                q.append(nb)
    return -1

from collections import deque

def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    def tile_of_point(px, py):
        bi = px // K
        bj = py // K
        if (bi - bj) % 2 == 0:
            return (bi, bj, py - bj * K)
        else:
            return (bi, bj, px - bi * K)

    def tile_box(tile):
        i, j, k = tile
        if (i - j) % 2 == 0:
            return (i * K, (i + 1) * K, j * K + k, j * K + k + 1)
        else:
            return (i * K + k, i * K + k + 1, j * K, (j + 1) * K)

    def neighbors(tile):
        x_lo, x_hi, y_lo, y_hi = tile_box(tile)
        res = set()
        for y in range(y_lo, y_hi):
            res.add(tile_of_point(x_lo - 1, y))
            res.add(tile_of_point(x_hi, y))
        for x in range(x_lo, x_hi):
            res.add(tile_of_point(x, y_lo - 1))
            res.add(tile_of_point(x, y_hi))
        res.discard(tile)
        return res

    start = tile_of_point(S_x, S_y)
    target = tile_of_point(T_x, T_y)
    if start == target:
        return 0

    # Bounded BFS: only feasible when K is small. For large K a closed form
    # is required, which I have not derived and verified.
    if K > 50:
        raise NotImplementedError("No verified closed form for large K yet.")

    dist = {start: 0}
    q = deque([start])
    limit = 10 * K + 10 * (abs(S_x) + abs(S_y) + abs(T_x) + abs(T_y)) // K + 100
    while q:
        cur = q.popleft()
        if cur == target:
            return dist[cur]
        for nb in neighbors(cur):
            if nb not in dist and dist[cur] < limit:
                dist[nb] = dist[cur] + 1
                q.append(nb)
    return -1

