def count_good_integers(num1: str, num2: str, min_sum: int, max_sum: int) -> int:
    MOD = 10**9 + 7

    def count_upto(s: str) -> int:
        # Count integers x in [0, int(s)] with min_sum <= digit_sum(x) <= max_sum
        # dp[t] = number of ways (prefixes, tight-free) to have digit sum t
        max_total = 9 * len(s)
        dp = [0] * (max_total + 1)  # free (already less than bound) prefixes
        tight_sum = 0
        for ch in s:
            d = int(ch)
            new_dp = [0] * (max_total + 1)
            # extend free prefixes with any digit 0..9
            for t in range(max_total + 1):
                if dp[t]:
                    for k in range(10):
                        if t + k <= max_total:
                            new_dp[t + k] = (new_dp[t + k] + dp[t]) % MOD
            # branch off from tight prefix: choose digit k < d
            for k in range(d):
                if tight_sum + k <= max_total:
                    new_dp[tight_sum + k] = (new_dp[tight_sum + k] + 1) % MOD
            tight_sum += d
            dp = new_dp
        # include the bound itself
        dp[tight_sum] = (dp[tight_sum] + 1) % MOD
        total = 0
        for t in range(max(min_sum, 0), min(max_sum, max_total) + 1):
            total = (total + dp[t]) % MOD
        return total

    def digit_sum(s: str) -> int:
        return sum(int(c) for c in s)

    result = count_upto(num2) - count_upto(num1)
    if min_sum <= digit_sum(num1) <= max_sum:
        result += 1
    return result % MOD

