def min_changes_for_semi_palindromes(s: str, k: int) -> int:
    n = len(s)

    # cost[i][j]: min changes to make s[i:j+1] a semi-palindrome
    cost = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(i + 1, n):
            length = j - i + 1
            best = float("inf")
            for d in range(1, length):
                if length % d != 0:
                    continue
                changes = 0
                for start in range(d):
                    # indices start, start+d, ... within [i, j]
                    idxs = list(range(i + start, j + 1, d))
                    l, r = 0, len(idxs) - 1
                    while l < r:
                        if s[idxs[l]] != s[idxs[r]]:
                            changes += 1
                        l += 1
                        r -= 1
                best = min(best, changes)
            cost[i][j] = best

    INF = float("inf")
    # dp[p][e]: min cost to split first e characters into p parts
    dp = [[INF] * (n + 1) for _ in range(k + 1)]
    dp[0][0] = 0
    for p in range(1, k + 1):
        for e in range(p, n + 1):
            for st in range(p - 1, e):
                if dp[p - 1][st] == INF:
                    continue
                c = dp[p - 1][st] + (cost[st][e - 1] if e - st >= 2 else INF)
                if c < dp[p][e]:
                    dp[p][e] = c
    return dp[k][n]

