def min_operations_to_sum(nums: List[int], target: int) -> int:
    total = sum(nums)
    if total < target:
        return -1

    # Count available powers of two by exponent
    counts = [0] * 64
    for x in nums:
        counts[x.bit_length() - 1] += 1

    ops = 0
    # Process bits from low to high, carrying as needed
    for bit in range(63):
        if (target >> bit) & 1:
            if counts[bit] > 0:
                counts[bit] -= 1
            else:
                # Need to split a larger available power of two
                j = bit + 1
                while j < 64 and counts[j] == 0:
                    j += 1
                if j >= 64:
                    return -1
                # Split 2^j down to 2^bit, costing (j - bit) operations
                counts[j] -= 1
                for k in range(bit, j):
                    counts[k] += 1
                ops += j - bit
                # One 2^bit is used for the target bit; the other pieces stay available
                counts[bit] -= 1
        # Carry leftover lower-power pieces upward (pairs combine)
        if bit + 1 < 64:
            counts[bit + 1] += counts[bit] // 2
            counts[bit] %= 2
    return ops

