from typing import List, Tuple


def min_sensor_cost(n: int, sections: List[int], sensor1: Tuple[int, int, int], sensor2: Tuple[int, int, int]) -> int:
    L1, C1, K1 = sensor1
    L2, C2, K2 = sensor2
    INF = float("inf")

    # dp[a][b] = min cost using a type-1 sensors and b type-2 sensors
    # across all sections processed so far.
    dp = [[INF] * (K2 + 1) for _ in range(K1 + 1)]
    dp[0][0] = 0

    for d in sections:
        # For this section, enumerate options: x type-1 sensors, y type-2 sensors
        # with x*L1 + y*L2 >= d, minimal per-section cost for each (x, y) pair.
        options = []
        for x in range(K1 + 1):
            for y in range(K2 + 1):
                if x * L1 + y * L2 >= d:
                    options.append((x, y, x * C1 + y * C2))
        if not options:
            return -1

        new_dp = [[INF] * (K2 + 1) for _ in range(K1 + 1)]
        for a in range(K1 + 1):
            for b in range(K2 + 1):
                if dp[a][b] == INF:
                    continue
                for x, y, c in options:
                    na, nb = a + x, b + y
                    if na <= K1 and nb <= K2:
                        val = dp[a][b] + c
                        if val < new_dp[na][nb]:
                            new_dp[na][nb] = val
        dp = new_dp

    best = min(min(row) for row in dp)
    return -1 if best == INF else best

