from typing import List, Tuple, Optional


def min_weight_hamiltonian_walk(n: int, m: int, edges: List[Tuple[int, int, int]]) -> Optional[int]:
    INF = float('inf')
    # dist[i][j]: shortest walk weight from i to j (no negative cycles)
    dist = [[INF] * n for _ in range(n)]
    for i in range(n):
        dist[i][i] = 0
    for u, v, w in edges:
        u -= 1
        v -= 1
        if w < dist[u][v]:
            dist[u][v] = w
    for k in range(n):
        for i in range(n):
            if dist[i][k] == INF:
                continue
            for j in range(n):
                nd = dist[i][k] + dist[k][j]
                if nd < dist[i][j]:
                    dist[i][j] = nd

    full = (1 << n) - 1
    # dp[mask][v]: min weight of walk starting anywhere, covering mask, ending at v
    dp = [[INF] * n for _ in range(1 << n)]
    for v in range(n):
        dp[1 << v][v] = 0
    for mask in range(1, 1 << n):
        for v in range(n):
            cur = dp[mask][v]
            if cur == INF:
                continue
            for u in range(n):
                if mask & (1 << u):
                    continue
                if dist[v][u] == INF:
                    continue
                nm = mask | (1 << u)
                val = cur + dist[v][u]
                if val < dp[nm][u]:
                    dp[nm][u] = val
    # Walk may end at any vertex; but it may also extend within already visited
    # vertices, which is captured by the dist closure at the end.
    best = INF
    for v in range(n):
        if dp[full][v] == INF:
            continue
        # no extra cost needed: ending at v is fine
        best = min(best, dp[full][v])
    return None if best == INF else int(best)

