def count_good_strings(n: int, k: int, s: str) -> int:
    MOD = 998244353
    # dp maps a bitmask of the last min(i, k-1) characters -> count.
    # Bit value 1 means 'B', 0 means 'A'. Lengths are tracked implicitly
    # by processing the first k-1 characters without palindrome checks.
    dp = {0: 1}
    length = 0  # number of characters placed so far in the mask
    for i, ch in enumerate(s):
        options = []
        if ch == 'A':
            options = [0]
        elif ch == 'B':
            options = [1]
        else:
            options = [0, 1]
        new_dp = {}
        for mask, cnt in dp.items():
            for c in options:
                if length + 1 < k:
                    # Not enough characters yet for a full window of length k
                    new_mask = (mask << 1) | c
                    new_dp[new_mask] = (new_dp.get(new_mask, 0) + cnt) % MOD
                else:
                    # Full window: last k-1 chars from mask plus c
                    window = (mask << 1) | c
                    window &= (1 << k) - 1
                    # Check whether the k-bit window is a palindrome
                    bits = [(window >> j) & 1 for j in range(k)]
                    if bits == bits[::-1]:
                        continue
                    new_mask = window & ((1 << (k - 1)) - 1)
                    new_dp[new_mask] = (new_dp.get(new_mask, 0) + cnt) % MOD
        dp = new_dp
        length += 1
    return sum(dp.values()) % MOD

