def count_arithmetic_subsequences(n: int, a: List[int]) -> List[int]:
    # dp[i] maps (difference, length) -> number of arithmetic subsequences
    # of that length ending at index i with that common difference.
    dp = [dict() for _ in range(n)]
    res = [0] * n
    res[0] = n % MOD  # every single element is a length-1 subsequence

    for i in range(n):
        for j in range(i):
            d = a[i] - a[j]
            # The pair (j, i) forms a length-2 subsequence.
            ways = {2: 1}
            # Extend every arithmetic subsequence ending at j with the same difference.
            for (pd, plen), c in dp[j].items():
                if pd == d:
                    ways[plen + 1] = ways.get(plen + 1, 0) + c
            for length, c in ways.items():
                key = (d, length)
                dp[i][key] = (dp[i].get(key, 0) + c) % MOD
                res[length - 1] = (res[length - 1] + c) % MOD
    return res

