def max_dishes_eaten(n: int, x: int, y: int, dishes: List[Tuple[int, int]]) -> int:
    # dp[k][s] = minimum total saltiness using k dishes with total sweetness exactly s (s <= x)
    INF = float("inf")
    dp = [[INF] * (x + 1) for _ in range(n + 1)]
    dp[0][0] = 0
    for sw, sa in dishes:
        for k in range(n, 0, -1):
            prev = dp[k - 1]
            cur = dp[k]
            for s in range(x, sw - 1, -1):
                if prev[s - sw] + sa < cur[s]:
                    cur[s] = prev[s - sw] + sa
    # largest count of dishes fitting both limits
    fit = 0
    for k in range(n + 1):
        for s in range(x + 1):
            if dp[k][s] <= y:
                fit = max(fit, k)
    # one more dish can be eaten last, even though it overflows
    return min(n, fit + 1)


