MOD = 998244353

def count_paths(N: int, M: int, K: int, extra_edges: list) -> int:
    # Build adjacency: each vertex has its cycle edge plus any extra edges.
    adj = [[] for _ in range(N + 1)]
    for i in range(1, N + 1):
        adj[i].append(i % N + 1)
    for x, y in extra_edges:
        adj[x].append(y)

    # Number of walks of length K from vertex 1, via DP over time.
    # Only vertices with out-degree > 1 branch; the rest are forced.
    # Direct DP is O(K * (N + M)); for the stated limits this is a
    # reference implementation, not an optimized one.
    cur = [0] * (N + 1)
    cur[1] = 1
    for _ in range(K):
        nxt = [0] * (N + 1)
        for v in range(1, N + 1):
            c = cur[v]
            if c:
                for w in adj[v]:
                    nxt[w] = (nxt[w] + c) % MOD
        cur = nxt
    return sum(cur) % MOD

