def minimum_shipping_dissatisfaction(n: int, k: int, x: int, order_days: List[int]) -> int:
    INF = float("inf")
    # states[i] : dict mapping last shipment day -> min cost, after shipping first i orders
    states = [dict() for _ in range(n + 1)]
    states[0][-x] = 0  # virtual shipment so the first one is unconstrained (day >= -x + x = 0)

    for i in range(n):
        for last_ship, cost in states[i].items():
            # form a batch of orders i .. j-1 (size between 1 and k)
            for j in range(i + 1, min(n, i + k) + 1):
                ship = max(order_days[j - 1], last_ship + x)
                batch_cost = sum(ship - order_days[t] for t in range(i, j))
                new_cost = cost + batch_cost
                d = states[j]
                if d.get(ship, INF) > new_cost:
                    d[ship] = new_cost

    return min(states[n].values())

