def minimum_shipping_dissatisfaction(n: int, k: int, x: int, order_days: List[int]) -> int:
    INF = float("inf")
    # states[i]: dict mapping last shipment day -> min cost to ship first i orders
    states = [dict() for _ in range(n + 1)]
    states[0][-(10**18)] = 0  # no previous shipment: any day is allowed

    for i in range(n):
        if not states[i]:
            continue
        for last_ship, cost in states[i].items():
