            for j in range(i + 1, min(n, i + k) + 1):
                ship = max(order_days[j - 1], earliest)
                batch_cost = sum(ship - order_days[t] for t in range(i, j))
                new_cost = cost + batch_cost
                if states[j].get(ship, INF) > new_cost:
                    states[j][ship] = new_cost

    return min(states[n].values())

