def minimum_shipping_dissatisfaction(n: int, k: int, x: int, order_days: List[int]) -> int:
    # states[i]: list of (last_ship_day, cost) pairs after shipping the first i orders
    states = [[] for _ in range(n + 1)]

    def add(i, day, cost):
        states[i].append((day, cost))

    # First batch covers orders [0, j): ships on the day of its last order.
    for j in range(1, min(n, k) + 1):
        day = order_days[j - 1]
        cost = sum(day - order_days[t] for t in range(j))
        add(j, day, cost)

    for i in range(1, n):
        # prune dominated states at position i
        states[i].sort()
        kept = []
        best = float("inf")
        for day, cost in states[i]:
            if cost < best:
                kept.append((day, cost))
                best = cost
        states[i] = kept

        for last_ship, cost in states[i]:
            earliest = last_ship + x
            for j in range(i + 1, min(n, i + k) + 1):
                ship = max(order_days[j - 1], earliest)
                new_cost = cost + sum(ship - order_days[t] for t in range(i, j))
                add(j, ship, new_cost)

    return min(c for _, c in states[n])

