def minimum_shipping_dissatisfaction(n: int, k: int, x: int, order_days: List[int]) -> int:
    INF = float("inf")
    # dp[i] = min cost to ship first i orders, where we track (cost, last_ship) via
    # a separate array per prefix; we use a clean two-array formulation below.
    # best[i] maps last_ship -> min cost
    best = [dict() for _ in range(n + 1)]
    best[0][None] = 0  # None = no shipment yet

    for i in range(n):
        for last, cost in best[i].items():
            earliest = order_days[i] if last is None else max(order_days[i], last + x)
            for j in range(i + 1, min(n, i + k) + 1):
                ship = max(order_days[j - 1], earliest) if last is not None else max(order_days[j - 1], earliest)
                batch = sum(ship - order_days[t] for t in range(i, j))
                nc = cost + batch
                if best[j].get(ship, INF) > nc:
                    best[j][ship] = nc

    return min(best[n].values())

