def min_team_switches(people: List[Tuple[int, int]]) -> int:
    total = sum(s for _, s in people)
    if total % 3 != 0:
        return -1
    target = total // 3

    # dp maps (sum_team1, sum_team2) -> minimum number of switches so far.
    # Team 3's sum is implied: sum_team3 = processed_total - sum1 - sum2.
    dp = {(0, 0): 0}
    processed = 0
    for orig_team, s in people:
        processed += s
        new_dp = {}
        for (s1, s2), cost in dp.items():
            s3 = processed - s - s1 - s2  # team 3 sum before this person
            # Assign this person to team 1, 2, or 3.
            for dest in (1, 2, 3):
                n1, n2 = s1, s2
                if dest == 1:
                    n1 += s
                elif dest == 2:
                    n2 += s
                # dest == 3: sums for 1 and 2 unchanged
                if n1 > target or n2 > target:
                    continue
                # Team 3 must not exceed target either.
                n3 = processed - n1 - n2
                if n3 > target:
                    continue
                c = cost + (0 if dest == orig_team else 1)
                key = (n1, n2)
                if key not in new_dp or new_dp[key] > c:
                    new_dp[key] = c
        dp = new_dp

    return dp.get((target, target), -1)

