def count_paths(H: int, W: int, K: int, grid: list[str]) -> int:
    visited = [[False] * W for _ in range(H)]
    dirs = [(1, 0), (-1, 0), (0, 1), (0, -1)]

    def dfs(r: int, c: int, remaining: int) -> int:
        if remaining == 0:
            return 1
        total = 0
        for dr, dc in dirs:
            nr, nc = r + dr, c + dc
            if 0 <= nr < H and 0 <= nc < W and grid[nr][nc] == '.' and not visited[nr][nc]:
                visited[nr][nc] = True
                total += dfs(nr, nc, remaining - 1)
                visited[nr][nc] = False
        return total

    count = 0
    for r in range(H):
        for c in range(W):
            if grid[r][c] == '.':
                visited[r][c] = True
                count += dfs(r, c, K)
                visited[r][c] = False
    return count

