def max_1122_subarray_length(n: int, a: List[int]) -> int:
    """ Given a list of positive integers, find the maximum length of a contiguous subarray 
    that forms a 1122 sequence.

    Args:
        n: The length of the array (1 <= n <= 2*10^5)
        a: The array of positive integers (1 <= a[i] <= n)

    Returns:
        The maximum length of a contiguous subarray that is a 1122 sequence
    """
    best = 0
    for start in range(n):
        for offset in (0, 1):
            # Window beginning at `start`, optionally skipping one leading element
            i = start + offset
            if i >= n:
                continue
            counts = {}
            length = 0
            j = i
            ok = True
            while j < n:
                # Pairs must be adjacent equal elements, and each value
                # may appear at most twice overall in the window
                if j + 1 < n and a[j] == a[j + 1]:
                    v = a[j]
                    if counts.get(v, 0) != 0:
                        break
                    counts[v] = 2
                    length += 2
                    j += 2
                else:
                    break
            if length > best:
                best = length
            if offset == 1:
                # A leftover leading element adds one to the length
                if length > 0 and length + 1 > best:
                    best = length + 1
    return best

