def minimize_path_weights(n: int, edges: List[Tuple[int, int, int]], a: List[int], b: List[int]) -> int:
    # Build minimum spanning tree (Kruskal) so that f(x, y) = max edge on MST path
    parent = list(range(n + 1))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    adj = [[] for _ in range(n + 1)]
    for u, v, w in sorted(edges, key=lambda e: e[2]):
        ru, rv = find(u), find(v)
        if ru != rv:
            parent[ru] = rv
            adj[u].append((v, w))
            adj[v].append((u, w))

    # For each source vertex in a, compute max-edge-to-every-vertex on the tree
    needed = set(a) | set(b)
    cache = {}

    def dist_from(s):
        if s in cache:
            return cache[s]
        best = [-1] * (n + 1)
        best[s] = 0
        stack = [s]
        while stack:
            x = stack.pop()
            for y, w in adj[x]:
                if best[y] == -1:
                    best[y] = max(best[x], w)
                    stack.append(y)
        cache[s] = best
        return best

    m = len(a)
    cost = [[0] * m for _ in range(m)]
    for i in range(m):
        d = dist_from(a[i])
        for j in range(m):
            cost[i][j] = d[b[j]]

    # Hungarian algorithm for min-cost perfect matching
    INF = float('inf')
    u = [0] * (m + 1)
    v = [0] * (m + 1)
    p = [0] * (m + 1)
    way = [0] * (m + 1)
    for i in range(1, m + 1):
        p[0] = i
        j0 = 0
        minv = [INF] * (m + 1)
        used = [False] * (m + 1)
        while True:
            used[j0] = True
            i0 = p[j0]
            delta = INF
            j1 = 0
            for j in range(1, m + 1):
                if not used[j]:
                    cur = cost[i0 - 1][j - 1] - u[i0] - v[j]
                    if cur < minv[j]:
                        minv[j] = cur
                        way[j] = j0
                    if minv[j] < delta:
                        delta = minv[j]
                        j1 = j
            for j in range(m + 1):
                if used[j]:
                    u[p[j]] += delta
                    v[j] -= delta
                else:
                    minv[j] -= delta
            j0 = j1
            if p[j0] == 0:
                break
        while True:
            j1 = way[j0]
            p[j0] = p[j1]
            j0 = j1
            if j0 == 0:
                break

    total = 0
    for j in range(1, m + 1):
        total += cost[p[j] - 1][j - 1]
    return total

