def min_deletions_to_snowflake(n: int, edges: List[Tuple[int, int]]) -> int:
    deg = [0] * (n + 1)
    adj = [[] for _ in range(n + 1)]
    for u, v in edges:
        deg[u] += 1
        deg[v] += 1
        adj[u].append(v)
        adj[v].append(u)

    best = 0
    for c in range(1, n + 1):
        kept = 1
        for u in adj[c]:
            if deg[u] >= 2:
                kept += deg[u]
        best = max(best, kept)

    if n == 3:
        best = max(best, 3)

    return n - best

