    for u, v in edges:
        deg[u] += 1
        deg[v] += 1
        adj[u].append(v)
        adj[v].append(u)

    # leaves_of[u]: number of neighbors of u that are leaves in the original tree
    leaves_of = [0] * (n + 1)
    for u in range(1, n + 1):
        for w in adj[u]:
            if deg[w] == 1:
                leaves_of[u] += 1

    best = 0
    for c in range(1, n + 1):
        total = 1
        branches = 0
        for u in adj[c]:
            # u is a valid branch if it has at least one leaf child other than c
            leaf_kids = leaves_of[u] - (1 if deg[c] == 1 else 0)
            if deg[u] >= 2 and leaf_kids >= 1:
                branches += 1
                total += 1 + leaf_kids
        if branches >= 1:
            best = max(best, total)

