    n, m = len(s), len(t)
    if abs(n - m) > k:
        return False
    if n > m:
        s, t = t, s
        n, m = m, n
    INF = k + 1
    prev = [min(j, INF) for j in range(m + 1)]
    for i in range(1, n + 1):
        lo = max(1, i - k)
        hi = min(m, i + k)
        cur = [INF] * (m + 1)
        if lo == 1:
            cur[0] = min(i, INF)
        for j in range(lo, hi + 1):
            cost = 0 if s[i - 1] == t[j - 1] else 1
            best = prev[j - 1] + cost
            if prev[j] + 1 < best:
