def count_ball_sets(n: int, positions: List[Tuple[int, int]]) -> int:
    MOD = 998244353

    def dominated_or_dominating(i, k):
        xi, yi = positions[i]
        xk, yk = positions[k]
        return (xi < xk and yi < yk) or (xi > xk and yi > yk)

    # State: frozenset of remaining balls (as bitmask)
    full = (1 << n) - 1
    seen = {full}
    stack = [full]
    finals = set()
    while stack:
        mask = stack.pop()
        # Check whether any operation is possible; a state with no further
        # operations is terminal. Each operation keeps k and removes some balls.
        moved = False
        for k in range(n):
            if not (mask >> k) & 1:
                continue
            new_mask = mask
            for i in range(n):
                if i != k and (mask >> i) & 1 and dominated_or_dominating(i, k):
                    new_mask &= ~(1 << i)
            if new_mask != mask:
                moved = True
                if new_mask not in seen:
                    seen.add(new_mask)
                    stack.append(new_mask)
        if not moved:
            finals.add(mask)
    return len(finals) % MOD

