from functools import lru_cache
from itertools import product


def _fixed_count_for_n(n: int) -> frozenset:
    """Return the set of achievable fixed-element counts for n x n binary matrices."""
    groups = {}
    for bits in product((0, 1), repeat=n * n):
        rows = tuple(sum(bits[i * n:(i + 1) * n]) for i in range(n))
        cols = tuple(sum(bits[j::n]) for j in range(n))
        key = (rows, cols)
        if key not in groups:
            groups[key] = [bits, bits]  # [AND-accumulator, OR-accumulator]
        else:
            groups[key][0] = tuple(a & b for a, b in zip(groups[key][0], bits))
            groups[key][1] = tuple(a | b for a, b in zip(groups[key][1], bits))
    achievable = set()
    for and_bits, or_bits in groups.values():
        # Position is fixed iff AND == OR at that position (same value across group).
        fixed = sum(1 for a, o in zip(and_bits, or_bits) if a == o)
        achievable.add(fixed)
    return frozenset(achievable)


@lru_cache(maxsize=None)
def _cached_table(n: int) -> frozenset:
    return _fixed_count_for_n(n)


def matrix_with_k_fixed_elements_exists(n: int, k: int) -> bool:
    """Return True if some n x n binary matrix has exactly k fixed elements."""
    if k < 0 or k > n * n:
        return False
    if n <= 4:
        return k in _cached_table(n)
    # For larger n the brute-force table is infeasible; this branch is
    # not yet implemented and will fail the large-n assertions.
    return False

