def count_polish_sequences(n: int, a: list[int]) -> int:
    MOD = 998244353
    from functools import lru_cache

    # f[m][k]: number of ways to fill m positions with k pending subtrees
    # (each pending subtree is a Polish tree consumed in preorder).
    def build_f(n):
        f = [[0] * (n + 2) for _ in range(n + 1)]
        f[0][0] = 1
        for m in range(1, n + 1):
            for k in range(1, n + 1):
                total = 0
                # first position of the remaining m positions has value v,
                # opening v new pending subtrees while closing one.
                for v in range(0, m):
                    kk = k - 1 + v
                    if kk <= n:
                        total += f[m - 1][kk]
                f[m][k] = total % MOD
        return f

    f = build_f(n)

    # Enumerate sequences lexicographically <= a via DFS with tight flag.
    # A prefix is valid if it can still be completed: pending count k and
    # remaining length m must satisfy f[m][k] > 0 for completion.
    @lru_cache(maxsize=None)
    def go(i, k, tight):
        m = n - i
        if m == 0:
            return 1 if k == 0 else 0
        if k == 0:
            return 0
        limit = a[i] if tight else n - 1
        res = 0
        for v in range(0, min(limit, m - 1) + 1):
            nt = tight and (v == limit)
            kk = k - 1 + v
            if kk < 0 or kk > m - 1:
                continue
            if f[m - 1][kk] == 0 and not (m - 1 == 0 and kk == 0):
                continue
            res += go(i + 1, kk, nt)
        return res % MOD

    return go(0, 1, True)

def count_polish_sequences(n: int, a: list[int]) -> int:
    MOD = 998244353

    # need = number of subtrees still to be produced (starts at 1 for the root).
    # Each element v consumes one pending subtree and opens v new ones.
    # The sequence is Polish iff need stays >= 1 until the last element,
    # where it becomes exactly 0.
    def go(i, need, tight):
        remaining = n - i
        if remaining == 0:
            return 1 if need == 0 else 0
        if need == 0:
            return 0
        # Each remaining element must be < n, and we need need-1+v subtrees
        # fillable by the remaining positions: need-1+v <= remaining-1.
        limit = a[i] if tight else n - 1
        res = 0
        for v in range(0, min(limit, remaining - 1) + 1):
            new_need = need - 1 + v
            if new_need < 0 or new_need > remaining - 1:
                continue
            res += go(i + 1, new_need, tight and v == limit)
        return res % MOD

    return go(0, 1, True)

def count_polish_sequences(n: int, a: list[int]) -> int:
    MOD = 998244353
    # T[m][k]: number of ways to fill m positions starting with need k,
    # ending with need exactly 0 at the end, never hitting need 0 earlier.
    # T[0][0] = 1. For m >= 1, k >= 1: first element v gives need k-1+v.
    T = [[0] * (n + 1) for _ in range(n + 1)]
    T[0][0] = 1
    for m in range(1, n + 1):
        # prefix sums over k' of T[m-1][k'] to get sums over v
        pre = [0] * (n + 2)
        for j in range(n + 1):
            pre[j + 1] = (pre[j] + T[m - 1][j]) % MOD
        for k in range(1, n + 1):
            # v ranges 0..m-1, so kk = k-1+v ranges over [k-1, k-1+m-1]
            lo = k - 1
            hi = min(n, k - 1 + m - 1)
            if lo <= hi:
                T[m][k] = (pre[hi + 1] - pre[lo]) % MOD

    # Walk the tight path.
    ans = 0
    need = 1
    for i in range(n):
        if need == 0:
            break
        m = n - i  # positions remaining including this one
        for v in range(0, min(a[i] - 1, m - 1) + 1):
            kk = need - 1 + v
            if 0 <= kk <= n:
                ans = (ans + T[m - 1][kk]) % MOD
        # commit to a[i]
        need = need - 1 + a[i]
        if need < 0 or need > n:
            break
    else:
        if need == 0:
            ans = (ans + 1) % MOD
    return ans

def count_polish_sequences(n: int, a: list[int]) -> int:
    MOD = 998244353

    # All Polish sequences of length exactly L, as tuples, by the definition:
    # (v, *W_1, ..., *W_v) where each W_i is a Polish sequence.
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def polish(L):
        if L == 0:
            return ()
        result = []
        if L == 1:
            return ((0,),)
        # first element v, then v children partitioning the remaining L-1
        for v in range(0, L):
            for parts in compositions_polish(L - 1, v):
                for seq in parts_to_seqs(parts):
                    result.append((v,) + seq)
        return tuple(result)

    @lru_cache(maxsize=None)
    def compositions_polish(total, k):
        # ways to split `total` positions into k consecutive Polish blocks,
        # returned as tuples of block lengths
        if k == 0:
            return ((),) if total == 0 else ()
        out = []
        for first in range(1, total + 1):
            for rest in compositions_polish(total - first, k - 1):
                out.append((first,) + rest)
        return tuple(out)

    def parts_to_seqs(parts):
        # Cartesian product of Polish sequences of the given block lengths
        seqs = [()]
        for length in parts:
            new = []
            for s in seqs:
                for p in polish(length):
                    new.append(s + p)
            seqs = new
        return seqs

    count = 0
    for seq in polish(n):
        if list(seq) <= a:
            count += 1
    return count % MOD

def count_polish_sequences(n: int, a: list[int]) -> int:
    MOD = 998244353
    from functools import lru_cache
    import sys
    sys.setrecursionlimit(10000)

    # T(m, k): number of length-m suffixes that take counter k to exactly 0,
    # keeping counter >= 1 before every element.
    @lru_cache(maxsize=None)
    def T(m, k):
        if m == 0:
            return 1 if k == 0 else 0
        if k == 0 or k > m:
            return 0
        total = 0
        # first element v: counter becomes k-1+v, must fit in m-1 remaining
        for v in range(0, m):
            nk = k - 1 + v
            if nk > m - 1:
                break
            total += T(m - 1, nk)
        return total % MOD

    ans = 0
    need = 1
    for i in range(n):
        m = n - i
        if need == 0:
            break
        # sequences that drop below a[i] here and are tight before
        for v in range(0, min(a[i] - 1, m - 1) + 1):
            nk = need - 1 + v
            if 0 <= nk <= m - 1:
                ans += T(m - 1, nk)
        ans %= MOD
        # commit to a[i]
        need = need - 1 + a[i]
        if need < 0 or need > n - i - 1:
            # no completion along the tight path; stop without adding a full match
            return ans % MOD
    else:
        if need == 0:
            ans += 1  # a itself is Polish
    return ans % MOD

def enumerate_polish(L):
    # Polish sequences of length L by the recursive definition.
    if L == 1:
        return [(0,)]
    out = []
    for v in range(0, L):
        # split the remaining L-1 positions into v nonempty Polish blocks
        for seq in split_into_polish(L - 1, v):
            out.append((v,) + seq)
    return out

def split_into_polish(total, k):
    if k == 0:
        return [()] if total == 0 else []
    res = []
    for first in range(1, total + 1):
        for head in enumerate_polish(first):
            for tail in split_into_polish(total - first, k - 1):
                res.append(head + tail)
    return res

def count_polish_sequences(n: int, a: list[int]) -> int:
    seqs = enumerate_polish(n)
    return sum(1 for s in seqs if list(s) <= a) % 998244353

