def count_sequences_without_subsequence(N: int, M: int, K: int, X: list[int]) -> int:
    if M != 2 or N < 2:
        # General M not yet derived; see explanation.
        return 0
    a, b = X
    # Requirement 1: a->b is not a subsequence of S.
    # Requirement 2: every other ordered pair (c, d) is a subsequence of S.
    # Brute-force feasible only for small N and K; used to validate the formula.
    from itertools import product
    if N > 8 or K > 4:
        return 0  # no efficient method yet
    count = 0
    for S in product(range(1, K + 1), repeat=N):
        def has(pattern):
            it = iter(S)
            return all(any(x == p for x in it) for p in pattern)
        if has((a, b)):
            continue
        if all(has((c, d)) for c in range(1, K + 1) for d in range(1, K + 1) if (c, d) != (a, b)):
            count += 1
    return count % MOD

