@lru_cache(maxsize=None)
def _reducible(a: int, b: int, c: int) -> bool:
    if a == 0 and b == 0 and c == 0:
        return True
    # operation 2: remove one of each
    if a >= 1 and b >= 1 and c >= 1 and _reducible(a - 1, b - 1, c - 1):
        return True
