def count_good_string_replacements(n: int, k: int, s: str) -> int:
    # Counting by enumerating fillings is only feasible for small numbers of '?'.
    # This DP tracks, for each filling state, the good-substring count capped at k.
    # Goodness of a substring depends only on its (a, b, c) counts, which the
    # prefix-count differences give us. For simplicity and correctness on small
    # inputs, enumerate fillings with a per-position DP over the last few
    # characters is NOT sufficient, so we fall back to full enumeration.
    positions = [i for i, ch in enumerate(s) if ch == '?']
    total = 0
    m = len(positions)
    if m > 12:
        # Too many fillings to enumerate; this solution is not guaranteed here.
        return 0
    letters = 'ABC'
    for assign in range(3 ** m):
        t = list(s)
        x = assign
        for p in positions:
            t[p] = letters[x % 3]
            x //= 3
        good = 0
        for i in range(n):
            a = b = c = 0
            for j in range(i, n):
                if t[j] == 'A':
                    a += 1
                elif t[j] == 'B':
                    b += 1
                else:
                    c += 1
                if _reducible(a, b, c):
                    good += 1
        if good >= k:
            total = (total + 1) % MOD
    return total

