def count_good_string_replacements(n: int, k: int, s: str) -> int:
    # State after processing a prefix: the tuple of prefix count-vectors
    # (as (a, b, c) relative to current prefix) for all earlier starts,
    # plus number of good substrings so far capped at k.
    # Represent each earlier prefix by its vector; a substring s[i:j] has counts
    # prefix[j] - prefix[i]. We keep the multiset of vectors of prefixes, which
    # is enough to count good substrings ending at the new position.
    dp = defaultdict(int)
    dp[((0, 0, 0),), 0] = 1  # key: (tuple of prefix vectors seen, good count capped)
    # Key uses a sorted tuple of prefix vectors to merge equivalent states.
    dp = {(tuple([(0, 0, 0)]), 0): 1}
    for ch in s:
        choices = 'ABC' if ch == '?' else ch
        ndp = defaultdict(int)
        for (prefixes, good), ways in dp.items():
            cur = prefixes[-1]
            for c in choices:
                a, b, cc = cur
                if c == 'A':
                    nv = (a + 1, b, cc)
                elif c == 'B':
                    nv = (a, b + 1, cc)
                else:
                    nv = (a, b, cc + 1)
                new_good = 0
                for p in prefixes:
                    da = nv[0] - p[0]
                    db = nv[1] - p[1]
                    dc = nv[2] - p[2]
                    if _reducible(da, db, dc) and (da + db + dc) > 0:
                        new_good += 1
                ng = min(k, good + new_good)
                nprefixes = tuple(sorted(prefixes + (nv,)))
                ndp[(nprefixes, ng)] = (ndp[(nprefixes, ng)] + ways) % MOD
        dp = ndp
    total = 0
    for (prefixes, good), ways in dp.items():
        if good >= k:
            total = (total + ways) % MOD
    return total

