def count_subsequence_pairs(nums: List[int]) -> int:
    MOD = 10**9 + 7
    MAXV = 200

    cnt = [0] * (MAXV + 1)
    for x in nums:
        cnt[x] += 1

    # divisor counts: c[d] = number of elements divisible by d
    c = [0] * (MAXV + 1)
    for d in range(1, MAXV + 1):
        c[d] = sum(cnt[m] for m in range(d, MAXV + 1, d))

    n = len(nums)
    pow2 = [1] * (n + 1)
    pow3 = [1] * (n + 1)
    for i in range(1, n + 1):
        pow2[i] = pow2[i - 1] * 2 % MOD
        pow3[i] = pow3[i - 1] * 3 % MOD

    # F(g): disjoint non-empty seq1, seq2 using only elements divisible by g
    F = [0] * (MAXV + 1)
    for g in range(1, MAXV + 1):
        k = c[g]
        F[g] = (pow3[k] - 2 * pow2[k] + 1) % MOD

    # Mobius function up to MAXV
    mu = [1] * (MAXV + 1)
    is_prime = [True] * (MAXV + 1)
    for p in range(2, MAXV + 1):
        if is_prime[p]:
            for m in range(p, MAXV + 1, p):
                if m != p:
                    is_prime[m] = False
                mu[m] = -mu[m]
            for m in range(p * p, MAXV + 1, p * p):
                mu[m] = 0

    # G(g): exact gcd g for both sequences
    total = 0
    for g in range(1, MAXV + 1):
        s = 0
        for k in range(1, MAXV // g + 1):
            if mu[k]:
                s += mu[k] * F[g * k]
        total = (total + s) % MOD
    return total % MOD

def count_k_reducible(s: str, k: int) -> int:
    MOD = 10**9 + 7
    L = len(s)

    # steps[c]: number of operations to reduce integer c to 1
    steps = [0] * (L + 2)
    for c in range(2, L + 2):
        steps[c] = 1 + steps[bin(c).count("1")]

    # Binomial coefficients modulo MOD
    C = [[0] * (L + 2) for _ in range(L + 2)]
    for i in range(L + 2):
        C[i][0] = 1
        for j in range(1, i + 1):
            C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % MOD

    # cnt[c]: number of integers x in [0, n-1] with exactly c set bits
    cnt = [0] * (L + 2)
    ones = 0
    for i, ch in enumerate(s):
        remaining = L - i - 1
        if ch == '1':
            for c in range(remaining + 1):
                cnt[ones + c] = (cnt[ones + c] + C[remaining][c]) % MOD
            ones += 1

    total = 0
    for c in range(1, L + 1):
        # x = 1 (popcount 1) needs 0 ops; any x >= 2 with popcount c needs 1 + steps[c] ops
        if c == 1 or steps[c] + 1 <= k:
            total = (total + cnt[c]) % MOD
    # Note: for c == 1, cnt[1] includes x = 1 and powers of two >= 2, all valid for k >= 1

    return total % MOD

