def count_balanced_graphs(n: int, p: int) -> list[int]:
    maxM = n * (n - 1) // 2
    half = n // 2

    # Binomial table mod p
    N = maxM + 2
    C = [[0] * (N + 1) for _ in range(N + 1)]
    for i in range(N + 1):
        C[i][0] = 1
        for j in range(1, i + 1):
            C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % p

    def binom(a, b):
        if a < 0 or b < 0 or b > a:
            return 0
        return C[a][b]

    def poly_mul(P, Q):
        R = [0] * (len(P) + len(Q) - 1)
        for i, x in enumerate(P):
            if x:
                for j, y in enumerate(Q):
                    if y:
                        R[i + j] = (R[i + j] + x * y) % p
        return R

    def poly_add(P, Q):
        L = max(len(P), len(Q))
        R = [0] * L
        for i, x in enumerate(P):
            R[i] = (R[i] + x) % p
        for i, x in enumerate(Q):
            R[i] = (R[i] + x) % p
        return R

    # Edges between a layer of size s (children) and previous layer of size b (parents),
    # every child having at least one parent: each child picks a nonempty subset of parents.
    # Per child generating function: (1+x)^b - 1. Total: ((1+x)^b - 1)^s.
    bip_cache = {}
    def bip(s, b):
        key = (s, b)
        if key in bip_cache:
            return bip_cache[key]
        child = [binom(b, e) for e in range(b + 1)]
        child[0] = 0
        R = [1]
        for _ in range(s):
            R = poly_mul(R, child)
        bip_cache[key] = R
        return R

    # Free edges inside a layer of size s: (1+x)^{C(s,2)}
    within_cache = {}
    def within(s):
        if s in within_cache:
            return within_cache[s]
        m = s * (s - 1) // 2
        R = [binom(m, e) for e in range(m + 1)]
        within_cache[s] = R
        return R

    # State: (placed, even_placed, last_layer_size) -> polynomial in edges.
    # Layer 0 is vertex 1 (distance 0, even).
    states = {(1, 1, 1): [1]}
