from typing import List


def count_strings_by_lcs_length(n: int, m: int, s: str) -> List[int]:
    MOD = 998244353
    full = (1 << n) - 1

    # match masks per character
    match = {}
    for j, ch in enumerate(s):
        match[ch] = match.get(ch, 0) | (1 << j)

    # transition on the bit-parallel LCS state
    def step(V: int, c: str) -> int:
        M = match.get(c, 0)
        U = V & M
        return ((V + U) | (V - U)) & full

    def lcs_of(V: int) -> int:
        # LCS length = number of zero bits in V (within n bits)
        return n - bin(V).count("1")

    # precompute transitions for all 26 letters
    letters = [chr(ord('a') + i) for i in range(26)]
    trans = [[step(V, c) for c in letters] for V in range(1 << n)]

    # dp over states: start with V = full (all ones, LCS = 0)
    dp = [0] * (1 << n)
    dp[full] = 1
    for _ in range(m):
        ndp = [0] * (1 << n)
        for V in range(1 << n):
            cnt = dp[V]
            if cnt == 0:
                continue
            row = trans[V]
            for nv in row:
                ndp[nv] = (ndp[nv] + cnt) % MOD
        dp = ndp

    result = [0] * (n + 1)
    for V in range(1 << n):
        if dp[V]:
            k = lcs_of(V)
            result[k] = (result[k] + dp[V]) % MOD
    return result

from typing import List


def count_strings_by_lcs_length(n: int, m: int, s: str) -> List[int]:
    MOD = 998244353
    letters = [chr(ord('a') + i) for i in range(26)]

    # Canonical state: the LCS DP row against s, as a tuple of length n+1.
    # row[j] = LCS(prefix of t, s[:j]). Row is non-decreasing with steps in {0,1}.
    def advance(row, c):
        new = [0] * (n + 1)
        for j in range(1, n + 1):
            if s[j - 1] == c:
                new[j] = row[j - 1] + 1
            else:
                new[j] = max(row[j], new[j - 1])
        return tuple(new)

    start = tuple([0] * (n + 1))
    dp = {start: 1}
    trans_cache = {}

    for _ in range(m):
        ndp = {}
        for row, cnt in dp.items():
            if row not in trans_cache:
                trans_cache[row] = [advance(row, c) for c in letters]
            for nrow in trans_cache[row]:
                ndp[nrow] = (ndp.get(nrow, 0) + cnt) % MOD
