def max_shortest_distance(n: int, m: int, k: int, edges: List[Tuple[int, int]]) -> int:
    def dist_with(chosen) -> int:
        # 0-1 BFS from vertex 1 to vertex n, where chosen edges have weight 1.
        adj = [[] for _ in range(n + 1)]
        for idx, (u, v) in enumerate(edges):
            w = 1 if idx in chosen else 0
            adj[u].append((v, w))
        INF = float("inf")
        dist = [INF] * (n + 1)
        dist[1] = 0
        dq = deque([1])
        while dq:
            x = dq.popleft()
            for y, w in adj[x]:
                if dist[x] + w < dist[y]:
                    dist[y] = dist[x] + w
                    if w == 0:
                        dq.appendleft(y)
                    else:
                        dq.append(y)
        return dist[n]

    best = 0
    # Exact search over all ways to choose exactly k edges (k <= m).
    # Setting extra edges to 1 never decreases the distance, so exactly k
    # and at most k give the same maximum.
    for combo in combinations(range(m), k):
        d = dist_with(set(combo))
        if d > best:
            best = d
    return best

