def sum_of_subarray_powers(n: int, k: int, a: List[int]) -> int:
    MOD = 998244353

    # Binomial coefficients C(k, j)
    C = [[0] * (k + 1) for _ in range(k + 1)]
    for i in range(k + 1):
        C[i][0] = 1
        for j in range(1, i + 1):
            C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % MOD

    # M[j] = sum over prefix sums P_l (l < r) of P_l^j, starting with P_0 = 0
    M = [0] * (k + 1)
    M[0] = 1

    prefix = 0
    result = 0
    for r in range(1, n + 1):
        prefix = (prefix + a[r - 1]) % MOD
        pw = [1] * (k + 1)
        for t in range(1, k + 1):
            pw[t] = pw[t - 1] * prefix % MOD

        contrib = 0
        for j in range(k + 1):
            term = C[k][j] * pw[k - j] % MOD * M[j] % MOD
            if j & 1:
                contrib -= term
            else:
                contrib += term
        result = (result + contrib) % MOD

        for j in range(k + 1):
            M[j] = (M[j] + pw[j]) % MOD

    return result % MOD

