def sum_of_subarray_powers(n: int, k: int, a: List[int]) -> int:
    MOD = 998244353

    # C[i][j] = binomial coefficient C(i, j) mod MOD
    C = [[0] * (k + 1) for _ in range(k + 1)]
    for i in range(k + 1):
        C[i][0] = 1
        for j in range(1, i + 1):
            C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % MOD

    # M[j] = sum of P_l^j over all prefix indices l seen so far (P_0 = 0)
    M = [0] * (k + 1)
    M[0] = 1  # 0^0 = 1 for P_0; 0^j = 0 for j >= 1

    prefix = 0
    result = 0
    for r in range(1, n + 1):
        prefix = (prefix + a[r - 1]) % MOD

        pw = [1] * (k + 1)  # pw[t] = prefix^t
        for t in range(1, k + 1):
            pw[t] = pw[t - 1] * prefix % MOD

        # sum_{l<r} (P_r - P_l)^k
        for j in range(k + 1):
            term = C[k][j] * pw[k - j] % MOD * M[j] % MOD
            if j & 1:
                result = (result - term) % MOD
            else:
                result = (result + term) % MOD

        for j in range(k + 1):
            M[j] = (M[j] + pw[j]) % MOD

    return result

