            val = 1
            if x > 0 and is_block(x - 1, y):
                val += f_cur[x - 1]
            if y > 0 and is_block(x, y - 1):
                val += f_prev[x]
            val %= MOD
            f_cur[x] = val
            total = (total + val) % MOD
        f_prev = f_cur
    return total % MOD

