def count_in_degree_sequences(n: int, s: str) -> int:
    # Build the edge list of G.
    edges = []
    for i in range(n):
        edges.append((i, (i + 1) % n))
    for i in range(n):
        if s[i] == '1':
            edges.append((i, n))

    m = len(edges)
    # Enumerate all orientations; each edge (u, v) is oriented toward v (bit 0)
    # or toward u (bit 1). Collect distinct in-degree sequences.
    seen = set()
    for mask in range(1 << m):
        indeg = [0] * (n + 1)
        for j, (u, v) in enumerate(edges):
            if (mask >> j) & 1:
                indeg[u] += 1
            else:
                indeg[v] += 1
        seen.add(tuple(indeg))
    return len(seen) % MOD

