MOD = 998244353

def count_distinct_parenthesis_sequences(n: int, s: str) -> int:
    """ Given a valid parenthesis sequence of length n, count the number of distinct strings
    that can be obtained by performing the following operation any number of times:
    - Choose a contiguous substring that is a valid parenthesis sequence and reverse it
      (where reversing means swapping all '(' with ')' and vice versa).

    Return the count modulo 998244353.

    This implementation performs a BFS over all reachable strings. It is correct
    but only practical for small n.
    """
    def valid_substring_ranges(t: str):
        # Yield (i, j) for every contiguous substring t[i:j] that is a valid
        # parenthesis sequence (balanced, never negative prefix balance).
        for i in range(n):
            bal = 0
            for j in range(i, n):
                bal += 1 if t[j] == '(' else -1
                if bal < 0:
                    break
                if bal == 0:
                    yield i, j + 1

    def flip(sub: str) -> str:
        return ''.join(')' if c == '(' else '(' for c in sub)

    seen = {s}
    queue = deque([s])
    while queue:
        cur = queue.popleft()
        for i, j in valid_substring_ranges(cur):
            nxt = cur[:i] + flip(cur[i:j]) + cur[j:]
            if nxt not in seen:
                seen.add(nxt)
                queue.append(nxt)

    return len(seen) % MOD

