def count_strongly_connected_partitions(n: int, s: str) -> int:
    MOD = 998244353
    m = 2 * n
    from collections import defaultdict

    dp = defaultdict(int)
    dp[(0, 0)] = 1
    for k in range(m):
        c = s[k]
        ndp = defaultdict(int)
        for (ob, ow), ways in dp.items():
            if c == 'B':
                ndp[(ob + 1, ow)] += ways
                if ow > 0:
                    ndp[(ob, ow - 1)] += ways * ow
            else:
                ndp[(ob, ow + 1)] += ways
                if ob > 0:
                    ndp[(ob - 1, ow)] += ways * ob
        if k < m - 1:
            ndp = defaultdict(int, {key: v for key, v in ndp.items() if key[0] >= 1})
        dp = ndp
    return dp.get((0, 0), 0) % MOD

def count_strongly_connected_partitions(n: int, s: str) -> int:
    MOD = 998244353
    m = 2 * n
    whites = [i for i in range(m) if s[i] == 'W']
    blacks = [i for i in range(m) if s[i] == 'B']
    if len(whites) != n or len(blacks) != n:
        return 0

    def strongly_connected(edges_extra):
        adj = [[] for _ in range(m)]
        radj = [[] for _ in range(m)]
        for i in range(m - 1):
            adj[i].append(i + 1)
            radj[i + 1].append(i)
        for u, v in edges_extra:
            adj[u].append(v)
            radj[v].append(u)

        def reach(g):
            seen = [False] * m
            stack = [0]
            seen[0] = True
