            while stack:
                x = stack.pop()
                for y in g[x]:
                    if not seen[y]:
                        seen[y] = True
                        cnt += 1
                        stack.append(y)
            return cnt == m

        return reach(adj) and reach(radj)

    count = 0

    def backtrack(idx, used, extra):
        nonlocal count
        if idx == n:
            if strongly_connected(extra):
                count += 1
            return
        w = whites[idx]
        for j, b in enumerate(blacks):
            if not used[j]:
