from typing import List


def max_product_subsequence(nums: List[int], k: int, limit: int) -> int:
    # states: (parity_of_next_index, alt_sum) -> set of achievable products <= limit
    # parity 0 means next element goes to an even index (added), parity 1 means odd (subtracted)
    states = {}
    best = -1

    for x in nums:
        new_states = {}
        # copy existing states (skip x)
        for key, prods in states.items():
            new_states.setdefault(key, set()).update(prods)

        # start a new subsequence with x at index 0
        if x <= limit:
            new_states.setdefault((1, x), set()).add(x)

        # extend existing subsequences with x
        for (parity, s), prods in states.items():
            if parity == 0:
                nkey = (1, s + x)
            else:
                nkey = (0, s - x)
            for p in prods:
                np_ = p * x
                if np_ <= limit:
                    new_states.setdefault(nkey, set()).add(np_)

        states = new_states

    for (parity, s), prods in states.items():
        if s == k and prods:
            best = max(best, max(prods))

    return best

