from functools import lru_cache


def kth_alternating_permutation(n: int, k: int) -> List[int]:
    """ Given two integers n and k, return the k-th alternating permutation of the first n positive integers.

    An alternating permutation is a permutation where no two adjacent elements are both odd or both even.
    The permutations are sorted in lexicographical order.

    If there are fewer than k valid alternating permutations, return an empty list.
    """
    odds = (n + 1) // 2
    evens = n // 2

    # ways(o, e, p): number of parity-alternating arrangements of o odd and e even
    # numbers, given the previous element has parity p (1 = odd, 0 = even).
    @lru_cache(maxsize=None)
    def ways(o: int, e: int, p: int) -> int:
        if o == 0 and e == 0:
            return 1
        total = 0
        # next element must have parity opposite to p
        if p == 1:  # previous odd -> next must be even
            if e > 0:
                total = ways(o, e - 1, 0)
        else:  # previous even -> next must be odd
            if o > 0:
                total = ways(o - 1, e, 1)
        return total

    def ways_start(o: int, e: int) -> int:
        # total arrangements with no previous element
        return ways(o, e, 0) if False else _start(o, e)

    @lru_cache(maxsize=None)
    def _start(o: int, e: int) -> int:
        if o + e == 0:
            return 1
        total = 0
        if o > 0:
            total += ways(o - 1, e, 1)
        if e > 0:
            total += ways(o, e - 1, 0)
        return total

    if k > _start(odds, evens):
        return []

    result: List[int] = []
    remaining_odd = list(range(1, n + 1, 2))
    remaining_even = list(range(2, n + 1, 2))
    o, e = odds, evens
    prev_parity = None  # None means no previous element

    for _ in range(n):
        # candidate parities allowed at this position
        if prev_parity is None:
            candidates = []
            if o > 0:
                candidates.append(1)
            if e > 0:
                candidates.append(0)
        else:
            candidates = [1 - prev_parity] if (o if prev_parity == 0 else e) > 0 else []

        # values in increasing order across allowed parities
        values = []
        for par in candidates:
            pool = remaining_odd if par == 1 else remaining_even
            for v in pool:
                values.append((v, par))
        values.sort()

        for v, par in values:
            if par == 1:
                no, ne = o - 1, e
            else:
                no, ne = o, e - 1
            cnt = ways(no, ne, par) if (no + ne) > 0 else 1
            if k <= cnt:
                result.append(v)
                if par == 1:
                    remaining_odd.remove(v)
                    o = no
                else:
                    remaining_even.remove(v)
                    e = ne
                prev_parity = par
                break
            k -= cnt

    return result

def brute(start, finish, limit, s):
    cnt = 0
    for x in range(start, finish + 1):
        t = str(x)
        if t.endswith(s) and all(int(c) <= limit for c in t):
            cnt += 1
    return cnt

