SIDE = 7
CUBE = SIDE ** 3


def _ov(d: int) -> int:
    return max(0, SIDE - abs(d))


def find_cube_placement(V1: int, V2: int, V3: int) -> Optional[Tuple[int, int, int, int, int, int, int, int, int]]:
    # Necessary condition: total cube volume counted with multiplicity.
    if V1 < 0 or V2 < 0 or V3 < 0:
        return None
    if V1 + 2 * V2 + 3 * V3 != 3 * CUBE:
        return None

    # Cube 1 fixed at origin. Overlaps are zero when any axis offset >= SIDE,
    # so only offsets in (-SIDE, SIDE) matter; the rest behave as "separated".
    offs = range(-SIDE + 1, SIDE)
    sep = 100  # representative separated coordinate (|x| <= 100)

    def axis_vals(lst):
        return lst

    cand = list(offs) + [sep]
    for qa in cand:
        for qb in cand:
            for qc in cand:
                p12 = _ov(qa) * _ov(qb) * _ov(qc)
                for ra in cand:
                    oa1 = _ov(ra)
                    oa2 = _ov(ra - qa)
                    for rb in cand:
                        ob1 = _ov(rb)
                        ob2 = _ov(rb - qb)
                        for rc in cand:
                            oc1 = _ov(rc)
                            oc2 = _ov(rc - qc)
                            p13 = oa1 * ob1 * oc1
                            p23 = oa2 * ob2 * oc2
                            tri = (
                                _ov_tri(0, qa, ra) * _ov_tri(0, qb, rb) * _ov_tri(0, qc, rc)
                            )
                            v3 = tri
                            v2 = p12 + p13 + p23 - 3 * v3
                            v1 = 3 * CUBE - 2 * (p12 + p13 + p23) + 3 * v3
                            if v1 == V1 and v2 == V2 and v3 == V3:
                                return (0, 0, 0, qa, qb, qc, ra, rb, rc)
    return None


def _ov_tri(x0: int, x1: int, x2: int) -> int:
    lo = max(x0, x1, x2)
    hi = min(x0, x1, x2) + SIDE
    return max(0, hi - lo)


