from typing import Optional, Tuple

SIDE = 7
CUBE = SIDE ** 3
FAR = 100
OFFS = list(range(-SIDE + 1, SIDE)) + [FAR]


def _ov2(d: int) -> int:
    return max(0, SIDE - abs(d))


def _ov3(a: int, b: int) -> int:
    lo = max(0, a, b)
    hi = min(SIDE, a + SIDE, b + SIDE)
    return max(0, hi - lo)


def find_cube_placement(V1: int, V2: int, V3: int) -> Optional[Tuple[int, int, int, int, int, int, int, int, int]]:
    if V1 < 0 or V2 < 0 or V3 < 0:
        return None
    if V1 + 2 * V2 + 3 * V3 != 3 * CUBE:
        return None

    # Precompute per-cube overlap with cube 1 (at origin): pair12 and per-axis data.
    cube2 = []
    for qa in OFFS:
        for qb in OFFS:
            for qc in OFFS:
                cube2.append((qa, qb, qc, _ov2(qa) * _ov2(qb) * _ov2(qc)))

    cube3 = []
    for ra in OFFS:
        for rb in OFFS:
            for rc in OFFS:
                cube3.append((ra, rb, rc, _ov2(ra) * _ov2(rb) * _ov2(rc)))

    for qa, qb, qc, p12 in cube2:
        for ra, rb, rc, p13 in cube3:
            p23 = _ov2(ra - qa) * _ov2(rb - qb) * _ov2(rc - qc)
            t = _ov3(qa, ra) * _ov3(qb, rb) * _ov3(qc, rc)
            pairs = p12 + p13 + p23
            if t == V3 and pairs - 3 * t == V2 and 3 * CUBE - 2 * pairs + 3 * t == V1:
                return (0, 0, 0, qa, qb, qc, ra, rb, rc)
    return None

