def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """ Determine if it's possible to place rectangular tiles on an H×W grid such that:
    - Every cell is covered by exactly one tile
    - Tiles can be rotated (so a 2×3 tile can be placed as 3×2)
    - Some tiles may remain unused
    - Tiles must be aligned with grid cells and cannot extend outside

    Args:
        n: Number of available tiles (1 ≤ n ≤ 7)
        h: Height of the grid (1 ≤ h ≤ 10)
        w: Width of the grid (1 ≤ w ≤ 10)
        tiles: List of (a, b) tuples where tile i has dimensions a×b (1 ≤ a, b ≤ 10)

    Returns:
        True if the grid can be perfectly tiled, False otherwise

    >>> can_tile_grid(5, 5, 5, [(1, 1), (3, 3), (4, 4), (2, 3), (2, 5)])
    True
    >>> can_tile_grid(1, 1, 2, [(2, 3)])
    False
    >>> can_tile_grid(1, 2, 2, [(1, 1)])
    False
    """
    # Each tile may be used at most once, so we choose a subset whose areas
    # sum exactly to h*w, and then check whether that subset tiles the grid.
    # Tiles are used at most once; grid is filled by exact cover via backtracking.
    total = h * w
    tile_list = list(tiles[:n])
    m = len(tile_list)

    # Quick reject: if no subset of tile areas can sum to total, impossible.
    reachable = {0}
    for a, b in tile_list:
        reachable |= {r + a * b for r in reachable if r + a * b <= total}
    if total not in reachable:
        return False

    grid = [[False] * w for _ in range(h)]
    used = [False] * m

    def find_first_empty():
        for r in range(h):
            for c in range(w):
                if not grid[r][c]:
                    return r, c
        return None

    def fits(r, c, rh, rw):
        if r + rh > h or c + rw > w:
            return False
        for i in range(r, r + rh):
            for j in range(c, c + rw):
                if grid[i][j]:
                    return False
        return True

    def set_cells(r, c, rh, rw, val):
        for i in range(r, r + rh):
            for j in range(c, c + rw):
                grid[i][j] = val

    def backtrack(filled):
        if filled == total:
            return True
        pos = find_first_empty()
        if pos is None:
            return True
        r, c = pos
        tried_shapes = set()
        for idx in range(m):
            if used[idx]:
                continue
            a, b = tile_list[idx]
            for rh, rw in {(a, b), (b, a)}:
                # Skip identical orientations/shapes already attempted at this cell
                if (rh, rw) in tried_shapes:
                    continue
                tried_shapes.add((rh, rw))
                if fits(r, c, rh, rw):
                    set_cells(r, c, rh, rw, True)
                    used[idx] = True
                    if backtrack(filled + rh * rw):
                        return True
                    used[idx] = False
                    set_cells(r, c, rh, rw, False)
        return False

    return backtrack(0)

