def count_ways_to_stair(k: int) -> int:
    # Exact state-space count: positions reachable with a given jump value
    # and whether the last move was a down-step. Reaching k is counted each
    # time the walk lands on it. Bounded by the largest jump that can still
    # return to k, so the search stays finite.
    from functools import lru_cache

    if k < 0:
        return 0

    limit = k + 2
    max_jump = limit.bit_length() + 1

    @lru_cache(maxsize=None)
    def dp(stair, jump, last_down):
        if stair < 0 or stair > limit or jump > max_jump:
            return 0
        ways = 1 if stair == k else 0
        # go down (not on stair 0, not consecutively)
        if stair > 0 and not last_down:
            ways += dp(stair - 1, jump, True)
        # go up by 2^jump
        up = stair + (1 << jump)
        if up <= limit:
            ways += dp(up, jump + 1, False)
        return ways

    return dp(1, 0, False)

