        return 0

    # Overshoot is needed: a path may go above k and come back down.
    # Any jump 2^j with 2^j > 2k+2 cannot be followed by a return to k,
    # because each down-step is only one stair and the walk must come back.
    upper = 2 * k + 4
    max_jump = upper.bit_length() + 1

    sys.setrecursionlimit(max(10000, 4 * max_jump + 100))

