def expected_black_ball_position(N: int, K: int) -> int:
    if N == 1:
        return 1
    invN = pow(N, MOD - 2, MOD)
    alpha = (1 - 2 * invN) % MOD
    c = (N + 1) * invN % MOD
    E = 1
    for _ in range(K):
        E = (alpha * E + c) % MOD
    return E

