from collections import deque

def min_operations_to_rearrange(n: int, s: str, t: str) -> int:
    if s == t:
        return 0
    if sorted(s) != sorted(t):
        return -1
    # State: tuple of stones in order (empties are implicit at the end)
    start = tuple(s)
    target = tuple(t)
    dist = {start: 0}
    q = deque([start])
    while q:
        cur = q.popleft()
        d = dist[cur]
        for i in range(len(cur) - 1):
            pair = (cur[i], cur[i + 1])
            rest = cur[:i] + cur[i + 2:]
            nxt = rest + pair
            if nxt not in dist:
                dist[nxt] = d + 1
                if nxt == target:
                    return d + 1
                q.append(nxt)
    return -1

