import time


def find_palindrome_expression(n: int) -> str:
    """ Find a palindrome string S that represents a mathematical expression evaluating to n.

    Searches for a palindrome over digits 1-9 and '*' whose value is n.
    Uses a time budget so it returns '-1' rather than hanging.
    """
    if n < 1:
        return '-1'
    if 1 <= n <= 9:
        return str(n)

    deadline = time.time() + 5.0

    def is_pal(s: str) -> bool:
        return s == s[::-1]

    def digit_palindromes(max_val: int):
        # Digit-palindromes over 1-9 with 1 < value <= max_val, ascending
        out = []
        length = 1
        while True:
            lo = 10 ** (length - 1)
            if lo > max_val:
                break
            half = (length + 1) // 2
            halves = ['']
            for _ in range(half):
                halves = [h + d for h in halves for d in '123456789']
            for h in halves:
                p = h + h[::-1] if length % 2 == 0 else h + h[-2::-1]
                v = int(p)
                if 1 < v <= max_val:
                    out.append(v)
            length += 1
        return sorted(out)

    cands = digit_palindromes(n)

    def search(rem: int, chain: list):
        if time.time() > deadline:
            return None
        if rem == 1:
            s = '*'.join(str(f) for f in chain)
            if chain and is_pal(s) and len(s) <= 1000:
                return s
            return None
        for f in cands:
            if f > rem:
                break
            if rem % f == 0:
                r = search(rem // f, chain + [f])
                if r is not None:
                    return r
                if time.time() > deadline:
                    return None
        return None

    result = search(n, [])
    return result if result is not None else '-1'


