def count_good_sequences(N: int, M: int) -> int:
    # Brute force: enumerate integers n <= N, factor them, check goodness,
    # and sum the number of length-M ordered factorizations of n.
    # Only practical for small N.
    def sigma_mod3(n):
        total = 1
        x = n
        p = 2
        while p * p <= x:
            if x % p == 0:
                e = 0
                while x % p == 0:
                    x //= p
                    e += 1
                s = sum(p**i for i in range(e + 1))
                total = total * s
            p += 1
        if x > 1:
            total = total * (1 + x)
        return total

    def factor_exponents(n):
        exps = []
        p = 2
        while p * p <= n:
            if n % p == 0:
                e = 0
                while n % p == 0:
                    n //= p
                    e += 1
                exps.append(e)
            p += 1
        if n > 1:
            exps.append(1)
        return exps

    result = 0
    for n in range(1, N + 1):
        if sigma_mod3(n) % 3 != 0:
            continue
        ways = 1
        for a in factor_exponents(n):
            ways = ways * comb(a + M - 1, M - 1) % MOD
        result = (result + ways) % MOD
    return result

