def _berlekamp_massey(s):
    C = [1]
    B = [1]
    L = 0
    m_ = 1
    b = 1
    for i in range(len(s)):
        d = s[i]
        for j in range(1, L + 1):
            d = (d + C[j] * s[i - j]) % MOD
        if d == 0:
            m_ += 1
            continue
        coef = d * pow(b, MOD - 2, MOD) % MOD
        T = C[:]
        if len(C) < len(B) + m_:
            C += [0] * (len(B) + m_ - len(C))
        for j in range(len(B)):
            C[j + m_] = (C[j + m_] - coef * B[j]) % MOD
        if 2 * L <= i:
            L = i + 1 - L
            B = T
            b = d
            m_ = 1
        else:
            m_ += 1
    C = C[:L + 1] + [0] * max(0, L + 1 - len(C))
    # recurrence: s[i] = -sum_{j=1..L} C[j] * s[i-j]
    return [(-c) % MOD for c in C[1:L + 1]]


def _linear_rec_nth(rec, init, n):
