    def weight(s):
        d = 1
        for x in s:
            d *= (x + 1)
        return d % MOD

    # Compute per-length totals A(k) = sum over sequences of length k of d(X), k = 1..K
    K = 40
    dist = {tuple([0] * P): 1}
    A = []
    for _ in range(K):
        dist = step(dist)
        A.append(sum(c * weight(s) for s, c in dist.items()) % MOD)

    # Prefix sums: S(k) = sum_{j=1..k} A(j). The prefix sum sequence is what we need.
    S = []
    acc = 0
    for a in A:
        acc = (acc + a) % MOD
        S.append(acc)

    if n <= K:
        return S[n - 1]

    rec = _berlekamp_massey(S)
    return _linear_rec_nth(rec, S, n - 1)


