def _lis(seq):
    # length of longest strictly increasing subsequence
    tails = []
    import bisect
    for x in seq:
        i = bisect.bisect_left(tails, x)
        if i == len(tails):
            tails.append(x)
        else:
            tails[i] = x
    return len(tails)

def _lds(seq):
    return _lis([-x for x in seq])

def _brute_count(A, B, M):
    n = A * B - 1
    count = 0
    for p in permutations(range(1, n + 1)):
        p = list(p)
        if _lis(p) != A or _lds(p) != B:
            continue
        # condition 3: exists n' such that appending n'+0.5 keeps LIS and LDS
        ok = False
        for k in range(0, n + 1):
            q = p + [k + 0.5]
            if _lis(q) == A and _lds(q) == B:
                ok = True
                break
        if ok:
            count += 1
    return count % M

