from collections import deque

def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    def tile_of(px, py):
        # Find the tile containing the point (px + 0.5, py + 0.5).
        # Candidate tiles are searched in a bounded neighborhood.
        x, y = px + 0.5, py + 0.5
        for i in range(x // K - 2, x // K + 3):
            for j in range(y // K - 2, y // K + 3):
                for k in range(K):
                    if (i - j) % 2 == 0:
                        x0, x1 = i * K, (i + 1) * K
                        y0, y1 = j * K + k, j * K + k + 1
                    else:
                        x0, x1 = i * K + k, i * K + k + 1
                        y0, y1 = j * K, (j + 1) * K
                    if x0 <= x <= x1 and y0 <= y <= y1:
                        return (i, j, k)
        raise ValueError("no tile found")

    def neighbors(t):
        i, j, k = t
        res = []
        for di in range(-2, 3):
            for dj in range(-2, 3):
                for kk in range(K):
                    u = (i + di, j + dj, kk)
                    if u == t:
                        continue
                    if adjacent(t, u):
                        res.append(u)
        return res

    def edges(t):
        i, j, k = t
        if (i - j) % 2 == 0:
            return (i * K, (i + 1) * K, j * K + k, j * K + k + 1)
        return (i * K + k, i * K + k + 1, j * K, (j + 1) * K)

    def adjacent(a, b):
        ax0, ax1, ay0, ay1 = edges(a)
        bx0, bx1, by0, by1 = edges(b)
        # Shared positive-length segment along x or y.
        x_overlap = min(ax1, bx1) - max(ax0, bx0)
        y_overlap = min(ay1, by1) - max(ay0, by0)
        touch_x = (ax1 == bx0 or bx1 == ax0) and y_overlap > 0
        touch_y = (ay1 == by0 or by1 == ay0) and x_overlap > 0
        return touch_x or touch_y

    start = tile_of(S_x, S_y)
    target = tile_of(T_x, T_y)
    if start == target:
        return 0
    seen = {start}
    q = deque([(start, 0)])
    while q:
        t, d = q.popleft()
        for u in neighbors(t):
            if u == target:
                return d + 1
            if u not in seen:
                seen.add(u)
                q.append((u, d + 1))
    return -1

