def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    # Work in doubled coordinates so the point (px + 0.5, py + 0.5)
    # becomes the integer point (2*px + 1, 2*py + 1), and tile
    # boundaries become even integers. All arithmetic stays exact.
    def tile_bounds(i, j, k):
        if (i - j) % 2 == 0:
            return (2 * i * K, 2 * (i + 1) * K,
                    2 * (j * K + k), 2 * (j * K + k + 1))
        return (2 * (i * K + k), 2 * (i * K + k + 1),
                2 * j * K, 2 * (j + 1) * K)

    def contains(t, X, Y):
        x0, x1, y0, y1 = tile_bounds(*t)
        return x0 <= X <= x1 and y0 <= Y <= y1

    def tile_of(px, py):
        X, Y = 2 * px + 1, 2 * py + 1
        # Candidate indices around the point; the tile containing the
        # point has i near X // (2K) and j near Y // (2K).
        ci = X // (2 * K)
        cj = Y // (2 * K)
        for i in range(ci - 2, ci + 3):
            for j in range(cj - 2, cj + 3):
                for k in range(K):
                    if contains((i, j, k), X, Y):
                        return (i, j, k)
        raise ValueError("no tile found")

    def adjacent(a, b):
        ax0, ax1, ay0, ay1 = tile_bounds(*a)
        bx0, bx1, by0, by1 = tile_bounds(*b)
        x_overlap = min(ax1, bx1) - max(ax0, bx0)
        y_overlap = min(ay1, by1) - max(ay0, by0)
        touch_x = (ax1 == bx0 or bx1 == ax0) and y_overlap > 0
        touch_y = (ay1 == by0 or by1 == ay0) and x_overlap > 0
        return touch_x or touch_y

    def neighbors(t):
        i, j, k = t
        res = []
        for di in range(-2, 3):
            for dj in range(-2, 3):
                for kk in range(K):
                    u = (i + di, j + dj, kk)
                    if u != t and adjacent(t, u):
                        res.append(u)
        return res

    start = tile_of(S_x, S_y)
    target = tile_of(T_x, T_y)
    if start == target:
        return 0
    seen = {start}
    q = deque([(start, 0)])
    while q:
        t, d = q.popleft()
        for u in neighbors(t):
            if u == target:
                return d + 1
            if u not in seen:
                seen.add(u)
                q.append((u, d + 1))
    return -1

