from collections import deque

def bfs_reference(K, S, T):
    def bounds(i, j, k):
        if (i - j) % 2 == 0:
            return (2*i*K, 2*(i+1)*K, 2*(j*K+k), 2*(j*K+k+1))
        return (2*(i*K+k), 2*(i*K+k+1), 2*j*K, 2*(j+1)*K)

    def tile_of(px, py):
        X, Y = 2*px+1, 2*py+1
        ci, cj = X // (2*K), Y // (2*K)
        for i in range(ci-3, ci+4):
            for j in range(cj-3, cj+4):
                for k in range(K):
                    x0, x1, y0, y1 = bounds(i, j, k)
                    if x0 <= X <= x1 and y0 <= Y <= y1:
                        return (i, j, k)
        raise ValueError

    def adjacent(a, b):
        ax0, ax1, ay0, ay1 = bounds(*a)
        bx0, bx1, by0, by1 = bounds(*b)
        xo = min(ax1, bx1) - max(ax0, bx0)
        yo = min(ay1, by1) - max(ay0, by0)
        return ((ax1 == bx0 or bx1 == ax0) and yo > 0) or \
               ((ay1 == by0 or by1 == ay0) and xo > 0)

    s = tile_of(*S)
    t = tile_of(*T)
    seen, q = {s: 0}, deque([s])
    while q:
        cur = q.popleft()
        if cur == t:
            return seen[cur]
        i, j, _ = cur
        for di in range(-3, 4):
            for dj in range(-3, 4):
                for kk in range(K):
                    u = (i+di, j+dj, kk)
                    if u not in seen and adjacent(cur, u):
                        seen[u] = seen[cur] + 1
                        q.append(u)
    return -1

