from functools import lru_cache

def can_color_all_points(n: int, k: int) -> bool:
    # Exact game-tree search over reflection-symmetric colorings.
    # Feasible only for small n; used to validate a closed-form rule.
    def legal_moves(colored, player):
        # player 0 is Alice at 0, player 1 is Bob at k
        center = 0 if player == 0 else k
        res = []
        for p in range(n):
            if colored[p]:
                continue
            # reflection about the line through player's point and the center
            q = (2 * center - p) % n
            new = list(colored)
            new[p] = True
            new[q] = True
            res.append(tuple(new))
        return res

    @lru_cache(maxsize=None)
    def best(colored, turn):
        # maximize colored count achievable under cooperation
        if all(colored):
            return n
        moves = legal_moves(colored, turn)
        if not moves:
            return sum(colored)
        return max(best(m, 1 - turn) for m in moves)

    start = tuple([False] * n)
    return best(start, 0) == n

