from functools import lru_cache

def count_beautiful_numbers(l: int, r: int) -> int:
    def count_upto(n: int) -> int:
        # Count beautiful positive integers in [1, n]
        if n <= 0:
            return 0
        digits = list(map(int, str(n)))
        L = len(digits)

        # Enumerate (digit_sum, digit_product) states reachable from prefixes.
        # Memoized DP over position, tight flag, started flag, sum, product.
        # Product is kept as a dict key; products of digits 1..9 are limited in number.
        @lru_cache(maxsize=None)
        def dp(pos: int, tight: bool, started: bool, s: int, p: int) -> int:
            if pos == L:
                if not started:
                    return 0
                return 1 if p % s == 0 else 0
            limit = digits[pos] if tight else 9
            total = 0
            for d in range(limit + 1):
                nt = tight and (d == limit)
                if not started and d == 0:
                    total += dp(pos + 1, nt, False, 0, 1)
                else:
                    np_ = 0 if (p == 0 or d == 0) else p * d
                    total += dp(pos + 1, nt, True, s + d, np_)
            return total

        result = dp(0, True, False, 0, 1)
        dp.cache_clear()
        return result

    return count_upto(r) - count_upto(l - 1)

