def count_good_integers(num1: str, num2: str, min_sum: int, max_sum: int) -> int:
    MOD = 10**9 + 7

    def count_upto(s: str) -> int:
        # count x in [0, int(s)] with min_sum <= digit_sum(x) <= max_sum
        # dp over digit sums: ways[k] = number of digit strings (length so far) with sum k
        n = len(s)
        limit = max_sum
        # free[k] = number of ways to fill remaining positions freely with sum k
        # precompute ways to fill m free digits with sum k
        from functools import lru_cache
        # ways[m][k]: number of m-digit strings (leading zeros allowed) with digit sum k, capped at max_sum
        ways = [[0] * (limit + 1) for _ in range(n + 1)]
        ways[0][0] = 1
        for m in range(1, n + 1):
            prev = ways[m - 1]
            cur = ways[m]
            for k in range(limit + 1):
                if prev[k]:
                    for d in range(10):
                        if k + d <= limit:
                            cur[k + d] = (cur[k + d] + prev[k]) % MOD
        total = 0
        prefix = 0  # digit sum of the tight prefix
        for i, ch in enumerate(s):
            c = int(ch)
            remaining = n - i - 1
            for d in range(c):
                base = prefix + d
                # need final sum in [min_sum, max_sum]
                for k in range(limit + 1):
                    if ways[remaining][k]:
                        full = base + k
                        if min_sum <= full <= max_sum:
                            total = (total + ways[remaining][k]) % MOD
            prefix += c
        # include s itself
        if min_sum <= prefix <= max_sum:
            total = (total + 1) % MOD
        return total

    def digit_sum(s: str) -> int:
        return sum(int(c) for c in s)

    # count in [num1, num2] = count(<= num2) - count(< num1)
    result = count_upto(num2) - count_upto(num1) + (1 if min_sum <= digit_sum(num1) <= max_sum else 0)
    # count_upto includes 0 (sum 0), which is excluded by min_sum >= 1, so no correction needed
    return result % MOD

