        ways[0][0] = 1
        for m in range(1, n + 1):
            prev, cur = ways[m - 1], ways[m]
            for k in range(max_sum + 1):
                if prev[k]:
                    for d in range(10):
                        if k + d <= max_sum:
                            cur[k + d] = (cur[k + d] + prev[k]) % MOD
        total = 0
        prefix = 0
        for i, ch in enumerate(s):
            c = int(ch)
            remaining = n - i - 1
            for d in range(c):
                base = prefix + d
                for k in range(max_sum + 1):
                    full = base + k
                    if min_sum <= full <= max_sum:
                        total = (total + ways[remaining][k]) % MOD
            prefix += c
        if min_sum <= prefix <= max_sum:
            total = (total + 1) % MOD
        return total

    def digit_sum(s: str) -> int:
        return sum(int(c) for c in s)

    # Inclusive range [num1, num2]
    result = count_upto(num2) - count_upto(num1) + (1 if min_sum <= digit_sum(num1) <= max_sum else 0)
    return result % MOD

def count_good_integers(num1: str, num2: str, min_sum: int, max_sum: int) -> int:
    MOD = 10**9 + 7

    def count_below_or_equal(s: str, inclusive: bool) -> int:
        # Count x in [0, int(s)] (or [0, int(s)) if not inclusive)
        # with min_sum <= digit_sum(x) <= max_sum
        n = len(s)
        ways = [[0] * (max_sum + 1) for _ in range(n + 1)]
        ways[0][0] = 1
        for m in range(1, n + 1):
            prev, cur = ways[m - 1], ways[m]
            for k in range(max_sum + 1):
                if prev[k]:
                    for d in range(10):
                        if k + d <= max_sum:
                            cur[k + d] = (cur[k + d] + prev[k]) % MOD
        total = 0
        prefix = 0
        for i, ch in enumerate(s):
            c = int(ch)
            remaining = n - i - 1
            for d in range(c):
                base = prefix + d
                for k in range(max_sum + 1):
                    if min_sum <= base + k <= max_sum:
                        total = (total + ways[remaining][k]) % MOD
            prefix += c
        if inclusive and min_sum <= prefix <= max_sum:
            total = (total + 1) % MOD
        return total

    # Count in [num1, num2] = (numbers <= num2) - (numbers < num1)
    result = count_below_or_equal(num2, True) - count_below_or_equal(num1, False)
    return result % MOD

def min_changes_for_semi_palindromes(s: str, k: int) -> int:
    n = len(s)

    # cost[i][j]: min changes to make s[i..j] (inclusive) a semi-palindrome
    INF = float("inf")
    cost = [[INF] * n for _ in range(n)]
    for i in range(n):
        for j in range(i + 1, n):
            length = j - i + 1
            best = INF
            for d in range(1, length):
                if length % d != 0:
                    continue
                changes = 0
                for r in range(d):
                    # indices i+r, i+r+d, ... within [i, j]
                    lo, hi = i + r, j - ((length - 1 - r) % d)
                    while lo < hi:
                        if s[lo] != s[hi]:
                            changes += 1
                        lo += d
                        hi -= d
                best = min(best, changes)
            cost[i][j] = best

    # dp[p][j]: min changes to split first j chars into p semi-palindrome parts
    dp = [[INF] * (n + 1) for _ in range(k + 1)]
    dp[0][0] = 0
    for p in range(1, k + 1):
        for j in range(p * 2, n + 1):
            for i in range(p - 1, j - 1):
                if dp[p - 1][i] == INF:
                    continue
                if cost[i][j - 1] == INF:
                    continue
                val = dp[p - 1][i] + cost[i][j - 1]
                if val < dp[p][j]:
                    dp[p][j] = val
    return int(dp[k][n])

