def min_operations_to_sum(nums: List[int], target: int) -> int:
    """ Given a list of non-negative powers of 2 and a target sum, find the minimum number
    of operations needed to create a subsequence that sums to the target.

    Each operation takes a power 2^k (k >= 1) and replaces it with two copies of 2^(k-1).
    Returns the minimum number of operations, or -1 if impossible.
    """
    if target <= 0:
        return 0

    if sum(nums) < target:
        return -1

    counts = [0] * 64
    for x in nums:
        counts[x.bit_length() - 1] += 1

    ops = 0
    for bit in range(64):
        if not (target >> bit) & 1:
            continue
        if counts[bit] > 0:
            counts[bit] -= 1
            continue
        j = bit + 1
        while j < 64 and counts[j] == 0:
            j += 1
        if j >= 64:
            return -1
        counts[j] -= 1
        for k in range(bit, j):
            counts[k] += 1
        ops += j - bit
        counts[bit] -= 1

    return ops

