    n = len(s)

    def count_partitions(t) -> int:
        # Greedy: repeatedly take the longest prefix with at most k distinct chars.
        partitions = 0
        i = 0
        while i < n:
            counts = {}
            j = i
            while j < n:
                c = t[j]
                if c not in counts:
                    if len(counts) == k:
                        break
                    counts[c] = 0
                j += 1
            partitions += 1
            i = j
        return partitions

    best = count_partitions(s)

    letters = 'abcdefghijklmnopqrstuvwxyz'
    chars = list(s)
    for pos in range(n):
        original = chars[pos]
        for ch in letters:
            if ch == original:
                continue
            chars[pos] = ch
            val = count_partitions(chars)
            if val > best:
                best = val
        chars[pos] = original

    return best

