from typing import List

MOD = 998244353


def dice_sum_probability(n: int, dice_faces: List[int]) -> int:
    # Achievable-subset-sum states: bitmask over sums 1..10 (bit s-1 set means sum s is achievable).
    # Start with the empty subset, which achieves sum 0 (not tracked), so state = 0.
    FULL = (1 << 10) - 1
    dp = {0: 1}  # state -> probability (mod MOD)

    for d in dice_faces:
        inv_d = pow(d, MOD - 2, MOD)
        new_dp = {}

        def add(state, p):
            new_dp[state] = (new_dp.get(state, 0) + p) % MOD

        # Faces 1..min(d,10): each with probability 1/d
        top = min(d, 10)
        for state, p in dp.items():
            pp = p * inv_d % MOD
            for v in range(1, top + 1):
                # New achievable sums: existing ones, plus existing shifted by v, plus v itself
                shifted = (state << v) & FULL
                new_state = state | shifted | (1 << (v - 1))
                add(new_state, pp)

        # Faces above 10: probability (d-10)/d, contribute nothing new
        if d > 10:
            pn = (d - 10) * inv_d % MOD
            for state, p in dp.items():
                add(state, p * pn % MOD)

        dp = new_dp

    # Probability that sum 10 is achievable
    ans = 0
    for state, p in dp.items():
        if state & (1 << 9):
            ans = (ans + p) % MOD
    return ans

