def divide_into_good_sequences(L: int, R: int) -> List[Tuple[int, int]]:
    result: List[Tuple[int, int]] = []
    cur = L
    while cur < R:
        # largest power of two that cur is aligned to (lowest set bit);
        # for cur == 0 any size is aligned, so cap by the remaining length
        if cur == 0:
            size = 1
            while size * 2 <= R - cur:
                size *= 2
        else:
            size = cur & -cur
            while size > R - cur:
                size //= 2
        result.append((cur, cur + size))
        cur += size
    return result

