def sum_of_powers(nums: List[int], k: int) -> int:
    MOD = 10**9 + 7
    arr = sorted(nums)
    n = len(arr)

    # Candidate power values: all positive pairwise differences
    cands = sorted({arr[j] - arr[i] for i in range(n) for j in range(i + 1, n) if arr[j] - arr[i] > 0})

    def count_at_least(d: int) -> int:
        # Number of k-subsets whose sorted consecutive gaps are all >= d
        dp = [[0] * n for _ in range(k + 1)]
        for i in range(n):
            dp[1][i] = 1
        for c in range(2, k + 1):
            for i in range(n):
                total = 0
                for j in range(i):
                    if arr[i] - arr[j] >= d:
                        total += dp[c - 1][j]
                dp[c][i] = total % MOD
        return sum(dp[k]) % MOD

    # sum of min-gaps = sum over thresholds v of (v - prev) * #{subsets with min gap >= v}
    result = 0
    prev = 0
    for v in cands:
        result = (result + (v - prev) * count_at_least(v)) % MOD
        prev = v
    return result % MOD

