MOD = 998244353

def count_good_strings(n: int, k: int, s: str) -> int:
    """ Count assignments of '?' to 'A'/'B' such that no length-k substring
    is a palindrome. Returns count modulo 998244353. """
    # Precompute palindrome status for each k-bit window (bit j = char at position j)
    def is_pal(mask: int) -> bool:
        for i in range(k // 2):
            if ((mask >> i) & 1) != ((mask >> (k - 1 - i)) & 1):
                return False
        return True

    pal = [is_pal(m) for m in range(1 << k)]

    full = 1 << (k - 1)  # number of masks of length k-1
    # dp over masks of the last up-to (k-1) characters
    # Use a dict for the prefix phase (length < k-1), then switch to arrays.
    dp = {0: 1}  # empty prefix
    length = 0   # current number of characters placed

    for i in range(n):
        allowed = []
        c = s[i]
        if c == 'A':
            allowed = [0]
        elif c == 'B':
            allowed = [1]
        else:
            allowed = [0, 1]

        new_dp = {}
        for mask, ways in dp.items():
            for b in allowed:
                newlen = length + 1
                if newlen >= k:
                    # window of exactly k chars: mask (length k-1) plus new bit
                    window = (mask << 1) | b
                    # window bit 0 = oldest char... we want palindrome check on
                    # the k-bit value where bit order is consistent; palindrome
                    # check is symmetric so orientation does not matter.
                    if pal[window]:
                        continue
                    newmask = window & (full - 1)
                else:
                    newmask = (mask << 1) | b
                new_dp[newmask] = (new_dp.get(newmask, 0) + ways) % MOD
        dp = new_dp
        length = min(length + 1, k - 1)

    return sum(dp.values()) % MOD

