MOD = 10**9 + 7


def count_valid_permutations(n: int, requirements: List[List[int]]) -> int:
    """Count permutations of [0..n-1] where each prefix perm[0:end+1] has exactly
    cnt inversions for each [end, cnt] requirement. Return count mod 1e9+7."""
    count = 0
    for perm in permutations(range(n)):
        ok = True
        for end, cnt in requirements:
            inv = 0
            prefix = perm[:end + 1]
            for i in range(len(prefix)):
                for j in range(i + 1, len(prefix)):
                    if prefix[i] > prefix[j]:
                        inv += 1
            if inv != cnt:
                ok = False
                break
        if ok:
            count += 1
    return count % MOD

MOD = 998244353

def count_paths(N: int, M: int, K: int, extra_edges: list) -> int:
    """Count the number of ways to move exactly K times in a directed graph.

    The graph has N vertices numbered 1 to N with N+M edges:
    - Edges 1 to N form a cycle: vertex i connects to vertex i+1 (vertex N connects to vertex 1)
    - M additional edges are given in extra_edges as (source, destination) pairs

    Starting from vertex 1, count the number of distinct paths of exactly K moves.
    Return the count modulo 998244353.
    """
    # Adjacency: each vertex has its cycle successor plus any extra out-edges
    extra_out = {}
    for x, y in extra_edges:
        extra_out.setdefault(x, []).append(y)

    def succ(v):
        return [(v % N) + 1] + extra_out.get(v, [])

    # Key vertices: vertex 1 and all sources of extra edges
    keys = sorted(set([1] + list(extra_out.keys())))
    idx = {v: i for i, v in enumerate(keys)}
    S = len(keys)

    # Number of ways to go from key u to key w in exactly t moves, where the
    # walk is forced along the cycle except at key vertices. Each leg is a
    # choice at a key vertex followed by a forced cycle run to the next key.
    # leg[i][j] is a list-of-(length, count) pairs.
    legs = [[dict() for _ in range(S)] for _ in range(S)]
    for i, u in enumerate(keys):
        for w in succ(u):
            steps = 1
            cur = w
            while cur not in idx:
                cur = (cur % N) + 1
                steps += 1
            j = idx[cur]
            legs[i][j][steps] = legs[i][j].get(steps, 0) + 1

    # Time-expanded state: (key index, delay) where delay counts remaining
    # moves of the leg in progress. Build the transfer matrix over this.
    L = max(s for i in range(S) for j in range(S) for s in legs[i][j]) if S else 1
    size = S * L

    def sid(i, d):
        return i * L + d

    A = [[0] * size for _ in range(size)]
    for i in range(S):
        for d in range(1, L):
            A[sid(i, d)][sid(i, d - 1)] = 1
    for i in range(S):
        for j in range(S):
            for s, c in legs[i][j].items():
                A[sid(j, s - 1)][sid(i, 0)] = (A[sid(j, s - 1)][sid(i, 0)] + c) % MOD

    def matmul(X, Y):
        n = len(X)
        Z = [[0] * n for _ in range(n)]
        for r in range(n):
            Xr = X[r]
            Zr = Z[r]
            for k in range(n):
                a = Xr[k]
                if a:
                    Yk = Y[k]
                    for c in range(n):
                        Zr[c] += a * Yk[c]
            for c in range(n):
                Zr[c] %= MOD
        return Z

    P = [[int(r == c) for c in range(size)] for r in range(size)]
    base = A
    e = K
    while e:
        if e & 1:
            P = matmul(P, base)
        base = matmul(base, base)
        e >>= 1

    # Start at vertex 1 at a leg boundary; count walks completing at a boundary
    start = sid(idx[1], 0)
    total = 0
    for i in range(S):
        total += P[sid(i, 0)][start]
    return total % MOD

from typing import List
from functools import lru_cache


def max_score(grid: List[List[int]]) -> int:
    """ Given a 2D matrix of positive integers, select one or more cells such that:
    - No two selected cells are in the same row
    - The values in the selected cells are unique

    Return the maximum sum of values you can achieve.

    Args:
        grid: A 2D list where 1 <= len(grid), len(grid[i]) <= 10 and 1 <= grid[i][j] <= 100

    >>> max_score([[1,2,3],[4,3,2],[1,1,1]])
    8
    >>> max_score([[8,7,6],[8,3,2]])
    15
    """
    n = len(grid)
    values = sorted({v for row in grid for v in row})
    idx = {v: i for i, v in enumerate(values)}

    @lru_cache(maxsize=None)
    def dp(row: int, used: int) -> int:
        if row == n:
            return 0
        best = dp(row + 1, used)
        for v in grid[row]:
            bit = 1 << idx[v]
            if not used & bit:
                cand = v + dp(row + 1, used | bit)
                if cand > best:
                    best = cand
        return best

    return dp(0, 0)

