def max_subsequence_value(nums: List[int], k: int) -> int:
    n = len(nums)
    if k == 0:
        return 0

    def bits_of(mask: int):
        res = []
        v = 0
        while mask:
            if mask & 1:
                res.append(v)
            mask >>= 1
            v += 1
        return res

    def or_shift(mask: int, val: int) -> int:
        # set of {x | val : x in mask}
        out = 0
        for x in bits_of(mask):
            out |= 1 << (x | val)
        return out

    # prefix[p][j]: bitmask of achievable ORs choosing j elements from nums[:p]
    prefix = [None] * (n + 1)
    dp = [0] * (k + 1)
    dp[0] = 1 << 0  # empty selection has OR 0
    prefix[0] = dp[:]
    for p in range(1, n + 1):
        v = nums[p - 1]
        for j in range(k, 0, -1):
            if dp[j - 1]:
                dp[j] |= or_shift(dp[j - 1], v)
        prefix[p] = dp[:]

    # suffix[p][j]: bitmask of achievable ORs choosing j elements from nums[p:]
    suffix = [None] * (n + 1)
    dp = [0] * (k + 1)
    dp[0] = 1 << 0
    suffix[n] = dp[:]
    for p in range(n - 1, -1, -1):
        v = nums[p]
        for j in range(k, 0, -1):
            if dp[j - 1]:
                dp[j] |= or_shift(dp[j - 1], v)
        suffix[p] = dp[:]

    best = 0
    found = False
    for p in range(n + 1):
        a_mask = prefix[p][k]
        b_mask = suffix[p][k]
        if a_mask == 0 or b_mask == 0:
            continue
        for a in bits_of(a_mask):
            for b in bits_of(b_mask):
                val = a ^ b
                if not found or val > best:
                    best = val
                    found = True
    return best

from typing import List


def max_subsequence_value(nums: List[int], k: int) -> int:
    n = len(nums)
    if k == 0:
        return 0

    # prefix[p][j]: set of achievable ORs choosing j elements from nums[:p]
    prefix = [[set() for _ in range(k + 1)] for _ in range(n + 1)]
    prefix[0][0] = {0}
    for p in range(1, n + 1):
        v = nums[p - 1]
        for j in range(k + 1):
            prefix[p][j] = set(prefix[p - 1][j])
            if j > 0:
                for x in prefix[p - 1][j - 1]:
                    prefix[p][j].add(x | v)

    # suffix[p][j]: set of achievable ORs choosing j elements from nums[p:]
    suffix = [[set() for _ in range(k + 1)] for _ in range(n + 1)]
    suffix[n][0] = {0}
    for p in range(n - 1, -1, -1):
        v = nums[p]
        for j in range(k + 1):
            suffix[p][j] = set(suffix[p + 1][j])
            if j > 0:
                for x in suffix[p + 1][j - 1]:
                    suffix[p][j].add(x | v)

    best = None
    for p in range(n + 1):
        for a in prefix[p][k]:
            for b in suffix[p][k]:
                val = a ^ b
                if best is None or val > best:
                    best = val
    return best if best is not None else 0

