from typing import List, Tuple


def max_production_capacity(n: int, x: int, machines: List[Tuple[int, int, int, int]]) -> int:
    def min_cost_for_process(c: int, a: int, p: int, b: int, q: int) -> int:
        # Minimize s*p + t*q subject to s*a + t*b >= c, s, t >= 0 integers.
        if c <= 0:
            return 0
        # Make machine "e" the one with better cost per product (p/a <= q/b).
        if p * b <= q * a:
            ea, ep, oa, op = a, p, b, q
        else:
            ea, ep, oa, op = b, q, a, p
        # Using >= oa copies of the other machine can always be replaced by ea copies
        # of the efficient machine without losing products or increasing cost,
        # so the other machine's count need only range over [0, ea-1] (and up to need).
        best = None
        max_other = min(ea - 1, -(-c // oa))
        for k in range(max_other + 1):
            rem = c - k * oa
            e = 0 if rem <= 0 else -(-rem // ea)
            cost = e * ep + k * op
            if best is None or cost < best:
                best = cost
        # Also consider pure efficient machine (k = 0 already covers it).
        return best

    def feasible(c: int) -> bool:
        total = 0
        for a, p, b, q in machines:
            total += min_cost_for_process(c, a, p, b, q)
            if total > x:
                return False
        return total <= x

    lo, hi = 0, 10**9 + 1
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if feasible(mid):
            lo = mid
        else:
            hi = mid - 1
    return lo

