                best = cost
        return best

    def feasible(c: int) -> bool:
        total = 0
        for a, p, b, q in machines:
            total += min_cost_for_process(c, a, p, b, q)
            if total > x:
                return False
        return total <= x

    lo, hi = 0, 10**9 + 1
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if feasible(mid):
            lo = mid
        else:
            hi = mid - 1
    return lo

