def count_valid_grids(H: int, W: int, grid: list[str]) -> int:
    MOD = 998244353

    # Transpose so that the profile width is the smaller dimension.
    if W > H:
        new_grid = [''.join(grid[r][c] for r in range(H)) for c in range(W)]
        grid = new_grid
        H, W = W, H

    # State: tuple of length W holding colors (1..3) of the last W processed cells,
    # with 0 meaning "no cell yet" (boundary).
    # dp maps state -> count.
    dp = {tuple([0] * W): 1}

    for r in range(H):
        for c in range(W):
            ch = grid[r][c]
            if ch == '?':
                allowed = (1, 2, 3)
            else:
                allowed = (int(ch),)
            new_dp = {}
            for state, cnt in dp.items():
                up = state[c]          # cell at (r-1, c), 0 if none
                left = state[c - 1] if c > 0 else 0  # cell at (r, c-1), 0 if none
                for color in allowed:
                    if color == up or color == left:
                        continue
                    lst = list(state)
                    lst[c] = color
                    key = tuple(lst)
                    new_dp[key] = (new_dp.get(key, 0) + cnt) % MOD
            dp = new_dp
            if not dp:
                return 0

    return sum(dp.values()) % MOD

