from typing import List, Tuple

def minimize_path_weights(n: int, edges: List[Tuple[int, int, int]], a: List[int], b: List[int]) -> int:
    # Kruskal's MST with union-find
    parent = list(range(n + 1))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    adj = [[] for _ in range(n + 1)]
    for u, v, w in sorted(edges, key=lambda e: e[2]):
        ru, rv = find(u), find(v)
        if ru != rv:
            parent[ru] = rv
            adj[u].append((v, w))
            adj[v].append((u, w))

    # Minimax distance from every vertex via BFS/DFS on the tree
    def minimax_from(src):
        dist = [None] * (n + 1)
        dist[src] = 0
        stack = [src]
        while stack:
            x = stack.pop()
            for y, w in adj[x]:
                if dist[y] is None:
                    dist[y] = max(dist[x], w)
                    stack.append(y)
        return dist

    m = len(a)
    cost = [[0] * m for _ in range(m)]
    for i in range(m):
        d = minimax_from(a[i])
        for j in range(m):
            cost[i][j] = d[b[j]]

    # Hungarian algorithm (min-cost assignment), O(m^3)
    INF = float('inf')
    u_p = [0] * (m + 1)
    v_p = [0] * (m + 1)
    p = [0] * (m + 1)
    way = [0] * (m + 1)
    for i in range(1, m + 1):
        p[0] = i
        j0 = 0
        minv = [INF] * (m + 1)
        used = [False] * (m + 1)
        while True:
            used[j0] = True
            i0 = p[j0]
            delta = INF
            j1 = 0
            for j in range(1, m + 1):
                if not used[j]:
                    cur = cost[i0 - 1][j - 1] - u_p[i0] - v_p[j]
                    if cur < minv[j]:
                        minv[j] = cur
                        way[j] = j0
                    if minv[j] < delta:
                        delta = minv[j]
                        j1 = j
            for j in range(m + 1):
                if used[j]:
                    u_p[p[j]] += delta
                    v_p[j] -= delta
                else:
                    minv[j] -= delta
            j0 = j1
            if p[j0] == 0:
                break
        while True:
            j1 = way[j0]
            p[j0] = p[j1]
            j0 = j1
            if j0 == 0:
                break

    total = 0
    for j in range(1, m + 1):
        total += cost[p[j] - 1][j - 1]
    return total

