def brute(n, edges):
    adj = {i: set() for i in range(1, n + 1)}
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)
    best = 0
    for mask in range(1, 1 << n):
        keep = [i + 1 for i in range(n) if mask >> i & 1]
        ks = set(keep)
        # induced edges
        ie = [(u, v) for u in keep for v in adj[u] if v in ks and u < v]
        if len(ie) != len(keep) - 1:
            continue  # not a tree (forest or disconnected)
        deg = {u: 0 for u in keep}
        for u, v in ie:
            deg[u] += 1
            deg[v] += 1
        for c in keep:
            xs = [u for u in adj[c] if u in ks]
            if not xs:
                continue
            ok = True
            for x in xs:
                leaves = [w for w in adj[x] if w in ks and w != c]
                if not leaves or any(deg[w] != 1 for w in leaves):
                    ok = False
                    break
            # every kept vertex must be center, an x-vertex, or a leaf of some x
            if ok and len(keep) == 1 + len(xs) + sum(
                len([w for w in adj[x] if w in ks and w != c]) for x in xs
            ):
                best = max(best, len(keep))
    return n - best

