def fixed_entries(M, n):
    count = 0
    for i in range(n):
        for j in range(n):
            flippable = False
            for i2 in range(n):
                if i2 == i:
                    continue
                for j2 in range(n):
                    if j2 == j:
                        continue
                    a, b, c, d = M[i][j], M[i][j2], M[i2][j], M[i2][j2]
                    if a == d and b == c and a != b:
                        flippable = True
            if not flippable:
                count += 1
    return count

