MOD = 998244353

def _is_polish(seq):
    # Parse seq as a preorder encoding: each value v opens v child blocks.
    # Valid iff the parse consumes exactly all elements.
    need = 1  # number of blocks still to be read
    for v in seq:
        if need <= 0:
            return False
        need = need - 1 + v
    return need == 0

def count_polish_sequences(n: int, a: list[int]) -> int:
    # Brute force, only suitable for small n: enumerate all sequences
    # with entries in [0, n), keep Polish ones that are <= a lexicographically.
    from itertools import product
    total = 0
    for seq in product(range(n), repeat=n):
        if list(seq) <= a and _is_polish(seq):
            total += 1
    return total % MOD

import sys
from functools import lru_cache

MOD = 998244353

def count_polish_sequences(n: int, a: list[int]) -> int:
    sys.setrecursionlimit(max(10000, 4 * n + 100))

    # State: (pos, need, tight). `need` is the number of pending Polish blocks
    # still to be read. A sequence is Polish iff `need` stays satisfiable and
    # ends at 0 exactly at position n.
    @lru_cache(maxsize=None)
    def dp(pos: int, need: int, tight: bool) -> int:
        remaining = n - pos
        if need > remaining:
            return 0
        if pos == n:
            return 1 if need == 0 else 0
        if need <= 0:
            return 0
        upper = a[pos] if tight else n - 1
        total = 0
        for v in range(min(upper, n - 1) + 1):
            new_need = need - 1 + v
            if new_need > n - pos - 1:
                continue
            total += dp(pos + 1, new_need, tight and v == a[pos])
        return total % MOD

    return dp(0, 1, True) % MOD

