def count_sequences_without_subsequence(N: int, M: int, K: int, X: list[int]) -> int:
    X = tuple(X)
    all_pats = list(product(range(1, K + 1), repeat=M))
    # X must be one of the length-M patterns, which it always is here.
    others = [p for p in all_pats if p != X]
    count = 0
    for T in product(range(1, K + 1), repeat=N):
        # Every pattern other than X must embed in T.
        ok = True
        for p in others:
