MOD = 998244353

def count_good_string_replacements(n: int, k: int, s: str) -> int:
    # Parity of prefix as a 3-bit mask over (A,B,C).
    # Substring [i,j) is good iff mask[i] ^ mask[j] in {0b000, 0b111}, and j > i.
    LETTER_BIT = {'A': 1, 'B': 2, 'C': 4}

    @lru_cache(maxsize=None)
    def dp(pos, cur_mask, hist, good):
        # hist: tuple of 8 counts of previous prefix masks (including the mask at pos
        # before processing character pos); good: number of good substrings so far (capped at k)
        if pos == n:
            return 1 if good >= k else 0
        choices = ['A', 'B', 'C'] if s[pos] == '?' else [s[pos]]
        total = 0
        for ch in choices:
            new_mask = cur_mask ^ LETTER_BIT[ch]
            # count good substrings ending at new prefix position (pos+1)
            add = hist[new_mask] + hist[new_mask ^ 7]
            new_good = min(k, good + add)
            new_hist = list(hist)
            new_hist[new_mask] += 1
            total = (total + dp(pos + 1, new_mask, tuple(new_hist), new_good)) % MOD
        return total

    init_hist = [0] * 8
    init_hist[0] = 1  # empty prefix has mask 0
    if k == 0:
        # Every assignment qualifies; count is product of choices.
        return pow(3, s.count('?'), MOD)
    return dp(0, 0, tuple(init_hist), 0)

