def count_good_string_replacements(n: int, k: int, s: str) -> int:
    LETTER_BIT = {'A': 1, 'B': 2, 'C': 4}

    if k == 0:
        return pow(3, s.count('?'), MOD)

    # State: (cur_mask, hist, good) -> number of ways.
    # hist is a tuple of 8 counts of prefix masks seen so far (including the current one).
    # good is capped at k.
    init_hist = [0] * 8
    init_hist[0] = 1
    states = {(0, tuple(init_hist), 0): 1}

    for pos in range(n):
        choices = ['A', 'B', 'C'] if s[pos] == '?' else [s[pos]]
        nxt = {}
        for (cur_mask, hist, good), ways in states.items():
            for ch in choices:
                new_mask = cur_mask ^ LETTER_BIT[ch]
                add = hist[new_mask] + hist[new_mask ^ 7]
                new_good = min(k, good + add)
                h = list(hist)
                h[new_mask] += 1
                key = (new_mask, tuple(h), new_good)
                nxt[key] = (nxt.get(key, 0) + ways) % MOD
        states = nxt

    total = 0
    for (_, _, good), ways in states.items():
        if good >= k:
            total = (total + ways) % MOD
    return total

