def min_longest_substring(s: str, numOps: int) -> int:
    n = len(s)

    def flips_needed(limit: int) -> int:
        # Minimum flips so that no run of identical characters exceeds `limit`.
        # Each run of length r needs r // (limit + 1) flips (break it every limit+1 chars).
        flips = 0
        run_len = 0
        prev = None
        for ch in s:
            if ch == prev:
                run_len += 1
            else:
                if prev is not None:
                    flips += run_len // (limit + 1)
                prev = ch
                run_len = 1
        flips += run_len // (limit + 1)
        return flips

    lo, hi = 1, n
    while lo < hi:
        mid = (lo + hi) // 2
        if flips_needed(mid) <= numOps:
            hi = mid
        else:
            lo = mid + 1
    return lo

