from math import comb

def count_balanced_graphs(n: int, p: int) -> list[int]:
    maxM = n * (n - 1) // 2

    def pmul(a, b):
        res = [0] * (maxM + 1)
        for i, x in enumerate(a):
            if x == 0:
                continue
            for j, y in enumerate(b):
                if y and i + j <= maxM:
                    res[i + j] = (res[i + j] + x * y) % p
        return res

    def padd(a, b):
        return [(x + y) % p for x, y in zip(a, b)]

    def within_poly(s):
        e = s * (s - 1) // 2
        return [comb(e, k) % p if k <= e else 0 for k in range(maxM + 1)]

    def between_poly(a, b):
        # each vertex in layer B picks a nonempty subset of layer A
        q = [comb(a, k) % p for k in range(a + 1)]
        q[0] = 0
        res = [1] + [0] * maxM
        for _ in range(b):
            res = pmul(res, q)
        return res

    def compositions(remaining):
        if remaining == 0:
            yield []
            return
        for first in range(1, remaining + 1):
            for rest in compositions(remaining - first):
                yield [first] + rest

    result = [0] * (maxM + 1)
    for comp in compositions(n - 1):
        layers = [1] + comp
        even_total = sum(layers[0::2])
        odd_total = sum(layers[1::2])
        if even_total != odd_total:
            continue
        # assign labels 2..n to layers 1..k
        ways = 1
        rem = n - 1
        for s in comp:
            ways = ways * comb(rem, s) % p
            rem -= s
        poly = [ways] + [0] * maxM
        for s in layers:
            poly = pmul(poly, within_poly(s))
        for i in range(len(layers) - 1):
            poly = pmul(poly, between_poly(layers[i], layers[i + 1]))
        result = padd(result, poly)

    return [result[M] % p for M in range(n - 1, maxM + 1)]

