def count_strings_by_lcs_length(n: int, m: int, s: str) -> List[int]:
    MOD = 998244353

    # Represent LCS DP row as a tuple dp[0..n], where dp[j] = LCS(prefix, s[:j]).
    # Rows are nondecreasing with steps of 0 or 1, so the row is determined
    # by the tuple of differences; we memoize by the row tuple directly.
    def next_row(row, c):
        new = [0] * (n + 1)
        for j in range(1, n + 1):
            if s[j - 1] == c:
                new[j] = row[j - 1] + 1
            else:
                new[j] = max(row[j], new[j - 1])
        return tuple(new)

    start = tuple([0] * (n + 1))
    cur = {start: 1}
    for _ in range(m):
        nxt = {}
        for row, cnt in cur.items():
            for ci in range(26):
                c = chr(ord('a') + ci)
                nr = next_row(row, c)
                nxt[nr] = (nxt.get(nr, 0) + cnt) % MOD
        cur = nxt

    res = [0] * (n + 1)
    for row, cnt in cur.items():
        res[row[n]] = (res[row[n]] + cnt) % MOD
    return res

