    MOD = 998244353

    # State: the LCS row with s, encoded as a tuple over j = 0..n.
    # Transition on character c: standard LCS row update.
    def step(row, c):
        new = [0] * (n + 1)
        for j in range(1, n + 1):
            if s[j - 1] == c:
                new[j] = row[j - 1] + 1
            else:
                new[j] = max(row[j], new[j - 1])
        return tuple(new)

    cur = {tuple([0] * (n + 1)): 1}
    letters = [chr(ord('a') + i) for i in range(26)]
    for _ in range(m):
        nxt = {}
        for row, cnt in cur.items():
            for c in letters:
                nr = step(row, c)
                nxt[nr] = (nxt.get(nr, 0) + cnt) % MOD
        cur = nxt

    res = [0] * (n + 1)
    for row, cnt in cur.items():
        k = row[n]
        res[k] = (res[k] + cnt) % MOD
    return res

