def max_shortest_distance(n: int, m: int, k: int, edges: List[Tuple[int, int]]) -> int:
    INF = 10**9

    def min_ones_needed(D: int) -> int:
        # Layered graph: node (v, i) = reached v having used i weight-1 edges (i < D).
        # Traversing an edge u->v either keeps weight 0 (same layer, must stay
        # uncuttable) or sets it to 1 (cost 1, moves to next layer).
        # We need every path from (1,0) to (n, i) for i < D to be blocked,
        # i.e. a min-cut separating (1,0) from all (n, i), i < D.
        node_id = {}

        def nid(v, i):
            if (v, i) not in node_id:
                node_id[(v, i)] = len(node_id) + 2
            return node_id[(v, i)]

        S, T = 0, 1
        cap = {}

        def add(a, b, c):
            cap.setdefault(a, {})
            cap.setdefault(b, {})
            cap[a][b] = cap[a].get(b, 0) + c
            cap[b].setdefault(a, 0)

        add(S, nid(1, 0), INF)
        for i in range(D):
            add(nid(n, i), T, INF)
        for i in range(D):
            for (u, v) in edges:
                # Set this edge to weight 1: cost 1, advance layer.
                add(nid(u, i), nid(v, i + 1), 1)
                # Keep weight 0: cannot be cut, stays in layer.
                add(nid(u, i), nid(v, i), INF)

        flow = 0
        while True:
            parent = {S: None}
            q = deque([S])
            while q and T not in parent:
                x = q.popleft()
                for y, c in cap.get(x, {}).items():
                    if c > 0 and y not in parent:
                        parent[y] = x
                        q.append(y)
            if T not in parent:
                break
            b = INF
            y = T
            while parent[y] is not None:
                x = parent[y]
                b = min(b, cap[x][y])
                y = x
            y = T
            while parent[y] is not None:
                x = parent[y]
                cap[x][y] -= b
                cap[y][x] += b
                y = x
            flow += b
            if flow > m:
                break
        return flow

    # Binary search the largest D such that at least D weight-1 edges are forced
    # on every path, using at most k weight-1 edges.
    lo, hi = 0, n
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if min_ones_needed(mid) <= k:
            lo = mid
        else:
            hi = mid - 1
    return lo

