def max_shortest_distance(n: int, m: int, k: int, edges: List[Tuple[int, int]]) -> int:
    # Brute force over all k-subsets of edges set to weight 1; compute the
    # 0-1 shortest path distance from 1 to n for each, and take the maximum.
    from itertools import combinations

    def dist_1_to_n(ones: set) -> int:
        # 0-1 BFS: edges in `ones` cost 1, all others cost 0.
        INF = float("inf")
        adj = [[] for _ in range(n + 1)]
        for idx, (u, v) in enumerate(edges):
            adj[u].append((v, 1 if idx in ones else 0))
        d = [INF] * (n + 1)
        d[1] = 0
        dq = deque([1])
        while dq:
            x = dq.popleft()
            for y, w in adj[x]:
                if d[x] + w < d[y]:
                    d[y] = d[x] + w
                    if w == 0:
                        dq.appendleft(y)
                    else:
                        dq.append(y)
        return d[n]

    best = 0
    for combo in combinations(range(m), k):
        best = max(best, dist_1_to_n(set(combo)))
    return best

