MOD = 998244353

def count_paths(W: int, H: int, L: int, R: int, D: int, U: int) -> int:
    # Direct DP over the grid: g[x][y] = number of monotone block-walks
    # ending at (x, y). Each walk is counted once by its endpoint, so the
    # answer is the sum of g over all blocks.
    # Note: this is O(W*H) and will be too slow for the largest tests.
    def is_block(x, y):
        return 0 <= x <= W and 0 <= y <= H and (x < L or x > R or y < D or y > U)

    total = 0
    prev_row = [0] * (W + 1)
    for y in range(H + 1):
        cur = [0] * (W + 1)
        for x in range(W + 1):
            if not is_block(x, y):
                continue
            val = 1
            if x > 0 and is_block(x - 1, y):
                val += cur[x - 1]
            if y > 0 and is_block(x, y - 1):
                val += prev_row[x]
            val %= MOD
            cur[x] = val
            total = (total + val) % MOD
        prev_row = cur
    return total % MOD

