MOD = 998244353

def sum_good_sequence_scores(n: int, a: list[int]) -> int:
    """ Given a positive integer n and a list a of length n-1 containing positive integers,
    find the sum of scores of all good sequences modulo 998244353.

    A sequence S of length n is called "good" if:
    - For every i from 0 to n-2, f(S[i]/S[i+1]) = a[i], where f(p/q) = p*q when gcd(p,q) = 1
    - gcd of all elements in S equals 1

    The score of a sequence is the product of all its elements.

    Args:
        n: The length of the sequences (2 <= n <= 1000)
        a: List of n-1 positive integers (1 <= a[i] <= 1000)

    Returns:
        The sum of scores of all good sequences modulo 998244353

    >>> sum_good_sequence_scores(6, [1, 9, 2, 2, 9])
    939634344
    >>> sum_good_sequence_scores(2, [9])
    18
    >>> sum_good_sequence_scores(3, [1, 1])
    1
    """
    from math import gcd

    def coprime_splits(x):
        # All (p, q) with p*q = x and gcd(p, q) = 1
        res = []
        for p in range(1, x + 1):
            if x % p == 0:
                q = x // p
                if gcd(p, q) == 1:
                    res.append((p, q))
        return res

    def mobius(m):
        result = 1
        d = 2
        while d * d <= m:
            if m % d == 0:
                m //= d
                if m % d == 0:
                    return 0
                result = -result
            d += 1
        if m > 1:
            result = -result
        return result

    def sum_scores_with_common_factor(g):
        # Sum of products over sequences where every S[i] is divisible by g.
        # Each S[i] = g * s_i, so the score scales by g^n.
        # We run the chain DP on the reduced values, requiring that each
        # element of the split be divisible by g.
        splits_all = []
        for x in a:
            valid = []
            for p, q in coprime_splits(x):
                if p % g == 0 and q % g == 0:
                    valid.append((p, q))
            splits_all.append(valid)

        # state: dict mapping current element value -> weighted sum of products
        # of all elements so far (including the current element).
        # Initialize with S[0] = p for the first split; S[1] = q.
        state = {}
        if not splits_all or not splits_all[0]:
            return 0
        for p, q in splits_all[0]:
            state[q] = (state.get(q, 0) + p * q) % MOD

        for i in range(1, n - 1):
            new_state = {}
            for prev_val, w in state.items():
                for p, q in splits_all[i]:
                    if prev_val == p:
                        new_state[q] = (new_state.get(q, 0) + w * q) % MOD
            state = new_state
            if not state:
                return 0

        total = sum(state.values()) % MOD
        return total

    answer = 0
    max_g = 1
    for x in a:
        max_g = max(max_g, x)
    for g in range(1, max_g + 1):
        mu = mobius(g)
        if mu == 0:
            continue
        answer = (answer + mu * sum_scores_with_common_factor(g)) % MOD
    return answer % MOD

def count_in_degree_sequences(n: int, s: str) -> int:
    MOD = 998244353
    # Edges: cycle edges (i, (i+1) % n) for i in 0..n-1, plus (i, n) where s[i] == '1'
    edges = []
    for i in range(n):
        edges.append((i, (i + 1) % n))
    for i in range(n):
        if s[i] == '1':
            edges.append((i, n))
    m = len(edges)
    seen = set()
    # Each edge oriented one of two ways: bit 0 -> (u, v) means v gains in-degree; bit 1 -> u gains
    for mask in range(1 << m):
        deg = [0] * (n + 1)
        for k, (u, v) in enumerate(edges):
            if (mask >> k) & 1:
                deg[u] += 1
            else:
                deg[v] += 1
        seen.add(tuple(deg))
    return len(seen) % MOD

