def brute_force_count(n: int, s: str) -> int:
    def is_balanced(t: str) -> bool:
        d = 0
        for ch in t:
            d += 1 if ch == '(' else -1
            if d < 0:
                return False
        return d == 0

    seen = {s}
    queue = deque([s])
    while queue:
        cur = queue.popleft()
        for i in range(n):
            for j in range(i + 2, n + 1, 2):
                sub = cur[i:j]
                if is_balanced(sub):
                    flipped = ''.join(')' if c == '(' else '(' for c in sub)
                    nxt = cur[:i] + flipped + cur[j:]
                    if nxt not in seen:
                        seen.add(nxt)
                        queue.append(nxt)
    return len(seen) % 998244353

