from typing import List


def max_product_subsequence(nums: List[int], k: int, limit: int) -> int:
    """Find a non-empty subsequence of nums whose alternating sum equals k
    and whose product is maximal without exceeding limit. Return -1 if none."""
    n = len(nums)
    OFFSET = 12 * n
    SIZE = 2 * OFFSET + 1

    # dp[parity][s]: set of achievable products <= limit for non-empty
    # subsequences with alternating sum offset s. parity = length mod 2.
    dp = [[set() for _ in range(SIZE)] for _ in range(2)]

    for x in nums:
        new_dp = [[set(s) for s in row] for row in dp]

        if x <= limit:
            new_dp[1][x + OFFSET].add(x)

        for parity in range(2):
            for s in range(SIZE):
                prods = dp[parity][s]
                if not prods:
                    continue
                ns = s + x if parity == 0 else s - x
                if not (0 <= ns < SIZE):
                    continue
                for p in prods:
                    q = p * x
                    if q <= limit:
                        new_dp[1 - parity][ns].add(q)
        dp = new_dp

    target = k + OFFSET
    best = -1
    if 0 <= target < SIZE:
        for parity in range(2):
            if dp[parity][target]:
                best = max(best, max(dp[parity][target]))
    return best

