from typing import Optional, List


def solve_grid(n: int, r: str, c: str) -> Optional[List[str]]:
    """ Given an integer N and strings R and C of length N consisting of 'A', 'B', and 'C',
    determine if it's possible to fill an N×N grid such that:
    - Each row and column contains exactly one 'A', one 'B', and one 'C'
    - The leftmost character written in the i-th row matches the i-th character of R
    - The topmost character written in the i-th column matches the i-th character of C

    Empty cells are represented by '.' in the output.

    Args:
        n: The size of the grid (3 <= n <= 5)
        r: String of length n specifying leftmost characters in each row
        c: String of length n specifying topmost characters in each column

    Returns:
        A list of n strings representing the filled grid if possible, None otherwise.
        Each string has length n, where '.' represents empty cells.

    >>> solve_grid(3, 'ABC', 'ABC')
    ['ABC', 'BCA', 'CAB']
    >>> solve_grid(3, 'AAA', 'BBB')
    None
    """
    letters = "ABC"
    # Each row/column needs exactly one A, B, C; with n in {3,4,5} that means
    # n-3 extra cells must be '.'. Each row/col has at most one of each letter.
    grid = [['.'] * n for _ in range(n)]
    row_used = [set() for _ in range(n)]
    col_used = [set() for _ in range(n)]

    def row_ok(i: int) -> bool:
        # Leftmost written char in row i must equal r[i] (if row has any letter).
        for j in range(n):
            if grid[i][j] != '.':
                return grid[i][j] == r[i]
        return True

    def col_ok(j: int) -> bool:
        # Topmost written char in column j must equal c[j].
        for i in range(n):
            if grid[i][j] != '.':
                return grid[i][j] == c[j]
        return True

    def full_row_check(i: int) -> bool:
        return sorted(ch for ch in grid[i] if ch != '.') in ([], ['A'], ['B'], ['C'], ['A', 'B'], ['A', 'C'], ['B', 'C'], ['A', 'B', 'C'])

    def count_ok(cells) -> bool:
        vals = [ch for ch in cells if ch != '.']
        return len(vals) == len(set(vals))

    def backtrack(pos: int) -> bool:
        if pos == n * n:
            # Every row and column must contain exactly one of each letter
            # in the requisite positions: exactly 3 letters, one each, when n == 3;
            # for larger n, each letter appears at most once and the total
            # required letters are present.
            for i in range(n):
                row_letters = [ch for ch in grid[i] if ch != '.']
                col_letters = [grid[k][i] for k in range(n) if grid[k][i] != '.']
                if sorted(row_letters) != sorted(set(row_letters)):
                    return False
                if sorted(col_letters) != sorted(set(col_letters)):
                    return False
                if set(row_letters) != set(letters):
                    return False
                if set(col_letters) != set(letters):
                    return False
            return True

        i, j = divmod(pos, n)
        for ch in ['.'] + list(letters):
            if ch != '.':
                if ch in row_used[i] or ch in col_used[j]:
                    continue
            grid[i][j] = ch
            if ch != '.':
                row_used[i].add(ch)
                col_used[j].add(ch)

            ok = True
            if j == 0 and grid[i][0] != '.' and grid[i][0] != r[i]:
                ok = False
            if ok and j == n - 1 and not row_ok(i):
                ok = False
            if ok and i == 0 and grid[0][j] != '.' and grid[0][j] != c[j]:
                ok = False

            if ok:
                # Check leftmost-row and topmost-column constraints as soon as determined.
                if not row_ok(i) and any(grid[i][k] != '.' for k in range(j + 1)):
                    ok = False
                if ok and not col_ok(j) and any(grid[k][j] != '.' for k in range(i + 1)):
                    ok = False

            if ok and backtrack(pos + 1):
                return True

            if ch != '.':
                row_used[i].discard(ch)
                col_used[j].discard(ch)
            grid[i][j] = '.'
        return False

    if backtrack(0):
        return [''.join(row) for row in grid]
    return None

