                if (i + j) % 2 == 1:
                    total += 1
                else:
                    total += 2 if ((i // 2 + j // 2) % 2 == 0) else 0
        # leftover row of height 1 (if Y odd), excluding the corner already counted
        if Y % 2 == 1:
            for i in range(X - (X % 2)):
                j = Y - 1
                if (i + j) % 2 == 1:
                    total += 1
                else:
                    total += 2 if ((i // 2 + j // 2) % 2 == 0) else 0
        return total

    return F(C, D) - F(A, D) - F(C, B) + F(A, B)

