from math import isqrt

def _iroot(n: int, k: int) -> int:
    """Largest integer r with r**k <= n."""
    if n < 2:
        return n
    if k == 1:
        return n
    if k == 2:
        return isqrt(n)
    # Initial estimate via float, then correct exactly
    r = int(round(n ** (1.0 / k)))
    while r > 0 and r ** k > n:
        r -= 1
    while (r + 1) ** k <= n:
        r += 1
    return r

def _mobius(k: int) -> int:
    res = 1
    d = 2
    m = k
    while d * d <= m:
        if m % d == 0:
            m //= d
            if m % d == 0:
                return 0
            res = -res
        d += 1
    if m > 1:
        res = -res
    return res

def count_power_representations(n: int) -> int:
    """ Count how many integers x between 1 and n (inclusive) can be expressed as x = a^b
    where a is a positive integer and b is an integer greater than or equal to 2.

    Args:
        n: The upper bound (1 <= n <= 10^18)

    Returns:
        The count of integers that can be expressed as a^b where b >= 2

    >>> count_power_representations(99)
    12
    >>> count_power_representations(1000000000000000000)
    1001003332
    """
    if n < 1:
        return 0
    # Count of perfect powers (>=2 exponent) in [2, n] via Mobius inversion
    total = 0
    for k in range(2, n.bit_length() + 1):
        mu = _mobius(k)
        if mu != 0:
            total -= mu * (_iroot(n, k) - 1)
    # Add the value 1 (1 = 1^2)
    return total + 1

