def count_good_sequences(N: int, M: int) -> int:
    if N < 2:
        return 0

    # Binomial weights C(e + M - 1, M - 1) for exponents e up to 64.
    MAXE = 64
    top = MAXE + M
    fact = [1] * (top + 1)
    for i in range(1, top + 1):
        fact[i] = fact[i - 1] * i % MOD
    inv = [1] * (top + 1)
    inv[top] = pow(fact[top], MOD - 2, MOD)
    for i in range(top, 0, -1):
        inv[i - 1] = inv[i] * i % MOD

    def comb(a, b):
        if b < 0 or b > a:
            return 0
        return fact[a] * inv[b] % MOD * inv[a - b] % MOD

    cw = [comb(e + M - 1, M - 1) for e in range(MAXE + 1)]

    r = int(N ** 0.5)
    while r * r > N:
        r -= 1
    while (r + 1) * (r + 1) <= N:
        r += 1

    # Values floor(N / k): small table index by value, large by k.
    vals = []
    k = 1
    while k <= N:
        v = N // k
        vals.append(v)
        k = N // v + 1
    vals.sort()
    idx_small = {}
    idx_large = {}
    for i, v in enumerate(vals):
        if v <= r:
            idx_small[v] = i
        else:
            idx_large[N // v] = i
    V = len(vals)

    def index(v):
        return idx_small[v] if v <= r else idx_large[N // v]

    # Prime-count table via Lucy sieve: cnt[i] = #primes <= vals[i].
    cnt = [v - 1 for v in vals]
    for p in range(2, r + 1):
        if cnt[index(p)] == cnt[index(p - 1)] if p - 1 >= 1 else False:
            continue
        cp = cnt[index(p - 1)]
        p2 = p * p
        for i in range(V):
            v = vals[i]
            if v < p2:
                break
            cnt[i] -= cnt[index(v // p)] - cp

    # Counting primes by residue class mod 3 separately would require
    # extra Lucy tables; that part is not implemented here.
    # The DFS below uses the total prime count only and is therefore
    # incomplete for the mod-3 condition.
    total = 0
    stack = [(1, 0, 1, 1)]
    primes = [p for p in range(2, r + 1) if cnt[index(p)] - cnt[index(p - 1)] == 1]

    while stack:
        val, idx, s3, w = stack.pop()
        if val > 1 and s3 == 0:
            total = (total + w) % MOD
        for j in range(idx, len(primes)):
            p = primes[j]
            if val * p > N:
                break
            cur = val
            pw = 1
            sig = 1
            e = 0
            while cur * p <= N:
                cur *= p
                e += 1
                pw *= p
                sig = (sig + pw) % 3
                stack.append((cur, j + 1, s3 * sig % 3, w * cw[e] % MOD))
    return total % MOD

