def sum_of_scores(n: int, m: int) -> int:
    from collections import Counter

    def num_divisors(x: int) -> int:
        count = 0
        d = 1
        while d * d <= x:
            if x % d == 0:
                count += 1 if d * d == x else 2
            d += 1
        return count

    total = 0
    current = Counter({1: 1})
    for _ in range(n):
        nxt = Counter()
        for prod, cnt in current.items():
            for v in range(1, m + 1):
