def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    def tile_of(x, y):
        # Find the tile (i, j, k) containing point (x + 0.5, y + 0.5).
        # Search a window of candidate i, j, k around the point.
        for i in range(x // K - 2, x // K + 3):
            for j in range(y // K - 2, y // K + 3):
                for k in range(K):
                    if i % 2 == j % 2:
                        # i and j same parity: iK <= x <= (i+1)K, jK+k <= y <= jK+k+1
                        xl, xh = i * K, (i + 1) * K
                        yl, yh = j * K + k, j * K + k + 1
                    else:
                        # different parity: iK+k <= x <= iK+k+1, jK <= y <= (j+1)K
                        xl, xh = i * K + k, i * K + k + 1
                        yl, yh = j * K, (j + 1) * K
                    if xl <= x + 0.5 <= xh and yl <= y + 0.5 <= yh:
                        return (i, j, k)
        raise ValueError("tile not found")

    def edges(tile):
        # Enumerate candidate neighbours in a window and test positive-length
        # shared boundary using the rectangle geometry of each tile.
        i0, j0, k0 = tile
        out = []
        for di in range(-3, 4):
            for dj in range(-3, 4):
                for dk in range(K):
                    cand = (i0 + di, j0 + dj, dk)
                    if cand != tile and share_edge(tile, cand):
                        out.append(cand)
        return out

