        bx0, bx1, by0, by1 = rect(b)
        # Positive-length overlap along x with touching in y, or vice versa.
        touch_x = (ax1 == bx0 or bx1 == ax0) and min(ay1, by1) > max(ay0, by0)
        touch_y = (ay1 == by0 or by1 == ay0) and min(ax1, bx1) > max(ax0, bx0)
        return touch_x or touch_y

    start = tile_of(S_x, S_y)
    target = tile_of(T_x, T_y)
    if start == target:
        return 0
    seen = {start: 0}
    q = deque([start])
    while q:
        cur = q.popleft()
        for nb in edges(cur):
            if nb not in seen:
                seen[nb] = seen[cur] + 1
                if nb == target:
                    return seen[nb]
                q.append(nb)
    return -1

