from fractions import Fraction

MOD = 998244353

def expected_operations(N: int, M: int) -> int:
    V = N * M + 1
    # Tree adjacency: vertex i (1..V-1) connects to max(i-N, 0)
    adj = [[] for _ in range(V)]
    for i in range(1, V):
        p = max(i - N, 0)
        adj[i].append(p)
        adj[p].append(i)

    full = (1 << V) - 1
    # E[(mask, v)]: expected remaining steps, painted set = mask, walker at v (v is in mask).
    E = {}
    for mask in sorted(range(1, 1 << V), key=lambda m: -bin(m).count("1")):
        if not (mask & 1):
            continue
        if mask == full:
            for v in range(V):
                if (mask >> v) & 1:
                    E[(mask, v)] = Fraction(0)
            continue
        painted = [v for v in range(V) if (mask >> v) & 1]
        k = {v: i for i, v in enumerate(painted)}
        n = len(painted)
        A = [[Fraction(0)] * n for _ in range(n)]
        b = [Fraction(0)] * n
        for v in painted:
            r = k[v]
            A[r][r] += 1
            d = len(adj[v])
            for u in adj[v]:
                w = Fraction(1, d)
                if (mask >> u) & 1:
                    A[r][k[u]] -= w
                else:
                    nm = mask | (1 << u)
                    b[r] += w * (1 + E[(nm, u)])
        # Gaussian elimination
        for c in range(n):
            piv = next(r for r in range(c, n) if A[r][c] != 0)
            A[c], A[piv] = A[piv], A[c]
            b[c], b[piv] = b[piv], b[c]
            inv = 1 / A[c][c]
            A[c] = [x * inv for x in A[c]]
            b[c] *= inv
            for r in range(n):
                if r != c and A[r][c] != 0:
                    f = A[r][c]
                    A[r] = [x - f * y for x, y in zip(A[r], A[c])]
                    b[r] -= f * b[c]
        for v in painted:
            E[(mask, v)] = b[k[v]]

    ans = E[(1, 0)]
    return ans.numerator % MOD * pow(ans.denominator % MOD, MOD - 2, MOD) % MOD

