def min_operations_to_match_grids(H: int, W: int, A: List[List[int]], B: List[List[int]]) -> Optional[int]:
    """Return the minimum number of adjacent row/column swaps turning A into B, or None."""
    def inversions(perm):
        cnt = 0
        n = len(perm)
        for i in range(n):
            for j in range(i + 1, n):
                if perm[i] > perm[j]:
                    cnt += 1
        return cnt

    best = None
    for p in permutations(range(H)):
        pc = inversions(p)
        for q in permutations(range(W)):
            ok = True
            for i in range(H):
                for j in range(W):
                    if A[p[i]][q[j]] != B[i][j]:
                        ok = False
                        break
                if not ok:
                    break
            if ok:
                cost = pc + inversions(q)
                if best is None or cost < best:
                    best = cost
    return best

