def min_weight_hamiltonian_walk(n: int, m: int, edges: List[Tuple[int, int, int]]) -> Optional[int]:
    INF = float('inf')
    dist = [[INF] * n for _ in range(n)]
    for i in range(n):
        dist[i][i] = 0
    for u, v, w in edges:
        u -= 1
        v -= 1
        if w < dist[u][v]:
            dist[u][v] = w

    # Floyd-Warshall (no negative cycles guaranteed)
    for k in range(n):
        dk = dist[k]
        for i in range(n):
            dik = dist[i][k]
            if dik == INF:
                continue
            di = dist[i]
            for j in range(n):
                nd = dik + dk[j]
                if nd < di[j]:
                    di[j] = nd

    full = (1 << n) - 1
    dp = [[INF] * n for _ in range(1 << n)]
    for s in range(n):
        dp[1 << s][s] = 0

    for mask in range(1 << n):
        row = dp[mask]
        for u in range(n):
            cur = row[u]
            if cur == INF:
                continue
            du = dist[u]
            for v in range(n):
                if mask & (1 << v):
                    continue
                if du[v] == INF:
                    continue
                nmask = mask | (1 << v)
                cand = cur + du[v]
                if cand < dp[nmask][v]:
                    dp[nmask][v] = cand

    best = min(dp[full])
    return None if best == INF else int(best)

