def count_paths(N: int, M: int, K: int, extra_edges: list) -> int:
    # adjacency: each vertex has its cycle edge plus extra edges
    out = {v: [v % N + 1] for v in range(1, N + 1)}
    for x, y in extra_edges:
        out[x].append(y)

    # ways[v] = number of walks of current length ending at v, starting at 1
    ways = [0] * (N + 1)
    ways[1] = 1
    for _ in range(K):
        nxt = [0] * (N + 1)
        for v in range(1, N + 1):
            w = ways[v]
            if w:
                for u in out[v]:
                    nxt[u] = (nxt[u] + w) % MOD
        ways = nxt
    return sum(ways) % MOD

