def count_valid_grids(H: int, W: int, grid: list[str]) -> int:
    MOD = 998244353

    # Build the cell-color options for each (row, col) in the original orientation.
    def options_at(r, c):
        ch = grid[r][c]
        if ch == '?':
            return (0, 1, 2)
        return (int(ch) - 1,)

    # Choose the frontier width as the smaller dimension. If we sweep by columns
    # instead of rows, the frontier holds one entry per row.
    if W <= H:
        rows, cols = H, W
        def opts(i, j):          # i = row index, j = column index
            return options_at(i, j)
    else:
        rows, cols = W, H
        def opts(i, j):          # i = column index, j = row index (sweeping by columns)
            return options_at(j, i)

    # Frontier of length `cols`: colors of the most recently processed cell in each
    # position. -1 means "no cell yet".
    dp = {tuple([-1] * cols): 1}

    for i in range(rows):
        for j in range(cols):
            new_dp = {}
            allowed = opts(i, j)
            for state, ways in dp.items():
                up = state[j]                          # cell at (i-1, j) in sweep coords
                left = state[j - 1] if j > 0 else -1   # cell at (i, j-1)
                for col in allowed:
                    if col == up or col == left:
                        continue
                    lst = list(state)
                    lst[j] = col
                    key = tuple(lst)
                    new_dp[key] = (new_dp.get(key, 0) + ways) % MOD
            dp = new_dp
            if not dp:
                return 0

    return sum(dp.values()) % MOD

