def count_ball_sets(n: int, positions: List[Tuple[int, int]]) -> int:
    # Brute force over reachable subsets (exponential in n).
    # Correct by definition for small n; too slow for n=25, 131, 300.
    MOD = 998244353
    start = (1 << n) - 1
    seen = {start}
    stack = [start]
    while stack:
        mask = stack.pop()
        for k in range(n):
            if not (mask >> k) & 1:
                continue
            xk, yk = positions[k]
            new = mask
            for i in range(n):
                if (mask >> i) & 1 and i != k:
                    xi, yi = positions[i]
                    if (xi < xk and yi < yk) or (xi > xk and yi > yk):
                        new &= ~(1 << i)
            if new not in seen:
                seen.add(new)
                stack.append(new)
    return len(seen) % MOD

