def find_triple_sum(n: int, x: int, a: List[int]) -> Optional[Tuple[int, int, int]]:
    positions = defaultdict(list)
    for idx, val in enumerate(a):
        positions[val].append(idx + 1)  # 1-based, sorted ascending

    for i in range(1, n - 1):
        ai = a[i - 1]
        for j in range(i + 1, n):
            need = x - ai - a[j - 1]
            if need < 1:
                continue
            plist = positions.get(need)
            if not plist:
                continue
            pos = bisect_right(plist, j)
            if pos < len(plist):
                return (i, j, plist[pos])
    return None

