def count_polish_sequences(n: int, a: list[int]) -> int:
    def split(total, k):
        if k == 0:
            if total == 0:
                yield []
            return
        for first in range(1, total - k + 2):
            for rest in split(total - first, k - 1):
                yield [first] + rest

    def gen(length):
        if length == 0:
            yield ()
            return
        for v in range(length):
            for parts in split(length - 1, v):
                def expand(i):
                    if i == v:
                        yield ()
                        return
                    for s in gen(parts[i]):
                        for r in expand(i + 1):
                            yield s + r
                for body in expand(0):
                    yield (v,) + body

    count = 0
    for seq in gen(n):
        if list(seq) <= a:
            count += 1
    return count % MOD


