    # Generate all Polish sequences of length exactly n, in lexicographic order.
    # A sequence starts with value v, followed by v Polish sequences
    # whose lengths sum to n - 1.
    def gen(length):
        if length == 0:
            yield ()
            return
        # first element v: needs v sub-blocks of total length length-1
        for v in range(0, length):
            for parts in _split(length - 1, v):
                # parts is a list of lengths for v consecutive Polish sequences
                def expand(idx, acc):
                    if idx == v:
                        yield tuple(acc)
                        return
                    for seq in gen(parts[idx]):
                        yield from expand(idx + 1, acc + list(seq))
                for body in expand(0, []):
                    yield (v,) + body

    def _split(total, k):
        # all ordered ways to write total as k positive parts (each part >= 1)
        if k == 0:
            if total == 0:
                yield []
            return
        for first in range(1, total - k + 2):
            for rest in _split(total - first, k - 1):
                yield [first] + rest

    return list(gen(n))


