def count_good_string_replacements(n: int, k: int, s: str) -> int:
    MOD = 998244353
    from itertools import product

    def is_good(t):
        # Reduce by the two operations on the multiset of letters, checked
        # by search over operations (exact, exponential in length).
        from functools import lru_cache

        @lru_cache(maxsize=None)
        def reducible(u):
            if u == "":
                return True
            L = len(u)
            # Operation 1: delete two equal characters at any two positions
            for i in range(L):
                for j in range(i + 1, L):
                    if u[i] == u[j]:
                        rest = u[:i] + u[i+1:j] + u[j+1:]
                        if reducible(rest):
                            return True
            # Operation 2: delete one A, one B, one C
            if "A" in u and "B" in u and "C" in u:
                for a in range(L):
                    if u[a] != "A":
                        continue
                    for b in range(L):
                        if u[b] != "B" or b == a:
                            continue
                        for c in range(L):
                            if u[c] != "C" or c in (a, b):
                                continue
                            rest = "".join(u[x] for x in range(L) if x not in (a, b, c))
                            if reducible(rest):
                                return True
            return False

        return reducible(t)

    qpos = [i for i, c in enumerate(s) if c == "?"]
    total = 0
    for choice in product("ABC", repeat=len(qpos)):
        t = list(s)
        for p, c in zip(qpos, choice):
            t[p] = c
        t = "".join(t)
        good = 0
        for i in range(n):
            for j in range(i + 1, n + 1):
                if is_good(t[i:j]):
                    good += 1
        if good >= k:
            total += 1
    return total % MOD

