    moves = ['F', 'W', 'E']
    offset = n  # difference d is stored at index d + offset
    size = 2 * n + 1

    # dp[last][d]: number of Bob prefixes ending in move `last` with difference d
    # Initialize with an empty "last" marker handled by a first-round pass.
    dp = [[0] * size for _ in range(3)]
