        for bi, b in enumerate(moves):
            # score delta for this round
            if b == a:
                delta = 0
            elif beats[b] == a:
                delta = 1   # Bob's creature beats Alice's
            else:
                delta = -1  # Alice's creature beats Bob's
            if first:
                new[bi][delta + offset] = (new[bi][delta + offset] + 1) % MOD
            else:
                for pi, p in enumerate(moves):
                    if p == b:
                        continue  # no same creature in consecutive rounds
                    for d in range(size):
                        v = dp[pi][d]
                        if v:
                            nd = d + delta
                            new[bi][nd] = (new[bi][nd] + v) % MOD
        dp = new
        first = False

    total = 0
    for bi in range(3):
