def count_k_reducible(s: str, k: int) -> int:
    MOD = 10**9 + 7
    n_len = len(s)

    # steps[v] = number of operations to reduce v to 1 (using popcount), for v >= 1
    MAXV = max(n_len, 2)
    steps = [0] * (MAXV + 1)
    for v in range(2, MAXV + 1):
        steps[v] = steps[bin(v).count("1")] + 1

    # ways[p] = number of integers x in [1, n-1] with popcount p
    # Digit DP: count numbers in [0, n) with popcount p, then subtract x=0 (popcount 0).
    # cnt[p] over [0, n)
    cnt = [0] * (n_len + 1)
    ones_before = 0  # number of 1s in prefix of s
    for i, ch in enumerate(s):
        remaining = n_len - i - 1
        if ch == "1":
            # place 0 here, free remaining bits
            # total popcount = ones_before + j, j ones in remaining bits
            for j in range(remaining + 1):
                cnt[ones_before + j] = (cnt[ones_before + j] + comb(remaining, j)) % MOD
            ones_before += 1
    # numbers in [0, n) include 0 possibly; n itself excluded automatically
    # cnt currently counts numbers < n; zero has popcount 0
    cnt[0] = (cnt[0] - 1) % MOD  # remove x = 0

    result = 0
    for p in range(1, n_len + 1):
        # x with popcount p, x != 1 case handled: x=1 has popcount 1, steps 0
        if p == 1:
            # x = 1 itself is k-reducible (0 operations) if n > 1
            # x with popcount 1 are powers of two; x=1 needs 0 ops, others need 1 + steps(1)=1 op
            # so all popcount-1 numbers are k-reducible when k >= 1
            if k >= 1:
                result = (result + cnt[p]) % MOD
            # x=1 is counted in cnt[1] and is always reducible; fine
        else:
            if steps[p] + 1 <= k:
                result = (result + cnt[p]) % MOD
    return result % MOD


def comb(n, r):
    if r < 0 or r > n:
        return 0
    # Pascal-style cached computation
    global _COMB_CACHE
    try:
        _COMB_CACHE
    except NameError:
        _COMB_CACHE = {}
    key = (n, r)
    if key in _COMB_CACHE:
        return _COMB_CACHE[key]
    res = 1
    rr = min(r, n - r)
    for i in range(rr):
        res = res * (n - i) // (i + 1)
    _COMB_CACHE[key] = res
    return res

