from math import comb

def count_balanced_graphs(n: int, p: int) -> list[int]:
    maxM = n * (n - 1) // 2
    half = n // 2

    def polymul(A, B):
        C = [0] * (len(A) + len(B) - 1)
        for i, a in enumerate(A):
            if a == 0:
                continue
            for j, b in enumerate(B):
                if b:
                    C[i + j] += a * b
        return C

    def polyadd(A, B, scale=1):
        L = max(len(A), len(B))
        C = [0] * L
        for i, a in enumerate(A):
            C[i] += a
        for i, b in enumerate(B):
            C[i] += scale * b
        return C

    # within[s]: polynomial in x, sum_e C(C(s,2), e) x^e  (any graph on s labeled vertices)
    @lru_cache(maxsize=None)
    def within(s):
        m = s * (s - 1) // 2
        return tuple(comb(m, e) for e in range(m + 1))

    # cover[a][b]: polynomial in x counting edge sets between new layer (size a)
    # and previous layer (size b) where every new-layer vertex has >=1 back edge.
    @lru_cache(maxsize=None)
    def cover(a, b):
        res = [0] * (a * b + 1)
        for j in range(a + 1):  # j vertices with no back edge
            sign = -1 if j % 2 else 1
            m = (a - j) * b
            coef = comb(a, j) * sign
            for e in range(m + 1):
                res[e] += coef * comb(m, e)
        return tuple(res)

    # State: (vertices placed so far including root, size of last layer, parity of last layer,
    #         count of even vertices placed, count of odd vertices placed)
    # Value: polynomial in x counting labeled structures.
    # Root is distance 0 (even), counted in even.
    from collections import defaultdict
    init_poly = [1]
    states = {(1, 1, 0, 1, 0): init_poly}
    total = [0] * (maxM + 1)

    # Process layer by layer; each step adds one layer.
    while states:
        nxt = defaultdict(lambda: [0])
        for (placed, last, par, ev, od), poly in states.items():
            # Record completed graph: all n vertices placed, balance achieved
            if placed == n and ev == half and od == half:
                for i, c in enumerate(poly):
                    total[i] = total[i] + c
                continue
            remaining = n - placed
            for a in range(1, remaining + 1):
                new_par = 1 - par
                nev, nod = (ev + a, od) if new_par == 0 else (ev, od + a)
                if nev > half or nod > half:
                    continue
                # Choose which labeled vertices form this layer
                mult = comb(remaining, a)
                layer_poly = polymul(list(cover(a, last)), list(within(a)))
                contrib = [mult * c for c in layer_poly]
                newp = polymul(poly, contrib)
                key = (placed + a, a, new_par, nev, nod)
                nxt[key] = polyadd(nxt[key], newp)
        # Trim unneeded states
        states = {k: v for k, v in nxt.items()}

    out = []
    for M in range(n - 1, maxM + 1):
        out.append(total[M] % p)
    return out

