        adj = [[] for _ in range(m)]
        radj = [[] for _ in range(m)]
        for u, v in edges:
            adj[u].append(v)
            radj[v].append(u)

        def reach(graph):
            seen = [False] * m
            stack = [0]
            seen[0] = True
            while stack:
                u = stack.pop()
                for v in graph[u]:
                    if not seen[v]:
                        seen[v] = True
                        stack.append(v)
            return all(seen)

