def kth_alternating_permutation(n: int, k: int) -> List[int]:
    # Count parity-alternating permutations of the given remaining numbers.
    # Only the counts of odd and even numbers matter for feasibility.
    from functools import lru_cache

    odds = [x for x in range(1, n + 1) if x % 2 == 1]
    evens = [x for x in range(1, n + 1) if x % 2 == 0]

    @lru_cache(maxsize=None)
    def count(o: int, e: int, last_parity: int) -> int:
        # last_parity: 0 = last placed is odd, 1 = last placed is even, 2 = nothing placed
        if o == 0 and e == 0:
            return 1
        total = 0
        if o > 0 and last_parity != 0:
            total += o * count(o - 1, e, 0) if False else 0  # placeholder, replaced below
        return total

    # Proper count: choosing a specific number of a given parity multiplies by the
    # count of remaining items of that parity (each choice is a distinct value).
    @lru_cache(maxsize=None)
    def ways(o: int, e: int, last: int) -> int:
        if o == 0 and e == 0:
            return 1
        total = 0
        if o > 0 and last != 0:
            total += ways(o - 1, e, 0)
        if e > 0 and last != 1:
            total += ways(o, e - 1, 1)
        return total

    # Build the k-th permutation by choosing the smallest feasible value at each step.
    if k < 1 or k > ways(len(odds), len(evens), 2):
        return []

    result: List[int] = []
    remaining = sorted(range(1, n + 1))
    last = 2
    while remaining:
        for v in remaining:
            p = v % 2
            if last != 2 and p == last:
                continue
            o = sum(1 for x in remaining if x % 2 == 1) - (1 if p == 0 else 0)
            e = sum(1 for x in remaining if x % 2 == 0) - (1 if p == 1 else 0)
            c = ways(o, e, p)
            if k <= c:
                result.append(v)
                remaining.remove(v)
                last = p
                break
            k -= c
        else:
            return []
    return result

