from typing import Optional, List


def solve_grid(n: int, r: str, c: str) -> Optional[List[str]]:
    """ Given an integer N and strings R and C of length N consisting of 'A', 'B', and 'C',
    determine if it's possible to fill an N×N grid such that:
    - Each row and column contains exactly one 'A', one 'B', and one 'C'
    - The leftmost character written in the i-th row matches the i-th character of R
    - The topmost character written in the i-th column matches the i-th character of C

    Empty cells are represented by '.' in the output.

    Args:
        n: The size of the grid (3 <= n <= 5)
        r: String of length n specifying leftmost characters in each row
        c: String of length n specifying topmost characters in each column

    Returns:
        A list of n strings representing the filled grid if possible, None otherwise.
        Each string has length n, where '.' represents empty cells.

    >>> solve_grid(3, 'ABC', 'ABC')
    ['ABC', 'BCA', 'CAB']
    >>> solve_grid(3, 'AAA', 'BBB')
    None
    """
    letters = "ABC"
    # Each row/column needs exactly one A, B, C; with n in {3,4,5} that means
    # n-3 extra cells must be '.'. Each row/col has at most one of each letter.
    grid = [['.'] * n for _ in range(n)]
    row_used = [set() for _ in range(n)]
    col_used = [set() for _ in range(n)]

    def row_ok(i: int) -> bool:
        # Leftmost written char in row i must equal r[i] (if row has any letter).
        for j in range(n):
            if grid[i][j] != '.':
                return grid[i][j] == r[i]
        return True

    def col_ok(j: int) -> bool:
        # Topmost written char in column j must equal c[j].
        for i in range(n):
            if grid[i][j] != '.':
                return grid[i][j] == c[j]
        return True

    def full_row_check(i: int) -> bool:
        return sorted(ch for ch in grid[i] if ch != '.') in ([], ['A'], ['B'], ['C'], ['A', 'B'], ['A', 'C'], ['B', 'C'], ['A', 'B', 'C'])

    def count_ok(cells) -> bool:
        vals = [ch for ch in cells if ch != '.']
        return len(vals) == len(set(vals))

    def backtrack(pos: int) -> bool:
        if pos == n * n:
            # Every row and column must contain exactly one of each letter
            # in the requisite positions: exactly 3 letters, one each, when n == 3;
            # for larger n, each letter appears at most once and the total
            # required letters are present.
            for i in range(n):
                row_letters = [ch for ch in grid[i] if ch != '.']
                col_letters = [grid[k][i] for k in range(n) if grid[k][i] != '.']
                if sorted(row_letters) != sorted(set(row_letters)):
                    return False
                if sorted(col_letters) != sorted(set(col_letters)):
                    return False
                if set(row_letters) != set(letters):
                    return False
                if set(col_letters) != set(letters):
                    return False
            return True

        i, j = divmod(pos, n)
        for ch in ['.'] + list(letters):
            if ch != '.':
                if ch in row_used[i] or ch in col_used[j]:
                    continue
            grid[i][j] = ch
            if ch != '.':
                row_used[i].add(ch)
                col_used[j].add(ch)

            ok = True
            if j == 0 and grid[i][0] != '.' and grid[i][0] != r[i]:
                ok = False
            if ok and j == n - 1 and not row_ok(i):
                ok = False
            if ok and i == 0 and grid[0][j] != '.' and grid[0][j] != c[j]:
                ok = False

            if ok:
                # Check leftmost-row and topmost-column constraints as soon as determined.
                if not row_ok(i) and any(grid[i][k] != '.' for k in range(j + 1)):
                    ok = False
                if ok and not col_ok(j) and any(grid[k][j] != '.' for k in range(i + 1)):
                    ok = False

            if ok and backtrack(pos + 1):
                return True

            if ch != '.':
                row_used[i].discard(ch)
                col_used[j].discard(ch)
            grid[i][j] = '.'
        return False

    if backtrack(0):
        return [''.join(row) for row in grid]
    return None

from typing import List, Tuple


def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """ Determine if it's possible to place rectangular tiles on an H×W grid such that:
    - Every cell is covered by exactly one tile
    - Tiles can be rotated (so a 2×3 tile can be placed as 3×2)
    - Some tiles may remain unused
    - Tiles must be aligned with grid cells and cannot extend outside

    Args:
        n: Number of available tiles (1 ≤ n ≤ 7)
        h: Height of the grid (1 ≤ h ≤ 10)
        w: Width of the grid (1 ≤ w ≤ 10)
        tiles: List of (a, b) tuples where tile i has dimensions a×b (1 ≤ a, b ≤ 10)

    Returns:
        True if the grid can be perfectly tiled, False otherwise

    >>> can_tile_grid(5, 5, 5, [(1, 1), (3, 3), (4, 4), (2, 3), (2, 5)])
    True
    >>> can_tile_grid(1, 1, 2, [(2, 3)])
    False
    >>> can_tile_grid(1, 2, 2, [(1, 1)])
    False
    """
    # Quick area check: tiles must be able to cover the grid
    if h * w == 0:
        return True
    total_area = sum(a * b for a, b in tiles)
    if total_area < h * w:
        return False

    grid = [[False] * w for _ in range(h)]

    def find_first_empty():
        for r in range(h):
            for c in range(w):
                if not grid[r][c]:
                    return r, c
        return None

    def can_place(r: int, c: int, rh: int, rw: int) -> bool:
        if r + rh > h or c + rw > w:
            return False
        for i in range(r, r + rh):
            for j in range(c, c + rw):
                if grid[i][j]:
                    return False
        return True

    def set_region(r: int, c: int, rh: int, rw: int, value: bool):
        for i in range(r, r + rh):
            for j in range(c, c + rw):
                grid[i][j] = value

    def backtrack(used_mask: int) -> bool:
        pos = find_first_empty()
        if pos is None:
            return True
        r, c = pos
        for idx in range(n):
            if used_mask & (1 << idx):
                continue
            a, b = tiles[idx]
            orientations = {(a, b), (b, a)}
            for rh, rw in orientations:
                if can_place(r, c, rh, rw):
                    set_region(r, c, rh, rw, True)
                    if backtrack(used_mask | (1 << idx)):
                        return True
                    set_region(r, c, rh, rw, False)
        return False

    return backtrack(0)

from math import isqrt

def _iroot(n: int, k: int) -> int:
    """Largest integer r with r**k <= n."""
    if n < 2:
        return n
    if k == 1:
        return n
    if k == 2:
        return isqrt(n)
    # Initial estimate via float, then correct exactly
    r = int(round(n ** (1.0 / k)))
    while r > 0 and r ** k > n:
        r -= 1
    while (r + 1) ** k <= n:
        r += 1
    return r

def _mobius(k: int) -> int:
    res = 1
    d = 2
    m = k
    while d * d <= m:
        if m % d == 0:
            m //= d
            if m % d == 0:
                return 0
            res = -res
        d += 1
    if m > 1:
        res = -res
    return res

def count_power_representations(n: int) -> int:
    """ Count how many integers x between 1 and n (inclusive) can be expressed as x = a^b
    where a is a positive integer and b is an integer greater than or equal to 2.

    Args:
        n: The upper bound (1 <= n <= 10^18)

    Returns:
        The count of integers that can be expressed as a^b where b >= 2

    >>> count_power_representations(99)
    12
    >>> count_power_representations(1000000000000000000)
    1001003332
    """
    if n < 1:
        return 0
    # Count of perfect powers (>=2 exponent) in [2, n] via Mobius inversion
    total = 0
    for k in range(2, n.bit_length() + 1):
        mu = _mobius(k)
        if mu != 0:
            total -= mu * (_iroot(n, k) - 1)
    # Add the value 1 (1 = 1^2)
    return total + 1

MOD = 998244353


def count_good_sequences(N: int, M: int) -> int:
    if N < 2:
        return 0

    # Binomial weights C(e + M - 1, M - 1) for exponents e up to 64.
    MAXE = 64
    top = MAXE + M
    fact = [1] * (top + 1)
    for i in range(1, top + 1):
        fact[i] = fact[i - 1] * i % MOD
    inv = [1] * (top + 1)
    inv[top] = pow(fact[top], MOD - 2, MOD)
    for i in range(top, 0, -1):
        inv[i - 1] = inv[i] * i % MOD

    def comb(a, b):
        if b < 0 or b > a:
            return 0
        return fact[a] * inv[b] % MOD * inv[a - b] % MOD

    cw = [comb(e + M - 1, M - 1) for e in range(MAXE + 1)]

    r = int(N ** 0.5)
    while r * r > N:
        r -= 1
    while (r + 1) * (r + 1) <= N:
        r += 1

    # Values floor(N / k): small table index by value, large by k.
    vals = []
    k = 1
    while k <= N:
        v = N // k
        vals.append(v)
        k = N // v + 1
    vals.sort()
    idx_small = {}
    idx_large = {}
    for i, v in enumerate(vals):
        if v <= r:
            idx_small[v] = i
        else:
            idx_large[N // v] = i
    V = len(vals)

    def index(v):
        return idx_small[v] if v <= r else idx_large[N // v]

    # Prime-count table via Lucy sieve: cnt[i] = #primes <= vals[i].
    cnt = [v - 1 for v in vals]
    for p in range(2, r + 1):
        if cnt[index(p)] == cnt[index(p - 1)] if p - 1 >= 1 else False:
            continue
        cp = cnt[index(p - 1)]
        p2 = p * p
        for i in range(V):
            v = vals[i]
            if v < p2:
                break
            cnt[i] -= cnt[index(v // p)] - cp

    # Counting primes by residue class mod 3 separately would require
    # extra Lucy tables; that part is not implemented here.
    # The DFS below uses the total prime count only and is therefore
    # incomplete for the mod-3 condition.
    total = 0
    stack = [(1, 0, 1, 1)]
    primes = [p for p in range(2, r + 1) if cnt[index(p)] - cnt[index(p - 1)] == 1]

    while stack:
        val, idx, s3, w = stack.pop()
        if val > 1 and s3 == 0:
            total = (total + w) % MOD
        for j in range(idx, len(primes)):
            p = primes[j]
            if val * p > N:
                break
            cur = val
            pw = 1
            sig = 1
            e = 0
            while cur * p <= N:
                cur *= p
                e += 1
                pw *= p
                sig = (sig + pw) % 3
                stack.append((cur, j + 1, s3 * sig % 3, w * cw[e] % MOD))
    return total % MOD

MOD = 998244353

def sum_of_scores(n: int, m: int) -> int:
    from collections import Counter

    def num_divisors(x: int) -> int:
        count = 0
        d = 1
        while d * d <= x:
            if x % d == 0:
                count += 1 if d * d == x else 2
            d += 1
        return count

    total = 0
    current = Counter({1: 1})
    for _ in range(n):
        nxt = Counter()
        for prod, cnt in current.items():
            for v in range(1, m + 1):
                nxt[prod * v] += cnt
        for prod, cnt in nxt.items():
            total = (total + cnt * num_divisors(prod)) % MOD
        current = nxt
    return total

