from bisect import bisect_left


def _lis_len(seq):
    tails = []
    for x in seq:
        i = bisect_left(tails, x)
        if i == len(tails):
            tails.append(x)
        else:
            tails[i] = x
    return len(tails)


def _lds_len(seq):
    return _lis_len([-x for x in seq])


def count_special_permutations(A: int, B: int, M: int) -> int:
    n = A * B - 1
    if n > 9:
        raise NotImplementedError(
            f"Brute force supports AB-1 <= 9; got n={n}. "
            "A closed-form/DP counting method is required for larger inputs."
        )
    count = 0
    for P in permutations(range(1, n + 1)):
        if _lis_len(P) != A or _lds_len(P) != B:
            continue
        P_list = list(P)
        for k in range(0, n + 1):
            v = k + 0.5
            if _lis_len(P_list + [v]) == A and _lds_len(P_list + [v]) == B:
                count += 1
                break
    return count % M

from collections import deque

def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    # NOT A SOLUTION: brute-force BFS over tiles, verified only by inspection.
    # It will time out on large K (tests use K up to 10^16).
    def rect(i, j, k):
        if (i - j) % 2 == 0:
            return (i * K, (i + 1) * K, j * K + k, j * K + k + 1)
        return (i * K + k, i * K + k + 1, j * K, (j + 1) * K)

    def tile_of(x, y):
        px, py = x + 0.5, y + 0.5
        for i in range(x // K - 2, x // K + 3):
            for j in range(y // K - 2, y // K + 3):
                for k in range(K):
                    x0, x1, y0, y1 = rect(i, j, k)
                    if x0 <= px <= x1 and y0 <= py <= y1:
                        return (i, j, k)
        raise ValueError("no tile")

    def adjacent(a, b):
        ax0, ax1, ay0, ay1 = rect(*a)
        bx0, bx1, by0, by1 = rect(*b)
        if (ax1 == bx0 or bx1 == ax0) and min(ay1, by1) > max(ay0, by0):
            return True
        if (ay1 == by0 or by1 == ay0) and min(ax1, bx1) > max(ax0, bx0):
            return True
        return False

    start = tile_of(S_x, S_y)
    target = tile_of(T_x, T_y)
    if start == target:
        return 0

    dist = {start: 0}
    q = deque([start])
    while q:
        cur = q.popleft()
        i0, j0, _ = cur
        for di in range(-2, 3):
            for dj in range(-2, 3):
                for k in range(K):
                    nb = (i0 + di, j0 + dj, k)
                    if nb in dist or nb == cur:
                        continue
                    if adjacent(cur, nb):
                        dist[nb] = dist[cur] + 1
                        if nb == target:
                            return dist[nb]
                        q.append(nb)
    return -1

def count_good_integers(num1: str, num2: str, min_sum: int, max_sum: int) -> int:
    MOD = 10**9 + 7

    def count_upto(s: str) -> int:
        # Count x in [0, int(s)] with min_sum <= digit_sum(x) <= max_sum
        # ways[t] = number of digit strings of current length with digit sum t
        # (for tight-free suffix states), computed via DP over positions.
        n = len(s)
        max_total = 9 * n
        # free[k][t]: number of length-k digit strings (leading zeros allowed) with digit sum t
        free = [[0] * (max_total + 1) for _ in range(n + 1)]
        free[0][0] = 1
        for k in range(1, n + 1):
            prev = free[k - 1]
            cur = free[k]
            for t in range(max_total + 1):
                if prev[t]:
                    for d in range(10):
                        if t + d <= max_total:
                            cur[t + d] += prev[t]
        # prefix-count of free[k] over sum range [lo, hi]
        def range_count(k, lo, hi):
            if lo < 0:
                lo = 0
            if hi > max_total:
                hi = max_total
            if lo > hi:
                return 0
            return sum(free[k][lo:hi + 1])

        total = 0
        prefix_sum = 0
        for i, ch in enumerate(s):
            cur_digit = int(ch)
            remaining = n - i - 1
            for d in range(cur_digit):
                # choose digit d at position i, remaining digits free
                base = prefix_sum + d
                total += range_count(remaining, min_sum - base, max_sum - base)
            prefix_sum += cur_digit
        # include s itself
        if min_sum <= prefix_sum <= max_sum:
            total += 1
        return total

    def digit_sum_of_str(s: str) -> int:
        return sum(int(c) for c in s)

    result = count_upto(num2) - count_upto(num1) 
    if min_sum <= digit_sum_of_str(num1) <= max_sum:
        result += 1
    return result % MOD

def min_changes_for_semi_palindromes(s: str, k: int) -> int:
    n = len(s)
    INF = float("inf")

    # cost[i][j] = min changes to make s[i..j] (inclusive) a semi-palindrome
    # (for length 1 this is INF, since a length-1 string is not a semi-palindrome)
    cost = [[INF] * n for _ in range(n)]
    for i in range(n):
        for j in range(i + 1, n):
            length = j - i + 1
            best = INF
            for d in range(1, length):
                if length % d != 0:
                    continue
                changes = 0
                # For each residue class r mod d, compare pairs from both ends
                for r in range(d):
                    idxs = list(range(i + r, j + 1, d))
                    a, b = 0, len(idxs) - 1
                    while a < b:
                        if s[idxs[a]] != s[idxs[b]]:
                            changes += 1
                        a += 1
                        b -= 1
                if changes < best:
                    best = changes
            cost[i][j] = best

    # dp[p][e] = min changes to split s[0..e-1] into p parts
    dp = [[INF] * (n + 1) for _ in range(k + 1)]
    dp[0][0] = 0
    for p in range(1, k + 1):
        for e in range(p, n + 1):
            best = INF
            for st in range(p - 1, e):
                if dp[p - 1][st] == INF:
                    continue
                c = cost[st][e - 1]
                if c == INF:
                    continue
                val = dp[p - 1][st] + c
                if val < best:
                    best = val
            dp[p][e] = best

    return int(dp[k][n])

