def count_paths(N: int, M: int, K: int, extra_edges: list) -> int:
    # adjacency: each vertex has its cycle edge plus extra edges
    out = {v: [v % N + 1] for v in range(1, N + 1)}
    for x, y in extra_edges:
        out[x].append(y)

    # ways[v] = number of walks of current length ending at v, starting at 1
    ways = [0] * (N + 1)
    ways[1] = 1
    for _ in range(K):
        nxt = [0] * (N + 1)
        for v in range(1, N + 1):
            w = ways[v]
            if w:
                for u in out[v]:
                    nxt[u] = (nxt[u] + w) % MOD
        ways = nxt
    return sum(ways) % MOD

def count_valid_grids(H: int, W: int, grid: list[str]) -> int:
    MOD = 998244353

    # Build the cell-color options for each (row, col) in the original orientation.
    def options_at(r, c):
        ch = grid[r][c]
        if ch == '?':
            return (0, 1, 2)
        return (int(ch) - 1,)

    # Choose the frontier width as the smaller dimension. If we sweep by columns
    # instead of rows, the frontier holds one entry per row.
    if W <= H:
        rows, cols = H, W
        def opts(i, j):          # i = row index, j = column index
            return options_at(i, j)
    else:
        rows, cols = W, H
        def opts(i, j):          # i = column index, j = row index (sweeping by columns)
            return options_at(j, i)

    # Frontier of length `cols`: colors of the most recently processed cell in each
    # position. -1 means "no cell yet".
    dp = {tuple([-1] * cols): 1}

    for i in range(rows):
        for j in range(cols):
            new_dp = {}
            allowed = opts(i, j)
            for state, ways in dp.items():
                up = state[j]                          # cell at (i-1, j) in sweep coords
                left = state[j - 1] if j > 0 else -1   # cell at (i, j-1)
                for col in allowed:
                    if col == up or col == left:
                        continue
                    lst = list(state)
                    lst[j] = col
                    key = tuple(lst)
                    new_dp[key] = (new_dp.get(key, 0) + ways) % MOD
            dp = new_dp
            if not dp:
                return 0

    return sum(dp.values()) % MOD

from typing import List, Tuple


def count_ball_sets(n: int, positions: List[Tuple[int, int]]) -> int:
    # Brute force over reachable subsets (exponential in n).
    # Correct by definition for small n; too slow for n=25, 131, 300.
    MOD = 998244353
    start = (1 << n) - 1
    seen = {start}
    stack = [start]
    while stack:
        mask = stack.pop()
        for k in range(n):
            if not (mask >> k) & 1:
                continue
            xk, yk = positions[k]
            new = mask
            for i in range(n):
                if (mask >> i) & 1 and i != k:
                    xi, yi = positions[i]
                    if (xi < xk and yi < yk) or (xi > xk and yi > yk):
                        new &= ~(1 << i)
            if new not in seen:
                seen.add(new)
                stack.append(new)
    return len(seen) % MOD

