from itertools import product

BEATS = {('F', 'E'), ('W', 'F'), ('E', 'W')}

def beats(x, y):
    return (x, y) in BEATS

def bob_seqs(n):
    for b in product('FWE', repeat=n):
        if all(b[i] != b[i + 1] for i in range(n - 1)):
            yield b

def total_rule(s):
    cnt = 0
    for b in bob_seqs(len(s)):
        a = sum(beats(s[i], b[i]) for i in range(len(s)))
        bb = sum(beats(b[i], s[i]) for i in range(len(s)))
        cnt += bb > a
    return cnt

def prefix_rule(s):
    cnt = 0
    for b in bob_seqs(len(s)):
        da = db = 0
        ok = True
        for i in range(len(s)):
            da += beats(s[i], b[i])
            db += beats(b[i], s[i])
            if db <= da:
                ok = False
                break
        cnt += ok
    return cnt

def final_win_rule(s):
    cnt = 0
    for b in bob_seqs(len(s)):
        a = sum(beats(s[i], b[i]) for i in range(len(s)))
        bb = sum(beats(b[i], s[i]) for i in range(len(s)))
        cnt += bb > a and beats(b[-1], s[-1])
    return cnt

