def count_k_reducible(s: str, k: int) -> int:
    MOD = 10**9 + 7
    n_len = len(s)

    # steps[v] = number of operations to reduce v to 1 (using popcount), for v >= 1
    MAXV = max(n_len, 2)
    steps = [0] * (MAXV + 1)
    for v in range(2, MAXV + 1):
        steps[v] = steps[bin(v).count("1")] + 1

    # ways[p] = number of integers x in [1, n-1] with popcount p
    # Digit DP: count numbers in [0, n) with popcount p, then subtract x=0 (popcount 0).
    # cnt[p] over [0, n)
    cnt = [0] * (n_len + 1)
    ones_before = 0  # number of 1s in prefix of s
    for i, ch in enumerate(s):
        remaining = n_len - i - 1
        if ch == "1":
            # place 0 here, free remaining bits
            # total popcount = ones_before + j, j ones in remaining bits
            for j in range(remaining + 1):
                cnt[ones_before + j] = (cnt[ones_before + j] + comb(remaining, j)) % MOD
            ones_before += 1
    # numbers in [0, n) include 0 possibly; n itself excluded automatically
    # cnt currently counts numbers < n; zero has popcount 0
    cnt[0] = (cnt[0] - 1) % MOD  # remove x = 0

    result = 0
    for p in range(1, n_len + 1):
        # x with popcount p, x != 1 case handled: x=1 has popcount 1, steps 0
        if p == 1:
            # x = 1 itself is k-reducible (0 operations) if n > 1
            # x with popcount 1 are powers of two; x=1 needs 0 ops, others need 1 + steps(1)=1 op
            # so all popcount-1 numbers are k-reducible when k >= 1
            if k >= 1:
                result = (result + cnt[p]) % MOD
            # x=1 is counted in cnt[1] and is always reducible; fine
        else:
            if steps[p] + 1 <= k:
                result = (result + cnt[p]) % MOD
    return result % MOD


def comb(n, r):
    if r < 0 or r > n:
        return 0
    # Pascal-style cached computation
    global _COMB_CACHE
    try:
        _COMB_CACHE
    except NameError:
        _COMB_CACHE = {}
    key = (n, r)
    if key in _COMB_CACHE:
        return _COMB_CACHE[key]
    res = 1
    rr = min(r, n - r)
    for i in range(rr):
        res = res * (n - i) // (i + 1)
    _COMB_CACHE[key] = res
    return res

from functools import lru_cache
from math import comb

def count_balanced_graphs(n: int, p: int) -> list[int]:
    maxM = n * (n - 1) // 2
    half = n // 2

    def polymul(A, B):
        C = [0] * (len(A) + len(B) - 1)
        for i, a in enumerate(A):
            if a == 0:
                continue
            for j, b in enumerate(B):
                if b:
                    C[i + j] += a * b
        return C

    def polyadd(A, B, scale=1):
        L = max(len(A), len(B))
        C = [0] * L
        for i, a in enumerate(A):
            C[i] += a
        for i, b in enumerate(B):
            C[i] += scale * b
        return C

    # within[s]: polynomial in x, sum_e C(C(s,2), e) x^e  (any graph on s labeled vertices)
    @lru_cache(maxsize=None)
    def within(s):
        m = s * (s - 1) // 2
        return tuple(comb(m, e) for e in range(m + 1))

    # cover[a][b]: polynomial in x counting edge sets between new layer (size a)
    # and previous layer (size b) where every new-layer vertex has >=1 back edge.
    @lru_cache(maxsize=None)
    def cover(a, b):
        res = [0] * (a * b + 1)
        for j in range(a + 1):  # j vertices with no back edge
            sign = -1 if j % 2 else 1
            m = (a - j) * b
            coef = comb(a, j) * sign
            for e in range(m + 1):
                res[e] += coef * comb(m, e)
        return tuple(res)

    # State: (vertices placed so far including root, size of last layer, parity of last layer,
    #         count of even vertices placed, count of odd vertices placed)
    # Value: polynomial in x counting labeled structures.
    # Root is distance 0 (even), counted in even.
    from collections import defaultdict
    init_poly = [1]
    states = {(1, 1, 0, 1, 0): init_poly}
    total = [0] * (maxM + 1)

    # Process layer by layer; each step adds one layer.
    while states:
        nxt = defaultdict(lambda: [0])
        for (placed, last, par, ev, od), poly in states.items():
            # Record completed graph: all n vertices placed, balance achieved
            if placed == n and ev == half and od == half:
                for i, c in enumerate(poly):
                    total[i] = total[i] + c
                continue
            remaining = n - placed
            for a in range(1, remaining + 1):
                new_par = 1 - par
                nev, nod = (ev + a, od) if new_par == 0 else (ev, od + a)
                if nev > half or nod > half:
                    continue
                # Choose which labeled vertices form this layer
                mult = comb(remaining, a)
                layer_poly = polymul(list(cover(a, last)), list(within(a)))
                contrib = [mult * c for c in layer_poly]
                newp = polymul(poly, contrib)
                key = (placed + a, a, new_par, nev, nod)
                nxt[key] = polyadd(nxt[key], newp)
        # Trim unneeded states
        states = {k: v for k, v in nxt.items()}

    out = []
    for M in range(n - 1, maxM + 1):
        out.append(total[M] % p)
    return out

