def count_strings_by_lcs_length(n: int, m: int, s: str) -> List[int]:
    MOD = 998244353

    # Distinct letters in s, each with its multiplicity as a "character class";
    # all other letters (26 - distinct) form one class that never matches s.
    distinct = sorted(set(s))
    classes = [(c, 1) for c in distinct]
    other = 26 - len(distinct)
    if other > 0:
        classes.append((None, other))

    # Encode LCS DP row as a bitmask: bit (j-1) set iff dp[j] == dp[j-1] + 1.
    # Recover the row from the mask, apply one character, re-encode.
    def row_from_mask(mask):
        row = [0] * (n + 1)
        for j in range(1, n + 1):
            row[j] = row[j - 1] + ((mask >> (j - 1)) & 1)
        return row

    def mask_from_row(row):
        mask = 0
        for j in range(1, n + 1):
            if row[j] > row[j - 1]:
                mask |= 1 << (j - 1)
        return mask

    def step(mask, c):
        dp = row_from_mask(mask)
        new = [0] * (n + 1)
        for j in range(1, n + 1):
            if c is not None and s[j - 1] == c:
                new[j] = dp[j - 1] + 1
            else:
                new[j] = max(dp[j], new[j - 1])
        return mask_from_row(new)

    # Precompute transitions: trans[mask] = list of (next_mask, weight).
    num_states = 1 << n
    trans = []
    for mask in range(num_states):
        agg = {}
        for c, w in classes:
            nm = step(mask, c)
            agg[nm] = agg.get(nm, 0) + w
        trans.append(list(agg.items()))

    cur = [0] * num_states
    cur[0] = 1  # empty prefix: all-zero row, mask 0
    for _ in range(m):
        nxt = [0] * num_states
        for mask in range(num_states):
            cnt = cur[mask]
            if cnt == 0:
                continue
            for nm, w in trans[mask]:
                nxt[nm] = (nxt[nm] + cnt * w) % MOD
        cur = nxt

    result = [0] * (n + 1)
    for mask in range(num_states):
        cnt = cur[mask]
        if cnt:
            k = bin(mask).count("1")
            result[k] = (result[k] + cnt) % MOD
    return result

def count_paths(W: int, H: int, L: int, R: int, D: int, U: int) -> int:
    MOD = 998244353

    def is_block(x, y):
        if x < 0 or y < 0 or x > W or y > H:
            return False
        return x < L or x > R or y < D or y > U

    f = [[0] * (H + 1) for _ in range(W + 1)]
    total = 0
    for x in range(W + 1):
        for y in range(H + 1):
            if not is_block(x, y):
                continue
            val = 1
            if x > 0 and is_block(x - 1, y):
                val += f[x - 1][y]
            if y > 0 and is_block(x, y - 1):
                val += f[x][y - 1]
            f[x][y] = val % MOD
            total = (total + f[x][y]) % MOD
    return total

