from functools import lru_cache


def kth_alternating_permutation(n: int, k: int) -> List[int]:
    # count completions given remaining odds, evens, and parity of last placed
    @lru_cache(maxsize=None)
    def ways(o: int, e: int, last: int) -> int:
        # last: 0 = last placed was odd, 1 = last placed was even, 2 = none placed
        if o == 0 and e == 0:
            return 1
        total = 0
        if o > 0 and last != 0:
            total += ways(o - 1, e, 0)
        if e > 0 and last != 1:
            total += ways(o, e - 1, 1)
        return total

    # Note: ways counts parity patterns, not actual values. Each parity pattern
    # is expanded by the number of distinct value choices, handled below.
    odds = sorted(x for x in range(1, n + 1) if x % 2 == 1)
    evens = sorted(x for x in range(1, n + 1) if x % 2 == 0)

    @lru_cache(maxsize=None)
    def total_count(o: int, e: int, last: int) -> int:
        if o == 0 and e == 0:
            return 1
        total = 0
        if o > 0 and last != 0:
            total += o * total_count(o - 1, e, 0)
        if e > 0 and last != 1:
            total += e * total_count(o, e - 1, 1)
        return total

    if k < 1 or k > total_count(len(odds), len(evens), 2):
        return []

    result: List[int] = []
    o_left, e_left = list(odds), list(evens)
    last = 2
    while o_left or e_left:
        # try candidates in increasing value order
        candidates = sorted(
            [(v, 0) for v in o_left if last != 0] + [(v, 1) for v in e_left if last != 1]
        )
        for v, p in candidates:
            no = len(o_left) - (1 if p == 0 else 0)
            ne = len(e_left) - (1 if p == 1 else 0)
            c = total_count(no, ne, p)
            if k <= c:
                result.append(v)
                (o_left if p == 0 else e_left).remove(v)
                last = p
                break
            k -= c
        else:
            return []
    return result

def count_powerful_integers(start: int, finish: int, limit: int, s: str) -> int:
    from functools import lru_cache

    suffix_val = int(s)
    m = len(s)
    scale = 10 ** m

    # s must itself have all digits <= limit, otherwise no valid x exists
    if any(int(c) > limit for c in s):
        return 0

    # Prefix p ranges so that start <= p*scale + suffix_val <= finish
    # => p >= ceil((start - suffix_val) / scale), p <= floor((finish - suffix_val) / scale)
    if finish < suffix_val:
        return 0
    hi = (finish - suffix_val) // scale
    if start - suffix_val <= 0:
        lo = 0
    else:
        lo = -((-(start - suffix_val)) // scale)  # ceil division

    if lo > hi:
        return 0

    def count_upto(n: int) -> int:
        """Count integers p in [0, n] whose digits are all <= limit (0 counts)."""
        if n < 0:
            return 0
        digits = list(map(int, str(n)))
        L = len(digits)

        @lru_cache(maxsize=None)
        def dp(pos: int, tight: bool, started: bool) -> int:
            if pos == L:
                return 1  # includes the number 0 (not started)
            limit_digit = digits[pos] if tight else 9
            total = 0
            for d in range(0, limit_digit + 1):
                if d > limit:
                    break
                new_tight = tight and (d == limit_digit)
                total += dp(pos + 1, new_tight, started or d != 0)
            return total

        result = dp(0, True, False)
        dp.cache_clear()
        return result

    return count_upto(hi) - count_upto(lo - 1)

