def find_cube_placement(V1: int, V2: int, V3: int) -> Optional[Tuple[int, int, int, int, int, int, int, int, int]]:
    """ Given three volumes V1, V2, V3, find a placement of three cubes with side length 7 such that:
    - The volume of the region contained in exactly one cube is V1
    - The volume of the region contained in exactly two cubes is V2
    - The volume of the region contained in all three cubes is V3

    Each cube C(a,b,c) is defined by the region (a ≤ x ≤ a+7) ∧ (b ≤ y ≤ b+7) ∧ (c ≤ z ≤ c+7).

    Returns:
        A tuple (a1, b1, c1, a2, b2, c2, a3, b3, c3) if a valid placement exists with all
        absolute values ≤ 100, otherwise None.
    """
    S = 7
    V = S ** 3
    # Necessary condition: total multiplicity-weighted volume equals 3V
    if V1 + 2 * V2 + 3 * V3 != 3 * V:
        return None

    def inter_len(a: int, b: int) -> int:
        # overlap length of [a, a+S] and [b, b+S] on one axis
        return max(0, min(a, b) + S - max(a, b))

    def box_vol(p, q):
        return (inter_len(p[0], q[0]) * inter_len(p[1], q[1]) * inter_len(p[2], q[2]))

    def triple_vol(p, q, r):
        lo = [max(p[i], q[i], r[i]) for i in range(3)]
        hi = [min(p[i], q[i], r[i]) + S for i in range(3)]
        d = [max(0, hi[i] - lo[i]) for i in range(3)]
        return d[0] * d[1] * d[2]

    # Search cube 2 and cube 3 offsets relative to cube 1 at origin, in [-S, S]
    rng = range(-S, S + 1)
    c1 = (0, 0, 0)
    for a2 in rng:
        for b2 in rng:
            for c2 in rng:
