def calculate_black_area_doubled(A: int, B: int, C: int, D: int) -> int:
    def cumulative(X: int, Y: int) -> int:
        # Twice the black area in the region [0, X] x [0, Y] (for X, Y >= 0),
        # extended to negative coordinates by symmetry of the 2x2 period.
        # Each unit cell contributes 1 (twice the average black area of 1/2).
        # Full 2x2 blocks contribute 4 each; remainders handled by the
        # coloring of the partial block containing (0.5, 0.5) as black.
        def block_area(x0: int, y0: int, x1: int, y1: int) -> int:
            # Count unit cells in [x0,x1)x[y0,y1), each contributes 1 (doubled)
            return (x1 - x0) * (y1 - y0)

        sx = 1 if X >= 0 else -1
        sy = 1 if Y >= 0 else -1
        ax, ay = abs(X), abs(Y)
        val = block_area(0, 0, ax, ay)
        return sx * sy * val

    return cumulative(C, D) - cumulative(A, D) - cumulative(C, B) + cumulative(A, B)

def calculate_black_area_doubled(A: int, B: int, C: int, D: int) -> int:
    def color(x2: int, y2: int) -> int:
        # x2 = 2x, y2 = 2y for a point off all lines.
        # Lines: x integer, y even, x+y even.
        # Parity of crossings from reference point (0.5, 0.5) decides color.
        fx = x2 // 2
        fy = y2 // 4
        fs = (x2 + y2) // 4
        return (fx + fy + fs) % 2

    def F(X: int, Y: int) -> int:
        # Twice the black area of [0, X] x [0, Y] for X, Y >= 0.
        # Sum over unit squares; each unit square is split by a diagonal into
        # two triangles of doubled area 1 each. Black triangles contribute 1.
        total = 0
        for i in range(X):
            for j in range(Y):
                # Triangle centroids (doubled coordinates, scaled by 3)
                c1 = color(2 * i * 3 + 2, 2 * j * 3 + 2)
                c2 = color(2 * i * 3 + 4, 2 * j * 3 + 4)
                total += (1 if c1 == 0 else 0) + (1 if c2 == 0 else 0)
        return total

    def G(x: int, y: int) -> int:
        sx = 1 if x >= 0 else -1
        sy = 1 if y >= 0 else -1
        return sx * sy * F(abs(x), abs(y))

    return G(C, D) - G(A, D) - G(C, B) + G(A, B)

