def count_good_sequences(N: int, M: int) -> int:
    def sigma(n):
        total = 0
        d = 1
        while d * d <= n:
            if n % d == 0:
                total += d
                if d != n // d:
                    total += n // d
            d += 1
        return total

    def ways(factorization):
        # number of ordered M-tuples with given prime exponents
        res = 1
        for e in factorization:
            res = res * comb(e + M - 1, M - 1) % MOD
        return res

    def factorize(n):
        exps = []
        d = 2
        while d * d <= n:
            e = 0
            while n % d == 0:
                n //= d
                e += 1
            if e:
                exps.append(e)
            d += 1
        if n > 1:
            exps.append(1)
        return exps

    total = 0
    for n in range(1, N + 1):
        if sigma(n) % 3 == 0:
            total = (total + ways(factorize(n))) % MOD
    return total

