def count_special_permutations(A: int, B: int, M: int) -> int:
    # Sum over partitions lambda with lambda_1 = A, number of rows = B,
    # |lambda| = A*B - 1, of (f^lambda)^2, where f^lambda is the number of
    # standard Young tableaux (hook length formula). The extra appendability
    # condition is NOT verified here; this is an unverified approximation.
    from functools import lru_cache

    N = A * B - 1

    def partitions_with(first_row, rows, total):
        # generate partitions with largest part == first_row, exactly `rows` parts
        # (parts may be zero-padded to length rows), summing to total
        res = []
        def rec(remaining, maxpart, parts_left, cur):
            if parts_left == 0:
                if remaining == 0:
                    res.append(tuple(cur))
                return
            for p in range(min(maxpart, remaining), 0, -1):
                if p * parts_left < remaining:
                    break
                rec(remaining - p, p, parts_left - 1, cur + [p])
        rec(total - first_row, first_row, rows - 1, [first_row])
        return res

    def num_syt(shape):
        n = sum(shape)
        conj = [sum(1 for r in shape if r > j) for j in range(shape[0])]
        prod = 1
        for i, r in enumerate(shape):
            for j in range(r):
                prod *= (r - j - 1) + (conj[j] - i - 1) + 1
        fact = 1
        for k in range(2, n + 1):
            fact *= k
        return fact // prod

    total = 0
    for lam in partitions_with(A, B, N):
        f = num_syt(lam)
        total += f * f
    return total % M

