def count_special_permutations(A: int, B: int, M: int) -> int:
    N = A * B - 1
    count = 0
    for P in permutations(range(1, N + 1)):
        P = list(P)
        if _lis(P) != A or _lds(P) != B:
            continue
        # Append n + 0.5 for some integer n. Only values within the range of
        # the permutation (0..N) matter, since n + 0.5 for other n can be
        # reduced to these cases; we check every n in 0..N.
        ok = False
        for n in range(0, N + 1):
            v = n + 0.5
            if _lis(P + [v]) == A and _lds(P + [v]) == B:
                ok = True
                break
        if ok:
            count += 1
    return count % M

def count_special_permutations(A: int, B: int, M: int) -> int:
    N = A * B - 1

    def partitions(total, max_part, max_len):
        # partitions of `total` with parts <= max_part and at most max_len parts
        if total == 0:
            yield []
            return
        if max_len == 0:
            return
        for p in range(min(total, max_part), 0, -1):
            for rest in partitions(total - p, p, max_len - 1):
                yield [p] + rest

    def num_syt(shape):
        n = sum(shape)
        conj = [sum(1 for r in shape if r > j) for j in range(shape[0])]
        prod = 1
        for i, r in enumerate(shape):
            for j in range(r):
                prod *= (r - j - 1) + (conj[j] - i - 1) + 1
        fact = 1
        for k in range(2, n + 1):
            fact *= k
        return fact // prod

    total = 0
    # shapes with first row exactly A and exactly B rows
    for rest in partitions(N - A, A, B - 1):
        shape = [A] + rest
        if len(shape) != B:
            continue
        # NOTE: appendability condition not enforced here.
        f = num_syt(shape)
        total += f * f
    return total % M

