from collections import deque


def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    # Tile identifier: (type, i, j, k)
    # type 0: same parity (i, j) -> x in [iK, (i+1)K], y in [jK+k, jK+k+1]
    # type 1: different parity (i, j) -> x in [iK+k, iK+k+1], y in [jK, (j+1)K]

    def tile_of(x, y):
        # Find the tile containing the unit cell (x+0.5, y+0.5)
        # Try both types; the point is in exactly one tile of the tiling.
        # Type 0: y lies in [jK+k, jK+k+1] with k = y - jK for some j, and
        # x in [iK, (i+1)K] with i = floor(x / K).
        i = x // K
        # For type 0 with cell x in [iK, (i+1)K), need j with same parity as i.
        # y = jK + k, 0 <= k < K  => j = floor(y / K), k = y mod K.
        j0 = y // K
        k0 = y - j0 * K
        if (i - j0) % 2 == 0:
            return (0, i, j0, k0)
        # Type 1 with x = iK + k => i = floor(x / K), k = x mod K, j = floor(y / K)
        k1 = x - i * K
        return (1, i, j0, k1)

    def tile_cells(t):
        # Return the set of unit cells (x, y) lying in tile t (for small bounded sweep)
        typ, i, j, k = t
        cells = []
        if typ == 0:
            for x in range(i * K, (i + 1) * K):
                cells.append((x, j * K + k))
        else:
            for y in range(j * K, (j + 1) * K):
                cells.append((i * K + k, y))
        return cells

    def neighbors(t):
        # Tiles sharing a positive-length edge with t: check the unit cells that
        # are edge-adjacent to t's cells and map them back to tiles.
        result = set()
        for (x, y) in tile_cells(t):
            for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nb = tile_of(x + dx, y + dy)
                if nb != t:
                    result.add(nb)
        return result

    start = tile_of(S_x, S_y)
    target = tile_of(T_x, T_y)
    if start == target:
        return 0

    # Plain BFS over tiles; only practical for small K and small coordinates.
    queue = deque([(start, 0)])
    seen = {start}
    while queue:
        t, d = queue.popleft()
        for nb in neighbors(t):
            if nb == target:
                return d + 1
            if nb not in seen:
                seen.add(nb)
                queue.append((nb, d + 1))
    return -1

