from math import gcd

def can_color_all_points(n: int, k: int) -> bool:
    g = gcd(n, k)
    m = n // g
    if m % 2 == 1:
        return g & (g - 1) == 0 or g == 1
    # m even
    if g == 1:
        return n & (n - 1) != 0 or n == 2
    return False

from functools import lru_cache

def can_color_all_points(n: int, k: int) -> bool:
    full = (1 << n) - 1
    positions = (0, k % n)

    @lru_cache(maxsize=None)
    def search(mask: int, turn: int) -> bool:
        if mask == full:
            return True
        p = positions[turn]
        seen = set()
        for x in range(n):
            if mask >> x & 1:
                continue
            # reflection across the axis through p
            y = (2 * p - x) % n
            if y in seen:
                continue
            new_mask = mask | (1 << x) | (1 << y)
            if new_mask == mask:
                continue
            seen.add(y)
            if search(new_mask, 1 - turn):
                return True
        return False

    return search(0, 0)

