                    for d in range(10):
                        if t + d <= max_total:
                            ways[k][t + d] = (ways[k][t + d] + ways[k - 1][t]) % MOD

        def range_sum_ways(k: int, prefix_sum: int) -> int:
            # Number of length-k digit strings s such that
            # min_sum <= prefix_sum + digit_sum(s) <= max_sum
            lo = max(0, min_sum - prefix_sum)
            hi = max_sum - prefix_sum
            if hi < 0:
                return 0
            total = 0
            for t in range(lo, min(hi, 9 * k) + 1):
                total += ways[k][t]
            return total % MOD

