def min_changes_for_semi_palindromes(s: str, k: int) -> int:
    n = len(s)
    INF = float("inf")

    # cost[i][j] = min changes to make s[i..j] (inclusive) a semi-palindrome
    cost = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(i + 1, n):
            length = j - i + 1
            best = INF
            for d in range(1, length):
                if length % d != 0:
                    continue
                changes = 0
                # For each residue class r in [0, d), compare mirrored positions
                for r in range(d):
                    idxs = list(range(i + r, j + 1, d))
                    a, b = 0, len(idxs) - 1
                    while a < b:
                        if s[idxs[a]] != s[idxs[b]]:
                            changes += 1
                        a += 1
                        b -= 1
                best = min(best, changes)
            cost[i][j] = best

    # dp[p][t] = min changes to split first t chars into p semi-palindromic parts
    dp = [[INF] * (n + 1) for _ in range(k + 1)]
    dp[0][0] = 0
    for p in range(1, k + 1):
        for t in range(p * 2, n + 1):
            best = INF
            # last part is s[st..t-1], length >= 2
            for st in range(p - 1 == 0 and 0 or (p - 1) * 2, t - 1):
                if dp[p - 1][st] == INF:
                    continue
                c = dp[p - 1][st] + cost[st][t - 1]
                if c < best:
                    best = c
            dp[p][t] = best
    return dp[k][n]

