from typing import List


def min_operations_to_sum(nums: List[int], target: int) -> int:
    if sum(nums) < target:
        return -1

    cnt = [0] * 64
    for x in nums:
        cnt[x.bit_length() - 1] += 1

    ops = 0
    for i in range(32):
        if (target >> i) & 1:
            if cnt[i] > 0:
                cnt[i] -= 1
            else:
                # find smallest higher available power and split it down to 2^i
                j = i + 1
                while j < 64 and cnt[j] == 0:
                    j += 1
                if j >= 64:
                    return -1
                # split 2^j into pieces: one 2^i is used, the rest become available
                cnt[j] -= 1
                for k in range(i, j):
                    cnt[k] += 1
                ops += j - i
                # the split produced an extra 2^i piece pair; one consumed above,
                # the remaining 2^i (from the last split) is already counted in cnt[i]
        # carry: pair up leftover lower powers into the next level
        if i + 1 < 64:
            cnt[i + 1] += cnt[i] // 2
            cnt[i] %= 2

    return ops

