MOD = 998244353


def dice_sum_probability(n: int, dice_faces: List[int]) -> int:
    TARGET = 10
    FULL = (1 << (TARGET + 1)) - 1  # bits 0..10

    # dp[mask] = probability of reaching subset-sum set `mask` (bit j set iff some subset sums to j)
    # Initially only sum 0 is achievable.
    dp = {1: 1}

    for m in dice_faces:
        inv_m = pow(m, MOD - 2, MOD)
        new_dp = {}
        small = min(TARGET, m)
        # Values > TARGET (and <= m) do not change the state
        big_count = m - small
        if big_count > 0:
            p_big = big_count % MOD * inv_m % MOD
            for mask, pr in dp.items():
                new_dp[mask] = (new_dp.get(mask, 0) + pr * p_big) % MOD
        for c in range(1, small + 1):
            p = inv_m
            for mask, pr in dp.items():
                nmask = (mask | (mask << c)) & FULL
                new_dp[nmask] = (new_dp.get(nmask, 0) + pr * p) % MOD
        dp = new_dp

    # Probability that target is achievable = sum over masks containing bit TARGET
    ans = 0
    for mask, pr in dp.items():
        if (mask >> TARGET) & 1:
            ans = (ans + pr) % MOD
    return ans

