def min_weight_hamiltonian_walk(n: int, m: int, edges: List[Tuple[int, int, int]]) -> Optional[int]:
    INF = float('inf')
    dist = [[INF] * n for _ in range(n)]
    for i in range(n):
        dist[i][i] = 0
    for u, v, w in edges:
        u -= 1
        v -= 1
        if w < dist[u][v]:
            dist[u][v] = w

    # Floyd-Warshall (no negative cycles guaranteed)
    for k in range(n):
        dk = dist[k]
        for i in range(n):
            dik = dist[i][k]
            if dik == INF:
                continue
            di = dist[i]
            for j in range(n):
                nd = dik + dk[j]
                if nd < di[j]:
                    di[j] = nd

    full = (1 << n) - 1
    # dp[mask][v]: min cost of a walk that has first-visited exactly the
    # vertices in mask (in some order), currently standing at v.
    dp = [[INF] * n for _ in range(1 << n)]
    for v in range(n):
        dp[1 << v][v] = 0

    for mask in range(1, 1 << n):
        row = dp[mask]
        for v in range(n):
            cur = row[v]
            if cur == INF:
                continue
            dv = dist[v]
            for u in range(n):
                if mask & (1 << u):
                    continue
                if dv[u] == INF:
                    continue
                nmask = mask | (1 << u)
                nc = cur + dv[u]
                if nc < dp[nmask][u]:
                    dp[nmask][u] = nc

    best = min(dp[full])
    return None if best == INF else best

