def count_paths(N: int, M: int, K: int, extra_edges: list) -> int:
    # Out-edges: each vertex has its cycle edge; special vertices have extra edges too.
    extra = {}
    for x, y in extra_edges:
        extra.setdefault(x, []).append(y)
    specials = sorted(set(extra.keys()) | {1})
    # Dist along cycle from vertex a to vertex b (number of cycle moves)
    def cyc(a, b):
        return (b - a) % N

    # dp: dict time -> dict vertex -> ways, where vertex is special and walk is there at that time
    from collections import defaultdict
    dp = defaultdict(lambda: defaultdict(int))
    dp[0][1] = 1
    total = 0
    # Process times in increasing order
    times = [0]
    import heapq
    heap = [0]
    seen = {0}
    while heap:
        t = heapq.heappop(heap)
        if t > K:
            continue
        cur = dp.pop(t, None)
        if cur is None:
            continue
        for v, ways in cur.items():
            if ways % MOD == 0:
                continue
            # Option 1: take cycle edge, then follow forced cycle until next special vertex
            # Walk forced from v: number of forced steps until next special vertex s' (strictly after v)
            # Each walk from v of length L is determined by the next move choice.
            # Enumerate the next special vertex reached by cycle-only walking from v.
            nxt_candidates = [s for s in specials if s != v]
            # Cycle-only walk from v hits the first special s at distance cyc(v,s) >=1 if s != v
            # Also, if no other special exists, it returns to v after N steps.
            # Walks that do not hit any special before K: count as 1 path if remaining moves fit.
            for choice in [0] + list(range(len(extra.get(v, [])))):
                if choice == 0:
                    start = (v % N) + 1 if v != N else 1
                    start = v % N + 1
                else:
                    start = extra[v][choice - 1]
                # walk forced from start until next special
                # distance from start to next special along cycle (first special >= start, excluding current)
                step_after = t + 1
                if step_after > K:
                    continue
                if start in extra or start == 1:
                    # arrived directly at special
                    nt = step_after
                    if nt <= K:
                        dp[nt][start] = (dp[nt][start] + ways) % MOD
                        if nt not in seen:
                            seen.add(nt)
                            heapq.heappush(heap, nt)
                else:
                    # forced walk until next special (cyclically)
                    best = None
                    for s in specials:
                        d = cyc(start, s)
                        if best is None or d < best[0]:
                            best = (d, s)
                    d, s = best
                    nt = step_after + d
                    if nt <= K:
                        dp[nt][s] = (dp[nt][s] + ways) % MOD
                        if nt not in seen:
                            seen.add(nt)
                            heapq.heappush(heap, nt)
                    elif step_after + d > K:
                        # walk ends in the middle of forced path: exactly one path
                        total = (total + ways) % MOD
        # Also, walks that end exactly at time K at a special vertex are counted via total below
    # Accumulate endings: those that reached exactly K steps
    for v, ways in dp.pop(K, {}).items():
        total = (total + ways) % MOD
    return total % MOD

