def min_team_switches(people: List[Tuple[int, int]]) -> int:
    teams = {1: [], 2: [], 3: []}
    for t, s in people:
        teams[t].append(s)

    total = sum(s for _, s in people)
    if total % 3 != 0:
        return -1
    target = total // 3
    cur = {t: sum(teams[t]) for t in (1, 2, 3)}
    excess = {t: cur[t] - target for t in (1, 2, 3)}

    INF = float('inf')

    def min_counts_table(values):
        # best[x] = minimum number of members whose strengths sum to exactly x
        cap = sum(values)
        best = [INF] * (cap + 1)
        best[0] = 0
        for v in values:
            for x in range(cap, v - 1, -1):
                if best[x - v] + 1 < best[x]:
                    best[x] = best[x - v] + 1
        return best

    tables = {t: min_counts_table(teams[t]) for t in (1, 2, 3)}

    # A team that sends out `out` strength and receives `inn` strength must satisfy
    # out - inn = excess[t]. Team t's departures are a subset of its members with
    # sum `out`; arrivals are people from other teams, which add to the departure
    # counts of their origin teams. Total moves = sum of departure counts.
    # Inflow to team t is the outflow of the other teams, so we enumerate
    # the outflow of teams 1 and 2 and derive team 3's outflow from balance.
    # Balance: out_t - in_t = excess[t] for all t, and sum of in = sum of out.
    # Feasible when the flows decompose across the pairs; we enumerate
    # flows f[a][b] = strength moved from a to b, using the departure subsets.
    best_moves = INF

    # Enumerate strength moved from team 1 to team 2 and 3, and from 2 to 1 and 3.
    # Team 3's flows are then determined by balance.
    # Represent the set of departing people from each team by its strength sum.
    for o1 in range(cur[1] + 1):
        c1 = tables[1][o1] if o1 < len(tables[1]) else INF
        if c1 == INF:
            continue
        for o2 in range(cur[2] + 1):
            c2 = tables[2][o2] if o2 < len(tables[2]) else INF
            if c2 == INF:
                continue
            # net: team1 out - in = excess[1]  ->  in1 = o1 - excess[1]
            # net: team2 out - in = excess[2]  ->  in2 = o2 - excess[2]
            in1 = o1 - excess[1]
            in2 = o2 - excess[2]
            # team 3 must be consistent: out3 - in3 = excess[3],
            # and total in = total out, so in3 = o1 + o2 + o3 - in1 - in2.
            # Team 3's outflow o3 = in1 + in2 - (o1+o2) + ... derived from balance:
            # in3 = out3 - excess[3], and out1+out2+out3 = in1+in2+in3.
            # Solving: out3 = in1 + in2 + in3 - o1 - o2, with in3 = out3 - excess[3]
            # gives excess[3] = in1 + in2 - o1 - o2 = -(excess[1] + excess[2]),
            # which always holds, so out3 is free. Choose out3 minimizing moves.
            if in1 < 0 or in2 < 0:
                continue
            for o3 in range(cur[3] + 1):
                c3 = tables[3][o3] if o3 < len(tables[3]) else INF
                if c3 == INF:
                    continue
                in3 = o3 - excess[3]
                if in3 < 0:
                    continue
                if o1 + o2 + o3 != in1 + in2 + in3:
                    continue
                moves = c1 + c2 + c3
                if moves < best_moves:
                    best_moves = moves

    return -1 if best_moves == INF else int(best_moves)

