def min_team_switches(people: List[Tuple[int, int]]) -> int:
    total = sum(s for _, s in people)
    if total % 3 != 0:
        return -1
    target = total // 3
    cur = {1: 0, 2: 0, 3: 0}
    for t, s in people:
        cur[t] += s
    need1 = target - cur[1]
    need2 = target - cur[2]
    # Net change vector (d1, d2) for teams 1 and 2; team 3 is implied.
    # A move of strength s from team a to team b contributes
    # -s to a and +s to b (in the change vector for teams 1,2 only).

    # dp maps (d1, d2) -> minimum number of moves achieving that net change.
    dp = {(0, 0): 0}
    for t, s in people:
        new_dp = dict(dp)  # option: person stays, cost 0
        for dest in (1, 2, 3):
            if dest == t:
                continue
            delta = [0, 0]
            # origin contribution
            if t == 1:
                delta[0] -= s
            elif t == 2:
                delta[1] -= s
            # destination contribution
            if dest == 1:
                delta[0] += s
            elif dest == 2:
                delta[1] += s
            for (d1, d2), c in dp.items():
                key = (d1 + delta[0], d2 + delta[1])
                if new_dp.get(key, float('inf')) > c + 1:
                    new_dp[key] = c + 1
        dp = new_dp

    # Team 3 is consistent automatically since the total is conserved.
    return dp.get((need1, need2), -1) if (need1, need2) in dp else -1

