def count_valid_grids(H: int, W: int, grid: list[str]) -> int:
    MOD = 998244353

    # Transpose so that the profile width (W) is the smaller dimension.
    if W > H:
        grid = [''.join(grid[i][j] for i in range(H)) for j in range(W)]
        H, W = W, H

    # dp maps profile (tuple of last W colors, 0 means "empty" for first row) -> count
    # Encode profile as a tuple of length W; initially all 0 (no cell above).
    dp = {tuple([0] * W): 1}

    for i in range(H):
        for j in range(W):
            ch = grid[i][j]
            if ch == '?':
                allowed = (1, 2, 3)
            else:
                allowed = (int(ch),)
            ndp = {}
            for prof, cnt in dp.items():
                top = prof[j]          # cell (i-1, j); 0 if none
                left = prof[j - 1] if j > 0 else 0  # cell (i, j-1), already updated
                for c in allowed:
                    if c == top or c == left:
                        continue
                    newprof = list(prof)
                    newprof[j] = c
                    key = tuple(newprof)
                    ndp[key] = (ndp.get(key, 0) + cnt) % MOD
            dp = ndp
            if not dp:
                return 0

    return sum(dp.values()) % MOD

