from functools import lru_cache

def card_game_winner(n: int, m: int, l: int, takahashi_cards: List[int], aoki_cards: List[int], table_cards: List[int]) -> str:
    @lru_cache(maxsize=None)
    def mover_wins(my_hand: Tuple[int, ...], other_hand: Tuple[int, ...], table: Tuple[int, ...]) -> bool:
        # Returns True if the player to move (holding my_hand) wins.
        for i, card in enumerate(my_hand):
            new_my = my_hand[:i] + my_hand[i+1:]
            new_table = tuple(sorted(table + (card,)))
            # Option 1: play without taking
            if not mover_wins(other_hand, new_my, new_table):
                return True
            # Option 2: play and take a smaller table card
            for j, t in enumerate(new_table):
                if t < card:
                    taken_table = new_table[:j] + new_table[j+1:]
                    taken_hand = tuple(sorted(new_my + (t,)))
                    if not mover_wins(other_hand, taken_hand, taken_table):
                        return True
        return False

    first_wins = mover_wins(tuple(sorted(takahashi_cards)), tuple(sorted(aoki_cards)), tuple(sorted(table_cards)))
    return "Takahashi" if first_wins else "Aoki"

