def min_deletions_to_snowflake(n: int, edges: List[Tuple[int, int]]) -> int:
    adj = [[] for _ in range(n + 1)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)
    deg = [len(a) for a in adj]

    best = 0
    for c in range(1, n + 1):
        total = 1
        for v in adj[c]:
            if deg[v] >= 2:
                total += deg[v]
        best = max(best, total)
    return n - best

