def count_ball_sets(n: int, positions: List[Tuple[int, int]]) -> int:
    MOD = 998244353
    pts = list(positions)

    def removed_by(k, alive):
        xk, yk = pts[k]
        res = set()
        for i in alive:
            if i == k:
                continue
            xi, yi = pts[i]
            if (xi < xk and yi < yk) or (xi > xk and yi > yk):
                res.add(i)
        return res

    full = frozenset(range(n))
    seen = {full}
    stack = [full]
    while stack:
        cur = stack.pop()
        for k in cur:
            nxt = frozenset(cur - removed_by(k, cur))
            if nxt not in seen:
                seen.add(nxt)
                stack.append(nxt)
    return len(seen) % MOD

