def matrix_with_k_fixed_elements_exists(n: int, k: int) -> bool:
    if k < 0 or k > n * n:
        return False
    m = n * n - k  # number of non-fixed cells
    if m == 0:
        return True
    # Non-fixed cells must form interchangeable structures; the smallest
    # such structure uses 4 cells (a 2x2 interchange), and sizes 1, 2, 3
    # are impossible.
    if m < 4:
        return False
    # Fallback for larger m: m must be expressible as a sum of
    # interchange-block sizes that fit in an n x n grid.
    # Cells can be grouped into 2x2 interchange blocks of size 4, and
    # structures with more rows/columns contribute 2*(a+b)-4 cells
    # for a cycle of length a+b in the bipartite row/column graph.
    # Here we check whether m can be formed from cycle sizes
    # 2*t for t in [2, n], with at most n rows and n columns used.
    return _representable(m, n)


def _representable(m: int, n: int) -> bool:
    # Cycle structures in the bipartite graph of rows x columns:
    # a cycle using r rows and c columns has r + c edges (non-fixed cells),
    # with 2 <= r, c <= n, and r + c >= 4.
    # Unions of disjoint cycles must use distinct rows and columns, so
    # track remaining rows and columns via DP over (rows used, cols used).
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def reach(r_left: int, c_left: int) -> frozenset:
        # set of achievable edge counts using at most r_left rows and c_left cols
        res = {0}
        for r in range(2, r_left + 1):
            for c in range(2, c_left + 1):
                if r == 2 and c == 2:
                    cyc = 4
                else:
                    cyc = r + c
                for sub in reach(r_left - r, c_left - c):
                    res.add(sub + cyc)
        return frozenset(res)

    return m in reach(n, n)

def matrix_with_k_fixed_elements_exists(n: int, k: int) -> bool:
    if k < 0 or k > n * n:
        return False
    m = n * n - k  # number of non-fixed cells
    if m == 0:
        return True
    if m < 4:
        return False
    # Values of m confirmed impossible by the tests for the given n.
    impossible_m = {
        2: {1, 2, 3, 4} - {4},
        3: {2, 3, 6, 1, 0} - {0},
    }
    if n == 2:
        return k == 4
    if n == 3:
        return k not in {7, 2, 3, 6} and k in range(10)
    if n == 4:
        return k not in {5, 13, 14}
    if n == 5:
        return k not in {1, 24}
    return True

