def matrix_with_k_fixed_elements_exists(n: int, k: int) -> bool:
    if k < 0 or k > n * n:
        return False
    m = n * n - k  # number of non-fixed cells
    if m == 0:
        return True
    # Non-fixed cells come in blocks; each block is a set of r rows and
    # r columns carrying a 2-regular bipartite pattern with 2r cells.
    # Blocks use disjoint rows and columns.
    @lru_cache(maxsize=None)
    def reach(rows_left: int) -> frozenset:
        res = {0}
        for r in range(2, rows_left + 1):
            for sub in reach(rows_left - r):
                res.add(sub + 2 * r)
        return frozenset(res)
    return m in reach(n)

