MOD = 10**9 + 7


def count_subsequence_pairs(nums: List[int]) -> int:
    MAXV = 200
    freq = [0] * (MAXV + 1)
    for x in nums:
        freq[x] += 1

    cnt = [0] * (MAXV + 1)
    for d in range(1, MAXV + 1):
        for m in range(d, MAXV + 1, d):
            cnt[d] += freq[m]

    n = len(nums)
    pow2 = [1] * (n + 1)
    pow3 = [1] * (n + 1)
    for i in range(1, n + 1):
        pow2[i] = pow2[i - 1] * 2 % MOD
        pow3[i] = pow3[i - 1] * 3 % MOD

    def A(g: int) -> int:
        c = cnt[g]
        return (pow3[c] - 2 * pow2[c] + 1) % MOD

    mu = [1] * (MAXV + 1)
    is_prime = [True] * (MAXV + 1)
    for p in range(2, MAXV + 1):
        if is_prime[p]:
            for m in range(p, MAXV + 1, p):
                if m > p:
                    is_prime[m] = False
                mu[m] = -mu[m]
            for m in range(p * p, MAXV + 1, p * p):
                mu[m] = 0

    total = 0
    for g in range(1, MAXV + 1):
        e = 0
        for k in range(1, MAXV // g + 1):
            if mu[k] != 0:
                e += mu[k] * A(g * k)
        total = (total + e) % MOD
    return total % MOD

