def count_k_reducible(s: str, k: int) -> int:
    MOD = 10**9 + 7
    L = len(s)

    # steps[m]: number of operations needed to reach 1 starting from m (m >= 1)
    def popcount(x):
        return bin(x).count("1")

    steps = [0] * (L + 2)
    steps[1] = 0
    for m in range(2, L + 2):
        steps[m] = 1 + steps[popcount(m)]

    # Binomial coefficients C[i][j] for i up to L
    C = [[0] * (L + 1) for _ in range(L + 1)]
    for i in range(L + 1):
        C[i][0] = 1
        for j in range(1, i + 1):
            C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % MOD

    # good_pop[c] : whether a number with popcount c is k-reducible (c >= 1)
    # x with popcount c (x >= 2): reducible iff 1 + steps[c] <= k
    # x = 1 (popcount 1): 0 operations, always reducible; handled as x itself
    def reducible_by_popcount(c):
        return 1 + steps[c] <= k

    # Count numbers x in [0, n) with exactly c set bits, using digit DP
    def count_less_with_popcount(c):
        # returns count of x in [0, n) with popcount c
        total = 0
        ones_so_far = 0
        for i, ch in enumerate(s):
            remaining = L - i - 1
            if ch == '1':
                # place 0 here, rest free
                need = c - ones_so_far
                if 0 <= need <= remaining:
                    total += C[remaining][need]
                ones_so_far += 1
        # n itself is excluded (strictly less), so no final addition
        return total % MOD

    ans = 0
    for c in range(1, L + 1):
        cnt = count_less_with_popcount(c)
        if cnt == 0:
            continue
        # x = 0 has popcount 0 and is never counted since c >= 1
        if c == 1:
            # includes x = 1 (0 operations, reducible) and powers of two
            # x = 1 is reducible for any k >= 0; other powers of two need 1 + steps[1] = 1 <= k
            # Powers of two other than 1 reach 1 in exactly 1 operation.
            # x = 1 always counts; the rest count iff k >= 1 (always true, k >= 1)
            ans = (ans + cnt) % MOD
        else:
            if reducible_by_popcount(c):
                ans = (ans + cnt) % MOD

