def count_strings_by_lcs_length(n: int, m: int, s: str) -> List[int]:
    MOD = 998244353
    alphabet = 'abcdefghijklmnopqrstuvwxyz'
    num_states = 1 << n

    # Precompute transitions: trans[mask][ci] -> new mask
    trans = [[0] * 26 for _ in range(num_states)]
    for mask in range(num_states):
        # decode row
        row = [0] * (n + 1)
        for j in range(1, n + 1):
            row[j] = row[j - 1] + ((mask >> (j - 1)) & 1)
