        for i, (a, b) in enumerate(edges):
            if a != u:
                continue
            w = 1 if i in weighted else 0
            if dist[u] + w < dist[b]:
                dist[b] = dist[u] + w
                if w == 0:
                    dq.appendleft(b)
                else:
