def _min_weights_for_distance(n: int, edges: List[Tuple[int, int]], d: int) -> int:
    # Minimum number of edges to weight 1 so that the 0-1 distance 1->n is >= d.
    # Model: vertex (v, L) for L in 0..d. Use min-cut (Dinic-style max flow).
    # Node index: v*(d+1)+L, source/sink appended.
    N = (n + 1) * (d + 1)
    S = N
    T = N + 1
    graph = [[] for _ in range(N + 2)]

    def add(u, v, c):
        graph[u].append([v, c, len(graph[v])])
        graph[v].append([u, 0, len(graph[u]) - 1])

    INF = 10**9
    idx = lambda v, L: v * (d + 1) + L
    # Chain edges per vertex: cutting (v,L)->(v,L+1) means label increases at v.
    for v in range(1, n + 1):
        for L in range(d):
            add(idx(v, L), idx(v, L + 1), INF)  # placeholder, replaced below
    # Rebuild cleanly with the standard vertex-cut construction.
    graph = [[] for _ in range(N + 2)]
    for v in range(1, n + 1):
        for L in range(d):
            add(idx(v, L), idx(v, L + 1), 0)
    for (a, b) in edges:
        # Edge a->b: if label(a)=L and label(b)=L', weight needed = max(0, ...)
        # Weighted edge costs 1 and bumps level by 1; unweighted keeps level.
        for L in range(d + 1):
            if L + 1 <= d:
                add(idx(a, L), idx(b, L + 1), 1)
            add(idx(a, L), idx(b, L), 0)
    add(S, idx(1, 0), INF)
    add(idx(n, d), T, INF)
    # Dinic max flow
    flow = 0
    while True:
        level = [-1] * (N + 2)
        level[S] = 0
        q = deque([S])
        while q:
            u = q.popleft()
            for v, c, _ in graph[u]:
                if c > 0 and level[v] < 0:
                    level[v] = level[u] + 1
                    q.append(v)
        if level[T] < 0:
            break
        it = [0] * (N + 2)

        def dfs(u, f):
            if u == T:
                return f
            while it[u] < len(graph[u]):
                e = graph[u][it[u]]
                v, c, r = e
                if c > 0 and level[v] == level[u] + 1:
                    got = dfs(v, min(f, c))
                    if got > 0:
                        e[1] -= got
                        graph[v][r][1] += got
                        return got
                it[u] += 1
            return 0

        while True:
            f = dfs(S, INF)
            if f == 0:
                break
            flow += f
    return flow


