def determine_winner(n: int, a: List[int]) -> str:
    # Exact game search: state = (remaining counts tuple, claimed mask).
    # The player to move wins if some move leads to a losing position for the opponent.
    # The game ends when all indices are claimed; the player who made the last move wins,
    # so a position with all indices claimed is a loss for the player to move
    # (the previous player made the last move).
    full = (1 << n) - 1

    @lru_cache(maxsize=None)
    def win(counts: tuple, mask: int) -> bool:
        if mask == full:
            return False
        for i in range(n):
            if counts[i] >= 1:
                new_counts = counts[:i] + (counts[i] - 1,) + counts[i + 1:]
                new_mask = mask | (1 << i)
                if not win(new_counts, new_mask):
                    return True
        return False

    return "Fennec" if win(tuple(a), 0) else "Snuke"

