def solve_grid(n: int, r: str, c: str) -> Optional[List[str]]:
    """ Given an integer N and strings R and C of length N consisting of 'A', 'B', and 'C',
    determine if it's possible to fill an N×N grid such that:
    - Each row and column contains exactly one 'A', one 'B', and one 'C'
    - The leftmost character written in the i-th row matches the i-th character of R
    - The topmost character written in the i-th column matches the i-th character of C

    Empty cells are represented by '.' in the output.

    Args:
        n: The size of the grid (3 <= n <= 5)
        r: String of length n specifying leftmost characters in each row
        c: String of length n specifying topmost characters in each column

    Returns:
        A list of n strings representing the filled grid if possible, None otherwise.
        Each string has length n, where '.' represents empty cells.

    >>> solve_grid(3, 'ABC', 'ABC')
    ['ABC', 'BCA', 'CAB']
    >>> solve_grid(3, 'AAA', 'BBB')
    None
    """
    letters = "ABC"
    grid = [['.'] * n for _ in range(n)]

    def first_letter_row(i: int) -> str:
        for j in range(n):
            if grid[i][j] != '.':
                return grid[i][j]
        return '.'

    def first_letter_col(j: int) -> str:
        for i in range(n):
            if grid[i][j] != '.':
                return grid[i][j]
        return '.'

    def row_ok(i: int, full: bool) -> bool:
        row = [grid[i][j] for j in range(n) if grid[i][j] != '.']
        if len(row) != len(set(row)):
            return False
        if full and sorted(row) != ['A', 'B', 'C']:
            return False
        return True

    def col_ok(j: int, full: bool) -> bool:
        col = [grid[i][j] for i in range(n) if grid[i][j] != '.']
        if len(col) != len(set(col)):
            return False
        if full and sorted(col) != ['A', 'B', 'C']:
            return False
        return True

    def prefix_ok() -> bool:
        for i in range(n):
            if first_letter_row(i) not in ('.', r[i]):
                return False
        for j in range(n):
            if first_letter_col(j) not in ('.', c[j]):
                return False
        return True

    cells = [(i, j) for i in range(n) for j in range(n)]

    def backtrack(idx: int) -> bool:
        if idx == len(cells):
            return all(row_ok(i, True) for i in range(n)) and \
                   all(col_ok(j, True) for j in range(n)) and prefix_ok()
        i, j = cells[idx]
        for ch in letters + '.':
            grid[i][j] = ch
            if row_ok(i, False) and col_ok(j, False) and prefix_ok():
                if backtrack(idx + 1):
                    return True
        grid[i][j] = '.'
        return False

    if not backtrack(0):
        return None
    return [''.join(row) for row in grid]

from typing import List, Tuple


def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """ Determine if it's possible to place rectangular tiles on an H×W grid such that:
    - Every cell is covered by exactly one tile
    - Tiles can be rotated (so a 2×3 tile can be placed as 3×2)
    - Some tiles may remain unused
    - Tiles must be aligned with grid cells and cannot extend outside

    Args:
        n: Number of available tiles (1 ≤ n ≤ 7)
        h: Height of the grid (1 ≤ h ≤ 10)
        w: Width of the grid (1 ≤ w ≤ 10)
        tiles: List of (a, b) tuples where tile i has dimensions a×b (1 ≤ a, b ≤ 10)

    Returns:
        True if the grid can be perfectly tiled, False otherwise

    >>> can_tile_grid(5, 5, 5, [(1, 1), (3, 3), (4, 4), (2, 3), (2, 5)])
    True
    >>> can_tile_grid(1, 1, 2, [(2, 3)])
    False
    >>> can_tile_grid(1, 2, 2, [(1, 1)])
    False
    """
    # Quick area feasibility: some subset of tiles must sum to exactly h*w.
    target = h * w
    areas = [a * b for a, b in tiles]

    # Subset-sum over areas to check if any subset matches the grid area.
    reachable = {0}
    for area in areas:
        reachable |= {r + area for r in reachable if r + area <= target}
    if target not in reachable:
        return False

    grid = [[False] * w for _ in range(h)]
    used = [False] * len(tiles)

    def first_empty():
        for r in range(h):
            for c in range(w):
                if not grid[r][c]:
                    return r, c
        return None

    def can_place(r, c, rh, rw):
        if r + rh > h or c + rw > w:
            return False
        for i in range(r, r + rh):
            for j in range(c, c + rw):
                if grid[i][j]:
                    return False
        return True

    def set_cells(r, c, rh, rw, val):
        for i in range(r, r + rh):
            for j in range(c, c + rw):
                grid[i][j] = val

    def backtrack():
        pos = first_empty()
        if pos is None:
            return True
        r, c = pos
        for idx, (a, b) in enumerate(tiles):
            if used[idx]:
                continue
            orientations = {(a, b), (b, a)}
            for rh, rw in orientations:
                if can_place(r, c, rh, rw):
                    set_cells(r, c, rh, rw, True)
                    used[idx] = True
                    if backtrack():
                        return True
                    used[idx] = False
                    set_cells(r, c, rh, rw, False)
        return False

    return backtrack()

def count_power_representations(n: int) -> int:
    def iroot(x: int, k: int) -> int:
        # largest r such that r**k <= x
        if x < 2:
            return x
        r = int(round(x ** (1.0 / k)))
        # adjust for floating point error
        while r > 0 and r ** k > x:
            r -= 1
        while (r + 1) ** k <= x:
            r += 1
        return r

    def mobius(m: int) -> int:
        result = 1
        d = 2
        mm = m
        while d * d <= mm:
            if mm % d == 0:
                mm //= d
                if mm % d == 0:
                    return 0
                result = -result
            d += 1
        if mm > 1:
            result = -result
        return result

    if n < 1:
        return 0
    # Count distinct perfect powers in [2, n] via inclusion-exclusion
    total = 0
    for b in range(2, n.bit_length() + 2):
        mu = mobius(b)
        if mu == 0:
            continue
        total += -mu * (iroot(n, b) - 1)
    # Add 1 (since 1 = 1^2 is representable)
    return total + 1

