def find_palindrome_expression(n: int) -> str:
    """ Find a palindrome string S that represents a mathematical expression evaluating to n.

    The string must satisfy:
    - Length between 1 and 1000 characters
    - Consists only of digits 1-9 and the multiplication symbol '*'
    - Is a palindrome (reads the same forwards and backwards)
    - First character must be a digit
    - When evaluated as a mathematical expression, equals n

    Args:
        n: An integer between 1 and 10^12

    Returns:
        A palindrome string representing an expression that evaluates to n,
        or '-1' if no such string exists.
    """
    def is_pal(s):
        return s == s[::-1]

    def valid_digits(x):
        return '0' not in str(x)

    def palindromic_divisors(x):
        res = set()
        d = 1
        while d * d <= x:
            if x % d == 0:
                for c in (d, x // d):
                    if valid_digits(c) and is_pal(str(c)):
                        res.add(c)
            d += 1
        return sorted(res)

    # Single number palindrome
    if valid_digits(n) and is_pal(str(n)):
        return str(n)

    @lru_cache(maxsize=None)
    def build(x):
        # Returns a tuple of palindromic factors a1..ak such that
        # product(ai)^2 == x, or None if impossible.
        if x == 1:
            return ()
        # x must be a perfect square for pure mirrored construction
        r = int(round(x ** 0.5))
        if r * r != x:
            return None
        # Find a factorization of r into palindromic factors (digits 1-9)
        seq = factor_into_palindromes(r)
        return seq

    @lru_cache(maxsize=None)
    def factor_into_palindromes(x):
        # Returns a tuple of palindromic factors (each > 1) whose product is x, or None
        if x == 1:
            return ()
        for c in palindromic_divisors(x):
            if c == 1:
                continue
            sub = factor_into_palindromes(x // c)
            if sub is not None:
                return (c,) + sub
        return None

    # Option 1: n = (prod ai)^2 with no middle factor
    seq = build(n)
    if seq is not None and len(seq) > 0:
        left = [str(a) for a in seq]
        expr = '*'.join(left + list(reversed(left)))
        if len(expr) <= 1000 and is_pal(expr):
            return expr

    # Option 2: n = m * (prod ai)^2 with palindromic middle factor m
    for m in palindromic_divisors(n):
        if m == 1:
            continue
        rest = n // m
        seq = build(rest)
        if seq is not None:
            left = [str(a) for a in seq]
            if left:
                expr = '*'.join(left + [str(m)] + list(reversed(left)))
            else:
                expr = str(m)
            if len(expr) <= 1000 and is_pal(expr):
                return expr

    return '-1'

