def min_sensor_cost(n: int, sections: List[int], sensor1: Tuple[int, int, int], sensor2: Tuple[int, int, int]) -> int:
    L1, C1, K1 = sensor1
    L2, C2, K2 = sensor2
    INF = float('inf')

    # dp maps (used1, used2) -> minimal cost
    dp = {(0, 0): 0}

    for D in sections:
        # Precompute options for this section: (a, b) pairs that cover D
        options = []
        max_a = -(-D // L1)  # ceil(D / L1)
        for a in range(0, max_a + 1):
            if a > K1:
                break
            remaining = D - a * L1
            b = 0 if remaining <= 0 else -(-remaining // L2)
            options.append((a, b, a * C1 + b * C2))

        # Keep only Pareto-optimal options (fewer a and fewer b with lower cost)
        # Simple pruning: remove options dominated in (a, b) with cost >= another
        new_dp = {}
        for (u1, u2), cost in dp.items():
            for a, b, c in options:
                n1 = u1 + a
                n2 = u2 + b
                if n1 > K1 or n2 > K2:
                    continue
                nc = cost + c
                key = (n1, n2)
                if nc < new_dp.get(key, INF):
                    new_dp[key] = nc
        dp = new_dp
        if not dp:
            return -1

    if not dp:
        return -1
    return min(dp.values())

