from itertools import permutations


def min_operations_to_match_grids(H: int, W: int, A: List[List[int]], B: List[List[int]]) -> Optional[int]:
    def inversions(perm):
        n = len(perm)
        count = 0
        for i in range(n):
            for j in range(i + 1, n):
                if perm[i] > perm[j]:
                    count += 1
        return count

    best = None
    row_perms = list(permutations(range(H)))
    col_perms = list(permutations(range(W)))

    for rp in row_perms:
        rc = inversions(rp)
        for cp in col_perms:
            cost = rc + inversions(cp)
            if best is not None and cost >= best:
                continue
            ok = True
            for i in range(H):
                ai = A[rp[i]]
                bi = B[i]
                for j in range(W):
                    if ai[cp[j]] != bi[j]:
                        ok = False
                        break
                if not ok:
                    break
            if ok:
                best = cost
    return best

