def sum_of_subsequence_powers(nums: List[int], k: int) -> int:
    MOD = 10**9 + 7
    n = len(nums)

    # dp[s][c] = number of subsets with sum s (capped at k) and size c
    dp = [[0] * (n + 1) for _ in range(k + 1)]
    dp[0][0] = 1

    for x in nums:
        # iterate sums downward so each element is used at most once
        for s in range(k, x - 1, -1):
            row_prev = dp[s - x]
            row_cur = dp[s]
            for c in range(n, 0, -1):
                if row_prev[c - 1]:
                    row_cur[c] = (row_cur[c] + row_prev[c - 1]) % MOD

    pow2 = [1] * (n + 1)
    for i in range(1, n + 1):
        pow2[i] = pow2[i - 1] * 2 % MOD

    result = 0
    for c in range(n + 1):
        if dp[k][c]:
            result = (result + dp[k][c] * pow2[n - c]) % MOD
    return result

def count_good_strings(n: int, k: int, s: str) -> int:
    MOD = 998244353
    m = k - 1  # number of trailing characters to remember

    # Normalize the pattern to exactly length n; missing positions are free ('?').
    if len(s) < n:
        s = s + '?' * (n - len(s))

    def is_pal(mask: int, length: int) -> bool:
        for i in range(length // 2):
            if ((mask >> i) & 1) != ((mask >> (length - 1 - i)) & 1):
                return False
        return True

    dp = {0: 1}
    cur_len = 0  # characters currently in the window, capped at m

    for i in range(n):
        ch = s[i]
        if ch == 'A':
            choices = (0,)
        elif ch == 'B':
            choices = (1,)
        else:
            choices = (0, 1)

        ndp = {}
        for mask, cnt in dp.items():
            for c in choices:
                full_len = cur_len + 1
                new_full = (mask << 1) | c
                if full_len >= k:
                    window = new_full & ((1 << k) - 1)
                    if is_pal(window, k):
                        continue
                new_mask = new_full & ((1 << m) - 1) if m > 0 else 0
                ndp[new_mask] = (ndp.get(new_mask, 0) + cnt) % MOD
        dp = ndp
        cur_len = min(cur_len + 1, m)

    return sum(dp.values()) % MOD

