def count_arithmetic_subsequences(n: int, a: List[int]) -> List[int]:
    MOD = 998244353
    res = [0] * n
    res[0] = n % MOD
    if n == 1:
        return res

    # dp[i][j][length]: number of arithmetic subsequences of given length
    # whose last two indices are j < i (in that order).
    dp = [[[0] * (n + 1) for _ in range(n)] for _ in range(n)]
    for i in range(n):
        for j in range(i):
            dp[i][j][2] = 1

    for i in range(n):
        for j in range(i):
            diff = a[i] - a[j]
            for l in range(i + 1, n):
                if a[l] - a[i] == diff:
                    for length in range(2, n):
                        v = dp[i][j][length]
                        if v:
                            dp[l][i][length + 1] = (dp[l][i][length + 1] + v) % MOD

    for i in range(n):
        for j in range(i):
            for length in range(2, n + 1):
                v = dp[i][j][length]
                if v:
                    res[length - 1] = (res[length - 1] + v) % MOD

    return res

