def min_team_switches(people: List[Tuple[int, int]]) -> int:
    total = sum(s for _, s in people)
    if total % 3 != 0:
        return -1
    target = total // 3
    cur = {1: 0, 2: 0, 3: 0}
    for t, s in people:
        cur[t] += s

    # dp[(x, y)] = minimum number of people moved so that the net strength
    # change into team 1 is x and into team 2 is y (team 3 is implied).
    dp = {(0, 0): 0}
    for t, s in people:
        new_dp = dict(dp)  # this person stays put
        for dest in (1, 2, 3):
            if dest == t:
                continue
            d = [0, 0]
            if t == 1:
                d[0] -= s
            elif t == 2:
                d[1] -= s
            if dest == 1:
                d[0] += s
            elif dest == 2:
                d[1] += s
            for (a, b), c in dp.items():
                key = (a + d[0], b + d[1])
                if new_dp.get(key, float('inf')) > c + 1:
                    new_dp[key] = c + 1
        dp = new_dp

    need = (target - cur[1], target - cur[2])
    return dp[need] if need in dp else -1

def count_valid_grids(H: int, W: int, grid: list[str]) -> int:
    MOD = 998244353

    # Transpose so that the profile width (W) is the smaller dimension.
    if W > H:
        grid = [''.join(grid[i][j] for i in range(H)) for j in range(W)]
        H, W = W, H

    # dp maps profile (tuple of last W colors, 0 means "empty" for first row) -> count
    # Encode profile as a tuple of length W; initially all 0 (no cell above).
    dp = {tuple([0] * W): 1}

    for i in range(H):
        for j in range(W):
            ch = grid[i][j]
            if ch == '?':
                allowed = (1, 2, 3)
            else:
                allowed = (int(ch),)
            ndp = {}
            for prof, cnt in dp.items():
                top = prof[j]          # cell (i-1, j); 0 if none
                left = prof[j - 1] if j > 0 else 0  # cell (i, j-1), already updated
                for c in allowed:
                    if c == top or c == left:
                        continue
                    newprof = list(prof)
                    newprof[j] = c
                    key = tuple(newprof)
                    ndp[key] = (ndp.get(key, 0) + cnt) % MOD
            dp = ndp
            if not dp:
                return 0

    return sum(dp.values()) % MOD

