from functools import lru_cache

def card_game_winner(n: int, m: int, l: int, takahashi_cards: List[int], aoki_cards: List[int], table_cards: List[int]) -> str:
    @lru_cache(maxsize=None)
    def mover_wins(my_hand: Tuple[int, ...], other_hand: Tuple[int, ...], table: Tuple[int, ...]) -> bool:
        # Returns True if the player to move (holding my_hand) wins.
        for i, card in enumerate(my_hand):
            new_my = my_hand[:i] + my_hand[i+1:]
            new_table = tuple(sorted(table + (card,)))
            # Option 1: play without taking
            if not mover_wins(other_hand, new_my, new_table):
                return True
            # Option 2: play and take a smaller table card
            for j, t in enumerate(new_table):
                if t < card:
                    taken_table = new_table[:j] + new_table[j+1:]
                    taken_hand = tuple(sorted(new_my + (t,)))
                    if not mover_wins(other_hand, taken_hand, taken_table):
                        return True
        return False

    first_wins = mover_wins(tuple(sorted(takahashi_cards)), tuple(sorted(aoki_cards)), tuple(sorted(table_cards)))
    return "Takahashi" if first_wins else "Aoki"

from itertools import product

MOD = 998244353


def count_sequences_without_subsequence(N: int, M: int, K: int, X: list[int]) -> int:
    X = tuple(X)
    letters = range(1, K + 1)
    all_words = list(product(letters, repeat=M))

    def contains(seq, w):
        it = iter(seq)
        return all(c in it for c in w)

    count = 0
    for seq in product(letters, repeat=N):
        missing = [w for w in all_words if not contains(seq, w)]
        if len(missing) == 1 and missing[0] == X:
            count += 1
    return count % MOD

def count_bob_winning_sequences(s: str) -> int:
    MOD = 10**9 + 7
    beats = {'F': 'E', 'W': 'F', 'E': 'W'}  # key beats value
    creatures = ['F', 'W', 'E']

    # state: (previous Bob creature or None, score difference Bob - Alice) -> count
    dp = {(None, 0): 1}
    for a in s:
        ndp = {}
        for (last, diff), cnt in dp.items():
            for b in creatures:
                if b == last:
                    continue
                nd = diff
                if beats[b] == a:
                    nd += 1
                elif beats[a] == b:
                    nd -= 1
                key = (b, nd)
                ndp[key] = (ndp.get(key, 0) + cnt) % MOD
        dp = ndp

    total = 0
    for (last, diff), cnt in dp.items():
        if diff > 0:
            total = (total + cnt) % MOD
    return total

def count_k_reducible(s: str, k: int) -> int:
    MOD = 10**9 + 7
    L = len(s)

    # steps[m]: number of operations needed to reach 1 starting from m (m >= 1)
    def popcount(x):
        return bin(x).count("1")

    steps = [0] * (L + 2)
    steps[1] = 0
    for m in range(2, L + 2):
        steps[m] = 1 + steps[popcount(m)]

    # Binomial coefficients C[i][j] for i up to L
    C = [[0] * (L + 1) for _ in range(L + 1)]
    for i in range(L + 1):
        C[i][0] = 1
        for j in range(1, i + 1):
            C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % MOD

    # good_pop[c] : whether a number with popcount c is k-reducible (c >= 1)
    # x with popcount c (x >= 2): reducible iff 1 + steps[c] <= k
    # x = 1 (popcount 1): 0 operations, always reducible; handled as x itself
    def reducible_by_popcount(c):
        return 1 + steps[c] <= k

    # Count numbers x in [0, n) with exactly c set bits, using digit DP
    def count_less_with_popcount(c):
        # returns count of x in [0, n) with popcount c
        total = 0
        ones_so_far = 0
        for i, ch in enumerate(s):
            remaining = L - i - 1
            if ch == '1':
                # place 0 here, rest free
                need = c - ones_so_far
                if 0 <= need <= remaining:
                    total += C[remaining][need]
                ones_so_far += 1
        # n itself is excluded (strictly less), so no final addition
        return total % MOD

    ans = 0
    for c in range(1, L + 1):
        cnt = count_less_with_popcount(c)
        if cnt == 0:
            continue
        # x = 0 has popcount 0 and is never counted since c >= 1
        if c == 1:
            # includes x = 1 (0 operations, reducible) and powers of two
            # x = 1 is reducible for any k >= 0; other powers of two need 1 + steps[1] = 1 <= k
            # Powers of two other than 1 reach 1 in exactly 1 operation.
            # x = 1 always counts; the rest count iff k >= 1 (always true, k >= 1)
            ans = (ans + cnt) % MOD
        else:
            if reducible_by_popcount(c):
                ans = (ans + cnt) % MOD

    # Positive integers only: x = 0 has popcount 0, never counted. Good.
    return ans % MOD

from math import comb, factorial

def count_balanced_graphs(n: int, p: int) -> list[int]:
    half = n // 2
    max_m = n * (n - 1) // 2

    def compositions(remaining):
        if remaining == 0:
            yield []
            return
        for first in range(1, remaining + 1):
            for rest in compositions(remaining - first):
                yield [first] + rest

    def mul(p1, p2):
        res = [0] * (len(p1) + len(p2) - 1)
        for i, x in enumerate(p1):
            if x:
                for j, y in enumerate(p2):
                    if y:
                        res[i + j] += x * y
        return res

    def layer_polynomial(sizes):
        poly = [1]
        # free intra-layer edges
        for s in sizes:
            k = comb(s, 2)
            poly = mul(poly, [comb(k, t) for t in range(k + 1)])
        # cross edges: every vertex in layer k needs >=1 neighbor in layer k-1
        for k in range(1, len(sizes)):
            a, b = sizes[k - 1], sizes[k]
            cross = [0] * (a * b + 1)
            for j in range(b + 1):
                sign = -1 if j % 2 else 1
                avail = (b - j) * a
                for t in range(avail + 1):
                    cross[t] += sign * comb(b, j) * comb(avail, t)
            poly = mul(poly, cross)
        return poly

    total = [0] * (max_m + 1)
    for rest in compositions(n - 1):
        sizes = [1] + rest
        even_count = sum(sizes[0::2])
        if even_count != half:
            continue
        # labeled assignment: vertex 1 fixed in layer 0; distribute vertices 2..n
        ways = factorial(n - 1)
        for s in rest:
            ways //= factorial(s)
        ways //= factorial(sizes[0] - 1) if sizes[0] > 1 else 1
        poly = layer_polynomial(sizes)
        for e, c in enumerate(poly):
            if e <= max_m and c:
                total[e] += c * ways

    return [total[m] % p for m in range(n - 1, max_m + 1)]

