def count_strings_by_lcs_length(n: int, m: int, s: str) -> List[int]:
    MOD = 998244353
    alphabet = 'abcdefghijklmnopqrstuvwxyz'
    num_states = 1 << n

    # Precompute transitions: trans[mask][ci] -> new mask
    trans = [[0] * 26 for _ in range(num_states)]
    for mask in range(num_states):
        # decode row
        row = [0] * (n + 1)
        for j in range(1, n + 1):
            row[j] = row[j - 1] + ((mask >> (j - 1)) & 1)
        for ci, c in enumerate(alphabet):
            new = [0] * (n + 1)
            for j in range(1, n + 1):
                if s[j - 1] == c:
                    new[j] = row[j - 1] + 1
                else:
                    new[j] = max(row[j], new[j - 1])
            nmask = 0
            for j in range(1, n + 1):
                if new[j] - new[j - 1] == 1:
                    nmask |= 1 << (j - 1)
            trans[mask][ci] = nmask

    dp = [0] * num_states
    dp[0] = 1  # initial row is all zeros -> mask 0
    for _ in range(m):
        ndp = [0] * num_states
        for mask in range(num_states):
            cnt = dp[mask]
            if cnt == 0:
                continue
            tm = trans[mask]
            for ci in range(26):
                nm = tm[ci]
                ndp[nm] = (ndp[nm] + cnt) % MOD
        dp = ndp

    res = [0] * (n + 1)
    for mask in range(num_states):
        cnt = dp[mask]
        if cnt:
            k = bin(mask).count('1')
            res[k] = (res[k] + cnt) % MOD
    return res

