def max_alkane_vertices(n: int, edges: List[Tuple[int, int]]) -> int:
    if n < 5:
        return -1
    adj = [[] for _ in range(n + 1)]
    for a, b in edges:
        adj[a].append(b)
        adj[b].append(a)

    NEG = float("-inf")

    # Root the tree at 1 to get a traversal order.
    parent = [0] * (n + 1)
    order = []
    visited = [False] * (n + 1)
    stack = [1]
    visited[1] = True
    while stack:
        v = stack.pop()
        order.append(v)
        for u in adj[v]:
            if not visited[u]:
                visited[u] = True
                parent[u] = v
                stack.append(u)

    # down[v]: best contribution of the branch consisting of v and its subtree
    # (rooted at 1), where v is entered from its parent.
    # Contribution is 1 if v is a leaf of the alkane; otherwise 1 + top-3 children.
    def branch_value(child_contribs):
        # child_contribs: list of contributions of available neighbors (excluding parent)
        # v as a leaf gives 1; v as internal (degree 4 incl. parent) needs 3 children.
        best = 1
        if len(child_contribs) >= 3:
            s = sorted(child_contribs, reverse=True)
            best = max(best, 1 + sum(s[:3]))
        return best

    down = [1] * (n + 1)
    for v in reversed(order):
        contribs = [down[u] for u in adj[v] if u != parent[v]]
        down[v] = branch_value(contribs)

    # up[v]: best contribution of the branch containing parent[v] when viewed from v
    # (i.e., the component reached through the edge v - parent[v], with parent[v] entered).
    up = [1] * (n + 1)
    best_answer = -1
    for v in order:
        # All neighbor contributions of v: children use down, parent uses up[v].
        neighbor_contribs = []
        for u in adj[v]:
            if u == parent[v]:
                neighbor_contribs.append(up[v])
            else:
                neighbor_contribs.append(down[u])

        # v as the root of the alkane: degree 4, takes exactly 4 neighbors.
        if len(neighbor_contribs) >= 4:
            s = sorted(neighbor_contribs, reverse=True)
            total = 1 + sum(s[:4])
            if total > best_answer:
                best_answer = total

        # Compute up[u] for each child u of v: branch containing v viewed from u.
        for u in adj[v]:
            if u == parent[v]:
                continue
            others = []
            for w in adj[v]:
                if w == u:
                    continue
                if w == parent[v]:
                    others.append(up[v])
                else:
                    others.append(down[w])
            up[u] = branch_value(others)

    return best_answer

