from collections import deque


def _dist(n: int, edges: List[Tuple[int, int]], weighted: frozenset) -> int:
    INF = 10**9
    dist = [INF] * (n + 1)
    dist[1] = 0
    dq = deque([1])
    while dq:
        u = dq.popleft()
        for i, (a, b) in enumerate(edges):
            if a != u:
                continue
            w = 1 if i in weighted else 0
            if dist[u] + w < dist[b]:
                dist[b] = dist[u] + w
                if w == 0:
                    dq.appendleft(b)
                else:
                    dq.append(b)
    return dist[n] if dist[n] < INF else 0


def max_shortest_distance(n: int, m: int, k: int, edges: List[Tuple[int, int]]) -> int:
    # Greedy hill-climb with restarts: the objective is monotone in the
    # weighted set, so we repeatedly add the single edge that increases
    # the distance the most (ties broken by a secondary count of
    # shortest-path edges). This is a heuristic, not a proof of optimality.
    best = 0
    for start in range(m):
        chosen = frozenset([start])
        while len(chosen) < k:
            cur = _dist(n, edges, chosen)
            cand_best, cand_val = None, -1
            for i in range(m):
                if i in chosen:
                    continue
                val = _dist(n, edges, chosen | {i})
                if val > cand_val:
                    cand_best, cand_val = i, val
            chosen = chosen | {cand_best}
        best = max(best, _dist(n, edges, chosen))
    return best

MOD = 998244353

def count_paths(W: int, H: int, L: int, R: int, D: int, U: int) -> int:
    def is_block(x, y):
        return 0 <= x <= W and 0 <= y <= H and (x < L or x > R or y < D or y > U)

    f = [[0] * (H + 2) for _ in range(W + 2)]
    total = 0
    for x in range(W, -1, -1):
        for y in range(H, -1, -1):
            if not is_block(x, y):
                continue
            val = 1
            if is_block(x + 1, y):
                val += f[x + 1][y]
            if is_block(x, y + 1):
                val += f[x][y + 1]
            val %= MOD
            f[x][y] = val
            total = (total + val) % MOD
    return total

def count_in_degree_sequences(n: int, s: str) -> int:
    MOD = 998244353
    edges = []
    for i in range(n):
        edges.append((i, (i + 1) % n))
    for i in range(n):
        if s[i] == '1':
            edges.append((i, n))
    m = len(edges)
    V = n + 1

    seen = set()
    for mask in range(1 << m):
        indeg = [0] * V
        for j, (u, v) in enumerate(edges):
            if (mask >> j) & 1:
                indeg[v] += 1
            else:
                indeg[u] += 1
        seen.add(tuple(indeg))
    return len(seen) % MOD

from collections import deque

def can_transform_string(n: int, x: int, y: int, s: str, t: str) -> bool:
    """ Given two binary strings s and t of length n, and two positive integers x and y,
    determine if s can be transformed into t by repeatedly performing the following operations
    in any order:

    Operation A: Find x consecutive 0s followed by y consecutive 1s, then swap them
    Operation B: Find y consecutive 1s followed by x consecutive 0s, then swap them

    Returns:
        True if s can be transformed into t, False otherwise
    """
    if s.count('0') != t.count('0'):
        return False
    if s == t:
        return True

    def neighbors(cur):
        result = []
        # Operation A: 0^x 1^y -> 1^y 0^x
        pat_a = '0' * x + '1' * y
        rep_a = '1' * y + '0' * x
        # Operation B: 1^y 0^x -> 0^x 1^y
        pat_b = '1' * y + '0' * x
        rep_b = '0' * x + '1' * y
        L = len(pat_a)
        for i in range(n - L + 1):
            if cur[i:i + L] == pat_a:
                result.append(cur[:i] + rep_a + cur[i + L:])
            if cur[i:i + L] == pat_b:
                result.append(cur[:i] + rep_b + cur[i + L:])
        return result

    seen = {s}
    queue = deque([s])
    while queue:
        cur = queue.popleft()
        for nxt in neighbors(cur):
            if nxt == t:
                return True
            if nxt not in seen:
                seen.add(nxt)
                queue.append(nxt)
    return False

def count_powerful_integers(start: int, finish: int, limit: int, s: str) -> int:
    from functools import lru_cache

    L = len(s)
    suffix = int(s)
    # Every digit of s must be <= limit, otherwise no powerful integer exists
    if any(int(c) > limit for c in s):
        return 0

    power = 10 ** L
    # x = p * power + suffix, p >= 0. Need start <= x <= finish.
    # p >= ceil((start - suffix) / power), p <= floor((finish - suffix) / power)
    lo_num = start - suffix
    if lo_num <= 0:
        lo = 0
    else:
        lo = (lo_num + power - 1) // power
    hi_num = finish - suffix
    if hi_num < 0:
        return 0
    hi = hi_num // power

    if lo > hi:
        return 0

    def count_upto(n: int) -> int:
        """Count integers p in [0, n] whose digits are all <= limit."""
        if n < 0:
            return 0
        digits = list(map(int, str(n)))
        m = len(digits)

        @lru_cache(maxsize=None)
        def dp(pos: int, tight: bool, started: bool) -> int:
            if pos == m:
                # started=False means the number is 0, which is valid (p = 0)
                return 1
            upper = digits[pos] if tight else 9
            total = 0
            for d in range(0, upper + 1):
                if d > limit:
                    break
                new_tight = tight and (d == upper)
                new_started = started or (d != 0)
                total += dp(pos + 1, new_tight, new_started)
            return total

        result = dp(0, True, False)
        dp.cache_clear()
        return result

    return count_upto(hi) - count_upto(lo - 1)

