from fractions import Fraction

def calculate_black_area_doubled(A: int, B: int, C: int, D: int) -> int:
    # Brute-force reference: decide the color of each unit cell by flood-fill from
    # the reference point (0.5, 0.5), crossing lines x=n, y=even, x+y=even.
    # Each unit cell is split by the diagonal if it is cut, so we sample
    # the two halves at off-line points and classify them by crossing parity.
    def crossings(p, q):
        # number of boundary lines strictly crossed on the segment p->q (generic endpoints)
        (x0, y0), (x1, y1) = p, q
        n = 0
        lo, hi = sorted([x0, x1])
        n += int(hi // 1) - int(lo // 1)
        lo, hi = sorted([y0, y1])
        n += int(hi // 2) - int(lo // 2)
        lo, hi = sorted([x0 + y0, x1 + y1])
        n += int(hi // 2) - int(lo // 2)
        return n

    def black(p):
        return crossings((Fraction(1, 2), Fraction(1, 2)), p) % 2 == 0

    total = 0
    for i in range(A, C):
        for j in range(B, D):
            if (i + j + 1) % 2 == 0:
                # the cell is cut by x+y = i+j+1
                for off in (Fraction(1, 5), Fraction(4, 5)):
                    if black((i + off, j + off)):
                        total += 1
            else:
                if black((i + Fraction(1, 2), j + Fraction(1, 2))):
                    total += 2
    return total

