from collections import deque

def min_operations_to_rearrange(n: int, s: str, t: str) -> int:
    # State: tuple of length n+2; 'B'/'W' for stones, '.' for empty cells.
    # Initially stones occupy cells 0..n-1 and cells n, n+1 are empty.
    start = tuple(list(s) + ['.', '.'])

    # Target: the first n cells read as t, with the two empty cells at the end.
    # Because empties can end up anywhere, we match on the stone sequence only.
    def stone_sequence(state):
        return ''.join(c for c in state if c != '.')

    if stone_sequence(start) == t and start[n:] == ('.', '.'):
        return 0

    dist = {start: 0}
    queue = deque([start])
    while queue:
        state = queue.popleft()
        d = dist[state]
        for i in range(n + 1):
            a, b = state[i], state[i + 1]
            if a == '.' or b == '.':
                continue
            # Remove the adjacent pair, then place it in the two empty cells.
            rest = list(state[:i]) + ['.', '.'] + list(state[i + 2:])
            # Find the two empty slots after removing the pair and append the pair there.
            new_list = [c for k, c in enumerate(state) if k not in (i, i + 1)]
            new_list = new_list + [a, b]
            # Normalize: blanks are the '.' markers, pair is now at the end.
            new_state = tuple(new_list)
            if new_state not in dist:
                dist[new_state] = d + 1
                if stone_sequence(new_state) == t and new_state[n:] == (a, b) or stone_sequence(new_state) == t:
                    # Stone sequence matches target; check the final arrangement is reachable.
                    pass
                queue.append(new_state)

    best = -1
    for state, d in dist.items():
        if stone_sequence(state) == t:
            if best == -1 or d < best:
                best = d
    return best

