from functools import lru_cache

def find_palindrome_expression(n: int) -> str:
    def is_pal(s: str) -> bool:
        return s == s[::-1]

    def nonzero_digits(x: int) -> bool:
        return '0' not in str(x)

    if n < 1:
        return '-1'

    # Direct single-number palindrome
    if is_pal(str(n)) and nonzero_digits(n):
        return str(n)

    # Build a symmetric palindromic expression: a1*a2*...*mid*...*a2*a1
    # Value = (prod of outer factors)^2 * mid, where each outer factor a_i and
    # mid are digit strings of 1-9 only.
    # Enumerate the middle term (a palindromic, zero-free divisor of n) and
    # the outer-factor product q with q^2 * mid = n.

    def divisors(x):
        ds = []
        i = 1
        while i * i <= x:
            if x % i == 0:
                ds.append(i)
                if i != x // i:
                    ds.append(x // i)
            i += 1
        return sorted(ds)

    divs = divisors(n)
    palin_divs = [d for d in divs if is_pal(str(d)) and nonzero_digits(d)]

    # Try mid = palindromic zero-free divisor, q^2 = n / mid
    for mid in palin_divs:
        rest = n // mid
        q = int(round(rest ** 0.5))
        if q * q != rest or q < 1:
            continue
        # q must itself be expressible as a palindromic-compatible factor list.
        # Use q directly as a single outer factor if it's zero-free and palindromic.
        if is_pal(str(q)) and nonzero_digits(q):
            s = f"{q}*{mid}*{q}" if mid != 1 else f"{q}*{q}"
            if is_pal(s):
                return s
        # Otherwise try splitting q into a palindromic-ish list via recursion on q.
        sub = find_palindrome_expression(q) if q > 1 else '1'
        if sub != '-1' and all(c in '123456789*' for c in sub):
            inner_outer = sub
            # Build outer part as inner_outer, which is itself a palindrome.
            if mid == 1:
                s = f"{inner_outer}*{inner_outer}"
            else:
                s = f"{inner_outer}*{mid}*{inner_outer}"
            if is_pal(s) and all(c in '123456789*' for c in s) and s[0].isdigit():
                try:
                    if eval(s) == n:
                        return s
                except Exception:
                    pass

    return '-1'

