def count_good_sequences(N: int, M: int) -> int:
    from math import comb

    def sigma_mod3(n: int) -> int:
        res = 1
        x = n
        p = 2
        while p * p <= x:
            if x % p == 0:
                s = 1
                pk = 1
                while x % p == 0:
                    x //= p
                    pk *= p
                    s += pk
                res = res * (s % 3) % 3
            p += 1
        if x > 1:
            res = res * ((1 + x) % 3) % 3
        return res

    def ordered_count(n: int) -> int:
        res = 1
        x = n
        p = 2
        while p * p <= x:
            if x % p == 0:
                e = 0
                while x % p == 0:
                    x //= p
                    e += 1
                res = res * comb(e + M - 1, M - 1) % MOD
            p += 1
        if x > 1:
            res = res * M % MOD
        return res

    total = 0
    for n in range(1, N + 1):
        if sigma_mod3(n) == 0:
            total = (total + ordered_count(n)) % MOD
    return total

