def _lis(seq):
    # Length of longest strictly increasing subsequence
    tails = []
    import bisect
    for x in seq:
        i = bisect.bisect_left(tails, x)
        if i == len(tails):
            tails.append(x)
        else:
            tails[i] = x
    return len(tails)

def _lds(seq):
    return _lis([-x for x in seq])

def count_special_permutations(A: int, B: int, M: int) -> int:
    N = A * B - 1
    count = 0
    for P in permutations(range(1, N + 1)):
        P = list(P)
        if _lis(P) != A or _lds(P) != B:
            continue
        # Condition 3: there exists n such that appending n+0.5 keeps LIS and LDS.
        # Values of n+0.5 range over 0.5, 1.5, ..., N+0.5; use n in 0..N.
        ok = False
        for n in range(0, N + 1):
            Q = P + [n + 0.5]
            if _lis(Q) == A and _lds(Q) == B:
                ok = True
                break
        if ok:
            count += 1
    return count % M

