def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    def tile_of(px, py):
        # Find the tile (type, i, j, k) that contains the point (px + 0.5, py + 0.5).
        # Candidate (i, j) pairs: tile index is roughly floor(px / K), floor(py / K).
        # Search a small neighborhood to find the tile containing the point.
        x = px + 0.5
        y = py + 0.5
        for i in range(x // K - 2, x // K + 3):
            for j in range(y // K - 2, y // K + 3):
                for k in range(K):
                    if (i - j) % 2 == 0:
                        # same parity: iK <= x <= (i+1)K and jK+k <= y <= jK+k+1
                        if i * K <= x <= (i + 1) * K and j * K + k <= y <= j * K + k + 1:
                            return (i, j, k)
                    else:
                        # different parity: iK+k <= x <= iK+k+1 and jK <= y <= (j+1)K
                        if i * K + k <= x <= i * K + k + 1 and j * K <= y <= (j + 1) * K:
                            return (i, j, k)
        raise ValueError("no tile found")

    def neighbors(tile):
        i, j, k = tile
        result = []
        for di in range(-2, 3):
            for dj in range(-2, 3):
                for dk in range(K):
                    cand = (i + di, j + dj, dk)
                    if cand == tile:
                        continue
                    if tiles_adjacent(tile, cand):
                        result.append(cand)
        return result

    def tiles_adjacent(a, b):
        # Two tiles are adjacent if their edges share a positive-length segment.
        # Check numerically on the boundary using a small sample of the shared edge.
        def bounds(t):
            i, j, k = t
            if (i - j) % 2 == 0:
                return (i * K, (i + 1) * K, j * K + k, j * K + k + 1)
            else:
                return (i * K + k, i * K + k + 1, j * K, (j + 1) * K)
        ax0, ax1, ay0, ay1 = bounds(a)
        bx0, bx1, by0, by1 = bounds(b)
        # Overlap along x and y (touching edges allowed, but need positive-length shared segment).
        ox = min(ax1, bx1) - max(ax0, bx0)
        oy = min(ay1, by1) - max(ay0, by0)
        touch_x = (ax1 == bx0 or bx1 == ax0) and oy > 0
        touch_y = (ay1 == by0 or by1 == ay0) and ox > 0
        return touch_x or touch_y

    start = tile_of(S_x, S_y)
    target = tile_of(T_x, T_y)
    if start == target:
        return 0
    seen = {start: 0}
    q = deque([start])
    while q:
        cur = q.popleft()
        for nb in neighbors(cur):
            if nb not in seen:
                seen[nb] = seen[cur] + 1
                if nb == target:
                    return seen[nb]
                q.append(nb)
    return -1

