        if (i - j) % 2 == 0:
            x0, x1 = i * K, (i + 1) * K
            y0, y1 = j * K + k, j * K + k + 1
        else:
            x0, x1 = i * K + k, i * K + k + 1
            y0, y1 = j * K, (j + 1) * K
        return 2 * x0, 2 * x1, 2 * y0, 2 * y1

