def expected_operations(N: int, M: int) -> int:
    # Exact expected cover time via a linear system over GF(MOD).
    # Correct for very small N*M only; large inputs are not handled yet.
    V = N * M + 1
    if V > 9:
        raise NotImplementedError("No verified closed form yet for this input size")

    adj = [[] for _ in range(V)]
    for i in range(1, V):
        p = max(i - N, 0)
        adj[i].append(p)
        adj[p].append(i)

    full = (1 << V) - 1
    # State: (current vertex, painted mask), mask always contains vertex 0.
    states = {}
    for mask in range(1, full + 1):
        if not (mask & 1):
            continue
        for cur in range(V):
            if mask >> cur & 1:
                states[(cur, mask)] = len(states)
    n = len(states)

    A = [[0] * n for _ in range(n)]
    b = [0] * n
    for (cur, mask), idx in states.items():
        A[idx][idx] = 1
        if mask == full:
            continue
        b[idx] = 1
        inv_d = pow(len(adj[cur]), MOD - 2, MOD)
        for nb in adj[cur]:
            nmask = mask | (1 << nb)
            j = states[(nb, nmask)]
            A[idx][j] = (A[idx][j] - inv_d) % MOD

    # Gaussian elimination mod p
    aug = [A[i][:] + [b[i]] for i in range(n)]
    for col in range(n):
        piv = next(r for r in range(col, n) if aug[r][col] % MOD)
        aug[col], aug[piv] = aug[piv], aug[col]
        inv = pow(aug[col][col], MOD - 2, MOD)
        aug[col] = [(x * inv) % MOD for x in aug[col]]
        for r in range(n):
            if r != col and aug[r][col]:
                f = aug[r][col]
                aug[r] = [(aug[r][k] - f * aug[col][k]) % MOD for k in range(n + 1)]

    return aug[states[(0, 1)]][n] % MOD

