def min_changes_for_semi_palindromes(s: str, k: int) -> int:
    n = len(s)

    # cost[i][j] = min changes to make s[i..j] (inclusive) a semi-palindrome
    # Only meaningful for length >= 2; length-1 segments are invalid (infinity).
    INF = float("inf")
    cost = [[INF] * n for _ in range(n)]
    for i in range(n):
        for j in range(i + 1, n):
            length = j - i + 1
            best = INF
            for d in range(1, length):
                if length % d != 0:
                    continue
                changes = 0
                # For each residue class r in [0, d), check palindrome on indices
                # i + r, i + r + d, i + r + 2d, ...
                for r in range(d):
                    lo = i + r
                    hi = j - (length - 1 - r) % d
                    # hi should be the last index in this residue class within [i, j]
                    # Walk inward comparing pairs.
                    idxs = list(range(lo, j + 1, d))
                    a, b = 0, len(idxs) - 1
                    while a < b:
                        if s[idxs[a]] != s[idxs[b]]:
                            changes += 1
                        a += 1
                        b -= 1
                if changes < best:
                    best = changes
            cost[i][j] = best

    # dp[p][e] = min changes partitioning s[0..e-1] into p semi-palindromic parts
    dp = [[INF] * (n + 1) for _ in range(k + 1)]
    dp[0][0] = 0
    for p in range(1, k + 1):
        for e in range(p * 2, n + 1):
            best = INF
            # last part is s[st..e-1], i.e. cost[st][e-1]
            for st in range(p - 1, e - 1):
                if dp[p - 1][st] == INF:
                    continue
                c = cost[st][e - 1]
                if c == INF:
                    continue
                val = dp[p - 1][st] + c
                if val < best:
                    best = val
            dp[p][e] = best

    return int(dp[k][n])

