def min_time_to_reduce_sum(nums1: List[int], nums2: List[int], x: int) -> int:
    n = len(nums1)
    base = sum(nums1)
    rate = sum(nums2)

    if base <= x:
        return 0

    NEG = float("-inf")
    for t in range(1, n + 1):
        dp = [NEG] * (t + 1)
        dp[0] = 0
        for i in range(n):
            a = nums1[i]
            b = nums2[i]
            for j in range(min(t, i + 1), 0, -1):
                if dp[j - 1] != NEG:
                    cand = dp[j - 1] + a + b * j
                    if cand > dp[j]:
                        dp[j] = cand
        best = max(dp[j] for j in range(t + 1) if dp[j] != NEG)
        if base + rate * t - best <= x:
            return t
    return -1

