from typing import List, Tuple, Optional


def min_weight_hamiltonian_walk(n: int, m: int, edges: List[Tuple[int, int, int]]) -> Optional[int]:
    """ Given a weighted directed graph with n vertices (numbered 1 to n) and m edges,
    determine if there exists a walk that visits each vertex at least once.
    If such a walk exists, return the minimum total weight of edges traversed.
    If no such walk exists, return None.

    The graph is guaranteed not to contain negative cycles.
    Edges can be traversed multiple times, with their weight counted each time.
    """
    INF = float('inf')

    # Shortest walk distances between all pairs (Floyd-Warshall).
    # Valid since there are no negative cycles.
    dist = [[INF] * n for _ in range(n)]
    for i in range(n):
        dist[i][i] = 0
    for u, v, w in edges:
        u -= 1
        v -= 1
        if w < dist[u][v]:
            dist[u][v] = w
    for k in range(n):
        dk = dist[k]
        for i in range(n):
            dik = dist[i][k]
            if dik == INF:
                continue
            di = dist[i]
            for j in range(n):
                nd = dik + dk[j]
                if nd < di[j]:
                    di[j] = nd

    full = (1 << n) - 1
    # dp[mask][v] = min cost of a walk that has visited exactly 'mask' and ends at v
    dp = [[INF] * n for _ in range(1 << n)]
    for s in range(n):
        dp[1 << s][s] = 0

    for mask in range(1, 1 << n):
        row = dp[mask]
        for v in range(n):
            cur = row[v]
            if cur == INF:
                continue
            dv = dist[v]
            for u in range(n):
                if dv[u] == INF or u == v:
                    continue
                nmask = mask | (1 << u)
                nc = cur + dv[u]
                if nc < dp[nmask][u]:
                    dp[nmask][u] = nc

    best = min(dp[full])
    return None if best == INF else best

