def sum_of_powers(nums: List[int], k: int) -> int:
    MOD = 10**9 + 7
    n = len(nums)
    a = sorted(nums)

    # Distinct pairwise differences (possible values of the power)
    diffs = sorted({a[j] - a[i] for i in range(n) for j in range(i + 1, n)})
    if not diffs:
        return 0

    def count_with_min_gap_at_least(t: int) -> int:
        # dp[c][j]: number of ways to choose c elements with last chosen index j,
        # where consecutive chosen elements differ by at least t
        dp = [[0] * n for _ in range(k + 1)]
        for j in range(n):
            dp[1][j] = 1
        for c in range(2, k + 1):
            for j in range(n):
                total = 0
                for i in range(j):
                    if a[j] - a[i] >= t:
                        total += dp[c - 1][i]
                dp[c][j] = total % MOD
        return sum(dp[k]) % MOD

    total_subsets = 1
    for i in range(k):
        total_subsets = total_subsets * (n - i) // (i + 1)
    total_subsets %= MOD

    # power(S) = d_1 + sum_{i>=2} (d_i - d_{i-1}) * [power(S) >= d_i]
    result = (diffs[0] % MOD) * total_subsets % MOD
    for idx in range(1, len(diffs)):
        gap = diffs[idx] - diffs[idx - 1]
        result = (result + gap % MOD * count_with_min_gap_at_least(diffs[idx])) % MOD

    return result % MOD

