from typing import List
from collections import deque
from functools import lru_cache


def max_knight_moves(kx: int, ky: int, positions: List[List[int]]) -> int:
    N = 50
    DIRS = [(1, 2), (2, 1), (-1, 2), (-2, 1),
            (1, -2), (2, -1), (-1, -2), (-2, -1)]

    def bfs(sx: int, sy: int) -> List[List[int]]:
        dist = [[-1] * N for _ in range(N)]
        dist[sx][sy] = 0
        q = deque([(sx, sy)])
        while q:
            x, y = q.popleft()
            for dx, dy in DIRS:
                nx, ny = x + dx, y + dy
                if 0 <= nx < N and 0 <= ny < N and dist[nx][ny] == -1:
                    dist[nx][ny] = dist[x][y] + 1
                    q.append((nx, ny))
        return dist

    n = len(positions)
    # Pawn-to-pawn costs (knight distance is symmetric)
    cost = [[0] * n for _ in range(n)]
    for i in range(n):
        d = bfs(positions[i][0], positions[i][1])
        for j in range(n):
            cost[i][j] = d[positions[j][0]][positions[j][1]]
    d0 = bfs(kx, ky)
    start_cost = [d0[positions[j][0]][positions[j][1]] for j in range(n)]

    full = (1 << n) - 1

    @lru_cache(maxsize=None)
    def solve(mask: int, last: int) -> int:
        if mask == full:
            return 0
        alice_turn = bin(mask).count("1") % 2 == 0
        best = None
        for j in range(n):
            if mask & (1 << j):
                continue
            step = start_cost[j] if last == n else cost[last][j]
            val = step + solve(mask | (1 << j), j)
            if best is None:
                best = val
            elif alice_turn:
                best = max(best, val)
            else:
                best = min(best, val)
        return best

    return solve(0, n)

