from typing import List


def max_subsequence_value(nums: List[int], k: int) -> int:
    if k == 0:
        return 0
    n = len(nums)
    if n < 2 * k:
        return 0

    def achievable_prefix(arr):
        res = []
        cur = [0] * (k + 1)
        cur[0] = 1
        res.append(cur[:])
        for x in arr:
            new = cur[:]
            for c in range(1, k + 1):
                m = cur[c - 1]
                if m:
                    acc = 0
                    v = 0
                    mm = m
                    while mm:
                        if mm & 1:
                            acc |= 1 << (v | x)
                        mm >>= 1
                        v += 1
                    new[c] |= acc
            cur = new
            res.append(cur[:])
        return res

    pre = achievable_prefix(nums)
    suf_rev = achievable_prefix(nums[::-1])

    def values(mask):
        return [v for v in range(128) if (mask >> v) & 1]

    best = -1
    for split in range(k, n - k + 1):
        left_mask = pre[split][k]
        right_mask = suf_rev[n - split][k]
        if not left_mask or not right_mask:
            continue
        for L in values(left_mask):
            for R in values(right_mask):
                val = L ^ R
                if val > best:
                    best = val
    return max(best, 0)

