from functools import lru_cache


def minimum_shipping_dissatisfaction(n: int, k: int, x: int, order_days: List[int]) -> int:
    d = sorted(order_days)
    prefix = [0] * (n + 1)
    for i in range(n):
        prefix[i + 1] = prefix[i] + d[i]

    INF = float("inf")

    @lru_cache(maxsize=None)
    def f(i, t):
        if i == n:
            return 0
        best = INF
        earliest = d[i] if t is None else max(d[i], t + x)
        for j in range(i + 1, min(n, i + k) + 1):
            s = max(earliest, d[j - 1])
            cnt = j - i
            cost = cnt * s - (prefix[j] - prefix[i])
            rest = f(j, s)
            if rest != INF:
                best = min(best, cost + rest)
        return best

    return f(0, None)

