from typing import List, Tuple


def max_production_capacity(n: int, x: int, machines: List[Tuple[int, int, int, int]]) -> int:
    def min_cost_for_process(t: int, a: int, p: int, b: int, q: int) -> int:
        # Minimum cost to reach at least t units/day using machine S (a units/day,
        # cost p) and machine T (b units/day, cost q). Integer purchases only.
        if t <= 0:
            return 0
        # Decide which machine is more cost-efficient per unit of output.
        # Compare p/a vs q/b without floating point: p*b vs q*a.
        if p * b <= q * a:
            eff_r, eff_c, ineff_r, ineff_c = a, p, b, q
        else:
            eff_r, eff_c, ineff_r, ineff_c = b, q, a, p
        # Pure strategy with the efficient machine only.
        best = -(-t // eff_r) * eff_c
        # Mixed: a small number of inefficient machines (at most 100 are ever
        # useful, since 100 machines can be exchanged for an equal-or-better mix
        # of the efficient type), with the rest covered by efficient machines.
        max_k = min(-(-t // ineff_r), 100)
        for k in range(1, max_k + 1):
            rem = t - k * ineff_r
            cost = k * ineff_c
            if rem > 0:
                cost += (-(-rem // eff_r)) * eff_c
            if cost < best:
                best = cost
        return best

    def feasible(t: int) -> bool:
        total = 0
        for (a, p, b, q) in machines:
            total += min_cost_for_process(t, a, p, b, q)
            if total > x:
                return False
        return total <= x

    lo, hi = 0, 10**9
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if feasible(mid):
            lo = mid
        else:
            hi = mid - 1
    return lo

