The approach below uses a per-team subset-sum table and a single loop over outflow choices, which keeps the search small enough to avoid the timeout.

```python
from typing import List, Tuple


def min_team_switches(people: List[Tuple[int, int]]) -> int:
    """ Given a list of people where each person is represented as (team_number, strength),
    determine the minimum number of people who need to switch teams so that all three teams
    have equal total strength. Teams are numbered 1, 2, and 3.

    Each person belongs to exactly one team and has a strength value. The strength of a team
    is the sum of strengths of all its members. Return -1 if it's impossible to make all
    teams have equal strength.

    Args:
        people: List of tuples (team_number, strength) where team_number is in {1, 2, 3}
                and strength is a positive integer.

    Returns:
        The minimum number of people who need to switch teams, or -1 if impossible.

    >>> min_team_switches([(1, 2), (2, 5), (1, 5), (3, 3), (1, 3), (3, 6)])
    2
    >>> min_team_switches([(1, 1), (1, 2), (2, 3), (3, 4)])
    -1
    >>> min_team_switches([(1, 1), (2, 1), (3, 1)])
    0
    """
    sums = [0, 0, 0, 0]
    members = {1: [], 2: [], 3: []}
    for team, s in people:
        sums[team] += s
        members[team].append(s)
    total = sum(sums)
    if total % 3 != 0:
        return -1
    target = total // 3

    def best_subsets(strengths):
        best = {0: 0}
        for s in strengths:
            for x, c in list(best.items()):
                nx = x + s
                if best.get(nx, float("inf")) > c + 1:
                    best[nx] = c + 1
        return best

    sub = {t: best_subsets(members[t]) for t in (1, 2, 3)}
    INF = float("inf")
    best_answer = INF

    for f12, c12 in sub[1].items():
        for f13, c13 in sub[1].items():
            in1 = f12 + f13 - (sums[1] - target)
            if in1 < 0:
                continue
            for f21, c21 in sub[2].items():
                f31 = in1 - f21
                if f31 < 0 or f31 not in sub[3]:
                    continue
                for f23, c23 in sub[2].items():
                    in2 = f21 + f23 - (sums[2] - target)
                    if in2 < 0:
                        continue
                    f32 = in2 - f12
                    if f32 < 0 or f32 not in sub[3]:
                        continue
                    if f31 + f32 - (f13 + f23) != sums[3] - target:
                        continue
                    cost = c12 + c13 + c21 + c23 + sub[3][f31] + sub[3][f32]
                    if cost < best_answer:
                        best_answer = cost
    return -1 if best_answer == INF else int(best_answer)


def check(candidate):
    # Test cases from the problem
    assert candidate([(1, 2), (2, 5), (1, 5), (3, 3), (1, 3), (3, 6)]) == 2
    assert candidate([(1, 1), (1, 2), (2, 3), (3, 4)]) == -1
    assert candidate([(1, 1), (2, 1), (3, 1)]) == 0
