def count_ball_sets(n: int, positions: List[Tuple[int, int]]) -> int:
    pts = list(positions)

    kill = [0] * n
    for k in range(n):
        xk, yk = pts[k]
        m = 0
        for i in range(n):
            if i == k:
                continue
            xi, yi = pts[i]
            if (xi < xk and yi < yk) or (xi > xk and yi > yk):
                m |= 1 << i
        kill[k] = m

    full = (1 << n) - 1
    seen = {full}
    stack = [full]
    while stack:
        state = stack.pop()
        for k in range(n):
            if (state >> k) & 1:
                nxt = state & ~kill[k]
                if nxt not in seen:
                    seen.add(nxt)
                    stack.append(nxt)
    return len(seen) % MOD

