def count_ball_sets(n: int, positions: List[Tuple[int, int]]) -> int:
    """Count reachable final sets of balls (exact, memoized search over remaining-ball sets).

    An operation picks a remaining ball k and removes every remaining ball that is
    strictly lower-left or strictly upper-right of k. Final sets are the distinct
    sets reachable by performing zero or more operations from the full set, where
    the state with no further operations applied counts as final.
    """
    pts = list(positions)

    def removes(k, i):
        xk, yk = pts[k]
        xi, yi = pts[i]
        return (xi < xk and yi < yk) or (xi > xk and yi > yk)

    @lru_cache(maxsize=None)
    def reach(state: int) -> frozenset:
        # state is a bitmask of remaining balls; returns set of reachable final states
        results = set()
        has_move = False
        for k in range(n):
            if not (state >> k) & 1:
                continue
            has_move = True
            new_state = state
            for i in range(n):
                if i != k and (state >> i) & 1 and removes(k, i):
                    new_state &= ~(1 << i)
            if new_state == state:
                # operation removed nothing; the state itself is still a candidate end
                results.add(state)
            else:
                results |= reach(new_state)
        if not has_move:
            results.add(state)
        return frozenset(results)

    full = (1 << n) - 1
    return len(reach(full)) % MOD

