from collections import defaultdict

def achievable_fixed_counts(n):
    classes = defaultdict(list)
    for bits in product((0, 1), repeat=n * n):
        M = [bits[i * n:(i + 1) * n] for i in range(n)]
        rows = tuple(sum(r) for r in M)
        cols = tuple(sum(M[i][j] for i in range(n)) for j in range(n))
        classes[(rows, cols)].append(M)
    counts = set()
    for members in classes.values():
        fixed = 0
        for i in range(n):
            for j in range(n):
                if len({M[i][j] for M in members}) == 1:
                    fixed += 1
        counts.add(fixed)
    return sorted(counts)

for n in (2, 3, 4):
    print(n, achievable_fixed_counts(n))

def matrix_with_k_fixed_elements_exists(n: int, k: int) -> bool:
    """Return True if an n x n binary matrix with exactly k fixed elements exists.

    Proven here: k = 0 (all cells free) and k = n*n (all-zeros matrix) are
    achievable. Other values are not yet characterized.
    """
    if not (2 <= n <= 30 and 0 <= k <= n * n):
        return False
    if k == 0 or k == n * n:
        return True
    raise NotImplementedError(
        f"Rule for intermediate k not yet derived (n={n}, k={k})."
    )

