def _reducible(t: str) -> bool:
    # Exact reduction check: a string is good iff it can be fully deleted using
    # (1) delete two identical characters, (2) delete one A, one B, one C.
    # Use a memoized search over the (string) state; strings are short in practice.
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def go(s: str) -> bool:
        if s == "":
            return True
        L = len(s)
        # Operation 1: remove two identical characters (any positions)
        for i in range(L):
            for j in range(i + 1, L):
                if s[i] == s[j]:
                    rest = s[:i] + s[i+1:j] + s[j+1:]
                    if go(rest):
                        return True
        # Operation 2: remove one A, one B, one C (any positions)
        if L >= 3:
            for i in range(L):
                for j in range(i + 1, L):
                    for k2 in range(j + 1, L):
                        if {s[i], s[j], s[k2]} == {"A", "B", "C"}:
                            rest = "".join(s[x] for x in range(L) if x not in (i, j, k2))
                            if go(rest):
                                return True
        return False

    return go(t)


def count_good_string_replacements(n: int, k: int, s: str) -> int:
    from itertools import product

    # Enumerate all fillings of '?' (exact but exponential in number of '?').
    # Each filling: count substrings that are good; accept if count >= k.
    q_positions = [i for i, c in enumerate(s) if c == '?']
    total = 0
    for fill in product("ABC", repeat=len(q_positions)):
        arr = list(s)
        for pos, ch in zip(q_positions, fill):
            arr[pos] = ch
        t = "".join(arr)
        good = 0
        for i in range(n):
            for j in range(i + 1, n + 1):
                if _reducible(t[i:j]):
                    good += 1
        if good >= k:
            total += 1
    return total % MOD

