def count_good_string_replacements(n: int, k: int, s: str) -> int:
    # Number of good substrings is at most n(n+1)/2; with k=0 every filling qualifies.
    if k <= 0:
        return pow(3, s.count('?'), MOD) if n >= 1 else 1

    # For k > 0 we need the exact count distribution. Process each filling
    # via DFS with pruning: stop early when the remaining '?' cannot reach k
    # is not directly bounded, so we use a memo over (position, good-substring
    # contribution) instead of enumerating full strings.
    #
    # Substring goodness depends on the full substring, so we enumerate windows
    # of length <= n with memoization on the substring content.
    q_positions = [i for i, c in enumerate(s) if c == '?']
    arr = list(s)
    total = 0

    def count_good(t: str) -> int:
        g = 0
        for i in range(n):
            for j in range(i + 1, n + 1):
                if _reducible(t[i:j]):
                    g += 1
        return g

    def dfs(idx: int):
        nonlocal total
        if idx == len(q_positions):
            if count_good("".join(arr)) >= k:
                total += 1
            return
        for ch in "ABC":
            arr[q_positions[idx]] = ch
            dfs(idx + 1)

    dfs(0)
    return total % MOD

