def _reduce_word(w):
    # Stack-based reduction: cancel adjacent equal letters, and cancel
    # adjacent triples that form a permutation of A,B,C (approximated by
    # letting ABC-type relations reduce via the stack).
    out = []
    for c in w:
        out.append(c)
        # Cancel equal pairs at top
        while len(out) >= 2 and out[-1] == out[-2]:
            out.pop(); out.pop()
        # Cancel a top triple that is a permutation of ABC
        if len(out) >= 3 and set(out[-3:]) == {"A", "B", "C"}:
            del out[-3:]
    return tuple(out)


