def _good_exact(t):
    # Exact reducibility via search, used only for verification of small cases.
    if t == "":
        return True
    L = len(t)
    for i in range(L):
        for j in range(i + 1, L):
            if t[i] == t[j]:
                if _good_exact(t[:i] + t[i+1:j] + t[j+1:]):
                    return True
    if L >= 3:
        for i in range(L):
            for j in range(i + 1, L):
                for m in range(j + 1, L):
                    if {t[i], t[j], t[m]} == {"A", "B", "C"}:
                        rest = "".join(t[x] for x in range(L) if x not in (i, j, m))
                        if _good_exact(rest):
                            return True
    return False


def count_good_string_replacements(n: int, k: int, s: str) -> int:
    # DP over positions. State: (reduced prefix word, number of good substrings so far, capped at k).
    # Substring [i, j) is good iff reduced(P_i) == reduced(P_j), where P_x = prefix of length x.
    # Prefix words are reduced incrementally; equal reduced words at positions i<j => good substring.
    from collections import defaultdict

    cap = k
    # dp maps (reduced_word, good_count, multiset-of-prefix-classes) -> ways.
    # The multiset of prior prefix classes is needed to count new good pairs; we track counts per class.
    # State: (current reduced word, tuple of class counts as sorted items, good_count).
    init_classes = ((( ), 1),)
    dp = defaultdict(int)
    dp[((), init_classes, 0)] = 1

    for ch in s:
        choices = "ABC" if ch == "?" else ch
        ndp = defaultdict(int)
        for (cur, classes, g), ways in dp.items():
            for c in choices:
                nxt = _reduce_word(cur + (c,))
                cdict = dict(classes)
                new_pairs = cdict.get(nxt, 0)  # prior prefixes equal to nxt form good substrings
                ng = min(cap, g + new_pairs)
                cdict[nxt] = cdict.get(nxt, 0) + 1
                key = (nxt, tuple(sorted(cdict.items())), ng)
                ndp[key] += ways
        dp = ndp

    total = 0
    for (cur, classes, g), ways in dp.items():
        if g >= cap:
            total += ways
    return total % MOD

