def count_bob_winning_sequences(s: str) -> int:
    # beats[x] = the move that x beats
    beats = {'F': 'E', 'W': 'F', 'E': 'W'}
    moves = ['F', 'W', 'E']
    n = len(s)
    offset = n
    # dp[last_move][diff + offset] = count
    # Start with no previous move: use None index 3
    # Represent last move as index into moves, 3 = none
    dp = [[0] * (2 * n + 1) for _ in range(4)]
    dp[3][offset] = 1
    for ch in s:
        ndp = [[0] * (2 * n + 1) for _ in range(4)]
        for last in range(4):
            row = dp[last]
            for d in range(2 * n + 1):
                cnt = row[d]
                if cnt == 0:
                    continue
                for j, bm in enumerate(moves):
                    if last != 3 and moves[last] == bm:
                        continue
                    delta = 0
                    if beats[bm] == ch:
                        delta = 1
                    elif beats[ch] == bm:
                        delta = -1
                    nd = d + delta
                    ndp[j][nd] = (ndp[j][nd] + cnt) % MOD
        dp = ndp
    total = 0
    for last in range(4):
        for d in range(offset + 1, 2 * n + 1):
            total = (total + dp[last][d]) % MOD
    return total

