def count_balanced_graphs(n: int, p: int) -> list[int]:
    h = n // 2
    max_m = n * (n - 1) // 2
    size = max_m - (n - 1) + 1
    result = [0] * size

    def poly_mul(a, b):
        r = [0] * (len(a) + len(b) - 1)
        for i, x in enumerate(a):
            if x:
                for j, y in enumerate(b):
                    if y:
                        r[i + j] = (r[i + j] + x * y) % p
        return r

    def layer_seqs():
        # Layer 0 is {vertex 1} (even class). Remaining layers 1,2,...
        # Odd-indexed layers are odd-distance, even-indexed (>=2) are even-distance.
        out = []

        def rec(idx, even_left, odd_left, cur):
            if even_left == 0 and odd_left == 0:
                out.append(tuple(cur))
                return
            if idx % 2 == 0:
                for s in range(1, even_left + 1):
                    cur.append(s)
                    rec(idx + 1, even_left - s, odd_left, cur)
                    cur.pop()
            else:
                for s in range(1, odd_left + 1):
                    cur.append(s)
                    rec(idx + 1, even_left, odd_left - s, cur)
                    cur.pop()

        rec(1, h - 1, h, [])
        return out

