        layers = [1] + list(sizes)
        # Labeling factor: assign the n-1 non-root labeled vertices to layers.
        # Vertex 1 is fixed in layer 0. Number of ways = (n-1)! / prod(s_i!).
        label_factor = 1
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = fact[i - 1] * i
        label_factor = fact[n - 1]
        for s in sizes:
            label_factor //= fact[s]
        # Within-layer free edges.
        poly = [1]
        for s in layers:
            e = comb(s, 2)
            poly = poly_mul(poly, [comb(e, k) % p for k in range(e + 1)])
        # Between consecutive layers: each vertex in the later layer needs
        # at least one neighbor in the earlier layer.
        for a, b in zip(layers, layers[1:]):
            base = [0] + [comb(a, k) % p for k in range(1, a + 1)]
            term = [1]
            for _ in range(b):
                term = poly_mul(term, base)
            poly = poly_mul(poly, term)
        return [(c * (label_factor % p)) % p for c in poly]

    for sizes in layer_seqs():
        poly = count_for_layers(sizes)
        for m, c in enumerate(poly):
            if n - 1 <= m <= max_m:
                result[m - (n - 1)] = (result[m - (n - 1)] + c) % p

