        fact[i] = fact[i - 1] * i % MOD
    inv = [1] * (N + 1)
    inv[N] = pow(fact[N], MOD - 2, MOD)
    for i in range(N, 0, -1):
        inv[i - 1] = inv[i] * i % MOD

    def C(n, k):
        if k < 0 or k > n or n < 0:
            return 0
        return fact[n] * inv[k] % MOD * inv[n - k] % MOD

    def paths(dx, dy):
        # number of monotone unit-step walks with dx right and dy up steps
        if dx < 0 or dy < 0:
            return 0
        return C(dx + dy, dx)

    # Blocks form the full rectangle minus the hole. A monotone walk
    # from p to q stays on blocks iff it never enters the hole.
    # Count walks from p that end at q, where the walk is in the full
    # rectangle, minus those passing through the hole, via inclusion-
    # exclusion on the hole's lower-left entry region.

    def hole_free_walks(x1, y1, x2, y2):
        # walks from (x1,y1) to (x2,y2) avoiding the hole [L,R]x[D,U]
        total = paths(x2 - x1, y2 - y1)
        if L > R or D > U:
            return total
        # a walk enters the hole iff it passes through some point
        # (x,y) in the hole with the first hole point being an entry
        # point on the hole's left or bottom boundary.
        bad = 0
        # entry on left edge: x = L, y in [max(D,y1), min(U,y2)]
        if x1 < L <= x2:
            for y in range(max(D, y1), min(U, y2) + 1):
                ways_in = paths(L - x1, y - y1)
                # first hole point is (L, y), so this is a walk to the hole entry
                # and any continuation from it (to q)
                bad += ways_in * paths(x2 - L, y2 - y)
        # entry on bottom edge: y = D, x in [max(L,x1), min(R,x2)], walks
        # that do not already enter via the left edge (x == L handled above)
        if y1 < D <= y2:
