from typing import List
from functools import lru_cache


def kth_alternating_permutation(n: int, k: int) -> List[int]:
    # Count of valid completions given remaining odd count, remaining even
    # count, and parity of the last placed element (None if nothing placed).
    @lru_cache(maxsize=None)
    def count(odds: int, evens: int, last_parity: int) -> int:
        # last_parity: 0 = last was even, 1 = last was odd, 2 = none placed
        if odds == 0 and evens == 0:
            return 1
        total = 0
        # Choosing an odd is allowed unless the last element was odd
        if odds > 0 and last_parity != 1:
            total += odds * count(odds - 1, evens, 1)
        # Choosing an even is allowed unless the last element was even
        if evens > 0 and last_parity != 0:
            total += evens * count(odds, evens - 1, 0)
        return total

    odds_total = (n + 1) // 2
    evens_total = n // 2

    # Total number of valid permutations; here the count is the number of
    # distinct values, so each choice multiplies by the number of available
    # numbers of that parity but we must pick specific numbers in order.
    # We handle this by choosing among the sorted remaining numbers of each
    # parity, which is why the multiplier above is replaced by index picking.
    total = count(odds_total, evens_total, 2)
    if k > total or k < 1:
        return []

    remaining_odds = list(range(1, n + 1, 2))
    remaining_evens = list(range(2, n + 1, 2))
    result: List[int] = []
    last_parity = 2
    rank = k - 1

    for _ in range(n):
        o, e = len(remaining_odds), len(remaining_evens)
        # Try candidates in increasing value order
        candidates = []
        if remaining_odds and last_parity != 1:
            candidates.append(("odd", remaining_odds[0]))
        if remaining_evens and last_parity != 0:
            candidates.append(("even", remaining_evens[0]))
        # Merge by value so we iterate in lexicographic order
        pool = []
        for val in remaining_odds:
            if last_parity != 1:
                pool.append((val, 1))
        for val in remaining_evens:
            if last_parity != 0:
                pool.append((val, 0))
        pool.sort()

        chosen = False
        for val, par in pool:
            if par == 1:
                ways = count(o - 1, e, 1)
            else:
                ways = count(o, e - 1, 0)
            if rank < ways:
                result.append(val)
                if par == 1:
                    remaining_odds.remove(val)
                else:
                    remaining_evens.remove(val)
                last_parity = par
                chosen = True
                break
            rank -= ways
        if not chosen:
            return []

    return result

