def solve_grid(n: int, r: str, c: str) -> Optional[List[str]]:
    letters = ['A', 'B', 'C']
    grid = [['.' for _ in range(n)] for _ in range(n)]

    def line_valid(cells: List[str], first: str) -> bool:
        # Letters present must be distinct, and the first non-empty letter must equal `first`.
        present = [x for x in cells if x != '.']
        if len(present) != len(set(present)):
            return False
        if present and present[0] != first:
            return False
        return True

    def row_ok(i: int) -> bool:
        return line_valid(grid[i], r[i])

    def col_ok(j: int) -> bool:
        return line_valid([grid[i][j] for i in range(n)], c[j])

    def full_ok() -> bool:
        return all(row_ok(i) for i in range(n)) and all(col_ok(j) for j in range(n))

    def complete() -> bool:
        # Every row and column must contain exactly one of each letter.
        for i in range(n):
            if sorted(x for x in grid[i] if x != '.') != letters:
                return False
        for j in range(n):
            if sorted(grid[i][j] for i in range(n) if grid[i][j] != '.') != letters:
                return False
        return True

    cells = [(i, j) for i in range(n) for j in range(n)]

    def backtrack(k: int) -> bool:
        if k == len(cells):
            return complete()
        i, j = cells[k]
        for ch in ['.'] + letters:
            grid[i][j] = ch
            if full_ok() and backtrack(k + 1):
                return True
        grid[i][j] = '.'
        return False

    if backtrack(0):
        return [''.join(row) for row in grid]
    return None

