def find_cube_placement(V1: int, V2: int, V3: int) -> Optional[Tuple[int, int, int, int, int, int, int, int, int]]:
    S = 7
    if V1 < 0 or V2 < 0 or V3 < 0:
        return None
    if V1 + 2 * V2 + 3 * V3 != 3 * S ** 3:
        return None
    if V3 > S ** 3:
        return None

    def ov(d):
        return max(0, S - abs(d))

    # Restrict offsets to a small set that still covers the useful overlap values
    offs = [0, 1, 2, 3, 4, 5, 6, -1, -2, -3, -4, -5, -6]

    # Cache for cube-pair overlap volume
    def pair_vol(p, q):
        return ov(p[0] - q[0]) * ov(p[1] - q[1]) * ov(p[2] - q[2])

    def triple_vol(p1, p2, p3):
        lo = [max(0, p1[i], p2[i], p3[i]) for i in range(3)]
        hi = [min(S, S + p1[i], S + p2[i], S + p3[i]) for i in range(3)]
        v = 1
        for i in range(3):
            v *= max(0, hi[i] - lo[i])
        return v

    origin = (0, 0, 0)
    cube_offsets = list(product(offs, offs, offs))
    for p2 in cube_offsets:
        v12 = pair_vol(origin, p2)
        for p3 in cube_offsets:
            v13 = pair_vol(origin, p3)
            v23 = pair_vol(p2, p3)
            v123 = triple_vol(origin, p2, p3)
            if v123 != V3:
                continue
            if v12 + v13 + v23 - 3 * v123 != V2:
                continue
            if 3 * S ** 3 - 2 * (v12 + v13 + v23) + 3 * v123 != V1:
                continue
            return (0, 0, 0, p2[0], p2[1], p2[2], p3[0], p3[1], p3[2])
    return None

