def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """ Determine if it's possible to place rectangular tiles on an H×W grid such that:
    - Every cell is covered by exactly one tile
    - Tiles can be rotated (so a 2×3 tile can be placed as 3×2)
    - Some tiles may remain unused
    - Tiles must be aligned with grid cells and cannot extend outside

    Args:
        n: Number of available tiles (1 ≤ n ≤ 7)
        h: Height of the grid (1 ≤ h ≤ 10)
        w: Width of the grid (1 ≤ w ≤ 10)
        tiles: List of (a, b) tuples where tile i has dimensions a×b (1 ≤ a, b ≤ 10)

    Returns:
        True if the grid can be perfectly tiled, False otherwise

    >>> can_tile_grid(5, 5, 5, [(1, 1), (3, 3), (4, 4), (2, 3), (2, 5)])
    True
    >>> can_tile_grid(1, 1, 2, [(2, 3)])
    False
    >>> can_tile_grid(1, 2, 2, [(1, 1)])
    False
    """
    from functools import lru_cache

    # Tiles can only be used if their area fits; we need a subset whose areas sum to h*w.
    # Backtrack over the grid in row-major order, filling the first empty cell.
    grid = [[False] * w for _ in range(h)]
    used = [False] * n

    def find_first_empty():
        for r in range(h):
            for c in range(w):
                if not grid[r][c]:
                    return r, c
        return None

    def can_place(r, c, rh, rw):
        if r + rh > h or c + rw > w:
            return False
        for i in range(r, r + rh):
            for j in range(c, c + rw):
                if grid[i][j]:
                    return False
        return True

    def set_region(r, c, rh, rw, value):
        for i in range(r, r + rh):
            for j in range(c, c + rw):
                grid[i][j] = value

    def solve(remaining_area):
        pos = find_first_empty()
        if pos is None:
            return True
        if remaining_area <= 0:
            return False
        r, c = pos
        for i in range(n):
            if used[i]:
                continue
            a, b = tiles[i]
            orientations = {(a, b), (b, a)}
            for rh, rw in orientations:
                if can_place(r, c, rh, rw):
                    set_region(r, c, rh, rw, True)
                    used[i] = True
                    if solve(remaining_area - rh * rw):
                        return True
                    used[i] = False
                    set_region(r, c, rh, rw, False)
        return False

    return solve(h * w)

from fractions import Fraction

def calculate_black_area_doubled(A: int, B: int, C: int, D: int) -> int:
    # Brute-force reference: decide the color of each unit cell by flood-fill from
    # the reference point (0.5, 0.5), crossing lines x=n, y=even, x+y=even.
    # Each unit cell is split by the diagonal if it is cut, so we sample
    # the two halves at off-line points and classify them by crossing parity.
    def crossings(p, q):
        # number of boundary lines strictly crossed on the segment p->q (generic endpoints)
        (x0, y0), (x1, y1) = p, q
        n = 0
        lo, hi = sorted([x0, x1])
        n += int(hi // 1) - int(lo // 1)
        lo, hi = sorted([y0, y1])
        n += int(hi // 2) - int(lo // 2)
        lo, hi = sorted([x0 + y0, x1 + y1])
        n += int(hi // 2) - int(lo // 2)
        return n

    def black(p):
        return crossings((Fraction(1, 2), Fraction(1, 2)), p) % 2 == 0

    total = 0
    for i in range(A, C):
        for j in range(B, D):
            if (i + j + 1) % 2 == 0:
                # the cell is cut by x+y = i+j+1
                for off in (Fraction(1, 5), Fraction(4, 5)):
                    if black((i + off, j + off)):
                        total += 1
            else:
                if black((i + Fraction(1, 2), j + Fraction(1, 2))):
                    total += 2
    return total

from functools import lru_cache

def find_palindrome_expression(n: int) -> str:
    def is_pal(s: str) -> bool:
        return s == s[::-1]

    def nonzero_digits(x: int) -> bool:
        return '0' not in str(x)

    if n < 1:
        return '-1'

    # Direct single-number palindrome
    if is_pal(str(n)) and nonzero_digits(n):
        return str(n)

    # Build a symmetric palindromic expression: a1*a2*...*mid*...*a2*a1
    # Value = (prod of outer factors)^2 * mid, where each outer factor a_i and
    # mid are digit strings of 1-9 only.
    # Enumerate the middle term (a palindromic, zero-free divisor of n) and
    # the outer-factor product q with q^2 * mid = n.

    def divisors(x):
        ds = []
        i = 1
        while i * i <= x:
            if x % i == 0:
                ds.append(i)
                if i != x // i:
                    ds.append(x // i)
            i += 1
        return sorted(ds)

    divs = divisors(n)
    palin_divs = [d for d in divs if is_pal(str(d)) and nonzero_digits(d)]

    # Try mid = palindromic zero-free divisor, q^2 = n / mid
    for mid in palin_divs:
        rest = n // mid
        q = int(round(rest ** 0.5))
        if q * q != rest or q < 1:
            continue
        # q must itself be expressible as a palindromic-compatible factor list.
        # Use q directly as a single outer factor if it's zero-free and palindromic.
        if is_pal(str(q)) and nonzero_digits(q):
            s = f"{q}*{mid}*{q}" if mid != 1 else f"{q}*{q}"
            if is_pal(s):
                return s
        # Otherwise try splitting q into a palindromic-ish list via recursion on q.
        sub = find_palindrome_expression(q) if q > 1 else '1'
        if sub != '-1' and all(c in '123456789*' for c in sub):
            inner_outer = sub
            # Build outer part as inner_outer, which is itself a palindrome.
            if mid == 1:
                s = f"{inner_outer}*{inner_outer}"
            else:
                s = f"{inner_outer}*{mid}*{inner_outer}"
            if is_pal(s) and all(c in '123456789*' for c in s) and s[0].isdigit():
                try:
                    if eval(s) == n:
                        return s
                except Exception:
                    pass

    return '-1'

MOD = 998244353

def count_good_sequences(N: int, M: int) -> int:
    from math import comb

    def sigma_mod3(n: int) -> int:
        res = 1
        x = n
        p = 2
        while p * p <= x:
            if x % p == 0:
                s = 1
                pk = 1
                while x % p == 0:
                    x //= p
                    pk *= p
                    s += pk
                res = res * (s % 3) % 3
            p += 1
        if x > 1:
            res = res * ((1 + x) % 3) % 3
        return res

    def ordered_count(n: int) -> int:
        res = 1
        x = n
        p = 2
        while p * p <= x:
            if x % p == 0:
                e = 0
                while x % p == 0:
                    x //= p
                    e += 1
                res = res * comb(e + M - 1, M - 1) % MOD
            p += 1
        if x > 1:
            res = res * M % MOD
        return res

    total = 0
    for n in range(1, N + 1):
        if sigma_mod3(n) == 0:
            total = (total + ordered_count(n)) % MOD
    return total

MOD = 998244353

def sum_of_scores(n: int, m: int) -> int:
    primes = [2, 3, 5, 7, 11, 13]

    def exps(x):
        v = []
        for p in primes:
            c = 0
            while x % p == 0:
                x //= p
                c += 1
            v.append(c)
        return tuple(v)

    vecs = [exps(v) for v in range(1, m + 1)]
    dp = {}
    for v in vecs:
        dp[v] = dp.get(v, 0) + 1
    total = 0
    length = 1
    while True:
        for vec, cnt in dp.items():
            d = 1
            for e in vec:
                d *= e + 1
            total = (total + cnt * d) % MOD
        if length == n:
            break
        ndp = {}
        for vec, cnt in dp.items():
            for w in vecs:
                nv = tuple(a + b for a, b in zip(vec, w))
                ndp[nv] = (ndp.get(nv, 0) + cnt) % MOD
        dp = ndp
        length += 1
    return total % MOD

MOD = 10**9 + 7

def count_good_integers(num1: str, num2: str, min_sum: int, max_sum: int) -> int:
    """ Count the number of integers x such that num1 <= x <= num2 and 
    min_sum <= digit_sum(x) <= max_sum, where digit_sum(x) is the sum of digits of x.

    Return the count modulo 10^9 + 7.
    """
    def count_upto(s: str, limit: int) -> int:
        # Number of x in [0, s] with digit sum <= limit
        if limit < 0:
            return 0
        n = len(s)
        # ways[r][t] = number of digit strings of length r with digit sum exactly t
        max_t = 9 * n
        ways = [[0] * (max_t + 1) for _ in range(n + 1)]
        ways[0][0] = 1
        for r in range(1, n + 1):
            for t in range(max_t + 1):
                total = 0
                for d in range(10):
                    if t - d >= 0:
                        total += ways[r - 1][t - d]
                ways[r][t] = total % MOD

        result = 0
        prefix_sum = 0
        for i, ch in enumerate(s):
            cur = int(ch)
            remaining = n - i - 1
            for d in range(cur):
                ps = prefix_sum + d
                # need total digit sum <= limit, remaining digits free
                for t in range(0, remaining * 9 + 1):
                    if ps + t <= limit:
                        result += ways[remaining][t]
                    else:
                        break
                result %= MOD
            prefix_sum += cur
            if prefix_sum > limit:
                return result % MOD
        # s itself
        if prefix_sum <= limit:
            result += 1
        return result % MOD

    def digit_sum_str(s: str) -> int:
        return sum(int(c) for c in s)

    upper = count_upto(num2, max_sum) - count_upto(num2, min_sum - 1)
    lower = count_upto(num1, max_sum) - count_upto(num1, min_sum - 1)
    # count_upto(num1, ...) includes num1 itself; the range is [num1, num2],
    # so we want f(num2) - f(num1) + [num1 is good]
    num1_good = 1 if min_sum <= digit_sum_str(num1) <= max_sum else 0
    return (upper - lower + num1_good) % MOD

def min_changes_for_semi_palindromes(s: str, k: int) -> int:
    n = len(s)

    # cost[i][j] = min changes to make s[i..j] (inclusive) a semi-palindrome
    # Only meaningful for length >= 2; length-1 segments are invalid (infinity).
    INF = float("inf")
    cost = [[INF] * n for _ in range(n)]
    for i in range(n):
        for j in range(i + 1, n):
            length = j - i + 1
            best = INF
            for d in range(1, length):
                if length % d != 0:
                    continue
                changes = 0
                # For each residue class r in [0, d), check palindrome on indices
                # i + r, i + r + d, i + r + 2d, ...
                for r in range(d):
                    lo = i + r
                    hi = j - (length - 1 - r) % d
                    # hi should be the last index in this residue class within [i, j]
                    # Walk inward comparing pairs.
                    idxs = list(range(lo, j + 1, d))
                    a, b = 0, len(idxs) - 1
                    while a < b:
                        if s[idxs[a]] != s[idxs[b]]:
                            changes += 1
                        a += 1
                        b -= 1
                if changes < best:
                    best = changes
            cost[i][j] = best

    # dp[p][e] = min changes partitioning s[0..e-1] into p semi-palindromic parts
    dp = [[INF] * (n + 1) for _ in range(k + 1)]
    dp[0][0] = 0
    for p in range(1, k + 1):
        for e in range(p * 2, n + 1):
            best = INF
            # last part is s[st..e-1], i.e. cost[st][e-1]
            for st in range(p - 1, e - 1):
                if dp[p - 1][st] == INF:
                    continue
                c = cost[st][e - 1]
                if c == INF:
                    continue
                val = dp[p - 1][st] + c
                if val < best:
                    best = val
            dp[p][e] = best

    return int(dp[k][n])

