def sum_of_subsequence_powers(nums: List[int], k: int) -> int:
    MOD = 10**9 + 7
    n = len(nums)
    # dp[s][t] = number of subsets with sum s (only sums <= k matter) and size t
    dp = [[0] * (n + 1) for _ in range(k + 1)]
    dp[0][0] = 1
    for x in nums:
        if x > k:
            continue
        for s in range(k, x - 1, -1):
            row_prev = dp[s - x]
            row = dp[s]
            for t in range(n, 0, -1):
                if row_prev[t - 1]:
                    row[t] = (row[t] + row_prev[t - 1]) % MOD
    # Each subset T with sum k and size t is contained in 2^(n-t) supersets
    total = 0
    for t in range(n + 1):
        if dp[k][t]:
            total = (total + dp[k][t] * pow(2, n - t, MOD)) % MOD
    return total

