def findProductQueries(queries: List[List[int]]) -> List[int]:
    def count_bit_in_range(n: int, b: int) -> int:
        # number of integers i in [0, n] whose bit b is set
        if n < 0:
            return 0
        cycle = 1 << (b + 1)
        full = (n + 1) // cycle
        rem = (n + 1) % cycle
        return full * (1 << b) + max(0, rem - (1 << b))

    def full_blocks_stats(n: int):
        # For integers 1..n: total length of their powerful arrays (sum of popcounts),
        # and for each exponent b, how many times 2^b appears (count of i with bit b set).
        total_len = 0
        bit_counts = []
        for b in range(64):
            c = count_bit_in_range(n, b)
            bit_counts.append(c)
            total_len += c
        return total_len, bit_counts

    def prefix_exp_sum(P: int) -> int:
        # Sum of exponents over big_nums[0 .. P-1]
        if P <= 0:
            return 0
        # Find largest i such that total length of blocks 1..i <= P
        lo, hi = 0, 1
        while full_blocks_stats(hi)[0] <= P:
            hi *= 2
        # Binary search on i in [0, hi)
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if full_blocks_stats(mid)[0] <= P:
                lo = mid
            else:
                hi = mid - 1
        i = lo
        used_len, bit_counts = full_blocks_stats(i)
        exp_sum = 0
        for b in range(64):
            exp_sum += b * bit_counts[b]
        remaining = P - used_len
        # Partial block for integer i+1: its exponents are the set bits of (i+1), ascending
        if remaining > 0:
            nxt = i + 1
            b = 0
            while remaining > 0 and nxt >> b:
                if (nxt >> b) & 1:
                    exp_sum += b
                    remaining -= 1
                b += 1
        return exp_sum

    results = []
    for from_i, to_i, mod_i in queries:
        if mod_i == 1:
            results.append(0)
            continue
        e = prefix_exp_sum(to_i + 1) - prefix_exp_sum(from_i)
        results.append(pow(2, e, mod_i))
    return results

