def count_arithmetic_subsequences(n: int, a: List[int]) -> List[int]:
    MOD = 998244353
    # dp[j] maps difference d -> list where dp[j][d][k] = number of arithmetic
    # subsequences of length k ending at index j with common difference d.
    dp = [dict() for _ in range(n)]
    result = [0] * n
    result[0] = n % MOD  # all single-element subsequences

    for j in range(n):
        for i in range(j):
            d = a[j] - a[i]
            prev = dp[i].get(d)
            cur = dp[j].get(d)
            if cur is None:
                cur = [0] * (n + 1)
                dp[j][d] = cur
            # subsequence of length 2: (i, j)
            cur[2] = (cur[2] + 1) % MOD
            if prev is not None:
                for k in range(2, n):
                    if prev[k]:
                        cur[k + 1] = (cur[k + 1] + prev[k]) % MOD
        for d, arr in dp[j].items():
            for k in range(2, n + 1):
                if arr[k]:
                    result[k - 1] = (result[k - 1] + arr[k]) % MOD

    return result

