    remaining_odds = list(range(1, n + 1, 2))
    remaining_evens = list(range(2, n + 1, 2))
    result: List[int] = []
    last_parity = 2
    rank = k - 1

    for _ in range(n):
        o, e = len(remaining_odds), len(remaining_evens)
        # Try candidates in increasing value order
        candidates = []
        if remaining_odds and last_parity != 1:
            candidates.append(("odd", remaining_odds[0]))
        if remaining_evens and last_parity != 0:
            candidates.append(("even", remaining_evens[0]))
