        M = [row[:] + [b[i]] for i, row in enumerate(A)]
        for col in range(size):
            piv = None
            for r in range(col, size):
                if M[r][col] % MOD:
                    piv = r
                    break
            if piv is None:
                return None
            M[col], M[piv] = M[piv], M[col]
            inv = pow(M[col][col], MOD - 2, MOD)
            M[col] = [(x * inv) % MOD for x in M[col]]
            for r in range(size):
