        Res = [[int(i == j) for j in range(s)] for i in range(s)]
        while p:
            if p & 1:
                Res = mat_mult(Res, M)
            M = mat_mult(M, M)
            p >>= 1
        return Res

    if coef is None:
        return sum(vals) % MOD

    # State: [S(k),...,S(k-R0+1), C(k)] where C(k)=sum_{i<=k} S(i)
    s = R0 + 1
    T = [[0] * s for _ in range(s)]
