def _lis_lds(p):
    n = len(p)
    # longest increasing subsequence
    inc = [1] * n
    for i in range(n):
        for j in range(i):
            if p[j] < p[i] and inc[j] + 1 > inc[i]:
                inc[i] = inc[j] + 1
    dec = [1] * n
    for i in range(n):
        for j in range(i):
            if p[j] > p[i] and dec[j] + 1 > dec[i]:
                dec[i] = dec[j] + 1
    return (max(inc) if n else 0), (max(dec) if n else 0)


def _appendable(p):
    # There exists n such that appending n + 0.5 leaves LIS and LDS unchanged.
    # Values are 1..L, so n ranges over 0..L (n + 0.5 is between integers).
    L = len(p)
    base_inc, base_dec = _lis_lds(p)
    for n in range(0, L + 1):
        q = [x if x <= n else x + 1 for x in p]  # shift to make room for n+0.5 as n+1
        q = q + [n + 1]  # value n+0.5 after relabeling
        inc, dec = _lis_lds(q)
        if inc == base_inc and dec == base_dec:
            return True
    return False


def count_special_permutations(A: int, B: int, M: int) -> int:
    """Count permutations P of (1..AB-1) with LIS = A, LDS = B, and an
    appendable n + 0.5 suffix, modulo M. Brute force; only feasible for
    small inputs."""
    L = A * B - 1
    if L < 1:
        return 0
    count = 0
    for p in permutations(range(1, L + 1)):
        inc, dec = _lis_lds(p)
        if inc == A and dec == B and _appendable(p):
            count += 1
    return count % M

