def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    def tile_of(x, y):
        # Find the tile (i, j, k) containing the cell with lower-left (x, y).
        # Tile bounds are closed intervals; a point (x+0.5, y+0.5) is strictly
        # inside exactly one tile in the interior-of-cell sense.
        px, py = x + 0.5, y + 0.5
        # Candidate block indices around the point.
        for i in range(px // K - 2, px // K + 3):
            for j in range(py // K - 2, py // K + 3):
                for k in range(K):
                    if (i % 2) == (j % 2):
                        x0, x1 = i * K, (i + 1) * K
                        y0, y1 = j * K + k, j * K + k + 1
                    else:
                        x0, x1 = i * K + k, i * K + k + 1
                        y0, y1 = j * K, (j + 1) * K
                    if x0 < px < x1 and y0 < py < y1:
                        return (i, j, k)
        raise ValueError("no tile found")

    def bounds(t):
        i, j, k = t
        if (i % 2) == (j % 2):
            return (i * K, (i + 1) * K, j * K + k, j * K + k + 1)
        return (i * K + k, i * K + k + 1, j * K, (j + 1) * K)

    def adjacent(a, b):
        ax0, ax1, ay0, ay1 = bounds(a)
        bx0, bx1, by0, by1 = bounds(b)
        # Shared edge of positive length: touching sides with overlapping span.
        vert = (ax1 == bx0 or bx1 == ax0) and min(ay1, by1) > max(ay0, by0)
        horz = (ay1 == by0 or by1 == ay0) and min(ax1, bx1) > max(ax0, bx0)
        return vert or horz

    start = tile_of(S_x, S_y)
    target = tile_of(T_x, T_y)
    if start == target:
        return 0

    seen = {start: 0}
    queue = deque([start])
    while queue:
        cur = queue.popleft()
        d = seen[cur]
        ci, cj, _ = cur
        for di in range(-2, 3):
            for dj in range(-2, 3):
                for dk in range(K):
                    nb = (ci + di, cj + dj, dk)
                    if nb in seen:
                        continue
                    if adjacent(cur, nb):
                        if nb == target:
                            return d + 1
                        seen[nb] = d + 1
                        queue.append(nb)
    return -1

