def sum_concatenated_permutations(n: int) -> int:
    MOD = 998244353

    # group 1..n by digit length: d -> (count, sum of values)
    groups = {}
    lo, d = 1, 1
    while lo <= n:
        hi = min(n, 10 ** d - 1)
        groups[d] = (hi - lo + 1, (lo + hi) * (hi - lo + 1) // 2)
        lo = hi + 1
        d += 1

    fact = [1] * (n + 1)
    for i in range(1, n + 1):
        fact[i] = fact[i - 1] * i % MOD
    inv = [0, 1] + [0] * (n)
    for i in range(2, n + 1):
        inv[i] = (MOD - (MOD // i) * inv[MOD % i] % MOD) % MOD

    def weight(s):
        return fact[s] * fact[n - 1 - s] % MOD

    # Full polynomial P(x) = prod_j (1 + 10^{d_j} x), degree n.
    # Log-derivative: P'(x) * D(x) = P(x) * N(x), where
    # D(x) = prod_d (1 + a_d x) and N(x) = sum_d c_d a_d / (1 + a_d x) * D(x).
    # Equivalently, with power sums p_k = sum_j a_j^k (a_j = 10^{d_j}),
    # Newton's identity gives k * e_k = sum_{i=1}^{k} (-1)^{i-1} e_{k-i} p_i.
    def elementary_from(power_sums_fn, deg):
        p = [0] * (deg + 1)
        for k in range(1, deg + 1):
            p[k] = power_sums_fn(k)
        e = [0] * (deg + 1)
        e[0] = 1
        for k in range(1, deg + 1):
            acc = 0
            sign_sum = 0
            for i in range(1, k + 1):
                term = e[k - i] * p[i] % MOD
                if i % 2 == 1:
                    acc += term
                else:
                    acc -= term
            e[k] = acc % MOD * inv[k] % MOD
        return e

    def make_power_sum(removed_dl):
        def ps(k):
            s = 0
            for dl, (cnt, _) in groups.items():
                c = cnt - (1 if dl == removed_dl else 0)
                if c:
                    s = (s + c * pow(10, dl * k, MOD)) % MOD
            return s
        return ps

    total = 0
    for dl, (cnt, sm) in groups.items():
        Q = elementary_from(make_power_sum(dl), n - 1)
        s_sum = 0
        for s in range(n):
            s_sum = (s_sum + weight(s) * Q[s]) % MOD
        total = (total + sm % MOD * s_sum) % MOD

    return total

