from typing import List


def sum_imbalance_numbers(nums: List[int]) -> int:
    """Sum of imbalance numbers over all subarrays of nums."""
    n = len(nums)
    total = 0
    for i in range(n):
        seen = [False] * (n + 2)
        count = 0
        for j in range(i, n):
            v = nums[j]
            if not seen[v]:
                seen[v] = True
                pred = v - 1
                while pred >= 1 and not seen[pred]:
                    pred -= 1
                succ = v + 1
                while succ <= n and not seen[succ]:
                    succ += 1
                if pred >= 1 and succ <= n and succ - pred > 1:
                    count -= 1
                if pred >= 1 and v - pred > 1:
                    count += 1
                if succ <= n and succ - v > 1:
                    count += 1
            total += count
    return total

