def min_changes_for_semi_palindromes(s: str, k: int) -> int:
    n = len(s)

    # cost[i][j] = minimum changes to make s[i..j] (inclusive) a semi-palindrome
    # Substrings of length < 2 are never semi-palindromes, so their cost is infinite.
    def semi_palindrome_cost(i: int, j: int) -> int:
        length = j - i + 1
        if length < 2:
            return float('inf')
        best = float('inf')
        for d in range(1, length):
            if length % d != 0:
                continue
            # For each residue class modulo d, count mismatches needed for palindrome
            changes = 0
            for r in range(d):
                idxs = list(range(i + r, j + 1, d))
                lo, hi = 0, len(idxs) - 1
                while lo < hi:
                    if s[idxs[lo]] != s[idxs[hi]]:
                        changes += 1
                    lo += 1
                    hi -= 1
            best = min(best, changes)
        return best

    cost = [[float('inf')] * n for _ in range(n)]
    for i in range(n):
        for j in range(i + 1, n):
            cost[i][j] = semi_palindrome_cost(i, j)

    INF = float('inf')
    # dp[p][j] = min changes to split s[0..j-1] into p parts
    dp = [[INF] * (n + 1) for _ in range(k + 1)]
    dp[0][0] = 0
    for p in range(1, k + 1):
        for j in range(p, n + 1):
            for i in range(p - 1, j):
                if dp[p - 1][i] == INF:
                    continue
                c = cost[i][j - 1]
                if c == INF:
                    continue
                dp[p][j] = min(dp[p][j], dp[p - 1][i] + c)
    return dp[k][n]

