def count_good_strings(n: int, k: int, s: str) -> int:
    MOD = 998244353
    m = len(s)  # use the actual string length to avoid index errors

    def is_pal(mask: int, length: int) -> bool:
        bits = [(mask >> i) & 1 for i in range(length)]
        return bits == bits[::-1]

    pal = [is_pal(x, k) for x in range(1 << k)]

    # State: (length of prefix stored, mask of that prefix), where
    # the stored prefix is the last min(i, k-1) characters.
    # Bit j of mask corresponds to the character j positions before the newest.
    dp = {(0, 0): 1}
    km1 = k - 1

    for i in range(m):
        ch = s[i]
        if ch == 'A':
            choices = (0,)
        elif ch == 'B':
            choices = (1,)
        else:
            choices = (0, 1)

        new_dp = {}
        for (L, mask), cnt in dp.items():
            for c in choices:
                if L < km1:
                    # Not enough characters for a full window yet
                    nm = (mask << 1) | c
                    key = (L + 1, nm)
                    new_dp[key] = (new_dp.get(key, 0) + cnt) % MOD
                else:
                    # Full window: last k-1 characters plus c
                    window = (mask << 1) | c  # k bits
                    if pal[window]:
                        continue
                    nm = window & ((1 << km1) - 1)
                    key = (km1, nm)
                    new_dp[key] = (new_dp.get(key, 0) + cnt) % MOD
        dp = new_dp

    return sum(dp.values()) % MOD

