def count_paths(N: int, M: int, K: int, extra_edges: list) -> int:
    MOD = 998244353
    # Map each vertex to its extra out-neighbors
    extra_out = {}
    for x, y in extra_edges:
        extra_out.setdefault(x, []).append(y)

    # Current state: dict mapping vertex -> number of ways to be there now
    # Each step, every vertex's mass moves to its cycle successor, plus to
    # any extra destinations. Simulate directly with a sparse dictionary;
    # the number of active vertices stays small (only reached via extra edges).
    # Mass at vertex 1 at time 0.
    cur = {1: 1}
    # Vertices that have nonzero mass: track cycle mass as a rotating shift.
    # For efficiency, we handle the pure-cycle portion by reducing K modulo N
    # when no extra edges are present.
    if M == 0:
        # Pure cycle: exactly one path, always ends at vertex 1 + K mod N.
        return 1 % MOD

    steps = 0
    while steps < K:
        nxt = {}
        for v, w in cur.items():
            succ = v + 1 if v < N else 1
            nxt[succ] = (nxt.get(succ, 0) + w) % MOD
            for d in extra_out.get(v, []):
                nxt[d] = (nxt.get(d, 0) + w) % MOD
        cur = nxt
        steps += 1
        # Stop early if the state is too large to be practical; this direct
        # simulation is exact but may be slow for large K.
    return sum(cur.values()) % MOD

