from typing import List
from functools import lru_cache
from collections import deque


def max_knight_moves(kx: int, ky: int, positions: List[List[int]]) -> int:
    N = 50
    DIRS = [(1, 2), (2, 1), (-1, 2), (-2, 1), (1, -2), (2, -1), (-1, -2), (-2, -1)]

    def bfs(sx, sy):
        dist = [[-1] * N for _ in range(N)]
        dist[sx][sy] = 0
        q = deque([(sx, sy)])
        while q:
            x, y = q.popleft()
            for dx, dy in DIRS:
                nx, ny = x + dx, y + dy
                if 0 <= nx < N and 0 <= ny < N and dist[nx][ny] < 0:
                    dist[nx][ny] = dist[x][y] + 1
                    q.append((nx, ny))
        return dist

    pts = [tuple(p) for p in positions]
    n = len(pts)

    # Distance from each "node" (knight start = index n, pawns = 0..n-1) to each pawn
    nodes = pts + [(kx, ky)]
    d = [[0] * n for _ in range(n + 1)]
    for i, (x, y) in enumerate(nodes):
        dist = bfs(x, y)
        for j, (px, py) in enumerate(pts):
            d[i][j] = dist[px][py]

    full = (1 << n) - 1

    @lru_cache(maxsize=None)
    def solve(mask: int, pos: int, alice: bool) -> int:
        # mask: set of remaining pawns; pos: current knight node index
        if mask == 0:
            return 0
        best = None
        for j in range(n):
            if mask >> j & 1:
                val = d[pos][j] + solve(mask ^ (1 << j), j, not alice)
                if best is None:
                    best = val
                elif alice:
                    best = max(best, val)
                else:
                    best = min(best, val)
        return best

    return solve(full, n, True)

