                out_deg[c] = 0
                in_deg[c] = 0
        union(u, v)
        out_deg[u] += 1
        in_deg[v] += 1

    comp_start = {}
    comp_absorb = {}
    comp_has_edge = {}
    for c in parent:
        r = find(c)
