def count_ball_sets(n: int, positions: List[Tuple[int, int]]) -> int:
    MOD = 998244353
    start = frozenset(range(n))

    def apply(state, k):
        xk, yk = positions[k]
        remaining = set()
        for i in state:
            if i == k:
                remaining.add(i)
                continue
            xi, yi = positions[i]
            if (xi < xk and yi < yk) or (xi > xk and yi > yk):
                continue
            remaining.add(i)
        return frozenset(remaining)

    seen = {start}
    stack = [start]
    while stack:
        state = stack.pop()
        for k in state:
            nxt = apply(state, k)
            if nxt != state and nxt not in seen:
                seen.add(nxt)
                stack.append(nxt)
    return len(seen) % MOD

