def _zero_one_dist(n, edges, chosen):
    INF = float("inf")
    adj = [[] for _ in range(n + 1)]
    for idx, (u, v) in enumerate(edges):
        adj[u].append((v, 1 if idx in chosen else 0))
    dist = [INF] * (n + 1)
    dist[1] = 0
    dq = deque([1])
    while dq:
        u = dq.popleft()
        for v, w in adj[u]:
            nd = dist[u] + w
            if nd < dist[v]:
                dist[v] = nd
                if w == 0:
                    dq.appendleft(v)
                else:
                    dq.append(v)
    return dist[n]


def max_shortest_distance(n: int, m: int, k: int, edges: List[Tuple[int, int]]) -> int:
    fwd = [[] for _ in range(n + 1)]
    bwd = [[] for _ in range(n + 1)]
    for u, v in edges:
        fwd[u].append(v)
        bwd[v].append(u)

    def reach(src, adjl):
        seen = {src}
        stack = [src]
        while stack:
            x = stack.pop()
            for y in adjl[x]:
                if y not in seen:
                    seen.add(y)
                    stack.append(y)
        return seen

    from_1 = reach(1, fwd)
    to_n = reach(n, bwd)
    relevant = [i for i, (u, v) in enumerate(edges) if u in from_1 and v in to_n]
    kk = min(k, len(relevant))

    best = 0
    chosen = set()

    def dfs(start, count):
        nonlocal best
        if best >= n - 1:
            return
        d = _zero_one_dist(n, edges, chosen)
        if d > best:
            best = d
        if count == kk:
            return
        for j in range(start, len(relevant)):
            chosen.add(relevant[j])
            dfs(j + 1, count + 1)
            chosen.remove(relevant[j])
            if best >= n - 1:
                return

