def solve_small(n, a):
    # Exact game solver for small inputs, for deriving the rule locally.
    @lru_cache(maxsize=None)
    def win(counts, mask):
        full = (1 << n) - 1
        if mask == full:
            return False  # player to move has lost; previous mover won
        for i in range(n):
            if counts[i] >= 1:
                nc = list(counts)
                nc[i] -= 1
                if not win(tuple(nc), mask | (1 << i)):
                    return True
        return False

    return "Fennec" if win(tuple(a), 0) else "Snuke"


