def sum_good_sequence_scores(n: int, a: list[int]) -> int:
    from math import gcd

    def solve_with_divisor(d: int) -> int:
        # Count sum of products over good sequences where every element is divisible by d.
        # Adjacent pairs satisfy u*v = a[i] (after dividing by d^2 for each pair,
        # since both elements are multiples of d), gcd(u, v) = 1.
        # Represent: element x = d * y, with y positive integer, and
        # (d*y1)*(d*y2) = a[i]  ->  y1*y2 = a[i] / d^2, gcd(y1,y2)=1.
        for ai in a:
            if ai % (d * d) != 0:
                return 0

        # Candidate values for y at each position.
        # Start with all positive y such that y divides some needed quotient.
        # Build set of possible y values from the first constraint onward.
        first_q = a[0] // (d * d)
        # Values of the first element y: any divisor y of first_q with
        # first_q / y coprime-compatible (checked during transitions).
        cur = {}
        for y in divisors(first_q):
            cur[y] = d * y % MOD  # score contribution of first element

        for i in range(n - 1):
            q = a[i] // (d * d)
            nxt = {}
            for u, s in cur.items():
                if q % u != 0:
                    continue
                v = q // u
                if gcd(u, v) != 1:
                    continue
                nxt[v] = (nxt.get(v, 0) + s * d * v) % MOD
            cur = nxt
            if not cur:
                return 0

        return sum(cur.values()) % MOD

    # Möbius inversion over common divisor to enforce overall gcd == 1.
    total = 0
    limit = max(a)
    for d in range(1, limit + 1):
        mu = mobius(d)
        if mu == 0:
            continue
        total = (total + mu * solve_with_divisor(d)) % MOD
    return total % MOD


def divisors(x: int) -> list[int]:
    res = []
    i = 1
    while i * i <= x:
        if x % i == 0:
            res.append(i)
            if i != x // i:
                res.append(x // i)
        i += 1
    return res


def mobius(d: int) -> int:
    result = 1
    m = d
    p = 2
    while p * p <= m:
        if m % p == 0:
            m //= p
            if m % p == 0:
                return 0
            result = -result
        p += 1
    if m > 1:
        result = -result
    return result

