def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """ Determine if it's possible to place rectangular tiles on an H×W grid such that:
    - Every cell is covered by exactly one tile
    - Tiles can be rotated (so a 2×3 tile can be placed as 3×2)
    - Some tiles may remain unused
    - Tiles must be aligned with grid cells and cannot extend outside

    Args:
        n: Number of available tiles (1 ≤ n ≤ 7)
        h: Height of the grid (1 ≤ h ≤ 10)
        w: Width of the grid (1 ≤ w ≤ 10)
        tiles: List of (a, b) tuples where tile i has dimensions a×b (1 ≤ a, b ≤ 10)

    Returns:
        True if the grid can be perfectly tiled, False otherwise

    >>> can_tile_grid(5, 5, 5, [(1, 1), (3, 3), (4, 4), (2, 3), (2, 5)])
    True
    >>> can_tile_grid(1, 1, 2, [(2, 3)])
    False
    >>> can_tile_grid(1, 2, 2, [(1, 1)])
    False
    """
    # Some tiles may be unused, so we pick a subset whose total area equals H*W,
    # then check whether that subset can exactly tile the grid.
    target = h * w
    areas = [a * b for a, b in tiles]
    if sum(areas) < target:
        return False

    grid = [[False] * w for _ in range(h)]

    def first_empty():
        for r in range(h):
            for c in range(w):
                if not grid[r][c]:
                    return r, c
        return None

    def fits(r, c, rh, rw):
        if r + rh > h or c + rw > w:
            return False
        for i in range(r, r + rh):
            for j in range(c, c + rw):
                if grid[i][j]:
                    return False
        return True

    def set_cells(r, c, rh, rw, val):
        for i in range(r, r + rh):
            for j in range(c, c + rw):
                grid[i][j] = val

    def fill(used):
        pos = first_empty()
        if pos is None:
            return True
        r, c = pos
        for idx in range(n):
            if used[idx]:
                continue
            a, b = tiles[idx]
            for rh, rw in {(a, b), (b, a)}:
                if fits(r, c, rh, rw):
                    set_cells(r, c, rh, rw, True)
                    used[idx] = True
                    if fill(used):
                        return True
                    used[idx] = False
                    set_cells(r, c, rh, rw, False)
        return False

    # Try every subset of tiles whose total area equals the grid area.
    for mask in range(1, 1 << n):
        total = 0
        for i in range(n):
            if mask >> i & 1:
                total += areas[i]
        if total != target:
            continue
        subset_used = [not (mask >> i & 1) for i in range(n)]
        for row in grid:
            for j in range(w):
                row[j] = False
        if fill(subset_used):
            return True
    return False

MOD = 998244353

def count_good_sequences(N: int, M: int) -> int:
    from math import comb

    def sigma_mod3(n: int) -> int:
        total = 1
        m = n
        p = 2
        while p * p <= m:
            if m % p == 0:
                pe = 1
                s = 1
                while m % p == 0:
                    m //= p
                    pe *= p
                    s += pe
                total = total * s % 3
            p += 1
        if m > 1:
            total = total * (1 + m) % 3
        return total

    def ordered_factorizations(n: int) -> int:
        res = 1
        m = n
        p = 2
        while p * p <= m:
            e = 0
            while m % p == 0:
                m //= p
                e += 1
            if e:
                res = res * comb(e + M - 1, M - 1) % MOD
            p += 1
        if m > 1:
            res = res * (M % MOD) % MOD
        return res

    total = 0
    for n in range(1, N + 1):
        if sigma_mod3(n) == 0:
            total = (total + ordered_factorizations(n)) % MOD
    return total

MOD = 998244353

def sum_of_scores(n: int, m: int) -> int:
    primes = [2, 3, 5, 7, 11, 13]
    P = len(primes)

    vecs = []
    for v in range(1, m + 1):
        x = v
        e = []
        for p in primes:
            c = 0
            while x % p == 0:
                x //= p
                c += 1
            e.append(c)
        vecs.append(tuple(e))

    total = 0
    cur = {tuple([0] * P): 1}
    for _ in range(n):
        nxt = {}
        for vec, c in cur.items():
            for vv in vecs:
                nv = tuple(a + b for a, b in zip(vec, vv))
                nxt[nv] = (nxt.get(nv, 0) + c) % MOD
        cur = nxt
        for vec, c in cur.items():
            d = 1
            for e in vec:
                d *= e + 1
            total = (total + c * d) % MOD
    return total

