def find_triple_sum(n: int, x: int, a: List[int]) -> Optional[Tuple[int, int, int]]:
    # Map each value to its sorted list of 1-based indices.
    positions = {}
    for idx, val in enumerate(a, start=1):
        positions.setdefault(val, []).append(idx)

    for i in range(1, n + 1):
        ai = a[i - 1]
        for j in range(i + 1, n + 1):
            need = x - ai - a[j - 1]
            if need < 1:
                continue
            lst = positions.get(need)
            if not lst:
                continue
            # Find the smallest index k > j with value 'need'.
            p = bisect_right(lst, j)
            if p < len(lst):
                return (i, j, lst[p])
    return None

