def _is_subsequence(pattern, seq):
    it = iter(seq)
    return all(c in it for c in pattern)

def count_sequences_without_subsequence(N: int, M: int, K: int, X: list[int]) -> int:
    X = tuple(X)
    all_words = [w for w in product(range(1, K + 1), repeat=M) if w != X]
    count = 0
    for S in product(range(1, K + 1), repeat=N):
        if _is_subsequence(X, S):
            continue
        if all(_is_subsequence(w, S) for w in all_words):
            count += 1
    return count % MOD

