def brute(s):
    beats = {'F': 'E', 'W': 'F', 'E': 'W'}
    total = 0
    for seq in product('FWE', repeat=len(s)):
        if any(seq[i] == seq[i + 1] for i in range(len(s) - 1)):
            continue
        score = sum((1 if beats[b] == a else -1) for b, a in zip(seq, s) if b != a)
        if score > 0:
            total += 1
    return total % (10**9 + 7)

