def min_longest_substring(s: str, numOps: int) -> int:
    """ Given a binary string s and an integer numOps, you can flip at most numOps characters 
    (change '0' to '1' or '1' to '0'). Return the minimum possible length of the longest 
    substring where all characters are identical after performing the operations.

    Args:
        s: A binary string consisting only of '0' and '1'
        numOps: Maximum number of flips allowed (0 <= numOps <= len(s))

    Returns:
        The minimum length of the longest substring with identical characters

    >>> min_longest_substring("000001", 1)
    2
    >>> min_longest_substring("0000", 2)
    1
    >>> min_longest_substring("0101", 0)
    1
    """
    INF = float('inf')

    def min_flips(L: int) -> int:
        # dp[(c, r)] = min flips so far, last char c, current run length r (1..L)
        dp = {}
        for i, ch in enumerate(s):
            orig = int(ch)
            new_dp = {}
            for c in (0, 1):
                cost = 0 if c == orig else 1
                if i == 0:
                    new_dp[(c, 1)] = cost
                    continue
                # continue the run of character c
                for r in range(1, L):
                    if (c, r) in dp:
                        key = (c, r + 1)
                        new_dp[key] = min(new_dp.get(key, INF), dp[(c, r)] + cost)
                # start a new run of character c (previous char was 1 - c)
                best_prev = min((v for (pc, _), v in dp.items() if pc != c), default=INF)
                if best_prev < INF:
                    key = (c, 1)
                    new_dp[key] = min(new_dp.get(key, INF), best_prev + cost)
            dp = new_dp
        return min(dp.values(), default=INF)

    def feasible(L: int) -> bool:
        return min_flips(L) <= numOps

    lo, hi = 1, len(s)
    while lo < hi:
        mid = (lo + hi) // 2
        if feasible(mid):
            hi = mid
        else:
            lo = mid + 1
    return lo

from math import comb
from functools import lru_cache


def count_balanced_graphs(n: int, p: int) -> list[int]:
    """ Given an even positive integer n and a prime number p, for each M from n-1 to n*(n-1)//2,
    count the number of undirected connected simple graphs with n vertices (labeled 1 to n) and M edges
    such that the number of vertices whose shortest distance from vertex 1 is even equals the number
    of vertices whose shortest distance from vertex 1 is odd. Return these counts modulo p.

    Args:
        n: Even positive integer (2 <= n <= 30)
        p: Prime number (10^8 <= p <= 10^9)

    Returns:
        List of counts modulo p for M = n-1, n, n+1, ..., n*(n-1)//2

    >>> count_balanced_graphs(4, 998244353)
    [12, 9, 3, 0]
    >>> count_balanced_graphs(6, 924844033)
    [810, 2100, 3060, 3030, 2230, 1210, 450, 100, 10, 0, 0]
    """
    maxM = n * (n - 1) // 2
    half = n // 2

    def polymul(a, b):
        res = [0] * (len(a) + len(b) - 1)
        for i, x in enumerate(a):
            if x:
                for j, y in enumerate(b):
                    if y:
                        res[i + j] = (res[i + j] + x * y) % p
        return res

    def polyadd(a, b):
        L = max(len(a), len(b))
        res = [0] * L
        for i in range(len(a)):
            res[i] = (res[i] + a[i]) % p
        for i in range(len(b)):
            res[i] = (res[i] + b[i]) % p
        return res

    def trim(a):
        a = list(a)
        while len(a) > 1 and a[-1] == 0:
            a.pop()
        return a

    @lru_cache(maxsize=None)
    def within(s):
        # free edges inside a layer of size s: (1+y)^{C(s,2)}
        e = s * (s - 1) // 2
        return tuple(comb(e, k) % p for k in range(e + 1))

    @lru_cache(maxsize=None)
    def attach(a, b):
        # each of b new vertices independently chooses a nonempty subset of
        # the a previous-layer vertices as parents: ((1+y)^a - 1)^b
        base = [comb(a, k) % p for k in range(a + 1)]
        base[0] = (base[0] - 1) % p
        res = [1]
        for _ in range(b):
            res = polymul(res, base)
        return tuple(res)

    # Count labelled structures. Non-root vertices are labelled 2..n.
    # State: (remaining vertices to place, size of previous layer, parity of
    # previous layer's distance, even-minus-odd balance) -> edge polynomial.
    # Root: distance 0 (even), balance +1, previous layer size 1.
    # We handle labels by choosing which vertices go into each layer with
    # multinomial coefficients.
    from collections import defaultdict

    total = [0] * (maxM + 1)

    # memo over (remaining, prev_size, prev_parity, balance)
    @lru_cache(maxsize=None)
    def go(remaining, prev_size, prev_parity, balance):
        # returns tuple: edge polynomial counting completions of the remaining
        # vertices, where the previous layer has size prev_size and parity prev_parity
        if remaining == 0:
            if balance == 0:
                return (1,)
            return (0,)
        result = [0]
        for s in range(1, remaining + 1):
            new_parity = 1 - prev_parity
            new_balance = balance + (s if new_parity == 0 else -s)
            # choose which labels go to this layer
            label_ways = comb(remaining, s) % p
            edges = polymul(list(attach(prev_size, s)), list(within(s)))
            rest = list(go(remaining - s, s, new_parity, new_balance))
            if all(x == 0 for x in rest):
                continue
            term = polymul(edges, rest)
            term = [(x * label_ways) % p for x in term]
            result = polyadd(result, term)
        return tuple(result)

    # Root layer: vertex 1 at distance 0. Remaining n-1 vertices, previous size 1,
    # previous parity 0 (even), balance +1 from root.
    poly = list(go(n - 1, 1, 0, 1))

    ans = []
    for M in range(n - 1, maxM + 1):
        ans.append(poly[M] % p if M < len(poly) else 0)
    return ans

