MOD = 998244353


def count_strings_by_lcs_length(n: int, m: int, s: str) -> List[int]:
    # Represent LCS table row via its difference bits: bit j set means
    # dp[j+1] - dp[j] == 1 (j from 0..n-1). Start with all zeros (empty t).
    # Transition for appending character c, computed via standard bit-parallel
    # LCS update on the full dp row for clarity.

    def dp_from_mask(mask: int) -> List[int]:
        dp = [0] * (n + 1)
        for j in range(n):
            dp[j + 1] = dp[j] + ((mask >> j) & 1)
        return dp

    def mask_from_dp(dp: List[int]) -> int:
        mask = 0
        for j in range(n):
            if dp[j + 1] - dp[j]:
                mask |= 1 << j
        return mask

    # Precompute transitions: trans[mask][c] -> new mask
    trans = [[0] * 26 for _ in range(1 << n)]
    for mask in range(1 << n):
        old = dp_from_mask(mask)
        for c in range(26):
            ch = chr(ord('a') + c)
            new = [0] * (n + 1)
            for j in range(1, n + 1):
                if s[j - 1] == ch:
                    new[j] = old[j - 1] + 1
                else:
                    new[j] = max(new[j - 1], old[j])
            trans[mask][c] = mask_from_dp(new)

    # Count strings by state
    cur = [0] * (1 << n)
    cur[0] = 1
    for _ in range(m):
        nxt = [0] * (1 << n)
        for mask in range(1 << n):
            v = cur[mask]
            if v == 0:
                continue
            row = trans[mask]
            for c in range(26):
                nm = row[c]
                nxt[nm] = (nxt[nm] + v) % MOD
        cur = nxt

    ans = [0] * (n + 1)
    for mask in range(1 << n):
        k = bin(mask).count('1')
        ans[k] = (ans[k] + cur[mask]) % MOD
    return ans

