def max_alkane_vertices(n: int, edges: List[Tuple[int, int]]) -> int:
    if n < 5:
        return -1
    adj = [[] for _ in range(n + 1)]
    for a, b in edges:
        adj[a].append(b)
        adj[b].append(a)

    NEG = -1  # marks invalid

    def combine(vals, need_extra):
        # vals: list of contributions from children (each >=1 if valid, or NEG)
        # returns size of hanging subtree at v given parent edge kept
        valid = sorted([x for x in vals if x > 0], reverse=True)
        best = 1  # v is a leaf of S
        if len(valid) >= 3:
            best = max(best, 1 + valid[0] + valid[1] + valid[2])
        return best

    parent = [0] * (n + 1)
    order = []
    visited = [False] * (n + 1)
    root = 1
    stack = [root]
    visited[root] = True
    while stack:
        v = stack.pop()
        order.append(v)
        for u in adj[v]:
            if not visited[u]:
                visited[u] = True
                parent[u] = v
                stack.append(u)

    # down[v]: hanging size of v with parent edge kept, using children only
    down = [0] * (n + 1)
    for v in reversed(order):
        vals = [down[u] for u in adj[v] if u != parent[v]]
        down[v] = combine(vals, True)

    # up[v]: hanging size of parent(v) when v is treated as child (parent side subtree)
    up = [0] * (n + 1)
    for v in order:
        children = [u for u in adj[v] if u != parent[v]]
        # contributions from all neighbors of v (for rerooting)
        contrib = {}
        if parent[v] != 0:
            contrib[parent[v]] = up[v]
        for u in children:
            contrib[u] = down[u]
        for u in children:
            vals = [contrib[w] for w in contrib if w != u]
            up[u] = combine(vals, True)

    best = -1
    for v in range(1, n + 1):
        if len(adj[v]) < 4:
            continue
        contribs = []
        if parent[v] != 0:
            contribs.append(up[v])
        for u in adj[v]:
            if u != parent[v]:
                contribs.append(down[u])
        valid = sorted([x for x in contribs if x > 0], reverse=True)
        if len(valid) >= 4:
            best = max(best, 1 + valid[0] + valid[1] + valid[2] + valid[3])
    return best

