from itertools import product


def _ov(lo1: int, hi1: int, lo2: int, hi2: int) -> int:
    return max(0, min(hi1, hi2) - max(lo1, lo2))


def find_cube_placement(V1: int, V2: int, V3: int) -> Optional[Tuple[int, int, int, int, int, int, int, int, int]]:
    """ Given three volumes V1, V2, V3, find a placement of three cubes with side length 7 such that:
    - The volume of the region contained in exactly one cube is V1
    - The volume of the region contained in exactly two cubes is V2
    - The volume of the region contained in all three cubes is V3

    Returns (a1, b1, c1, a2, b2, c2, a3, b3, c3) with all |coord| <= 100, or None.
    """
    total = 3 * 343
    if V1 < 0 or V2 < 0 or V3 < 0:
        return None
    if V1 + 2 * V2 + 3 * V3 != total:
        return None

    # Cube 1 fixed at origin. For a single axis, record for each offset pair (p, q)
    # of cubes 2 and 3 the overlaps (o12, o13, o23, t).
    rng = range(-7, 8)
    axis_info = {}
    for p, q in product(rng, repeat=2):
        o12 = _ov(0, 7, p, p + 7)
        o13 = _ov(0, 7, q, q + 7)
        o23 = _ov(p, p + 7, q, q + 7)
        t = max(0, min(7, p + 7, q + 7) - max(0, p, q))
        axis_info.setdefault((o12, o13, o23, t), (p, q))

    items = list(axis_info.items())

    # Search over per-axis choices (x, y, z).
    for (x12, x13, x23, xt), (xp, xq) in items:
        if xt == 0 and V3 != 0:
            # triple product would be zero on this axis; still possible only if V3 == 0
            pass
        for (y12, y13, y23, yt), (yp, yq) in items:
            for (z12, z13, z23, zt), (zp, zq) in items:
                if xt * yt * zt != V3:
                    continue
                P = x12 * y12 * z12 + x13 * y13 * z13 + x23 * y23 * z23
                if P != V2 + 3 * V3:
                    continue
                if total - 2 * P + 3 * V3 != V1:
                    continue
                return (0, 0, 0, xp, yp, zp, xq, yq, zq)
    return None

