def calculate_black_area_doubled(A: int, B: int, C: int, D: int) -> int:
    """ Calculate twice the area of black-painted regions inside a rectangle on AtCoder's wallpaper pattern.

    >>> calculate_black_area_doubled(0, 0, 3, 3)
    10
    >>> calculate_black_area_doubled(-1, -2, 1, 3)
    11
    >>> calculate_black_area_doubled(-1000000000, -1000000000, 1000000000, 1000000000)
    4000000000000000000
    """
    def unit_black(i: int, j: int) -> int:
        # Doubled black area inside unit cell [i, i+1] x [j, j+1] (value in {0, 1, 2}).
        # Cuts inside a cell: x+y = even crosses it diagonally when i+j is even and i+j+1... handled
        # by the half-cell rule: a cell split by a diagonal contributes 1 (half of doubled 2).
        s = i + j
        base = 1 if (i + (j // 2)) % 2 == 0 else 0
        # Diagonal cut x+y = s+1 splits the cell when s+1 is even, giving a half-cell each side.
        if (s + 1) % 2 == 0:
            return 1
        return 2 * base

    def F(x: int, y: int) -> int:
        # Doubled black area of [0, x] x [0, y], for x, y >= 0 with sign handled by caller.
        if x == 0 or y == 0:
            return 0
        # Period: 2 in x, 4 in y; a full period block [0,2]x[0,4] has doubled black area 8.
        px, py = x // 2, y // 4
        total = px * py * 8
        # Remaining strip in x over full periods in y (width rx = x - 2*px, height 4*py).
        rx, ry = x - 2 * px, y - 4 * py
        for i in range(2 * px, x):
            for j in range(0, 4 * py):
                total += unit_black(i, j)
        for i in range(0, x):
            for j in range(4 * py, y):
                total += unit_black(i, j)
        return total

    def G(x: int, y: int) -> int:
        sign = 1
        if x < 0:
            x = -x
            sign = -sign
        if y < 0:
            y = -y
            sign = -sign
        return sign * F(x, y)

    return G(C, D) - G(A, D) - G(C, B) + G(A, B)

