from fractions import Fraction

def color_at(x, y):
    # (0.5, 0.5) is black. Flip color across each cut: x = n, y = even n, x + y = even n.
    # Count crossings from the base point (0.5, 0.5) to (x, y) and take parity.
    def crossings(a, b):
        # number of cut lines crossed going from a to b on each family
        cnt = 0
        lo, hi = sorted([a, b])
        cnt += (int(hi // 1) - int(lo // 1))           # x = n
        return cnt
    # Use the three families directly.
    def cnt_vertical(x0, x1):
        import math
        return math.floor(x1) - math.floor(x0)
    def cnt_horizontal(y0, y1):
        import math
        return math.floor(y1 / 2) - math.floor(y0 / 2)
    def cnt_diag(s0, s1):
        import math
        return math.floor(s1 / 2) - math.floor(s0 / 2)
    x0, y0 = 0.5, 0.5
    n = cnt_vertical(x0, x) + cnt_horizontal(y0, y) + cnt_diag(x0 + y0, x + y)
    return n % 2 == 0  # True if black

def brute(A, B, C, D, step=Fraction(1, 2)):
    # Sum doubled area by midpoints of step x step cells.
    total = 0
    x = Fraction(A) + step / 2
    while x < C:
        y = Fraction(B) + step / 2
        while y < D:
            if color_at(float(x), float(y)):
                total += 2 * step * step
            y += step
        x += step
    return total

