def find_palindrome_expression(n: int) -> str:
    def is_pal(s: str) -> bool:
        return s == s[::-1]

    def digits_ok(s: str) -> bool:
        return all(c in '123456789' for c in s)

    # Palindromic numbers with digits 1-9 that divide n (candidate factors)
    def pal_factors(m: int):
        res = []
        # generate palindromes with digits 1-9 up to m, dividing m
        # enumerate by length
        length = 1
        while True:
            lo = 10 ** (length - 1)
            if lo > m:
                break
            # generate all palindromes of given length with digits 1-9
            half = (length + 1) // 2
            # enumerate half-digit prefixes
            def gen(prefix, depth):
                if depth == half:
                    s = prefix + (prefix[::-1][1:] if length % 2 else prefix[::-1])
                    v = int(s)
                    if v <= m and m % v == 0:
                        res.append(s)
                    return
                for d in '123456789':
                    gen(prefix + d, depth + 1)
            gen('', 0)
            length += 1
        return res

    if n == 1:
        return '1'

    # Limit string length to 1000 chars; use memoized search over (remaining value)
    # returning a palindromic list of factors (as strings) whose product is value.
    @lru_cache(maxsize=None)
    def solve(m: int):
        if m == 1:
            return ()  # empty product
        # try a single middle factor
        if m <= 10**12:
            # single factor palindrome equal to m
            s = str(m)
            if digits_ok(s) and is_pal(s):
                return (s,)
        for p in pal_factors(m):
            v = int(p)
            if m % (v * v) == 0:
                inner = solve(m // (v * v))
                if inner is not None:
                    return (p,) + inner + (p,)
        return None

    factors = solve(n)
    if factors is None:
        return '-1'
    expr = '*'.join(factors)
    if len(expr) > 1000 or not is_pal(expr):
        return '-1'
    return expr

