        # (1 would not reduce the remaining value, causing infinite recursion)
        res = []
        length = 1
        while 10 ** (length - 1) <= m:
            half = (length + 1) // 2
            stack = ['']
            for _ in range(half):
                stack = [p + d for p in stack for d in '123456789']
            for prefix in stack:
                s = prefix + (prefix[::-1][1:] if length % 2 else prefix[::-1])
                v = int(s)
                if 1 < v <= m and m % v == 0:
                    res.append(s)
            length += 1
        return tuple(res)

