def count_good_sequences(N: int, M: int) -> int:
    def sigma(n):
        total = 0
        d = 1
        while d * d <= n:
            if n % d == 0:
                total += d
                if d * d != n:
                    total += n // d
            d += 1
        return total

    def is_good(n):
        return sigma(n) % 3 == 0

    def count_sequences(n):
        # number of ordered M-tuples of positive integers with product n
        result = 1
        x = n
        p = 2
        while p * p <= x:
            e = 0
            while x % p == 0:
                x //= p
                e += 1
            if e:
                # C(e + M - 1, e)
                num = 1
                for i in range(e):
                    num = num * (M + i) // (i + 1)
                result = result * num
            p += 1
        if x > 1:
            result = result * M
        return result % MOD

    total = 0
    for n in range(1, N + 1):
        if is_good(n):
            total += count_sequences(n)
    return total % MOD

