    # products, so for correctness we brute-force the distribution of the
    # exponent vector for small lengths only.
    from collections import defaultdict

    def step(dist):
        new = defaultdict(int)
        for state, cnt in dist.items():
            for e in exps:
                ns = tuple(s + x for s, x in zip(state, e))
                new[ns] = (new[ns] + cnt) % MOD
        return new

    def weight(state):
        w = 1
        for s in state:
            w = w * (s + 1) % MOD
        return w

    total = 0
    dist = {tuple([0] * P): 1}
    for L in range(1, min(n, 60) + 1):
        dist = step(dist)
        for state, cnt in dist.items():
            total = (total + cnt * weight(state)) % MOD
    return total

