from itertools import permutations
from bisect import bisect_left


def _lis_len(seq):
    tails = []
    for x in seq:
        i = bisect_left(tails, x)
        if i == len(tails):
            tails.append(x)
        else:
            tails[i] = x
    return len(tails)


def _lds_len(seq):
    return _lis_len([-x for x in seq])


def count_special_permutations(A: int, B: int, M: int) -> int:
    n = A * B - 1
    if n <= 0:
        return 0
    count = 0
    for P in permutations(range(1, n + 1)):
        if _lis_len(P) != A or _lds_len(P) != B:
            continue
        ok = False
        for v in range(0, n + 2):
            Q = list(P) + [v + 0.5]
            if _lis_len(Q) == A and _lds_len(Q) == B:
                ok = True
                break
        if ok:
            count += 1
    return count % M

