from typing import List, Tuple, Optional


def min_weight_hamiltonian_walk(n: int, m: int, edges: List[Tuple[int, int, int]]) -> Optional[int]:
    INF = float('inf')
    # All-pairs shortest paths (no negative cycles guaranteed)
    dist = [[INF] * n for _ in range(n)]
    for i in range(n):
        dist[i][i] = 0
    for u, v, w in edges:
        u -= 1
        v -= 1
        if w < dist[u][v]:
            dist[u][v] = w
    for k in range(n):
        for i in range(n):
            if dist[i][k] == INF:
                continue
            for j in range(n):
                nd = dist[i][k] + dist[k][j]
                if dist[k][j] != INF and nd < dist[i][j]:
                    dist[i][j] = nd

    full = (1 << n) - 1
    # dp[mask][v]: min cost of walk visiting exactly mask, ending at v
    dp = [[INF] * n for _ in range(1 << n)]
    for v in range(n):
        dp[1 << v][v] = 0
    for mask in range(1 << n):
        for v in range(n):
            cur = dp[mask][v]
            if cur == INF:
                continue
            for u in range(n):
                if dist[v][u] == INF:
                    continue
                nmask = mask | (1 << u)
                nc = cur + dist[v][u]
                if nc < dp[nmask][u]:
                    dp[nmask][u] = nc
    best = min(dp[full])
    return None if best == INF else int(best)

