from typing import List
from functools import lru_cache


def tic_tac_toe_winner(grid: List[List[int]]) -> str:
    """ Play a modified tic-tac-toe game on a 3x3 grid where each cell has a value.

    Takahashi (first player) and Aoki (second player) take turns choosing white cells.
    When a player chooses a cell, they score the points in that cell and paint it their color
    (Takahashi: red, Aoki: blue).

    The game ends when:
    - A player gets 3 consecutive cells of their color (row/column/diagonal) - that player wins
    - All cells are painted - the player with higher total score wins

    Both players play optimally. The sum of all values in the grid is guaranteed to be odd.

    Args:
        grid: A 3x3 grid of integers representing cell values

    Returns:
        "Takahashi" if Takahashi wins, "Aoki" if Aoki wins

    >>> tic_tac_toe_winner([[0, 0, 0], [0, 1, 0], [0, 0, 0]])
    'Takahashi'
    >>> tic_tac_toe_winner([[-1, 1, 0], [-4, -2, -5], [-4, -1, -5]])
    'Aoki'
    """
    values = [grid[i // 3][i % 3] for i in range(9)]
    lines = [
        (0, 1, 2), (3, 4, 5), (6, 7, 8),
        (0, 3, 6), (1, 4, 7), (2, 5, 8),
        (0, 4, 8), (2, 4, 6),
    ]
    full = (1 << 9) - 1

    def completes_line(mask: int) -> bool:
        for a, b, c in lines:
            if (mask >> a) & 1 and (mask >> b) & 1 and (mask >> c) & 1:
                return True
        return False

    def total(mask: int) -> int:
        return sum(values[i] for i in range(9) if (mask >> i) & 1)

    @lru_cache(maxsize=None)
    def takahashi_wins(t_mask: int, a_mask: int, takahashi_turn: bool) -> bool:
        """Return True if Takahashi wins from this state under optimal play."""
        painted = t_mask | a_mask
        if painted == full:
            return total(t_mask) > total(a_mask)

        options = []
        for i in range(9):
            if (painted >> i) & 1:
                continue
            if takahashi_turn:
                nt = t_mask | (1 << i)
                if completes_line(nt):
                    return True
                options.append(takahashi_wins(nt, a_mask, False))
            else:
                na = a_mask | (1 << i)
                if completes_line(na):
                    return False
                options.append(takahashi_wins(t_mask, na, True))

        # Takahashi wants any winning option; Aoki wants any losing option for Takahashi.
        return any(options) if takahashi_turn else all(options)

    result = takahashi_wins(0, 0, True)
    return "Takahashi" if result else "Aoki"

