def count_paths(N: int, M: int, K: int, extra_edges: list) -> int:
    MOD = 998244353

    # Adjacency: out-edges of each vertex (cycle edge plus extra edges)
    out = {v: [v % N + 1] for v in range(1, N + 1)}
    for x, y in extra_edges:
        out[x].append(y)

    # Vertices with more than one out-edge are branch points.
    branch = [v for v in out if len(out[v]) > 1]
    if not branch:
        # Pure cycle: exactly one walk of any length
        return 1

    # Distance (in steps along the cycle) between branch points, and
    # the count of ways to reach each branch point from each other one
    # via deterministic cycle segments, with step lengths.
    # Standard DP over steps: dp[v] = number of walks ending at v after t steps.
    # K can be large, so we advance using a sparse "event" approach:
    # between branch events the walk is forced along the cycle.
    # We track states as (vertex, time) only at branch points.
    from collections import defaultdict
    import heapq

    branch_set = set(branch)
    # ways[(v, t)] = number of walks reaching branch vertex v exactly at time t
    ways = defaultdict(int)
    ways[(1, 0)] = 1 if 1 in branch_set else 0

    # Start: walk forced from vertex 1 until first branch point
    def forced_next(start):
        # follow cycle from start until hitting a branch vertex (or time limit)
        steps = 0
        v = start
        while True:
            if v in branch_set and steps > 0:
                return v, steps
            v = v % N + 1
            steps += 1
            if steps > N:
                return None, None

    result = 0
    heap = []
    # initial walk from vertex 1
    first_ways = defaultdict(int)
    if 1 in branch_set:
        heapq.heappush(heap, (0, 1, 1))
    else:
        v, s = forced_next(1)
        if v is None or s > K:
            v = None
        if v is not None:
            heapq.heappush(heap, (s, v, 1))

    if 1 not in branch_set:
        # Walk forced until first branch point; if none reached within K, answer is 1
        pass
    else:
        pass

    best = defaultdict(int)
    if 1 in branch_set:
        best[(0, 1)] = 1
    else:
        v, s = forced_next(1)
        if v is None or s > K:
            return 1 if s is None or s > K else 0
        best[(s, v)] = 1

    # Process states in increasing time
    states = sorted(best.keys())
    ways_at = defaultdict(int)
    for (t, v), c in best.items():
        ways_at[(t, v)] += c

    pending = defaultdict(int)
    for k, c in ways_at.items():
        pending[k] += c

    times = sorted(pending.keys())
    import bisect
    timeline = defaultdict(lambda: defaultdict(int))
    for (t, v), c in pending.items():
        timeline[t][v] = (timeline[t][v] + c) % MOD

    cur_times = sorted(timeline.keys())
    processed = set()
    while cur_times:
        t = cur_times.pop(0)
        if t in processed or t > K:
            continue
        processed.add(t)
        for v, c in timeline[t].items():
            if c == 0:
                continue
            # branch at v: choose each out-edge
            for w in out[v]:
                if w == v % N + 1:
                    # cycle edge: go to next branch point along cycle
                    nxt, s = forced_next(w)
                    if nxt is None:
                        s = N
                        nxt = None
                else:
                    nxt, s = w, 1
                nt = t + s
                if nt == K and (nxt is None or True):
                    if nxt is not None and nxt in branch_set and nt == K:
                        result = (result + c) % MOD
                    elif nxt is not None and nt == K:
                        result = (result + c) % MOD
                    continue
                if nt < K and nxt is not None:
                    if nt not in timeline:
                        bisect.insort(cur_times, nt)
                    timeline[nt][nxt] = (timeline[nt][nxt] + c) % MOD

