def minimum_shipping_dissatisfaction(n: int, k: int, x: int, order_days: List[int]) -> int:
    # dp[i] maps last shipment day -> minimal total dissatisfaction
    # for the first i orders (all shipped, last shipment on that day).
    dp = [dict() for _ in range(n + 1)]
    dp[0][-(10 ** 30)] = 0

    for i in range(n):
        if not dp[i]:
            continue
        for last_day, cost in dp[i].items():
            for size in range(1, k + 1):
                j = i + size
                if j > n:
                    break
                ship = max(order_days[j - 1], last_day + x)
                batch_cost = sum(ship - order_days[t] for t in range(i, j))
                new_cost = cost + batch_cost
                prev = dp[j].get(ship)
                if prev is None or new_cost < prev:
                    dp[j][ship] = new_cost

    return min(dp[n].values())

