from functools import lru_cache
from itertools import product


def _fixed_count(n, rows, cols):
    """Count fixed entries for the class with row sums `rows` and column sums `cols`.
    An entry is fixed if it has the same value in every matrix with these sums.
    Brute-force: enumerate all matrices with these margins."""
    matrices = []

    def build(i, cur_cols, mat):
        if i == n:
            if all(c == 0 for c in cur_cols):
                matrices.append([row[:] for row in mat])
            return
        for combo in product((0, 1), repeat=n):
            if sum(combo) != rows[i]:
                continue
            if any(cur_cols[j] - combo[j] < 0 for j in range(n)):
                continue
            new_cols = [cur_cols[j] - combo[j] for j in range(n)]
            build(i + 1, new_cols, mat + [list(combo)])

    build(0, list(cols), [])
    if not matrices:
        return None
    fixed = 0
    for i in range(n):
        for j in range(n):
            vals = {m[i][j] for m in matrices}
            if len(vals) == 1:
                fixed += 1
    return fixed


@lru_cache(maxsize=None)
def _achievable_ks(n):
    """Set of fixed-entry counts over all margin pairs for n x n binary matrices.
    Only feasible for very small n."""
    achievable = set()
    row_sets = [tuple(r) for r in product(range(n + 1), repeat=n)]
    for rows in row_sets:
        if list(rows) != sorted(rows, reverse=True):
            continue
        for cols in row_sets:
            if sum(rows) != sum(cols):
                continue
            if list(cols) != sorted(cols, reverse=True):
                continue
            f = _fixed_count(n, rows, cols)
            if f is not None:
                achievable.add(f)
    return frozenset(achievable)


def matrix_with_k_fixed_elements_exists(n: int, k: int) -> bool:
    if k < 0 or k > n * n:
        return False
    if n <= 4:
        return k in _achievable_ks(n)
    # Not yet verified for larger n; returning a guess would be unreliable.
    raise NotImplementedError("Only n <= 4 is verified by enumeration.")

