    """ Given a string s of length n consisting of 'A', 'B', 'C', and '?', count the number
    of ways to replace each '?' with 'A', 'B', or 'C' such that the resulting string contains
    at least k "good strings" as contiguous substrings.

    A "good string" is a non-empty string that can be turned into an empty string by:
    - Operation 1: Choose two identical characters and delete them
    - Operation 2: Choose one A, one B, and one C and delete them

    Substrings at different positions are counted separately even if they are identical.
    Return the count modulo 998244353.
    """
    def is_good(t):
        # Reduce using a stack; a string is good iff it can be fully erased.
        # Try exhaustive reduction via memoized search over strings (small lengths).
        @lru_cache(maxsize=None)
        def can_erase(u):
            if not u:
                return True
            m = len(u)
            for i in range(m):
                for j in range(i + 1, m):
                    if u[i] == u[j]:
                        rest = u[:i] + u[i + 1:j] + u[j + 1:]
                        if can_erase(rest):
                            return True
            if m >= 3:
                for i in range(m):
                    for j in range(i + 1, m):
                        for l in range(j + 1, m):
                            trip = {u[i], u[j], u[l]}
                            if trip == {'A', 'B', 'C'}:
                                rest = [u[x] for x in range(m) if x not in (i, j, l)]
                                if can_erase(''.join(rest)):
                                    return True
            return False
        return can_erase(t)

    total = 0
    qs = [i for i, ch in enumerate(s) if ch == '?']
    for assign in range(3 ** len(qs)):
        arr = list(s)
        a = assign
        for idx in qs:
            arr[idx] = 'ABC'[a % 3]
            a //= 3
        t = ''.join(arr)
