from functools import lru_cache
from math import comb

def count_balanced_graphs(n: int, p: int) -> list[int]:
    half = n // 2
    maxM = n * (n - 1) // 2
    # Number of edges between layer sizes a (upper) and b (lower) such that
    # every vertex in the lower layer has at least one neighbor in the upper layer.
    # Returns polynomial in edge count: dict edges -> ways (exact integers).
    @lru_cache(maxsize=None)
    def bip_poly(a, b):
        # each of b vertices picks a nonempty subset of a upper vertices
        # ways with exactly e edges: coefficient of x^e in (( 1+x)^a - 1)^b
        base = [0] * (a + 1)
        for k in range(1, a + 1):
            base[k] = comb(a, k)
        # raise base polynomial to power b
        result = [1]
        for _ in range(b):
            result = poly_mul(result, base)
        return tuple(result)

    def poly_mul(f, g):
        h = [0] * (len(f) + len(g) - 1)
        for i, x in enumerate(f):
            if x == 0:
                continue
            for j, y in enumerate(g):
                if y:
                    h[i + j] += x * y
        return h

    # Within-layer edges are allowed? In BFS layering, same-layer edges are
    # permitted (they don't change distances). Each layer of size s contributes
    # a free choice of subset of its C(s,2) internal edges.
    @lru_cache(maxsize=None)
    def inner_poly(s):
        # (1+x)^{C(s,2)}
        m = s * (s - 1) // 2
        return tuple(comb(m, k) for k in range(m + 1))

    # Count connected graphs via DP over layers with exact integer arithmetic.
    # State: (vertices placed, even-vertex count, odd-vertex count, layer index parity,
    #         last layer size) -> polynomial in edges.
    # We enumerate compositions of the remaining vertices into layers.
    @lru_cache(maxsize=None)
    def dp(placed, even_cnt, odd_cnt, last_size, last_parity):
        # returns tuple poly over edges, counting ways to finish from this state
        # where the current last layer has size last_size at parity last_parity.
        result = [0] * (maxM + 1)
        if placed == n:
            if even_cnt == odd_cnt:
                result[0] = 1
            return tuple(result)
        next_parity = 1 - last_parity
        for s in range(1, n - placed + 1):
            if next_parity == 0:
                ne, no = even_cnt + s, odd_cnt
            else:
                ne, no = even_cnt, odd_cnt + s
            if ne > half or no > half:
                continue
            link = bip_poly(last_size, s)
            inner = inner_poly(s)
            step = poly_mul(list(link), list(inner))
            sub = dp(placed + s, ne, no, s, next_parity)
            combined = poly_mul(step, list(sub))
            for i, v in enumerate(combined):
                if i <= maxM:
                    result[i] += v
        return tuple(result)

    # Layer 0: vertex 1 alone (even). Layer 1 must have >=1 vertex.
    # Within-layer-0 has no internal edges (size 1).
    total = [0] * (maxM + 1)
    if n == 1:
        pass
    else:
        sub = dp(1, 1, 0, 1, 0)
        for i, v in enumerate(sub):
            if i <= maxM:
                total[i] = v

    out = []
    for M in range(n - 1, maxM + 1):
        out.append(total[M] % p)
    return out

from itertools import combinations
from collections import deque

def count_balanced_graphs(n: int, p: int) -> list[int]:
    pairs = list(combinations(range(n), 2))
    m_total = len(pairs)
    counts = [0] * (m_total + 1)

    for mask in range(1 << m_total):
        adj = [[] for _ in range(n)]
        edges = 0
        for i, (u, v) in enumerate(pairs):
            if mask >> i & 1:
                adj[u].append(v)
                adj[v].append(u)
                edges += 1
        dist = [-1] * n
        dist[0] = 0
        q = deque([0])
        while q:
            x = q.popleft()
            for y in adj[x]:
                if dist[y] < 0:
                    dist[y] = dist[x] + 1
                    q.append(y)
        if min(dist) < 0:
            continue
        even = sum(1 for d in dist if d % 2 == 0)
        odd = n - even
        if even == odd:
            counts[edges] += 1

    return [counts[M] % p for M in range(n - 1, m_total + 1)]

