def sum_good_sequence_scores(n: int, a: list[int]) -> int:
    from math import gcd

    def divisors(x):
        return [d for d in range(1, x + 1) if x % d == 0]

    def mobius(x):
        res = 1
        m = x
        p = 2
        while p * p <= m:
            if m % p == 0:
                m //= p
                if m % p == 0:
                    return 0
                res = -res
            p += 1
        if m > 1:
            res = -res
        return res

    # Candidate values for elements of S: any positive integer. Each S[i] must divide
    # a bounded set; since f(p/q)=pq and pq <= 1000 for each pair, every element is <= 1000.
    LIMIT = 1000

    def count_with_gcd_multiple(d):
        # Sum of products over good sequences where every element is divisible by d.
        # Elements must be multiples of d, so S[i] = d * T[i], and the constraint becomes
        # f(T[i]/T[i+1]) pattern with a[i] scaled: S[i]*S[i+1]/gcd^2 = a[i].
        # Enumerate sequences directly via DP over the value of the current element.
        # dp maps value of S[i] -> sum of products of S[0..i] ending with that value.
        dp = {}
        for v in range(d, LIMIT + 1, d):
            dp[v] = v
        for i in range(n - 1):
            target = a[i]
            ndp = {}
            for u, val in dp.items():
                for v in range(d, LIMIT + 1, d):
                    g = gcd(u, v)
                    if (u // g) * (v // g) == target:
                        ndp[v] = (ndp.get(v, 0) + val * v) % MOD
            dp = ndp
            if not dp:
                return 0
        return sum(dp.values()) % MOD

    total = 0
    for d in range(1, LIMIT + 1):
        mu = mobius(d)
        if mu == 0:
            continue
        total = (total + mu * count_with_gcd_multiple(d)) % MOD
    return total % MOD

