        # min(e, f) = 0 (exactly one side carries the prime).
        # Start: e_0 can be any value that is compatible with step 0.
        # Enumerate candidate exponents for e_0.
        if n - 1 == 0:
            return 1
        cmax = max(c) if c else 0
        dp = {}
        for e in range(0, cmax + 1):
            if force_positive and e == 0:
                continue
            dp[e] = pow(p, e, MOD)
        for i in range(n - 1):
