        # Efficient counting for larger n is not implemented.
        return 0

    deg_of = [0] * V
    for a, b in edges:
        deg_of[a] += 1
        deg_of[b] += 1

    def orientable(deg):
        if sum(deg) != m:
            return False
        for mask in range(1, 1 << V):
            dsum = 0
            for v in range(V):
                if mask >> v & 1:
                    dsum += deg[v]
            inside = 0
            for a, b in edges:
                if (mask >> a & 1) and (mask >> b & 1):
                    inside += 1
            if dsum < inside:
                return False
        return True

    count = 0
    for tup in product(*[range(deg_of[v] + 1) for v in range(V)]):
        if orientable(tup):
            count += 1
    return count % MOD

