def count_strongly_connected_partitions(n: int, s: str) -> int:
    MOD = 998244353
    m = 2 * n
    if s.count('W') != n or s.count('B') != n:
        return 0

    whites = [i for i in range(m) if s[i] == 'W']
    blacks = [i for i in range(m) if s[i] == 'B']

    def strongly_connected(edges):
        adj = [[] for _ in range(m)]
        radj = [[] for _ in range(m)]
        for i in range(m - 1):
            adj[i].append(i + 1)
            radj[i + 1].append(i)
        for u, v in edges:
            adj[u].append(v)
            radj[v].append(u)

        def reach(g):
            seen = [False] * m
            stack = [0]
            seen[0] = True
            while stack:
                x = stack.pop()
                for y in g[x]:
                    if not seen[y]:
                        seen[y] = True
                        stack.append(y)
            return all(seen)

        return reach(adj) and reach(radj)

    count = 0

    def backtrack(idx, used_b, edges):
        nonlocal count
        if idx == len(whites):
            if strongly_connected(edges):
                count += 1
            return
        w = whites[idx]
        for j, b in enumerate(blacks):
            if not (used_b >> j) & 1:
                edges.append((w, b))
                backtrack(idx + 1, used_b | (1 << j), edges)
                edges.pop()

    backtrack(0, 0, [])
    return count % MOD

