from typing import Optional, List


def solve_grid(n: int, r: str, c: str) -> Optional[List[str]]:
    """ Given an integer N and strings R and C of length N consisting of 'A', 'B', and 'C',
    determine if it's possible to fill an N×N grid such that:
    - Each row and column contains exactly one 'A', one 'B', and one 'C'
    - The leftmost character written in the i-th row matches the i-th character of R
    - The topmost character written in the i-th column matches the i-th character of C

    Empty cells are represented by '.' in the output.

    Args:
        n: The size of the grid (3 <= n <= 5)
        r: String of length n specifying leftmost characters in each row
        c: String of length n specifying topmost characters in each column

    Returns:
        A list of n strings representing the filled grid if possible, None otherwise.
        Each string has length n, where '.' represents empty cells.

    >>> solve_grid(3, 'ABC', 'ABC')
    ['ABC', 'BCA', 'CAB']
    >>> solve_grid(3, 'AAA', 'BBB')
    None
    """
    letters = ['A', 'B', 'C']
    grid = [['.'] * n for _ in range(n)]

    # Track which letters are used in each row and column
    row_used = [set() for _ in range(n)]
    col_used = [set() for _ in range(n)]

    def first_letter_in_row(i):
        for j in range(n):
            if grid[i][j] != '.':
                return grid[i][j]
        return None

    def first_letter_in_col(j):
        for i in range(n):
            if grid[i][j] != '.':
                return grid[i][j]
        return None

    def backtrack(pos):
        if pos == n * n:
            # Verify full row/column constraints
            for i in range(n):
                if set(grid[i]) - {'.'} != {'A', 'B', 'C'} or sorted(
                    ch for ch in grid[i] if ch != '.'
                ) != ['A', 'B', 'C']:
                    return False
            for j in range(n):
                col = [grid[i][j] for i in range(n)]
                if sorted(ch for ch in col if ch != '.') != ['A', 'B', 'C']:
                    return False
            # Check R and C constraints
            for i in range(n):
                if first_letter_in_row(i) != r[i]:
                    return False
            for j in range(n):
                if first_letter_in_col(j) != c[j]:
                    return False
            return True

        i, j = divmod(pos, n)
        # Each row/column may hold at most one of each letter, and can be
        # left empty as long as the final counts end up correct.
        options = ['.'] + [ch for ch in letters if ch not in row_used[i] and ch not in col_used[j]]
        for ch in options:
            if ch != '.':
                row_used[i].add(ch)
                col_used[j].add(ch)
            grid[i][j] = ch
            if ch == '.' or True:
                if feasible_prefix(i, j):
                    if backtrack(pos + 1):
                        return True
            if ch != '.':
                row_used[i].discard(ch)
                col_used[j].discard(ch)
            grid[i][j] = '.'
        return False

    def feasible_prefix(i, j):
        # Prune: if a row is finished (j == n-1), it must contain all three letters
        if j == n - 1 and row_used[i] != {'A', 'B', 'C'}:
            return False
        # Prune: if a column is finished (i == n-1), it must contain all three letters
        if i == n - 1 and col_used[j] != {'A', 'B', 'C'}:
            return False
        # Prune: leftmost letter of row i must match r[i] once set
        if j == 0 and grid[i][0] != '.' and grid[i][0] != r[i]:
            return False
        # Prune: topmost letter of column j must match c[j] once set
        if i == 0 and grid[0][j] != '.' and grid[0][j] != c[j]:
            return False
        return True

    # Pre-check that the leftmost/topmost constraints are consistent with the 'exactly one per row/col' rule
    if backtrack(0):
        return [''.join(row) for row in grid]
    return None

