def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """ Determine if it's possible to place rectangular tiles on an H×W grid such that:
    - Every cell is covered by exactly one tile
    - Tiles can be rotated (so a 2×3 tile can be placed as 3×2)
    - Some tiles may remain unused
    - Tiles must be aligned with grid cells and cannot extend outside

    Args:
        n: Number of available tiles (1 ≤ n ≤ 7)
        h: Height of the grid (1 ≤ h ≤ 10)
        w: Width of the grid (1 ≤ w ≤ 10)
        tiles: List of (a, b) tuples where tile i has dimensions a×b (1 ≤ a, b ≤ 10)

    Returns:
        True if the grid can be perfectly tiled, False otherwise

    >>> can_tile_grid(5, 5, 5, [(1, 1), (3, 3), (4, 4), (2, 3), (2, 5)])
    True
    >>> can_tile_grid(1, 1, 2, [(2, 3)])
    False
    >>> can_tile_grid(1, 2, 2, [(1, 1)])
    False
    """
    total_cells = h * w
    tile_area_sum = sum(a * b for a, b in tiles)
    if tile_area_sum < total_cells:
        return False

    full_mask = (1 << total_cells) - 1

    # Precompute placements: for each tile index, list of (cell-bitmask) for each
    # rotation placed at each origin, keyed by the cell index of its top-left cell.
    placements = []
    for idx, (a, b) in enumerate(tiles):
        orientations = {(a, b), (b, a)}
        per_tile = {}
        for (rh, rw) in orientations:
            if rh > h or rw > w:
                continue
            for r in range(h - rh + 1):
                for c in range(w - rw + 1):
                    mask = 0
                    for dr in range(rh):
                        for dc in range(rw):
                            mask |= 1 << ((r + dr) * w + (c + dc))
                    # top-left cell index = r*w + c
                    per_tile.setdefault(r * w + c, []).append(mask)
        placements.append(per_tile)

    @lru_cache(maxsize=None)
    def solve(covered: int, used: int) -> bool:
        if covered == full_mask:
            return True
        # first uncovered cell (row-major)
        free = ~covered & full_mask
        pos = (free & -free).bit_length() - 1
        for idx in range(n):
            if used & (1 << idx):
                continue
            for mask in placements[idx].get(pos, []):
                if mask & covered == 0:
                    if solve(covered | mask, used | (1 << idx)):
                        return True
        return False

    return solve(0, 0)

from functools import lru_cache

def find_palindrome_expression(n: int) -> str:
    def is_pal(s: str) -> bool:
        return s == s[::-1]

    def valid_factor(s: str) -> bool:
        return is_pal(s) and all(c in '123456789' for c in s)

    @lru_cache(maxsize=None)
    def pal_divisors(m: int):
        # Palindromes over digits 1-9 that divide m, excluding 1.
        # Built from divisors of m rather than enumerating all palindromes.
        divs = []
        i = 1
        while i * i <= m:
            if m % i == 0:
                divs.append(i)
                if i != m // i:
                    divs.append(m // i)
            i += 1
        return tuple(sorted(d for d in divs if d > 1 and valid_factor(str(d))))

    @lru_cache(maxsize=None)
    def solve(m: int):
        # Returns a tuple of factor strings forming a palindromic sequence
        # whose product is m, or None. Requires at least one factor pair
        # when m > 9 (so a bare multi-digit number is not returned).
        if m == 1:
            return ()
        for p in pal_divisors(m):
            sq = p * p
            if m % sq == 0:
                inner = solve(m // sq)
                if inner is not None:
                    return (str(p),) + inner + (str(p),)
        if m <= 9:
            return (str(m),)
        return None

    if n == 1:
        return '1'
    factors = solve(n)
    if factors is None:
        return '-1'
    expr = '*'.join(factors)
    if len(expr) > 1000 or not is_pal(expr):
        return '-1'
    return expr

