def _lis_len(seq):
    tails = []
    for x in seq:
        i = bisect_left(tails, x)
        if i == len(tails):
            tails.append(x)
        else:
            tails[i] = x
    return len(tails)


def _lds_len(seq):
    return _lis_len([-x for x in seq])


def count_special_permutations(A: int, B: int, M: int) -> int:
    n = A * B - 1
    if n <= 0:
        return 0
    count = 0
    for P in permutations(range(1, n + 1)):
        if _lis_len(P) != A or _lds_len(P) != B:
            continue
        ok = False
        for v in range(0, n + 2):
            Q = list(P) + [v + 0.5]
            if _lis_len(Q) == A and _lds_len(Q) == B:
                ok = True
                break
        if ok:
            count += 1
    return count % M

from collections import deque

def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    def bounds2(t):
        i, j, k = t
        if (i - j) % 2 == 0:
            return (2 * i * K, 2 * (j * K + k), 2 * (i + 1) * K, 2 * (j * K + k + 1))
        return (2 * (i * K + k), 2 * j * K, 2 * (i * K + k + 1), 2 * (j + 1) * K)

    def contains(t, x2, y2):
        x0, y0, x1, y1 = bounds2(t)
        return x0 <= x2 <= x1 and y0 <= y2 <= y1

    def find(x2, y2):
        bi = x2 // (2 * K)
        bj = y2 // (2 * K)
        for i in range(bi - 1, bi + 2):
            for j in range(bj - 1, bj + 2):
                for k in range(K):
                    if contains((i, j, k), x2, y2):
                        return (i, j, k)
        return None

    def adjacent(a, b):
        ax0, ay0, ax1, ay1 = bounds2(a)
        bx0, by0, bx1, by1 = bounds2(b)
        xo = min(ax1, bx1) - max(ax0, bx0)
        yo = min(ay1, by1) - max(ay0, by0)
        if xo > 0 and (ay1 == by0 or by1 == ay0):
            return True
        if yo > 0 and (ax1 == bx0 or bx1 == ax0):
            return True
        return False

    s = find(2 * S_x + 1, 2 * S_y + 1)
    t = find(2 * T_x + 1, 2 * T_y + 1)
    if s is None or t is None:
        return -1
    if s == t:
        return 0

    dist = {s: 0}
    q = deque([s])
    while q:
        cur = q.popleft()
        if cur == t:
            return dist[cur]
        ci, cj, _ = cur
        for di in range(-2, 3):
            for dj in range(-2, 3):
                for k in range(K):
                    nb = (ci + di, cj + dj, k)
                    if nb not in dist and adjacent(cur, nb):
                        dist[nb] = dist[cur] + 1
                        q.append(nb)
    return -1

