def count_good_integers(num1: str, num2: str, min_sum: int, max_sum: int) -> int:
    MOD = 10**9 + 7

    def count_upto(s: str) -> int:
        # Count x in [0, int(s)] with min_sum <= digit_sum(x) <= max_sum
        # Digit DP: dp[t] = number of ways (prefix-free counting) to reach digit sum t
        n = len(s)
        max_total = 9 * n
        # ways[k][t] = number of k-digit strings (leading zeros allowed) with digit sum t
        ways = [[0] * (max_total + 1) for _ in range(n + 1)]
        ways[0][0] = 1
        for k in range(1, n + 1):
            for t in range(max_total + 1):
                if ways[k - 1][t]:
                    for d in range(10):
                        if t + d <= max_total:
                            ways[k][t + d] = (ways[k][t + d] + ways[k - 1][t]) % MOD

        def count_range(lo: int, hi: int, length: int) -> int:
            # number of length-digit strings with digit sum in [lo, hi]
            total = 0
            for t in range(max(lo, 0), min(hi, 9 * length) + 1):
                total = (total + ways[length][t]) % MOD
            return total

        result = 0
        prefix_sum = 0
        for i, ch in enumerate(s):
            cur = int(ch)
            remaining = n - i - 1
            for d in range(cur):
                ps = prefix_sum + d
                # remaining digits free: need total in [min_sum, max_sum]
                lo = min_sum - ps
                hi = max_sum - ps
                result = (result + count_range(lo, hi, remaining)) % MOD
            prefix_sum += cur
        # include s itself
        if min_sum <= prefix_sum <= max_sum:
            result = (result + 1) % MOD
        return result

    def digit_sum_str(s: str) -> int:
        return sum(int(c) for c in s)

    total = count_upto(num2) - count_upto(num1)
    if min_sum <= digit_sum_str(num1) <= max_sum:
        total += 1
    return total % MOD

def min_changes_for_semi_palindromes(s: str, k: int) -> int:
    n = len(s)

    # cost[i][j]: min changes to make s[i..j] (inclusive) a semi-palindrome
    cost = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(i + 1, n):
            length = j - i + 1
            best = float('inf')
            for d in range(1, length):
                if length % d != 0:
                    continue
                changes = 0
                # For each residue class r modulo d, check palindrome
                for r in range(d):
                    idxs = list(range(i + r, j + 1, d))
                    a, b = 0, len(idxs) - 1
                    while a < b:
                        if s[idxs[a]] != s[idxs[b]]:
                            changes += 1
                        a += 1
                        b -= 1
                best = min(best, changes)
            cost[i][j] = best

    INF = float('inf')
    # dp[p][e]: min changes to split s[0..e-1] into p parts
    dp = [[INF] * (n + 1) for _ in range(k + 1)]
    dp[0][0] = 0
    for p in range(1, k + 1):
        for e in range(p, n + 1):
            for st in range(p - 1, e):
                if dp[p - 1][st] == INF:
                    continue
                # substring s[st..e-1]
                if e - st >= 2:
                    c = dp[p - 1][st] + cost[st][e - 1]
                    if c < dp[p][e]:
                        dp[p][e] = c
    return dp[k][n]

def count_stepping_numbers(low: str, high: str) -> int:
    """ Count the number of stepping numbers in the inclusive range [low, high].

    A stepping number is an integer such that all of its adjacent digits have an 
    absolute difference of exactly 1. A stepping number should not have a leading zero.

    Args:
        low: A string representing a positive integer (1 <= int(low) <= int(high) < 10^100)
        high: A string representing a positive integer

    Returns:
        The count of stepping numbers in the range [low, high], modulo 10^9 + 7

    >>> count_stepping_numbers("1", "11")
    10
    >>> count_stepping_numbers("90", "101")
    2
    >>> count_stepping_numbers("4", "9")
    6
    """
    MOD = 10**9 + 7

    def is_stepping(s: str) -> bool:
        return all(abs(int(s[i]) - int(s[i + 1])) == 1 for i in range(len(s) - 1))

    def count_upto(num: str) -> int:
        # Count stepping numbers in [1, int(num)] (inclusive)
        n = len(num)
        from functools import lru_cache

        @lru_cache(maxsize=None)
        def dp(pos: int, prev: int, tight: bool, started: bool) -> int:
            if pos == n:
                return 1 if started else 0
            limit = int(num[pos]) if tight else 9
            total = 0
            for d in range(limit + 1):
                new_tight = tight and d == limit
                if not started:
                    if d == 0:
                        # still not started (leading zero)
                        total += dp(pos + 1, -1, new_tight, False)
                    else:
                        total += dp(pos + 1, d, new_tight, True)
                else:
                    if abs(d - prev) == 1:
                        total += dp(pos + 1, d, new_tight, True)
            return total % MOD

        return dp(0, -1, True, False)

    result = (count_upto(high) - count_upto(low) + (1 if is_stepping(low) else 0)) % MOD
    return result

