MOD = 998244353


def dice_sum_probability(n: int, dice_faces: List[int]) -> int:
    FULL = (1 << 11) - 1  # bits 0..10 represent sums 0..10
    inv_cache = {}

    def inv(x: int) -> int:
        if x not in inv_cache:
            inv_cache[x] = pow(x, MOD - 2, MOD)
        return inv_cache[x]

    # dp maps reachable-sum bitmask -> probability (mod MOD)
    dp = {1: 1}  # initially only sum 0 is reachable (bit 0)

    for m in dice_faces:
        p_each = inv(m)
        new_dp = {}
        small = min(m, 10)
        for mask, prob in dp.items():
            # die shows a value v in 1..small (each with prob 1/m)
            for v in range(1, small + 1):
                nmask = (mask | (mask << v)) & FULL
                new_dp[nmask] = (new_dp.get(nmask, 0) + prob * p_each) % MOD
            # die shows a value > 10: mask unchanged
            if m > 10:
                p_big = (m - 10) * p_each % MOD
                new_dp[mask] = (new_dp.get(mask, 0) + prob * p_big) % MOD
        dp = new_dp

    ans = 0
    for mask, prob in dp.items():
        if mask & (1 << 10):
            ans = (ans + prob) % MOD
    return ans

