def min_sensor_cost(n: int, sections: List[int], sensor1: Tuple[int, int, int], sensor2: Tuple[int, int, int]) -> int:
    L1, C1, K1 = sensor1
    L2, C2, K2 = sensor2
    INF = float("inf")

    # dp[i][j] = minimum cost using i type-1 sensors and j type-2 sensors so far
    dp = [[INF] * (K2 + 1) for _ in range(K1 + 1)]
    dp[0][0] = 0

    for D in sections:
        # For this section, enumerate options (a, b) that cover D, with minimal b for each a
        options = []
        max_a = min(K1, -(-D // L1))  # ceil(D / L1)
        for a in range(max_a + 1):
            remaining = D - a * L1
            if remaining <= 0:
                b = 0
            else:
                b = -(-remaining // L2)  # ceil(remaining / L2)
            if b <= K2:
                options.append((a, b, a * C1 + b * C2))

        new_dp = [[INF] * (K2 + 1) for _ in range(K1 + 1)]
        for i in range(K1 + 1):
            for j in range(K2 + 1):
                if dp[i][j] == INF:
                    continue
                for a, b, cost in options:
                    ni, nj = i + a, j + b
                    if ni <= K1 and nj <= K2:
                        val = dp[i][j] + cost
                        if val < new_dp[ni][nj]:
                            new_dp[ni][nj] = val
        dp = new_dp

    best = min(min(row) for row in dp)
    return -1 if best == INF else int(best)

