def max_knight_moves(kx: int, ky: int, positions: List[List[int]]) -> int:
    N = 50
    KNIGHT = [(1, 2), (2, 1), (-1, 2), (-2, 1), (1, -2), (2, -1), (-1, -2), (-2, -1)]

    def bfs(sx, sy):
        dist = [[-1] * N for _ in range(N)]
        dist[sx][sy] = 0
        q = deque([(sx, sy)])
        while q:
            x, y = q.popleft()
            for dx, dy in KNIGHT:
                nx, ny = x + dx, y + dy
                if 0 <= nx < N and 0 <= ny < N and dist[nx][ny] < 0:
                    dist[nx][ny] = dist[x][y] + 1
                    q.append((nx, ny))
        return dist

    n = len(positions)
    pts = [(p[0], p[1]) for p in positions]

    # Distance from the knight's start to each pawn
    start_dist = bfs(kx, ky)
    cost_start = [start_dist[x][y] for x, y in pts]

    # Distance between each pawn and every other pawn (knight moves to a captured pawn)
    cost = [[0] * n for _ in range(n)]
    for i, (x, y) in enumerate(pts):
        d = bfs(x, y)
        for j, (tx, ty) in enumerate(pts):
            cost[i][j] = d[tx][ty]

    full = (1 << n) - 1

    # State: mask of remaining pawns, current knight location
    # (-1 = start, otherwise index of last captured pawn), and whose turn.
    @lru_cache(maxsize=None)
    def solve(mask: int, last: int, alice_turn: bool) -> int:
        if mask == 0:
            return 0
        best = None
        for j in range(n):
            if mask >> j & 1:
                step = cost_start[j] if last < 0 else cost[last][j]
                total = step + solve(mask & ~(1 << j), j, not alice_turn)
                if best is None:
                    best = total
                elif alice_turn:
                    best = max(best, total)
                else:
                    best = min(best, total)
        return best

    return solve(full, -1, True)

