def count_valid_grids(H: int, W: int, grid: list[str]) -> int:
    MOD = 998244353

    # Transpose so the profile width is the smaller dimension.
    if W > H:
        grid = [''.join(grid[r][c] for r in range(H)) for c in range(W)]
        H, W = W, H

    # Now W <= 14 (since H * W <= 200 and W <= H).
    # State: tuple of length W holding the color (0,1,2) of the most recent
    # cell in each column; -1 means "nothing placed yet" (first row).
    dp = {tuple([-1] * W): 1}

    for r in range(H):
        row = grid[r]
        for c in range(W):
            ch = row[c]
            if ch == '?':
                options = (0, 1, 2)
            else:
                options = (int(ch) - 1,)

            new_dp = {}
            for state, ways in dp.items():
                up = state[c]          # cell above (or -1 if first row)
                left = state[c - 1] if c > 0 else -1  # cell to the left, already updated this row
                for col in options:
                    if col == up or (c > 0 and col == left):
                        continue
                    lst = list(state)
                    lst[c] = col
                    key = tuple(lst)
                    new_dp[key] = (new_dp.get(key, 0) + ways) % MOD
            dp = new_dp
            if not dp:
                return 0

    return sum(dp.values()) % MOD

