def card_game_winner(n: int, m: int, l: int, takahashi_cards: List[int], aoki_cards: List[int], table_cards: List[int]) -> str:
    # Brute-force minimax over the full state. Only feasible for small inputs.
    # The move rules are an assumption and may not match the tests.

    @lru_cache(maxsize=None)
    def can_win(hand_mover: Tuple[int, ...], hand_other: Tuple[int, ...], table: Tuple[int, ...]) -> bool:
        # Returns True if the player to move (holding hand_mover) wins.
        moved_any = False
        for i, card in enumerate(hand_mover):
            new_mover = hand_mover[:i] + hand_mover[i+1:]
            new_table = tuple(sorted(table + (card,)))
            # Option 1: play without taking
            moved_any = True
            if not can_win(hand_other, new_mover, new_table):
                return True
            # Option 2: play and take one smaller table card
            for j, t in enumerate(new_table):
                if t < card:
                    taken_mover = tuple(sorted(new_mover + (t,)))
                    taken_table = new_table[:j] + new_table[j+1:]
                    if not can_win(hand_other, taken_mover, taken_table):
                        return True
        return False

    t_win = can_win(tuple(sorted(takahashi_cards)), tuple(sorted(aoki_cards)), tuple(sorted(table_cards)))
    return "Takahashi" if t_win else "Aoki"

