def minimize_path_weights(n: int, edges: List[Tuple[int, int, int]], a: List[int], b: List[int]) -> int:
    m = len(a)
    if m == 0:
        return 0

    # Size structures by the largest vertex index actually used, so that
    # inputs referencing vertices beyond n do not cause index errors.
    max_v = n
    for u, v, _ in edges:
        max_v = max(max_v, u, v)
    for x in a:
        max_v = max(max_v, x)
    for x in b:
        max_v = max(max_v, x)

    parent = list(range(max_v + 1))
    members = [[i] for i in range(max_v + 1)]
    INF = float('inf')
    dist = [[INF] * (max_v + 1) for _ in range(max_v + 1)]
    for i in range(max_v + 1):
        dist[i][i] = 0

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    # Kruskal-style merge: when two components join at edge weight w,
    # every cross pair's minimax path weight is w.
    for u, v, w in sorted(edges, key=lambda e: e[2]):
        ru, rv = find(u), find(v)
        if ru == rv:
            continue
        for x in members[ru]:
            for y in members[rv]:
                dist[x][y] = w
                dist[y][x] = w
        if len(members[ru]) < len(members[rv]):
            ru, rv = rv, ru
        parent[rv] = ru
        members[ru].extend(members[rv])
        members[rv] = []

    # Cost matrix: cost[i][j] = f(a[i], b[j])
    cost = [[dist[a[i]][b[j]] for j in range(m)] for i in range(m)]

    # Hungarian algorithm for minimum-cost assignment
    INF_H = float('inf')
    u_pot = [0] * (m + 1)
    v_pot = [0] * (m + 1)
    p = [0] * (m + 1)
    way = [0] * (m + 1)
    for i in range(1, m + 1):
        p[0] = i
        j0 = 0
        minv = [INF_H] * (m + 1)
        used = [False] * (m + 1)
        while True:
            used[j0] = True
            i0 = p[j0]
            delta = INF_H
            j1 = 0
            for j in range(1, m + 1):
                if not used[j]:
                    cur = cost[i0 - 1][j - 1] - u_pot[i0] - v_pot[j]
                    if cur < minv[j]:
                        minv[j] = cur
                        way[j] = j0
                    if minv[j] < delta:
                        delta = minv[j]
                        j1 = j
            for j in range(m + 1):
                if used[j]:
                    u_pot[p[j]] += delta
                    v_pot[j] -= delta
                else:
                    minv[j] -= delta
            j0 = j1
            if p[j0] == 0:
                break
        while True:
            j1 = way[j0]
            p[j0] = p[j1]
            j0 = j1
            if j0 == 0:
                break

    total = 0
    for j in range(1, m + 1):
        total += cost[p[j] - 1][j - 1]
    return int(total)

