def _is_subsequence(pat, seq):
    it = iter(seq)
    return all(c in it for c in pat)

def count_sequences_without_subsequence(N: int, M: int, K: int, X: list[int]) -> int:
    X = tuple(X)
    others = [p for p in product(range(1, K + 1), repeat=M) if p != X]
    count = 0
    for S in product(range(1, K + 1), repeat=N):
        if _is_subsequence(X, S):
            continue
        if all(_is_subsequence(p, S) for p in others):
            count += 1
    return count % MOD

def count_bob_winning_sequences(s: str) -> int:
    MOD = 10**9 + 7
    beats = {'F': 'E', 'W': 'F', 'E': 'W'}  # beats[x] = what x beats
    moves = ('F', 'W', 'E')
    dp = {(None, 0): 1}
    for ch in s:
        ndp = {}
        for (last, diff), cnt in dp.items():
            for b in moves:
                if b == last:
                    continue
                nd = diff
                if beats[b] == ch:
                    nd += 1
                elif beats[ch] == b:
                    nd -= 1
                key = (b, nd)
                ndp[key] = (ndp.get(key, 0) + cnt) % MOD
        dp = ndp
    return sum(cnt for (last, diff), cnt in dp.items() if diff > 0) % MOD

