def count_strings_by_lcs_length(n: int, m: int, s: str) -> List[int]:
    MOD = 998244353
    full = (1 << n) - 1

    # match masks for each letter
    match = {}
    for c in set(s):
        mask = 0
        for j, ch in enumerate(s):
            if ch == c:
                mask |= 1 << j
        match[c] = mask
    letters = [chr(ord('a') + i) for i in range(26)]
    # letters not in s have mask 0
    masks = [match.get(c, 0) for c in letters]

    # state: V profile (n bits), start all ones
    cur = {full: 1}
    for _ in range(m):
        nxt = {}
        for V, cnt in cur.items():
            for mk in masks:
                U = V & mk
                NV = ((V + U) | (V - U)) & full
                nxt[NV] = (nxt.get(NV, 0) + cnt) % MOD
        cur = nxt

    result = [0] * (n + 1)
    for V, cnt in cur.items():
        lcs = n - bin(V).count('1')
        result[lcs] = (result[lcs] + cnt) % MOD
    return result

