def max_alkane_vertices(n: int, edges: List[Tuple[int, int]]) -> int:
    """ Given an undirected tree with n vertices (numbered 1 to n) and edges connecting them,
    find the maximum number of vertices in a subgraph that forms an alkane.

    An alkane is defined as:
    - An undirected tree
    - Every vertex has degree 1 or 4
    - There is at least one vertex of degree 4

    If no such subgraph exists, return -1.
    """
    if n < 5:
        return -1

    adj = [[] for _ in range(n + 1)]
    for a, b in edges:
        adj[a].append(b)
        adj[b].append(a)

    # Root the tree at 1 and get a BFS order.
    parent = [0] * (n + 1)
    order = []
    visited = [False] * (n + 1)
    stack = [1]
    visited[1] = True
    while stack:
        v = stack.pop()
        order.append(v)
        for u in adj[v]:
            if not visited[u]:
                visited[u] = True
                parent[u] = v
                stack.append(u)

    # down[v]: best size of subtree hanging from v when v's parent is parent[v].
    down = [1] * (n + 1)
    for v in reversed(order):
        vals = []
        for u in adj[v]:
            if u != parent[v]:
                vals.append(down[u])
        if len(vals) >= 3:
            vals.sort(reverse=True)
            down[v] = 1 + vals[0] + vals[1] + vals[2]
        else:
            down[v] = 1

    # up[v]: best size of subtree hanging from parent[v] when parent's parent is v
    # (i.e., the value of the "upward" neighbor as seen from v).
    up = [0] * (n + 1)
    for v in order:
        # Gather all neighbor values as seen from v.
        cand = []
        for u in adj[v]:
            if u == parent[v]:
                cand.append((up[v], u))
            else:
                cand.append((down[u], u))
        cand.sort(key=lambda x: x[0], reverse=True)
        # For each child c of v, compute the value of v as seen from c.
        for c in adj[v]:
            if c == parent[v]:
                continue
            vals = [val for val, u in cand if u != c]
            if len(vals) >= 3:
                up[c] = 1 + vals[0] + vals[1] + vals[2]
            else:
                up[c] = 1

    best = -1
    for v in range(1, n + 1):
        vals = []
        for u in adj[v]:
            if u == parent[v]:
                vals.append(up[v])
            else:
                vals.append(down[u])
        if len(vals) >= 4:
            vals.sort(reverse=True)
            total = 1 + vals[0] + vals[1] + vals[2] + vals[3]
            if total > best:
                best = total
    return best

