def count_paths(W: int, H: int, L: int, R: int, D: int, U: int) -> int:
    def is_block(x, y):
        if not (0 <= x <= W and 0 <= y <= H):
            return False
        return x < L or x > R or y < D or y > U

    prev = [0] * (W + 1)
    prev_block = [False] * (W + 1)
    total = 0
    for y in range(H + 1):
        cur = [0] * (W + 1)
        cur_block = [is_block(x, y) for x in range(W + 1)]
        for x in range(W + 1):
            if not cur_block[x]:
                continue
            v = 1
            if x > 0 and cur_block[x - 1]:
                v += cur[x - 1]
            if prev_block[x]:
                v += prev[x]
            cur[x] = v % MOD
            total = (total + cur[x]) % MOD
        prev, prev_block = cur, cur_block
    return total

