    ['ABC', 'BCA', 'CAB']
    >>> solve_grid(3, 'AAA', 'BBB')
    None
    """
    letters = "ABC"
    # grid[i][j] is None (empty) or one of 'A','B','C'
    grid = [[None] * n for _ in range(n)]

    # Each row/column needs exactly one of each letter; count what is used.
    def row_ok(i):
        vals = [grid[i][j] for j in range(n) if grid[i][j] is not None]
        return len(vals) == len(set(vals))

    def col_ok(j):
        vals = [grid[i][j] for i in range(n) if grid[i][j] is not None]
        return len(vals) == len(set(vals))

