from math import isqrt

def _iroot(n: int, k: int) -> int:
    # Largest integer r with r^k <= n
    if n < 2:
        return n
    r = int(round(n ** (1.0 / k)))
    while r ** k > n:
        r -= 1
    while (r + 1) ** k <= n:
        r += 1
    return r

def _mobius(k: int) -> int:
    result = 1
    d = 2
    m = k
    while d * d <= m:
        if m % d == 0:
            m //= d
            if m % d == 0:
                return 0
            result = -result
        d += 1
    if m > 1:
        result = -result
    return result

def count_power_representations(n: int) -> int:
    if n < 1:
        return 0
    total = 0
    for k in range(2, n.bit_length() + 2):
        r = _iroot(n, k)
        if r < 2:
            break
        total += -_mobius(k) * (r - 1)
    return total + 1

