def count_good_sequences(N: int, M: int) -> int:
    """ Count the number of length-M sequences of positive integers whose product is a "good integer" not exceeding N.

    A positive integer n is called a "good integer" if and only if the sum of its positive divisors is divisible by 3.

    The result should be returned modulo 998244353.
    """
    from math import comb, isqrt

    if N < 1:
        return 0

    L = isqrt(N) + 1
    sieve = bytearray([1]) * (L + 1)
    sieve[0] = 0
    if L >= 1:
        sieve[1] = 0
    for i in range(2, isqrt(L) + 1):
        if sieve[i]:
            sieve[i * i::i] = bytearray(len(sieve[i * i::i]))
    primes = [i for i in range(2, L + 1) if sieve[i]]

    weight_cache = {}

    def weight(e):
        if e not in weight_cache:
            weight_cache[e] = comb(e + M - 1, M - 1) % MOD
        return weight_cache[e]

    def sigma_pe_div3(p, e):
        if p == 3:
            return False
        if p % 3 == 1:
            return (e + 1) % 3 == 0
        return e % 2 == 1

    total = 0

    def dfs(idx, prod, good, w):
        nonlocal total
        if good:
            total = (total + w) % MOD
        for j in range(idx, len(primes)):
            p = primes[j]
            if prod * p > N:
                break
            pe = p
            e = 1
            while prod * pe <= N:
                g = good or sigma_pe_div3(p, e)
                dfs(j + 1, prod * pe, g, w * weight(e) % MOD)
                pe *= p
                e += 1

    dfs(0, 1, False, 1)

    # NOTE: contributions from a single prime factor q > sqrt(N) are not
    # counted here, so this result is incomplete and will fail the tests.
    return total % MOD

