def sum_manhattan_distances(m: int, n: int, k: int) -> int:
    N = m * n
    # Factorials up to N for binomial coefficients
    fact = [1] * (N + 1)
    for i in range(1, N + 1):
        fact[i] = fact[i - 1] * i % MOD
    inv_fact = [1] * (N + 1)
    inv_fact[N] = pow(fact[N], MOD - 2, MOD)
    for i in range(N, 0, -1):
        inv_fact[i - 1] = inv_fact[i] * i % MOD

    def C(a, b):
        if b < 0 or a < 0 or b > a:
            return 0
        return fact[a] * inv_fact[b] % MOD * inv_fact[a - b] % MOD

    # Sum of Manhattan distances over all unordered pairs of cells
    pair_sum = 0
    for d in range(1, n):
        pair_sum = (pair_sum + d * (n - d) * m * m) % MOD
    for d in range(1, m):
        pair_sum = (pair_sum + d * (m - d) * n * n) % MOD

    # Each unordered pair of cells appears in C(N-2, k-2) k-subsets
    return pair_sum * C(N - 2, k - 2) % MOD

