from typing import List


def findProductQueries(queries: List[List[int]]) -> List[int]:
    def count_bit_upto(n, b):
        # number of integers in [0, n] with bit b set
        if n < 0:
            return 0
        period = 1 << (b + 1)
        half = 1 << b
        full = (n + 1) // period
        rem = (n + 1) % period
        return full * half + max(0, rem - half)

    def prefix_len(n):
        # total entries contributed by integers 1..n (sum of popcounts)
        return sum(count_bit_upto(n, b) for b in range(62))

    def exp_counts_prefix(p):
        # returns list cnt where cnt[k] = number of entries equal to 2^k
        # among the first p entries of big_nums
        cnt = [0] * 62
        if p <= 0:
            return cnt
        # single binary search for the integer containing position p
        lo, hi = 0, 1 << 40
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if prefix_len(mid) <= p:
                lo = mid
            else:
                hi = mid - 1
        full_i = lo
        covered = prefix_len(full_i)
        for k in range(62):
            cnt[k] = count_bit_upto(full_i, k)
        remaining = p - covered
        if remaining > 0:
            nxt = full_i + 1
            bits = [b for b in range(62) if (nxt >> b) & 1]
            for b in bits[:remaining]:
                cnt[b] += 1
        return cnt

    results = []
    for l, r, m in queries:
        if m == 1:
            results.append(0)
            continue
        hi_cnt = exp_counts_prefix(r + 1)
        lo_cnt = exp_counts_prefix(l)
        result = 1 % m
        for k in range(62):
            e = hi_cnt[k] - lo_cnt[k]
            if e:
                result = (result * pow(pow(2, k, m), e, m)) % m
        results.append(result)
    return results

