from collections import defaultdict


def min_ng_list_size(n: int, product_names: List[str]) -> int:
    adj = defaultdict(set)
    radj = defaultdict(set)
    nodes = set()
    for name in product_names:
        a, b = name[0], name[1]
        adj[a].add(b)
        radj[b].add(a)
        nodes.add(a)
        nodes.add(b)

    # Weakly connected components (only over nodes that carry edges)
    seen = set()
    comps = []
    for s in nodes:
        if s in seen:
            continue
        stack = [s]
        seen.add(s)
        comp = []
        while stack:
            u = stack.pop()
            comp.append(u)
            for v in adj[u] | radj[u]:
                if v not in seen:
                    seen.add(v)
                    stack.append(v)
        comps.append(set(comp))

    def reach(start, graph, allowed):
        vis = {start}
        st = [start]
        while st:
            u = st.pop()
            for v in graph[u]:
                if v in allowed and v not in vis:
                    vis.add(v)
                    st.append(v)
        return vis

    total = 0
    for comp in comps:
        # Count edges within component to decide whether it is trivially covered
        # Walks may reuse edges, so the number of walks needed for a weakly
        # connected component equals the number of "source" strongly connected
        # components in its condensation (1 if it has a single source).
        # Compute SCCs via reachability (graphs here are small: <= 26 nodes).
        comp_list = list(comp)
        reach_map = {u: reach(u, adj, comp) for u in comp_list}
        sccs = []
        assigned = set()
        for u in comp_list:
            if u in assigned:
                continue
            group = {v for v in comp_list if v in reach_map[u] and u in reach_map[v]}
            assigned |= group
            sccs.append(group)
        # An SCC is a source if no edge enters it from outside
        sources = 0
        for scc in sccs:
            is_source = True
            for other in sccs:
                if other is scc:
                    continue
                if any(v in scc for o in other for v in adj[o]):
                    is_source = False
                    break
            if is_source:
                sources += 1
        total += max(1, sources)
    return total

