def min_team_switches(people: List[Tuple[int, int]]) -> int:
    """ Given a list of people where each person is represented as (team_number, strength),
    determine the minimum number of people who need to switch teams so that all three teams
    have equal total strength. Teams are numbered 1, 2, and 3.

    Each person belongs to exactly one team and has a strength value. The strength of a team
    is the sum of strengths of all its members. Return -1 if it's impossible to make all
    teams have equal strength.

    Args:
        people: List of tuples (team_number, strength) where team_number is in {1, 2, 3}
                and strength is a positive integer.

    Returns:
        The minimum number of people who need to switch teams, or -1 if impossible.

    >>> min_team_switches([(1, 2), (2, 5), (1, 5), (3, 3), (1, 3), (3, 6)])
    2
    >>> min_team_switches([(1, 1), (1, 2), (2, 3), (3, 4)])
    -1
    >>> min_team_switches([(1, 1), (2, 1), (3, 1)])
    0
    """
    total = sum(s for _, s in people)
    if total % 3 != 0:
        return -1
    target = total // 3

    sums = {1: 0, 2: 0, 3: 0}
    members = {1: [], 2: [], 3: []}
    for team, s in people:
        sums[team] += s
        members[team].append(s)

    if sums[1] == target and sums[2] == target and sums[3] == target:
        return 0

    def min_leaving(team: int, to_a: int, to_b: int):
        """Minimum number of members of `team` that must leave so that a disjoint
        subset with total exactly to_a goes to one destination and a disjoint subset
        with total exactly to_b goes to the other. Returns None if impossible."""
        dp = {(0, 0): 0}
        for w in members[team]:
            new = dict(dp)
            for (x, y), c in dp.items():
                if x + w <= to_a:
                    key = (x + w, y)
                    if new.get(key, float('inf')) > c + 1:
                        new[key] = c + 1
                if y + w <= to_b:
                    key = (x, y + w)
                    if new.get(key, float('inf')) > c + 1:
                        new[key] = c + 1
            dp = new
        return dp.get((to_a, to_b))

    best = float('inf')
    s1, s2, s3 = sums[1], sums[2], sums[3]

    # f_ij = strength moved from team i to team j.
    # Team 1 sends f12 to team 2 and f13 to team 3.
    # Team 2 sends f21 to team 1 and f23 to team 3.
    # Team 3's outflows f31, f32 are forced by the balance equations.
    for f12 in range(0, s1 + 1):
        for f13 in range(0, s1 - f12 + 1):
            for f21 in range(0, s2 + 1):
                for f23 in range(0, s2 - f21 + 1):
                    f31 = target - s1 + f12 + f13 - f21
                    f32 = target - s2 + f21 + f23 - f12
                    if f31 < 0 or f32 < 0:
                        continue
                    if s3 - (f31 + f32) + (f13 + f23) != target:
                        continue
                    if f31 + f32 > s3:
                        continue
                    c1 = min_leaving(1, f12, f13)
                    if c1 is None:
                        continue
                    c2 = min_leaving(2, f21, f23)
                    if c2 is None:
                        continue
                    c3 = min_leaving(3, f31, f32)
                    if c3 is None:
                        continue
                    best = min(best, c1 + c2 + c3)

    return -1 if best == float('inf') else best

