    # Determine the true vertex range from the input, since edges may reference
    # vertices beyond n in some inputs.
    max_v = n
    for u, v, _ in edges:
        if u > max_v:
            max_v = u
        if v > max_v:
            max_v = v
    for x in a:
        if x > max_v:
            max_v = x
    for x in b:
