    UNREACH = 10 ** 18  # finite sentinel for unreachable pairs

    parent = list(range(N + 1))
    members = {i: [i] for i in range(1, N + 1)}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    dist = [[UNREACH] * (N + 1) for _ in range(N + 1)]
