def min_deletions_to_snowflake(n: int, edges: List[Tuple[int, int]]) -> int:
    adj = [[] for _ in range(n + 1)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    deg = [len(adj[i]) for i in range(n + 1)]

    # L[u] = number of leaf neighbors of u (candidate y-leaves if u is an x-vertex)
    L = [0] * (n + 1)
    for u in range(1, n + 1):
        L[u] = sum(1 for w in adj[u] if deg[w] == 1)

    best_kept = -1
    for c in range(1, n + 1):
        kept = 1  # the center
        has_x = False
        for u in adj[c]:
            # u can be an x-vertex only if it is not a leaf and has at least one leaf child
            if deg[u] > 1 and L[u] >= 1:
                kept += 1 + L[u]
                has_x = True
        if has_x and kept > best_kept:
            best_kept = kept

    return n - best_kept

