from itertools import product
from functools import lru_cache

def _fixed_count_set(n: int) -> frozenset:
    """Exact set of achievable fixed-element counts for n x n binary matrices.
    Brute force: only feasible for very small n."""
    classes = {}
    for bits in product((0, 1), repeat=n * n):
        rows = tuple(sum(bits[i * n:(i + 1) * n]) for i in range(n))
        cols = tuple(sum(bits[i * n + j] for i in range(n)) for j in range(n))
        classes.setdefault((rows, cols), []).append(bits)
    counts = set()
    for members in classes.values():
        fixed = 0
        for pos in range(n * n):
            vals = {m[pos] for m in members}
            if len(vals) == 1:
                fixed += 1
        counts.add(fixed)
    return frozenset(counts)

@lru_cache(maxsize=None)
def _small_table(n: int) -> frozenset:
    return _fixed_count_set(n)

def matrix_with_k_fixed_elements_exists(n: int, k: int) -> bool:
    if k < 0 or k > n * n:
        return False
    if n <= 3:
        return k in _small_table(n)
    # Large n: no verified characterization available yet.
    raise NotImplementedError("No verified rule for n > 3")

