def count_polish_sequences(n: int, a: list[int]) -> int:
    # Brute-force: enumerate all sequences of length n that are Polish
    # and lexicographically <= a. Correct but only feasible for small n.
    from functools import lru_cache

    def is_polish_full(seq):
        # Parse seq as a preorder tree where each node value = child count.
        # Returns True iff the whole sequence is exactly one Polish sequence.
        stack = [1]  # pending subtrees to read
        for v in seq:
            if stack[-1] == 0:
                return False
            stack[-1] -= 1
            stack.append(v)
            # pop finished nodes
            while stack and stack[-1] == 0:
                stack.pop()
                if not stack:
                    break
        return len(stack) == 0

    count = 0
    def rec(prefix):
        nonlocal count
        if len(prefix) == n:
            if is_polish_full(prefix) and prefix <= a:
                count += 1
            return
        for v in range(n):
            if len(prefix) == 0 or True:
                rec(prefix + [v])
    # Only feasible for very small n
    rec([])
    return count % MOD

