    # Reading value v requires need >= 1; afterwards need = need - 1 + v.
    # A sequence is Polish iff need reaches 0 exactly at the last position.
    count = 0

    def dfs(pos, need, tight):
        nonlocal count
        if pos == n:
            if need == 0:
                count += 1
            return
        if need == 0:
            return
        upper = a[pos] if tight else n - 1
        for v in range(0, upper + 1):
            new_need = need - 1 + v
            # Remaining positions must be able to close all owed subtrees.
            if new_need > n - pos - 1:
                break
            dfs(pos + 1, new_need, tight and v == a[pos])

    dfs(0, 1, True)
    return count % MOD

