def can_reach_end(n: int, m: int, a: int, b: int, bad_intervals: List[Tuple[int, int]]) -> bool:
    """ Determine if it's possible to move from square 1 to square N by repeatedly jumping.

    Args:
        n: The number of squares (2 <= n <= 10^12)
        m: The number of bad intervals (0 <= m <= 2*10^4)
        a: The minimum jump size (1 <= a <= b <= 20)
        b: The maximum jump size
        bad_intervals: List of tuples (l_i, r_i) representing bad intervals.
                      The intervals are sorted and non-overlapping.

    Returns:
        True if it's possible to reach square n from square 1, False otherwise.
    """
    if n == 1:
        return True

    bad = sorted(bad_intervals)

    # Fast path: small n, direct DP with prefix sums.
    if n <= 10**6:
        is_bad = [False] * (n + 2)
        for l, r in bad:
            for j in range(max(l, 1), min(r, n) + 1):
                is_bad[j] = True
        reach = [False] * (n + 2)
        pref = [0] * (n + 2)  # pref[i] = number of reachable squares in [1, i]
        reach[1] = True
        pref[1] = 1
        for x in range(2, n + 1):
            if not is_bad[x]:
                lo = max(1, x - b)
                hi = x - a
                if hi >= lo:
                    cnt = pref[hi] - pref[lo - 1]
                    if cnt > 0:
                        reach[x] = True
            pref[x] = pref[x - 1] + (1 if reach[x] else 0)
        return reach[n]

    # Large n: work with intervals of reachable squares.
    # Good segments are the maximal gaps between bad intervals.
    segments = []
    cur = 1
    for l, r in bad:
        if l > cur:
            segments.append((cur, min(l - 1, n)))
        cur = max(cur, r + 1)
        if cur > n:
            break
    if cur <= n:
        segments.append((cur, n))

    def merge(ranges):
        ranges = sorted(ranges)
        out = []
        for s, e in ranges:
            if s > e:
                continue
            if out and s <= out[-1][1] + 1:
                out[-1] = (out[-1][0], max(out[-1][1], e))
            else:
                out.append((s, e))
        return out

    # reachable: merged list of reachable intervals found so far.
    reachable = [(1, 1)]

    for s, e in segments:
        # Contributions into this good segment from earlier reachable squares.
        seeds = []
        for qs, qe in reachable:
            lo = qs + a
            hi = qe + b
            if hi < s or lo > e:
                continue
            seeds.append((max(lo, s), min(hi, e)))
        cur_set = merge(seeds)

        # Propagate chains inside the segment until stable.
        # Any reachable p in the segment makes [p+a, p+b] reachable within it.
        while True:
            extra = []
            for ps, pe in cur_set:
                lo = ps + a
                hi = pe + b
                if lo <= e and hi >= s:
                    extra.append((max(lo, s), min(hi, e)))
            new_set = merge(cur_set + extra)
            if new_set == cur_set:
                break
            cur_set = new_set

        if cur_set:
            reachable = merge(reachable + cur_set)
            if reachable and reachable[-1][1] >= n:
                return True

    return bool(reachable) and reachable[-1][1] >= n

