from typing import List


def count_strings_by_lcs_length(n: int, m: int, s: str) -> List[int]:
    MOD = 998244353
    # Each state is the LCS DP row of the processed prefix against s:
    # row[j] = LCS(prefix, s[:j]) for j in 0..n
    start = tuple([0] * (n + 1))
    alphabet = 'abcdefghijklmnopqrstuvwxyz'

    transition_cache = {}

    def step(row, c):
        key = (row, c)
        if key in transition_cache:
            return transition_cache[key]
        new = [0] * (n + 1)
        for j in range(1, n + 1):
            best = max(new[j - 1], row[j])
            if s[j - 1] == c:
                best = max(best, row[j - 1] + 1)
            new[j] = best
        result = tuple(new)
        transition_cache[key] = result
        return result

    dp = {start: 1}
    for _ in range(m):
        ndp = {}
        for row, cnt in dp.items():
            for c in alphabet:
                nrow = step(row, c)
                ndp[nrow] = (ndp.get(nrow, 0) + cnt) % MOD
        dp = ndp

    ans = [0] * (n + 1)
    for row, cnt in dp.items():
        ans[row[n]] = (ans[row[n]] + cnt) % MOD
    return ans

