def count_in_degree_sequences(n: int, s: str) -> int:
    # Build the edge list of G: cycle edges and hub edges.
    edges = []
    for i in range(n):
        edges.append((i, (i + 1) % n))
    for i in range(n):
        if s[i] == '1':
            edges.append((i, n))

    seqs = set()
    # Each edge is oriented toward one endpoint; the in-degree vector
