from collections import deque

def can_transform_string(n: int, x: int, y: int, s: str, t: str) -> bool:
    if s == t:
        return True
    if s.count('0') != t.count('0'):
        return False

    def neighbors(cur: str):
        res = set()
        # Operation A: x zeros followed by y ones -> y ones followed by x zeros
        pat_a0 = '0' * x + '1' * y
        pat_a1 = '1' * y + '0' * x
        # Operation B: y ones followed by x zeros -> x zeros followed by y ones
        pat_b0 = pat_a1
        pat_b1 = pat_a0
        for i in range(n - x - y + 1):
            seg = cur[i:i + x + y]
            if seg == pat_a0:
                res.add(cur[:i] + pat_a1 + cur[i + x + y:])
            if seg == pat_b0:
                res.add(cur[:i] + pat_b1 + cur[i + x + y:])
        return res

    seen = {s}
    queue = deque([s])
    while queue:
        cur = queue.popleft()
        for nxt in neighbors(cur):
            if nxt == t:
                return True
            if nxt not in seen:
                seen.add(nxt)
                queue.append(nxt)
    return False

