def count_strongly_connected_partitions(n: int, s: str) -> int:
    MOD = 998244353
    N = 2 * n

    def is_strongly_connected(pairs):
        # Path edges i -> i+1 for vertices 0..N-1, plus white->black for each pair
        adj = [[] for _ in range(N)]
        radj = [[] for _ in range(N)]
        for i in range(N - 1):
            adj[i].append(i + 1)
            radj[i + 1].append(i)
        for w, b in pairs:
            adj[w].append(b)
            radj[b].append(w)

        def reach(g):
            seen = [False] * N
            stack = [0]
            seen[0] = True
            cnt = 1
            while stack:
                u = stack.pop()
                for v in g[u]:
                    if not seen[v]:
                        seen[v] = True
                        cnt += 1
                        stack.append(v)
            return cnt == N

        return reach(adj) and reach(radj)

    whites = [i for i in range(N) if s[i] == 'W']
    blacks = [i for i in range(N) if s[i] == 'B']
    if len(whites) != n or len(blacks) != n:
        return 0

    count = 0

    def backtrack(idx, used, pairs):
        nonlocal count
        if idx == len(whites):
            if is_strongly_connected(pairs):
                count += 1
            return
        w = whites[idx]
        for j, b in enumerate(blacks):
            if not used[j]:
                used[j] = True
                pairs.append((w, b))
                backtrack(idx + 1, used, pairs)
                pairs.pop()
                used[j] = False

    backtrack(0, [False] * n, [])
    return count % MOD

