def count_powerful_integers(start: int, finish: int, limit: int, s: str) -> int:
    L = len(s)
    suffix = int(s)
    scale = 10 ** L

    # If any digit of s exceeds limit, no valid number can end with s
    if any(int(c) > limit for c in s):
        return 0

    def count_prefixes_upto(bound: int) -> int:
        # Count p in [0, bound] whose decimal digits are all <= limit (0 counts as valid)
        if bound < 0:
            return 0
        digits = list(map(int, str(bound)))
        n = len(digits)
        from functools import lru_cache

        @lru_cache(maxsize=None)
        def dp(pos: int, tight: bool, started: bool) -> int:
            if pos == n:
                return 1  # includes the number 0 (not started)
            upper = digits[pos] if tight else 9
            total = 0
            for d in range(0, upper + 1):
                if d > limit:
                    break
                nt = tight and (d == upper)
                if not started and d == 0:
                    total += dp(pos + 1, nt, False)
                else:
                    total += dp(pos + 1, nt, True)
            return total

        return dp(0, True, False)

    def count_upto(N: int) -> int:
        # Count valid x in [0, N] ending with s with all digits <= limit
        if N < suffix:
            return 0
        bound = (N - suffix) // scale
        return count_prefixes_upto(bound)

    return count_upto(finish) - count_upto(start - 1)

