        # Placeholder closed form: doubled black area of [0, X] x [0, Y].
        # Not derived from the coloring rule; expected to fail assertions.
        if X <= 0 or Y <= 0:
            return 0
        return X * Y

    return F(C, D) - F(A, D) - F(C, B) + F(A, B)

