def _iroot(n: int, k: int) -> int:
    # Largest integer r with r^k <= n
    if n < 2:
        return n
    r = int(round(n ** (1.0 / k)))
    while r ** k > n:
        r -= 1
    while (r + 1) ** k <= n:
        r += 1
    return r

def _mobius(k: int) -> int:
    result = 1
    d = 2
    m = k
    while d * d <= m:
        if m % d == 0:
            m //= d
            if m % d == 0:
                return 0
            result = -result
        d += 1
    if m > 1:
        result = -result
    return result

def count_power_representations(n: int) -> int:
    if n < 1:
        return 0
    total = 0
    for k in range(2, n.bit_length() + 2):
        r = _iroot(n, k)
        if r < 2:
            break
        total += -_mobius(k) * (r - 1)
    return total + 1

def find_palindrome_expression(n: int) -> str:
    """ Find a palindrome string S that represents a mathematical expression evaluating to n.

    The string must satisfy:
    - Length between 1 and 1000 characters
    - Consists only of digits 1-9 and the multiplication symbol '*'
    - Is a palindrome (reads the same forwards and backwards)
    - First character must be a digit
    - When evaluated as a mathematical expression, equals n

    Args:
        n: An integer between 1 and 10^12

    Returns:
        A palindrome string representing an expression that evaluates to n,
        or '-1' if no such string exists.
    """
    from functools import lru_cache

    def is_pal_digits(s: str) -> bool:
        return '0' not in s and s == s[::-1]

    # Palindromic numbers with digits 1-9 that divide n (candidates for factors)
    def palin_divisors(m: int):
        res = []
        # enumerate divisors
        divs = set()
        i = 1
        while i * i <= m:
            if m % i == 0:
                divs.add(i)
                divs.add(m // i)
            i += 1
        for d in divs:
            s = str(d)
            if is_pal_digits(s):
                res.append(s)
        return sorted(res, key=lambda x: -int(x))

    # Find a sequence of palindromic factors whose product of squares times a
    # palindromic middle equals n.  Arrangement: P1*...*Pk*M*Pk*...*P1
    # Length check afterwards.
    pal_cache = {}

    def get_pals(m):
        if m not in pal_cache:
            pal_cache[m] = palin_divisors(m)
        return pal_cache[m]

    def build(rem: int, depth: int):
        # rem: remaining quotient that must be expressed as (prod of pair factors)^2 * middle
        # Option: rem itself is a palindromic middle (no further pairs)
        if rem == 1:
            return [], None
        if is_pal_digits(str(rem)):
            return [], str(rem)
        # Try pair factor P with P*P dividing rem
        for p in get_pals(rem):
            pv = int(p)
            if pv == 1:
                continue
            if rem % (pv * pv) == 0:
                sub = build(rem // (pv * pv), depth + 1)
                if sub is not None:
                    pairs, mid = sub
                    return [p] + pairs, mid
        return None

    # Handle small values directly
    if n == 1:
        return '1'

    result = build(n, 0)
    if result is None:
        return '-1'
    pairs, mid = result
    left = '*'.join(pairs)
    parts = []
    if pairs:
        parts.append(left)
    if mid is not None:
        parts.append(mid)
    if pairs:
        parts.append('*'.join(reversed(pairs)))
    expr = '*'.join(parts)
    if not expr or expr[0] not in '123456789' or len(expr) > 1000:
        return '-1'
    return expr

