def count_arithmetic_subsequences(n: int, a: List[int]) -> List[int]:
    MOD = 998244353
    # result[k] = number of arithmetic subsequences of length k+1
    result = [0] * n
    result[0] = n  # every single element is a subsequence

    if n == 1:
        return result

    # dp[j] maps difference d -> list where cnt[L] = number of arithmetic
    # subsequences of length L (L >= 2) ending at index j with difference d.
    dp = [dict() for _ in range(n)]

    for j in range(n):
        for i in range(j):
            d = a[j] - a[i]
            # subsequences of length 2 ending at (i, j)
            cnt = dp[j].setdefault(d, [0] * (n + 1))
            cnt[2] = (cnt[2] + 1) % MOD
            # extend subsequences of length L ending at i with same difference d
            if d in dp[i]:
                prev = dp[i][d]
                for L in range(2, n + 1):
                    if prev[L]:
                        cnt[L + 1] = (cnt[L + 1] + prev[L]) % MOD

    for j in range(n):
        for d, cnt in dp[j].items():
            for L in range(2, n + 1):
                if cnt[L]:
                    result[L - 1] = (result[L - 1] + cnt[L]) % MOD

    return result

