def max_dishes_eaten(n: int, x: int, y: int, dishes: List[Tuple[int, int]]) -> int:
    INF = float("inf")
    # dp[s] = minimum total saltiness over chosen dishes with total sweetness s,
    # where all prefix totals so far were within limits before each dish was eaten
    dp = [INF] * (x + 1)
    dp[0] = 0
    best = 0
    for a, b in dishes:
        new = dp[:]
        for s in range(x + 1):
            if dp[s] == INF or dp[s] > y:
                continue
            ns = min(x, s + a)
            nt = dp[s] + b
            if nt < new[ns]:
                new[ns] = nt
        dp = new
    for s in range(x + 1):
        if dp[s] != INF:
            best = max(best, 1)
    return best

MOD = 998244353

def count_paths(N: int, M: int, K: int, extra_edges: list) -> int:
    # 0-indexed vertices. A walker at time t located at vertex v is stored
    # under key k where v = (k + t) mod N. Forced cycle moves keep k fixed.
    out = {}
    for x, y in extra_edges:
        out.setdefault(x - 1, []).append(y - 1)
    sources = list(out.keys())

    cur = {0: 1}  # start at vertex 0 at time 0: key = 0
    for t in range(K):
        additions = {}
        for x in sources:
            k = (x - t) % N
            c = cur.get(k, 0)
            if c == 0:
                continue
            for y in out[x]:
                nk = (y - (t + 1)) % N
                additions[nk] = (additions.get(nk, 0) + c) % MOD
        for nk, a in additions.items():
            cur[nk] = (cur.get(nk, 0) + a) % MOD
    return sum(cur.values()) % MOD

