def minimize_path_weights(n: int, edges: List[Tuple[int, int, int]], a: List[int], b: List[int]) -> int:
    # Determine the true vertex range from the input, since edges may reference
    # vertices beyond n in some inputs.
    max_v = n
    for u, v, _ in edges:
        if u > max_v:
            max_v = u
        if v > max_v:
            max_v = v
    for x in a:
        if x > max_v:
            max_v = x
    for x in b:
        if x > max_v:
            max_v = x

    N = max_v
    UNREACH = 10 ** 18  # finite sentinel for unreachable pairs

    parent = list(range(N + 1))
    members = {i: [i] for i in range(1, N + 1)}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    dist = [[UNREACH] * (N + 1) for _ in range(N + 1)]
    for i in range(1, N + 1):
        dist[i][i] = 0

    for u, v, w in sorted(edges, key=lambda e: e[2]):
        ru, rv = find(u), find(v)
        if ru == rv:
            continue
        for x in members[ru]:
            for y in members[rv]:
                dist[x][y] = w
                dist[y][x] = w
        if len(members[ru]) < len(members[rv]):
            ru, rv = rv, ru
        parent[rv] = ru
        members[ru].extend(members.pop(rv))

    m = len(a)
    cost = [[0] * (m + 1) for _ in range(m + 1)]
    for i in range(m):
        for j in range(m):
            cost[i + 1][j + 1] = dist[a[i]][b[j]]

    # Hungarian algorithm (min-cost perfect assignment), 1-indexed
    INF = float('inf')
    u_pot = [0] * (m + 1)
    v_pot = [0] * (m + 1)
    p = [0] * (m + 1)
    way = [0] * (m + 1)
    for i in range(1, m + 1):
        p[0] = i
        j0 = 0
        minv = [INF] * (m + 1)
        used = [False] * (m + 1)
        while True:
            used[j0] = True
            i0 = p[j0]
            delta = INF
            j1 = 0
            for j in range(1, m + 1):
                if not used[j]:
                    cur = cost[i0][j] - u_pot[i0] - v_pot[j]
                    if cur < minv[j]:
                        minv[j] = cur
                        way[j] = j0
                    if minv[j] < delta:
                        delta = minv[j]
                        j1 = j
            for j in range(m + 1):
                if used[j]:
                    u_pot[p[j]] += delta
                    v_pot[j] -= delta
                else:
                    minv[j] -= delta
            j0 = j1
            if p[j0] == 0:
                break
        while True:
            j1 = way[j0]
            p[j0] = p[j1]
            j0 = j1
            if j0 == 0:
                break

    total = 0
    for j in range(1, m + 1):
        total += cost[p[j]][j]
    return int(total)

