MOD = 998244353

def count_sequences_without_subsequence(N: int, M: int, K: int, X: list[int]) -> int:
    if any(x < 1 or x > K for x in X):
        return 0

    def is_subsequence(w, s):
        it = iter(s)
        return all(c in it for c in w)

    others = [list(w) for w in product(range(1, K + 1), repeat=M) if list(w) != list(X)]

    count = 0
    for S in product(range(1, K + 1), repeat=N):
        if is_subsequence(X, S):
            continue
        if all(is_subsequence(w, S) for w in others):
            count += 1
    return count % MOD

def count_bob_winning_sequences(s: str) -> int:
    MOD = 10**9 + 7
    # key beats value
    beats = {'F': 'E', 'W': 'F', 'E': 'W'}

    # State: (Bob's last move, bob_points - alice_points)
    dp = {(None, 0): 1}
    for a in s:
        ndp = {}
        for (last, diff), cnt in dp.items():
            for b in 'FWE':
                if b == last:
                    continue
                nd = diff
                if beats[b] == a:
                    nd += 1
                elif beats[a] == b:
                    nd -= 1
                key = (b, nd)
                ndp[key] = (ndp.get(key, 0) + cnt) % MOD
        dp = ndp
    return sum(cnt for (last, diff), cnt in dp.items() if diff > 0) % MOD

