def exact(n, a):
    @lru_cache(maxsize=None)
    def win(counts, visited, turn):
        if visited == (1 << n) - 1:
            return False
        for i in range(n):
            if counts[i] >= 1:
                nc = counts[:i] + (counts[i] - 1,) + counts[i + 1:]
                if not win(nc, visited | (1 << i), 1 - turn):
                    return True
        return False
    return 'Fennec' if win(tuple(a), 0, 0) else 'Snuke'

